export const vpNewHymns: Hymn[] = [
  { id: "vp-psalm-116", title: "Ⲛⲓⲉⲑⲛⲟⲥ ⲧⲏⲣⲟⲩ (Psalm 116)", versions: [
    { language: 'coptic', text: "Ⲇⲟⲝⲁ ⲥⲓ ⲟ̀ Ⲑⲉⲟⲥ ⲏ̀ⲙⲱⲛ.\n\nⲚⲓⲉⲑⲛⲟⲥ ⲧⲏⲣⲟⲩ ⲥ̀ⲙⲟⲩ Ⲡ̀ϭⲟⲓⲥ: ⲙⲁⲣⲟⲩⲥ̀ⲙⲟⲩ ⲉ̀ⲣⲟϥ ⲛ̀ϫⲉ ⲛⲓⲗⲁⲟⲥ ⲧⲏⲣⲟⲩ: ϫⲉ ⲁ̀ ⲡⲉϥⲛⲁⲓ ⲧⲁϫⲣⲟ ⲉ̀ϩ̀ⲣⲏⲓ ⲉ̀ϫⲱⲛ: ⲟⲩⲟϩ ϯⲙⲉⲑⲙⲏⲓ ⲛ̀ⲧⲉ Ⲡ̀ϭⲟⲓⲥ ϣⲟⲡ ϣⲁ ⲉ̀ⲛⲉϩ: ⲁⲗⲗⲏⲗⲟⲩⲓⲁ.\n\nⲆⲟⲝⲁ Ⲡⲁⲧⲣⲓ ⲕⲉ Ⲩ̀ⲓⲱ ⲕⲉ Ⲁ̀ⲅⲓⲱ Ⲡ̀ⲛⲉⲩⲙⲁⲧⲓ: ⲕⲉ ⲛⲩⲛ ⲕⲉ ⲁ̀ⲓ̀ ⲕⲉ ⲓⲥ ⲧⲟⲩⲥ ⲉ̀ⲱ̀ⲛⲁⲥ ⲧⲱⲛ ⲉ̀ⲱ̀ⲛⲱⲛ ⲁ̀ⲙⲉⲛ: ⲁⲗⲗⲏⲗⲟⲩⲓⲁ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ\n\nⲆⲟⲝⲁ ⲥⲓ ⲟ̀ Ⲑⲉⲟⲥ ⲩ̀ⲙⲱⲛ.\n\nⲠⲓⲟⲩⲏⲃ:\n\nⲀ̀ⲙⲏⲛ Ⲁⲗⲗⲏⲗⲟⲩⲓⲁ. Ⲕⲩⲣⲓⲉ ⲉ̀ⲗⲉⲏ̀ⲥⲟⲛ.\n\nⲠⲓⲗⲁⲟⲥ:\n\nⲔⲩⲣⲓⲉ ⲉ̀ⲗⲉⲏ̀ⲥⲟⲛ (ⲃ︦)" },
    { language: 'english', text: "Glory be to You, O our God.\n\nPraise the Lord all you nations, praise Him all you peoples, for His mercy is confirmed upon us, and the truth of the Lord endures forever, Alleluia.\n\nGlory to the Father, and the Son, and the Holy Spirit, now and ever and unto the age of ages. Amen. Alleluia. Alleluia.\n\nGlory be to You, O our God.\n\nPriest:\n\nAmen. Alleluia. Lord Have Mercy.\n\nPeople:\n\nLord have mercy. (2)" },
    { language: 'arabic', text: "المجد لإلهنا.\n\nيا كل الأمم سبحوا الرب، ولتباركه جميع الشعوب، لأن رحمته قد قويت علينا، وحق الرب يدوم إلى الأبد، هلليلويا.\n\nالمجد للآب والإبن والرُّوح القُدُس، الآن وكل أوان وإلى دهر الدهور آمين، هلليلويا هلليلويا\n\nالمجد لإلهنا.\n\nالكاهن:\n\nآمين، هلليلويا. يا الله إرحمنا\n\nالشعب:\n\nيا الله إرحمنا (٢)" },
    { language: 'englishArabic', text: "El-magd li-ilahina.\n\nYa kull el-umam sabbihou er-Rabb, wal-tubarikhu gamee' esh-shu'oub, li-anna rahmatahu qad qawiyat 'alayna, wa haqq er-Rabb yadoum ila el-abad, hallelouia.\n\nEl-magd lil-Ab wal-Ibn war-Rouh el-Qudus, el-an wa kull awan wa ila dahr ed-dohour, ameen, hallelouia hallelouia.\n\nEl-magd li-ilahina.\n\nEl-Kahin:\n\nAmeen, hallelouia. Ya Allah irhamna.\n\nEsh-Sha'b:\n\nYa Allah irhamna (2)." },
  ] },
  { id: "vp-watos-psali-after-the-friday-theotokion", title: "Watos Psali After the Friday Theotokion", versions: [
    { language: 'english', text: "Praise to God's name, I begin / Creator of everything / I praise Mary the Virgin / who was prophesied by all the fathers.\n\nBore the God of the living / You are worthy of praising / He is the King of all kings / I begin this praise in order.\n\nThe sayings, fulfilled truly / Mother of the Majesty / announcing this mystery / Gabriel, the Lord sent.\n\nHe came to you revering, / gave you peace by his coming / you became Jesus' dwelling / all observed this Advent\n\nThe Holy Spirit descended / and the Word was incarnate / more than all those created / in every generation\n\nThe Maker of humanity / fulfilled the economy / dwelt in the Virgin Mary / for Adam's salvation.\n\nAlways and everlasting / as human, was Your coming / and by the Spirit's dwelling / in Saint Mary, Aaron's censer.\n\nThe unseen Lord of glory / Being, from eternity / took for Himself a body / and became our Savior\n\nThe pride of virginity / the Mother of God, Mary / carried in a mystery / in her womb, the Holy One\n\nYou are the second heaven / who carried the hidden gem / you bore Him in Bethlehem / and the Virgin conceived a Son\n\nIn your arms, you carried Him / and you nourished and fed Him / from the east, they came for Him / and the Magi worshipped.\n\nA throne to your King, you were I you bore the divine Cluster / blessed are you O daughter / for Solomon was delighted.\n\nIncarnate humanity / while one of the Trinity / the Word, the Son, the Holy / carried in the temple by Simeon.\n\nA Mother to the Greatness / descendant of the righteous / your purity was spotless / O daughter of Zion.\n\nA wonderous mystery appeared / which perplexed all those revered / the wise brilliant admired / all were unable to explain.\n\nWonderful is God's wisdom / none could gather or fathom / He made Mary like heaven / and hid His nature from Satan.\n\nSave us O Mother of Light / from all sadness and all plight / David mentioned you with might / in the holy Scriptures.\n\nMore blessed than all creation / and the angels of Heaven / He who came will come again / with saints and apostles.\n\nFor they called you Moses' dome / a second heaven, a home / the beautiful and awesome / exalted by all the faithful.\n\nAll things were fulfilled, truly / concerning the mystery / through you, we have become free / rejoicing and joyful.\n\nParadise opened once more / and those tormented before / Adam and all those he bore / were granted all jubilation.\n\nMary bore Jesus, the Lord / Christ the Son of God, the Word / whom all the angels adored restored all creation.\n\nWe believe and are revived / God incarnate, glorified / and by John He was baptized / the Father and the Spirit witnessed.\n\nChrist our God fasted for us / God incarnate, mysterious / He was nailed upon the cross / freeing all the oppressed.\n\nTo the Father, Almighty / He gave Himself up freely / and they buried His body / yet He rose from the dead\n\nHuman and divine union / He ascended to heaven / His body is communion / on the right hand, He is seated\n\nDo not forget Your faithful / O omiscient, powerful / You are good and merciful / grant us faith without strife\n\nRaise the state of the Christian / annointed by the Chrism / You who saved Adam's children and restored them to life.\n\nYou saved Noah's family / from the great calamity / keep the Church open fully / and bless our faithful priests.\n\nAnd all of Stephen's orders / deacons and faithful brothers / I ask of You, Lord of Powers / save them from evil beasts.\n\nO Lady of purity / keep me from authority / my works and deeds condemn me / please hear my petitions.\n\nFor I am chief of sinners / and my sins grow in numbers / O Mother of all mothers / forgive my transgressions.\n\nI ask of her with these rhymes / to intercede at all times / hear our worship with these lines / for all of Christ's people.\n\nI ask You, please be patient / Jesus, the omnipotent / with those present and absent / men and women, all Your people." },
  ] },
  { id: "vp-adam-psali-for-coptic-new-year", title: "Ϯⲛⲁⲟⲩⲱϣⲧ ⲙ̀ⲙⲟⲕ (Adam Psali for Coptic New Year)", versions: [
    { language: 'coptic', text: "Ϯⲛⲁⲟⲩⲱϣⲧ ⲙ̀ⲙⲟⲕ: Ⲡⲁϭⲟⲓⲥ Ⲓⲏⲥⲟⲩⲥ Ⲡⲓⲭⲣⲓⲥⲧⲟⲥ: ⲡⲓⲱⲟⲩ ⲛⲁⲕ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ: ⲇⲟⲝⲁ ⲥⲓ ⲟ ⲑⲉⲟⲥ.\n\nϬⲓⲙⲱⲓⲧ ⲛⲏⲓ ⲁⲛⲟⲕ: ϧⲁ ⲡⲓⲉⲗⲁⲭⲓⲥⲧⲟⲥ: ⲡⲓⲱⲟⲩ ⲛⲁⲕ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ: ⲇⲟⲝⲁ ⲥⲓ ⲟ ⲑⲉⲟⲥ.\n\nϪⲟⲩϣⲧ ⲉ̀ϧⲣⲏⲓ ⲉ̀ϫⲱⲛ: ϧⲉⲛ ⲧⲉⲕⲙⲉⲧⲁⲅⲁⲑⲟⲛ: ⲡⲓⲱⲟⲩ ⲛⲁⲕ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ: ⲇⲟⲝⲁ ⲥⲓ ⲟ ⲑⲉⲟⲥ.\n\nϨⲏⲡⲡⲉ ϯⲛⲁⲥⲁϫⲓ: ⲉⲑⲃⲉ ⲡⲉⲕⲱⲟⲩ ϧⲉⲛ ⲡⲁⲗⲁⲥ: ⲡⲓⲱⲟⲩ ⲛⲁⲕ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ: ⲇⲟⲝⲁ ⲥⲓ ⲟ ⲑⲉⲟⲥ.\n\nϦⲱⲧⲉⲃ ⲛ̀ⲛⲁⲙⲉⲩⲓ: ⲉⲑⲙⲉϩ ⲛ̀ⲕⲁⲕⲱⲥ: ⲡⲓⲱⲟⲩ ⲛⲁⲕ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ: ⲇⲟⲝⲁ ⲥⲓ ⲟ ⲑⲉⲟⲥ.\n\nϤ̀ⲉⲙⲡ̀ϣⲁ ⲛ̀ϫⲉ ⲡⲓⲥ̀ⲙⲟⲩ: ⲛⲉⲙ ⲡⲓⲱⲟⲩ ⲛⲉⲙ ⲡⲓϩⲱⲥ: ⲡⲓⲱⲟⲩ ⲛⲁⲕ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ: ⲇⲟⲝⲁ ⲥⲓ ⲟ ⲑⲉⲟⲥ.\n\nϢⲱⲡⲓ ⲛⲏⲓ ⲛ̀ⲛⲟⲙϯ: ϧⲉⲛ ⲛⲁⲗⲟⲅⲓⲥⲙⲟⲥ: ⲡⲓⲱⲟⲩ ⲛⲁⲕ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ: ⲇⲟⲝⲁ ⲥⲓ ⲟ ⲑⲉⲟⲥ.\n\nⲰⲗⲓ ⲉ̀ⲃⲟⲗ ϩⲁⲣⲟⲛ: ⲛ̀ⲛⲓⲛⲟⲃⲓ ⲙ̀ⲡⲁⲑⲟⲥ: ⲡⲓⲱⲟⲩ ⲛⲁⲕ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ: ⲇⲟⲝⲁ ⲥⲓ ⲟ ⲑⲉⲟⲥ.\n\nⲮⲟⲗⲥⲉⲗ ⲛ̀ⲛⲉⲛⲡⲛⲉⲩⲙⲁ: ⲡ̀ⲉⲣⲟⲩⲟⲧ ⲙ̀ⲡⲉⲛⲗⲁⲥ: ⲡⲓⲱⲟⲩ ⲛⲁⲕ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ: ⲇⲟⲝⲁ ⲥⲓ ⲟ ⲑⲉⲟⲥ.\n\nⲬⲟⲩⲁⲃ ⲭⲟⲩⲁⲃ ⲭⲟⲩⲁⲃ: ⲡⲉⲕⲡⲛⲉⲩⲙⲁ ⲙ̀ⲡⲁⲛⲁⲅⲓⲁⲥ: ⲡⲓⲱⲟⲩ ⲛⲁⲕ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ: ⲇⲟⲝⲁ ⲥⲓ ⲟ ⲑⲉⲟⲥ.\n\nⲪⲛⲟⲩϯ ⲡⲓⲛⲁⲏⲧ: ⲟⲩⲟϩ ⲛ̀ⲁⲅⲁⲑⲟⲥ: ⲡⲓⲱⲟⲩ ⲛⲁⲕ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ: ⲇⲟⲝⲁ ⲥⲓ ⲟ ⲑⲉⲟⲥ.\n\nⲨⲡⲉⲣ ⲙ̀ⲡⲉⲕⲛⲁⲓ: ⲫⲛⲟⲩϯ ⲛ̀ⲧⲉ ⲡⲁⲟⲩϫⲁⲓ: ⲡⲓⲱⲟⲩ ⲛⲁⲕ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ: ⲇⲟⲝⲁ ⲥⲓ ⲟ ⲑⲉⲟⲥ.\n\nⲦⲉⲕⲙⲉⲧⲟⲩⲣⲟ ⲡⲉⲛⲛⲏⲃ: ⲁⲣⲓⲧⲉⲛ ⲛ̀ⲉⲙⲡ̀ϣⲁ ⲙ̀ⲙⲟⲥ: ⲡⲓⲱⲟⲩ ⲛⲁⲕ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ: ⲇⲟⲝⲁ ⲥⲓ ⲟ ⲑⲉⲟⲥ.\n\nⲤⲱⲧⲉⲙ ⲉ̀ⲡⲉⲛϣ̀ⲗⲏⲗ: ⲡⲉⲛⲟⲩⲣⲟ ⲡⲓⲭⲣⲓⲥⲧⲟⲥ: ⲡⲓⲱⲟⲩ ⲛⲁⲕ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ: ⲇⲟⲝⲁ ⲥⲓ ⲟ ⲑⲉⲟⲥ.\n\nⲢⲱⲓⲥ ⲉ̀ⲣⲟⲛ ⲡ⳪: ⲉ̀ⲃⲟⲗ ϧⲉⲛ ⲡⲓⲇⲓⲁⲃⲟⲗⲟⲥ: ⲡⲓⲱⲟⲩ ⲛⲁⲕ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ: ⲇⲟⲝⲁ ⲥⲓ ⲟ ⲑⲉⲟⲥ.\n\nⲠⲉⲕⲣⲁⲛ ϥⲥⲙⲁⲣⲱⲟⲩⲧ: ϧⲉⲛ ⲣⲱⲟⲩ ⲛ̀ⲛⲓⲡⲓⲥⲧⲟⲥ: ⲡⲓⲱⲟⲩ ⲛⲁⲕ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ: ⲇⲟⲝⲁ ⲥⲓ ⲟ ⲑⲉⲟⲥ.\n\nⲞⲩⲱⲟⲩ ⲛ̀ⲧⲉⲕⲙⲉⲑⲛⲟⲩϯ: ϯⲁⲧⲥⲁϫⲓ ⲙ̀ⲙⲟⲥ: ⲡⲓⲱⲟⲩ ⲛⲁⲕ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ: ⲇⲟⲝⲁ ⲥⲓ ⲟ ⲑⲉⲟⲥ.\n\nⲜⲱⲟⲩⲛ ⲛ̀ⲑⲟⲕ ⲡ⳪: ⲛ̀ⲧⲁⲙⲉⲧⲁⲥⲑⲉⲛⲏⲥ: ⲡⲓⲱⲟⲩ ⲛⲁⲕ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ: ⲇⲟⲝⲁ ⲥⲓ ⲟ ⲑⲉⲟⲥ.\n\nⲚⲁⲓ ⲛⲏⲓ ϧⲉⲛ ⲡⲉⲕⲛⲁⲓ: ⲱ ⲡⲓⲇⲏⲙⲓⲟⲩⲣⲅⲟⲥ: ⲡⲓⲱⲟⲩ ⲛⲁⲕ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ: ⲇⲟⲝⲁ ⲥⲓ ⲟ ⲑⲉⲟⲥ.\n\nⲘ̀ⲡⲉⲣⲉⲛⲧⲉⲛ ⲁ̀ⲛⲟⲛ: ⲉ̀ϧⲟⲩⲛ ⲉ̀ⲡⲓⲣⲁⲥⲙⲟⲥ: ⲡⲓⲱⲟⲩ ⲛⲁⲕ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ: ⲇⲟⲝⲁ ⲥⲓ ⲟ ⲑⲉⲟⲥ.\n\nⲖⲁⲥ ⲛⲓⲃⲉⲛ ⲥⲉϩⲱⲥ: ⲉ̀ⲡⲉⲕⲣⲁⲛ ⲛ̀ⲁⲗⲏⲑⲱⲥ: ⲡⲓⲱⲟⲩ ⲛⲁⲕ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ: ⲇⲟⲝⲁ ⲥⲓ ⲟ ⲑⲉⲟⲥ.\n\nⲔⲁⲧⲁ ⲧⲉⲕⲃⲟⲏⲑⲓⲁ: ⲧⲁϩⲟⲓ ϧⲉⲛ ⲟⲩⲓⲏⲥ: ⲡⲓⲱⲟⲩ ⲛⲁⲕ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ: ⲇⲟⲝⲁ ⲥⲓ ⲟ ⲑⲉⲟⲥ.\n\nⲒⲏⲥⲟⲩⲥ ⲡⲉ ⲧⲁϩⲉⲗⲡⲓⲥ: Ⲓⲏⲥⲟⲩⲥ ⲡⲉ ⲡⲁⲃⲟⲏⲑⲟⲥ: ⲡⲓⲱⲟⲩ ⲛⲁⲕ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ: ⲇⲟⲝⲁ ⲥⲓ ⲟ ⲑⲉⲟⲥ.\n\nⲐⲱⲕ ⲡⲉ ⲡⲓⲁ̀ⲙⲁϩⲓ: ϣⲁ ⲡϫⲱⲕ ⲛ̀ⲛⲓⲭⲣⲟⲛⲟⲥ: ⲡⲓⲱⲟⲩ ⲛⲁⲕ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ: ⲇⲟⲝⲁ ⲥⲓ ⲟ ⲑⲉⲟⲥ.\n\nⲎⲡⲡⲉ ϯⲛⲁⲥ̀ⲙⲟⲩ ⲉ̀ⲣⲟⲕ: ⲱ̀ ⲩⲓⲟⲥ ⲑⲉⲟⲥ: ⲡⲓⲱⲟⲩ ⲛⲁⲕ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ: ⲇⲟⲝⲁ ⲥⲓ ⲟ ⲑⲉⲟⲥ.\n\nⲌⲉⲟϣ ⲛⲉⲕⲛⲁⲓ: ⲱ̀ ⲡⲓⲁⲓⲇⲓⲟⲥ: ⲡⲓⲱⲟⲩ ⲛⲁⲕ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ: ⲇⲟⲝⲁ ⲥⲓ ⲟ ⲑⲉⲟⲥ.\n\nⲈ̀ⲣⲉ ⲡⲓⲧⲁⲓⲟ: ⲉⲣⲡⲉⲣⲡⲓ ⲛ̀ⲑⲉⲟⲥ: ⲡⲓⲱⲟⲩ ⲛⲁⲕ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ: ⲇⲟⲝⲁ ⲥⲓ ⲟ ⲑⲉⲟⲥ.\n\nⲆⲉⲥⲡⲟⲧⲁ ⲛⲁⲓ ⲛⲏⲓ: ⲱ̀ ⲡⲓⲁⲓⲇⲓⲟⲥ: ⲡⲓⲱⲟⲩ ⲛⲁⲕ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ: ⲇⲟⲝⲁ ⲥⲓ ⲟ ⲑⲉⲟⲥ.\n\nⲄⲉ ⲅⲁⲣ ⲛ̀ⲑⲟⲕ ⲡ⳪: ⲡⲟⲩⲣⲟ ⲛ̀ⲛⲓⲇⲓⲕⲉⲟⲥ: ⲡⲓⲱⲟⲩ ⲛⲁⲕ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ: ⲇⲟⲝⲁ ⲥⲓ ⲟ ⲑⲉⲟⲥ.\n\nⲂⲟⲏⲑⲓⲁ ⲅⲁⲣ ⲛⲓⲃⲉⲛ: ⲥⲉ ⲉ̀ⲃⲟⲗ ϩⲓⲧⲉⲛ ⲑⲉⲟⲥ: ⲡⲓⲱⲟⲩ ⲛⲁⲕ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ: ⲇⲟⲝⲁ ⲥⲓ ⲟ ⲑⲉⲟⲥ.\n\nⲀⲓⲙⲉⲛⲣⲉ ⲡⲉⲕϩⲟ: ϫⲟⲕⲧⲉⲛ ⲉ̀ⲃⲟⲗ ⲕⲁⲗⲱⲥ: ⲡⲓⲱⲟⲩ ⲛⲁⲕ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ: ⲇⲟⲝⲁ ⲥⲓ ⲟ ⲑⲉⲟⲥ." },
    { language: 'english', text: "I will worship You, / O my Lord Jesus Christ. / Glory be to You, alleluia. / Glory be to God.\n\nLead me O Lord, / I the poor. / Glory be to You, alleluia. / Glory be to God.\n\nLook upon us / with Your goodness. / Glory be to You, alleluia. / Glory be to God.\n\nBehold, I will declare / Your glory with my tongue. / Glory be to You, alleluia. / Glory be to God.\n\nSlay in me, / the thoughts full of evil. / Glory be to You, alleluia. / Glory be to God.\n\nYou are worthy of blessing, / glory and praise. / Glory be to You, alleluia. / Glory be to God.\n\nBe a comfort for me / in my thoughts. / Glory be to You, alleluia. / Glory be to God.\n\nTake away from us, / the sins of the passions / Glory be to You, alleluia. / Glory be to God.\n\nThe adornment of our spirits / and the joy of our tongue. / Glory be to You, alleluia. / Glory be to God.\n\nHoly, holy, holy, / Your all-holy Spirit. / Glory be to You, alleluia. / Glory be to God.\n\nO God the Merciful / and the Good One. / Glory be to You, alleluia. / Glory be to God.\n\nFor the sake of Your mercy, / O God of my salvation. / Glory be to You, alleluia. / Glory be to God.\n\nMake us worthy, O our Master, / of Your kingdom. / Glory be to You, alleluia. / Glory be to God.\n\nHear our prayer / O Christ our King. / Glory be to You, alleluia. / Glory be to God.\n\nGuard us O Lord / from the Devil. / Glory be to You, alleluia. / Glory be to God.\n\nYour name is blessed / on the mouths of the faithful. / Glory be to You, alleluia. / Glory be to God.\n\nGlory to Your / ineffable Divinity / Glory be to You, alleluia. / Glory be to God.\n\nYou O Lord know / my weakness. / Glory be to You, alleluia. / Glory be to God.\n\nIn Your mercy, O Creator, / have mercy on me. / Glory be to You, alleluia. / Glory be to God.\n\nLead us not / into temptation. / Glory be to You, alleluia. / Glory be to God.\n\nTruly, every tongue / praises Your name. / Glory be to You, alleluia. / Glory be to God.\n\nLet Your help / come speedily to me. / Glory be to You, alleluia. / Glory be to God.\n\nJesus is my hope; / Jesus is my help. / Glory be to You, alleluia. / Glory be to God.\n\nYours is the might / to the end of time. / Glory be to You, alleluia. / Glory be to God.\n\nBehold, I will bless You, / O Son of God. / Glory be to You, alleluia. / Glory be to God.\n\nPlenteous are Your mercies, / O Eternal One. / Glory be to You, alleluia. / Glory be to God.\n\nBehold, the honor / befits God. / Glory be to You, alleluia. / Glory be to God.\n\nO Master have mercy on me, / O Eternal One. / Glory be to You, alleluia. / Glory be to God.\n\nFor You are, O Lord, / the King of the righteous. / Glory be to You, alleluia. / Glory be to God.\n\nFor every help / comes from God. / Glory be to You, alleluia. / Glory be to God.\n\nI love Your face; / make us all perfect. / Glory be to You, alleluia. / Glory be to God." },
    { language: 'arabic', text: "أسجد لك، يا ربي يسوع المسيح، المجد لك هلليلويا، المجد لك يا الله.\n\nأهديني، أنا الحقير، المجد لك هلليلويا، المجد لك يا الله.\n\nإطلع علينا، بصلاحك، المجد لك هلليلويا، المجد لك يا الله.\n\nهأنذا إنطق بلساني، من أجل مجدك، المجد لك هلليلويا، المجد لك يا الله.\n\nإقتل أفكاري، المملوءة شراً، المجد لك هلليلويا، المجد لك يا الله.\n\nتليق بك البركة، والمجد والتسبيح، المجد لك هلليلويا، المجد لك يا الله.\n\nكن لي معزياً، في حواسي، المجد لك هلليلويا، المجد لك يا الله.\n\nإنزع عنا، آلام الخطايا، المجد لك هلليلويا، المجد لك يا الله.\n\nعزاء أرواحنا، وفرح لساننا، المجد لك هلليلويا، المجد لك يا الله.\n\nقدوس قدوس قدوس، روحك الكلي القدوس، المجد لك هلليلويا، المجد لك يا الله.\n\nيا الله الرحوم، والصالح، المجد لك هلليلويا، المجد لك يا الله.\n\nمن أجل رحمتك، يا إله خلاصي، المجد لك هلليلويا، المجد لك يا الله.\n\nأجعلنا مستحقين، ملكوتك يا سيدنا، المجد لك هلليلويا، المجد لك يا الله.\n\nيا ملكنا المسيح، إسمع صلاتنا، المجد لك هلليلويا، المجد لك يا الله.\n\nاحرسنا يا رب، من إبليس، المجد لك هلليلويا، المجد لك يا الله.\n\nإسمك مبارك، في أفواه المؤمنين، المجد لك هلليلويا، المجد لك يا الله.\n\nالمجد للاهوتك، الذي لا يُنطق به، المجد لك هلليلويا، المجد لك يا الله.\n\nأنت يا رب، تعرف ضعفي، المجد لك هلليلويا، المجد لك يا الله.\n\nإرحمني برحمتك، أيها الخالق، المجد لك هلليلويا، المجد لك يا الله.\n\nلا تدخلنا نحن، في تجربة، المجد لك هلليلويا، المجد لك يا الله.\n\nكل لسان يسبح، إسمك بالحقيقة، المجد لك هلليلويا، المجد لك يا الله.\n\nإدركني سريعاً، بمعونتك، المجد لك هلليلويا، المجد لك يا الله.\n\nيسوع هو رجائي، يسوع هو معيني، المجد لك هلليلويا، المجد لك يا الله.\n\nلك العزة، إلى كمال الأزمنة، المجد لك هلليلويا، المجد لك يا الله.\n\nهأنذا أباركك، يا إبن الله، المجد لك هلليلويا، المجد لك يا الله.\n\nمراحمك كثيرة، أيها الذاتي، المجد لك هلليلويا، المجد لك يا الله.\n\nالكرامة، تليق بالله، المجد لك هلليلويا، المجد لك يا الله.\n\nيا سيد إرحمني، أيها الذاتي، المجد لك هلليلويا، المجد لك يا الله.\n\nلأنك أنت يا رب، ملك الصديقين، المجد لك هلليلويا، المجد لك يا الله.\n\nلأن كل معونة، هي من قِبَل الله، المجد لك هلليلويا، المجد لك يا الله.\n\nأحببت وجهك، كملنا حسنًا، المجد لك هلليلويا، المجد لك يا الله." },
    { language: 'englishArabic', text: "Asgudu lak, ya Rabbi Yasou' el-Maseeh, el-magd lak hallelouia, el-magd lak ya Allah.\n\nIhdini, ana el-haqeer, el-magd lak hallelouia, el-magd lak ya Allah.\n\nIttali' 'alayna, bi-salahak, el-magd lak hallelouia, el-magd lak ya Allah.\n\nHa-anadha antiqu bi-lisani, min agl magdak, el-magd lak hallelouia, el-magd lak ya Allah.\n\nUqtul afkari, el-mamlou'a sharran, el-magd lak hallelouia, el-magd lak ya Allah.\n\nTaleequ bika el-baraka, wal-magd wat-tasbeeh, el-magd lak hallelouia, el-magd lak ya Allah.\n\nKun li mu'azziyan, fi hawassi, el-magd lak hallelouia, el-magd lak ya Allah.\n\nInza' 'anna, alam el-khataya, el-magd lak hallelouia, el-magd lak ya Allah.\n\n'Aza' arwahina, wa farah lisanina, el-magd lak hallelouia, el-magd lak ya Allah.\n\nQuddous quddous quddous, rouhuka el-kulli el-quddous, el-magd lak hallelouia, el-magd lak ya Allah.\n\nYa Allah er-rahoum, was-salih, el-magd lak hallelouia, el-magd lak ya Allah.\n\nMin agl rahmatik, ya ilah khalasi, el-magd lak hallelouia, el-magd lak ya Allah.\n\nIg'alna mustahiqqeen, malakoutak ya sayyidana, el-magd lak hallelouia, el-magd lak ya Allah.\n\nYa malikana el-Maseeh, isma' salatana, el-magd lak hallelouia, el-magd lak ya Allah.\n\nIhrusna ya Rabb, min Iblees, el-magd lak hallelouia, el-magd lak ya Allah.\n\nIsmuka mubarak, fi afwah el-mu'mineen, el-magd lak hallelouia, el-magd lak ya Allah.\n\nEl-magd li-lahoutik, alladhi la yuntaqu bih, el-magd lak hallelouia, el-magd lak ya Allah.\n\nAnta ya Rabb, ta'rif da'fi, el-magd lak hallelouia, el-magd lak ya Allah.\n\nIrhamni bi-rahmatik, ayyuha el-khaliq, el-magd lak hallelouia, el-magd lak ya Allah.\n\nLa tudkhilna nahnu, fi tagriba, el-magd lak hallelouia, el-magd lak ya Allah.\n\nKull lisan yusabbih, ismak bil-haqeeqa, el-magd lak hallelouia, el-magd lak ya Allah.\n\nAdrikni saree'an, bi-ma'ounatik, el-magd lak hallelouia, el-magd lak ya Allah.\n\nYasou' huwa raga'i, Yasou' huwa mu'eeni, el-magd lak hallelouia, el-magd lak ya Allah.\n\nLaka el-'izza, ila kamal el-azmina, el-magd lak hallelouia, el-magd lak ya Allah.\n\nHa-anadha ubarikuk, ya Ibn Allah, el-magd lak hallelouia, el-magd lak ya Allah.\n\nMarahimuka katheera, ayyuha edh-dhati, el-magd lak hallelouia, el-magd lak ya Allah.\n\nEl-karama, taleequ billah, el-magd lak hallelouia, el-magd lak ya Allah.\n\nYa sayyid irhamni, ayyuha edh-dhati, el-magd lak hallelouia, el-magd lak ya Allah.\n\nLi-annaka anta ya Rabb, malik es-siddeeqeen, el-magd lak hallelouia, el-magd lak ya Allah.\n\nLi-anna kull ma'ouna, hiya min qibal Allah, el-magd lak hallelouia, el-magd lak ya Allah.\n\nAhbabtu wagh-hak, kammalna hasanan, el-magd lak hallelouia, el-magd lak ya Allah." },
  ] },
  { id: "vp-the-first-greek-interpretation", title: "The First Greek Interpretation", versions: [
    { language: 'coptic', text: "Ⲥⲩⲛⲇⲟⲝⲁⲥⲑⲱⲙⲉⲛ ⲏ̀ⲙⲉⲣⲁⲛ: ⲉⲑⲃⲏϯ ⲱ̀ ϯⲡⲣⲟⲥⲧⲁ̀ⲥⲓⲁ̀: ⲁⲛϣⲁⲛⲉⲣⲫⲙⲉⲩⲓ̀ ⲙ̀ⲡⲉⲣⲁⲛ: ⲩ̀ⲙⲛⲟⲩⲙⲉⲛ ⲥⲉ ⲁ̀ⲇⲓⲭⲟⲥⲧⲁⲥⲓⲁ̀.\n\nⲀⲥⲡⲓⲗⲉ ⲕⲉ ⲁ̀ⲅⲓⲱⲧⲉ̀ⲣⲁ: ⲡⲁⲥⲏⲥ ⲕ̀ⲧⲏ̀ⲥⲉⲱⲥ ⲇⲓⲁ̀ⲡⲁⲛⲧⲟ̀ⲥ: ⲕⲉ ⲏ̀ ⲕⲟ̀ⲣⲏ ⲁ̀ⲗⲏⲑⲉⲥⲧⲉ̀ⲣⲁ: ϫⲉ Ⲡϣⲏⲣⲓ ⲙ̀Ⲫϯ ⲁ̀ⲙⲓ̀ⲁⲛⲧⲟⲥ.\n\nⲢⲱⲙⲁⲗⲉ̀ⲟⲥ ⲡⲟⲗⲩⲉ̀ⲗⲉⲟⲥ: ⲁϥⲓ̀ ϣⲁⲣⲟⲛ ⲥⲉⲥⲁⲣⲕⲱⲙⲉ̀ⲛⲟⲥ: ⲉ̀ⲃⲟⲗϧⲉⲛ ⲧⲉⲙⲟⲩⲙⲓ ⲉⲩⲕ̀ⲗⲉⲟⲥ: ⲉⲛ ⲙⲩⲥⲧⲏⲣⲓⲟⲛ ⲑⲁⲩⲙⲁ̀ⲝⲉⲛⲟⲛ.\n\nⲔⲉ ⲇⲓ ⲁⲩⲧⲟⲩ ⲁ̀ⲛⲟⲛ ⲩ̀ⲙⲛⲟⲩⲙⲉⲛ: ⲉⲛ ⲥ̀ⲧⲓⲭⲉⲣⲁ ⲕⲉ ⲁⲛⲧⲓ̀ⲫⲱⲛⲟⲛ: ⲕⲉ ⲇⲓⲁ̀ⲥⲟⲩ ⲉ̀ⲡⲉⲛⲟⲩⲙⲉⲛ: ⲓ̀ⲡⲱⲙⲉⲛ ⲇⲉ ⲉ̀ⲡⲓ̀ⲫⲁⲛⲟⲛ.\n\nⲒⲥ ⲡ̀ϣⲏⲣⲓ ⲛ̀ⲗⲟⲅⲟⲥ ⲉⲑⲣⲱⲧⲉⲃ: ϧⲉⲛ ⲕⲉⲛϥ ⲙ̀ⲡⲉϥⲓⲱⲧ ⲉⲧⲁⲥⲁⲡ̀ϣⲱⲓ: ⲛ̀ⲁⲣⲭⲏ ⲛⲓⲃⲉⲛ ⲱ̀ ϯⲁⲧⲑⲱⲗⲉⲃ: ⲁ̀ⲣⲉⲉⲛϥ ⲉϥⲧⲁⲗⲏⲟⲩⲧ ⲉ̀ϫⲉⲛ ⲛⲉϫ̀ⲫⲟⲓ.\n\nⲤⲉⲣⲁϣⲓ ⲛⲉⲙⲉ ⲛ̀ϫⲉ ϯⲟⲓⲕⲟⲩⲙⲉⲛⲏ: ⲛⲉⲙ ⲛⲏⲉⲧϣⲟⲡ ⲛ̀ϧⲏⲧⲥ ⲉⲩⲥⲟⲡ: ϫⲉ ⲭⲉⲣⲉ ⲕⲉ ⲭⲁⲣⲓⲧⲱⲙⲉ̀ⲛⲏ: Ⲡⲟ︦ⲥ︦ ⲛⲉⲙⲉ ⲱ̀ ⲑⲏⲉ︦ⲑ︦ⲩ︦.\n\nⲦⲉⲛϯⲱ̀ⲟⲩ ⲛⲉ ⲱ̀ ⲑⲏⲉⲧⲥⲙⲁⲙⲁⲧ: ϣⲁ ⲡⲓⲛⲓϥⲓ ⲛ̀ⲧⲉ ⲗⲉⲩⲧⲉⲟⲥ: ϫⲉ ⲁⲣⲉϫⲓⲙⲓ ⲅⲁⲣ ⲛ̀ⲟⲩϩ̀ⲙⲟⲧ: ϧⲁⲧⲉⲛ Ⲡⲉⲛⲟⲩϯ Ⲩⲓⲟⲥ Ⲑⲉⲟⲥ." },
    { language: 'english', text: "Today we glorify, because of you O intercessor, when we remembered your name, praising you with accord.\n\nO Pure one holier than all the creation, and all their kinds, and the truly young girl, for the Son of God is far above.\n\nThe strong the merciful One, came to us incarnated, from the proud fountain, by a wondrous and strange mystery.\n\nAnd because of Him we praise, with songs and great joy, and because of you we praise, and proclaim saying:\n\nBehold the Son the Word, who abides in the bosom of His Father, who is above all principalities, O undefiled you carried Him in your arms.\n\nThe creation rejoices with you, and all those who dwell therein, saying \"Rejoice O full of grace, the Lord is with you O holy one.\"\n\nWe glorify you O blessed one, until the last breath saying, \"You have found favor before, your God the Son of God.\"" },
    { language: 'arabic', text: "نتمجد في هذا اليوم من أجلك أيتها الشفيعة إذا ما ذكرنا أسمك مسبحين إياك باتفاق.\n\nيا طاهرة واقدس من كل الخليقة بأسرها وفتاة حقيقية لأن ابن الله المنزه.\n\nالقوى الكثير الرحمة أتي إلينا متجسداً من ينبوعك الفاخر بسر عجيب غريب.\n\nفمن أجله نحن نسبح بترنيم وتهليل ومن أجلك نمدح ونقول جهراً.\n\nختامها هوذا الابن الكلمة المتكئ في حضن ابيه الذي هو فوق كل رئاسة أيتها غير الدنسة حملته راكباً على ذراعيك.\n\nتفرح معك المسكونة وسكانها معاً قائلين افرحي يا ممتلئة نعمة الرب معك أيتها الطاهرة.\n\nقرارنمجدك ايتها المباركة إلى النفس الأخير لأنك وجدت نعمة عند إلهك ابن الله." },
    { language: 'englishArabic', text: "Natamaggad fi hadha el-yawm min aglik ayyatuha esh-shafee'a idha ma dhakarna ismik musabbiheen iyyaki bi-ittifaq.\n\nYa tahira wa aqdas min kull el-khaleeqa bi-asriha wa fatat haqeeqiyya li-anna Ibn Allah el-munazzah.\n\nEl-qawiyy el-katheer er-rahma ata ilayna mutagassidan min yanbou'ik el-fakhir bi-sirr 'ageeb ghareeb.\n\nFa-min aglihi nahnu nusabbih bi-tarneem wa tahleel wa min aglik namdah wa naqoul gahran.\n\nKhitamuha: hawadha el-Ibn el-Kalima el-muttaki' fi hudn abeeh alladhi huwa fawq kull ri'asa, ayyatuha ghayr ed-danisa hamaltihi rakiban 'ala dhira'ayki.\n\nTafrah ma'aki el-maskouna wa sukkanuha ma'an qa'ileen: ifrahi ya mumtali'a ni'ma er-Rabb ma'aki ayyatuha et-tahira.\n\nQarar: numaggiduki ayyatuha el-mubaraka ila en-nafas el-akheer li-annaki wagadti ni'ma 'ind ilahik Ibn Allah." },
  ] },
  { id: "vp-the-first-bohairic-interpretation-a", title: "The First Bohairic Interpretation A", versions: [
    { language: 'coptic', text: "Ⲓⲥϫⲉⲛ ϣⲱⲣⲡ ϣⲁ ⲣⲟⲩϩⲓ ⲙ̀ⲙⲏⲛⲓ: ⲧⲉⲛⲟⲩⲱϣⲧ ⲛ̀ϯⲧⲣⲓⲁⲥ ⲉ︦ⲑ︦ⲩ︦: Ⲡⲉⲛⲛⲟⲩϯ ⲛ̀ⲟⲩⲱⲧ ⲉ̀ⲧⲉϩⲉⲙⲓ: Ⲫⲓⲱⲧ ⲛⲉⲙ Ⲡϣⲏⲣⲓ ⲛⲉⲙ Ⲡⲓⲡ︦ⲛ︦ⲁ︦ ⲉ︦ⲑ︦ⲩ︦.\n\nⲠⲁⲗⲓⲛ ⲟⲛ ⲧⲉⲛϯⲱⲟⲩ ⲛⲉ: ⲱ̀ ϯⲁⲧⲑⲱⲗⲉⲃ ⲛ̀ⲥⲉⲙⲛⲏ: Ⲙⲁⲣⲓⲁ ϯⲟⲩⲣⲱ ⲛ̀ⲁⲗⲏⲑⲓⲛⲉ: ⲙⲁϩⲥ̀ⲛⲟⲩϯ ⲛ̀ⲥⲕⲩⲛⲏ.\n\nⲤⲉⲣⲁϣⲓ ⲛⲉⲙⲉ ⲛ̀ϫⲉ ϯⲟⲓⲕⲟⲩⲙⲉⲛⲏ: ⲛⲉⲙ ⲛⲏ ⲧⲏⲣⲟⲩ ⲉⲧϣⲟⲡ ⲛ̀ϧⲏⲧⲥ: ϫⲉ ⲭⲉⲣⲉ ⲕⲉ ⲭⲁⲣⲓⲧⲱⲙⲉⲛⲏ: ⲉⲧⲁ Ⲡⲭ︦ⲥ︦ ϭⲓⲥⲁⲣⲝ ⲛ̀ϧⲏⲧⲥ.\n\nⲦⲉⲛϯⲱⲟⲩ ⲛⲉ ⲱ̀ ⲑⲏⲉ̀ⲧⲉⲛϩⲟⲧ: ⲛⲉⲙ ⲡⲓⲁⲅⲅⲉⲗⲟⲥ ⲛ̀ⲧⲉ ⲡⲓⲥ̀ⲙⲟⲩ: ϫⲉ ⲭⲉⲣⲉ ⲕⲉ ⲭⲁⲣⲓⲧⲱⲙⲉⲛⲏ ⲱ̀ ⲑⲏⲉⲑⲙⲉϩ ⲛ̀ϩⲙⲟⲧ: ⲟⲩⲟϩ Ⲡⲟ︦ⲥ︦ ϣⲟⲡ ⲛⲉⲙⲉ." },
    { language: 'english', text: "Morning and night everyday, we worship the holy Trinity, our one God the Almighty, the Father the Son and the Holy Spirit.\n\nAnd we also glorify you, O chaste and undefiled, Mary the true Queen, the second tabernacle.\n\nThe whole world rejoice with you, and all its inhabitants saying, \"Hail to you O full of grace,\" of whom Christ was incarnate.\n\nWe glorify you O trusted one, with the angel of blessing saying, \"Hail to you O full of grace, the Lord is with you.\"" },
    { language: 'arabic', text: "من الصباح إلى المساء كل يوم نسجد للثالوث الأقدس. إلهنا الواحد المدبر الآب والابن والروح القدس.\n\nوأيضاً نمجدك أيتها غير الدنسة الهادئة. مريم الملكة الحقيقية القبة الثانية.\n\nتفرح معك كل المسكونة وكل سكانها قائلين افرحي يا ممتلئة نعمة التي تجسد منها المسيح.\n\nنمجدك أيتها الأمينة قائلين مع ملاك البركة أفرحي أيتها الممتلئة نعمة . الرب معك." },
    { language: 'englishArabic', text: "Min es-sabah ila el-masa' kull yawm nasgudu lith-thalouth el-aqdas. Ilahuna el-wahid el-mudabbir el-Ab wal-Ibn war-Rouh el-Qudus.\n\nWa aydan numaggiduki ayyatuha ghayr ed-danisa el-hadi'a. Maryam el-malika el-haqeeqiyya el-qubba eth-thaniya.\n\nTafrah ma'aki kull el-maskouna wa kull sukkaniha qa'ileen: ifrahi ya mumtali'a ni'ma allati tagassada minha el-Maseeh.\n\nNumaggiduki ayyatuha el-ameena qa'ileen ma'a malak el-baraka: ifrahi ayyatuha el-mumtali'a ni'ma, er-Rabb ma'aki." },
  ] },
  { id: "vp-the-first-bohairic-interpretation-b", title: "The First Bohairic Interpretation B", versions: [
    { language: 'coptic', text: "Ⲁⲣⲓⲟⲩⲱⲓⲛⲓ ⲉ̀ⲣⲟⲓ Ⲫϯ: ϧⲉⲛ ⲫ̀ⲟⲩⲱⲓⲛⲓ ⲛ̀ⲧⲉ ⲧⲉⲕⲙⲉⲑⲛⲟⲩϯ: ⲛ̀ⲧⲁϯⲧⲁⲓⲟ ⲛ̀ϯⲙⲁⲥⲛⲟⲩϯ: ϯⲁⲧⲑⲱⲗⲉⲃ ⲛ̀ⲥⲉⲙⲛⲏ.\n\nϮϣⲉⲗⲉⲧ ⲛ̀ⲕⲁⲑⲁⲣⲟⲥ: ϯϩⲓⲉⲃⲓ ⲛ̀ⲉⲑⲛⲉⲥⲱⲥ: ϯⲡⲁⲛⲁ̀ⲅⲓⲁ̀ ⲙ̀ⲡⲁⲣⲑⲉⲛⲟⲥ: Ⲙⲁⲣⲓⲁ ⲧ̀ϣⲉⲣⲓ ⲛ̀Ⲓⲱⲁ̀ⲕⲓⲙ.\n\nⲐⲏⲉ̀ⲧⲁⲥⲙⲓⲥⲓ ⲛ̀ⲧⲁⲫ̀ⲙⲏⲓ: Ⲓⲏ︦ⲥ︦ ⲡⲓⲗⲟⲅⲟⲥ ⲙ̀ⲙⲏⲓ: ⲉϥⲧⲁⲗⲏⲟⲩⲧ ⲉ̀ϫⲉⲛ ⲛⲉⲥϫ̀ⲫⲟⲓ: ϫⲉ ⲛ̀ⲑⲟϥ ϧⲉⲛ ⲟⲩⲙⲉⲑⲙⲏⲓ.\n\nⲘⲁⲣⲉⲛϯⲱ̀ⲟⲩ ⲛ̀ϯⲁ̀ⲅⲓⲁ̀: ϧⲉⲛ ϩⲁⲛⲥ̀ⲙⲏ ⲛ̀ⲇⲟⲝⲟⲗⲟⲅⲓⲁ̀: ϫⲉ ⲭⲉⲣⲉ ⲣⲁϣⲓ ⲱ̀ Ⲙⲁⲣⲓⲁ: ⲟ̀ Ⲕⲩⲣⲓⲟⲥ ⲙⲉⲧⲁ ⲥⲟⲩ." },
    { language: 'english', text: "Enlighten me O God, with the light of Your divinity, that I may honor the Mother of God, the chaste and undefiled.\n\nThe pure bride, the beautiful lamb, the all-holy Virgin, Mary the daughter of Joachim.\n\nWho truly gave birth to, Jesus the true Logos, and carried Him upon her arms, for it is truly He.\n\nLet us glorify the saint, in voice of glorification saying, \"Hail to you rejoice O Mary, the Lord is with you.\"" },
    { language: 'arabic', text: "انرني يا الله بنور لاهوتك. لأكرم والدة الإله غير الدنسة الهادئة.\n\nالعروسة النقية النعجة الحسنة العذراء القديسة مريم إبنة يواقيم.\n\nالتي ولدت بالحقيقة يسوع الكلمة الحقيقي وحملته على ذراعيها لأنه هو بالحقيقة.\n\nفلنمجد القديسة بأصوات التمجيد قائلين السلام أفرحي يا مريم الرب معك." },
    { language: 'englishArabic', text: "Anirni ya Allah bi-nour lahoutik, li-ukrim walidat el-Ilah ghayr ed-danisa el-hadi'a.\n\nEl-'arousa en-naqiyya en-na'ga el-hasana el-'Adhra' el-qiddeesa Maryam ibnat Yowakeem.\n\nAllati waladat bil-haqeeqa Yasou' el-Kalima el-haqeeqi wa hamalathu 'ala dhira'ayha li-annahu huwa bil-haqeeqa.\n\nFal-numaggid el-qiddeesa bi-aswat et-tamgeed qa'ileen: es-salam, ifrahi ya Maryam er-Rabb ma'aki." },
  ] },
  { id: "vp-the-first-coptic-mo-aqap-interpretation", title: "The First Coptic Mo-‘aqap Interpretation", versions: [
    { language: 'coptic', text: "Ⲁⲓⲛⲁϩⲱⲥ ⲛⲁⲕ Ⲡⲟ︦ⲥ︦ ⲛ̀ⲟⲩⲛⲁⲓ: ⲁⲓⲛⲁⲕⲱϯ ⲛ̀ⲥⲁ ⲡⲉⲕⲟⲩϫⲁⲓ: ⲙⲁⲕⲁϯ ⲛⲏⲓ ⲕⲁⲧⲁ ⲡⲉⲕⲛⲁⲓ: ⲭⲱ ⲛⲏⲓ ⲉ̀ⲃⲟⲗ ⲛ̀ⲧⲁⲙⲉⲧⲁⲧϩⲏⲧ.\n\nⲬⲱ ⲛⲏⲓ ⲉ̀ⲃⲟⲗ ⲛ̀ⲧⲁⲙⲉⲧⲁⲧϩⲏⲧ: ⲁ̀ⲣⲓⲟⲩⲱⲓⲛⲓ ⲙ̀ⲡⲁϩⲏⲧ: ⲉⲑⲣⲓϫⲱ ⲙ̀ⲡ̀ⲧⲁⲓⲟ ⲛ̀ⲧⲉ ⲧⲁⲓϣⲉⲗⲉⲧ: ϯⲁⲧⲑⲱⲗⲉⲃ ⲛ̀ⲥⲉⲙⲛⲏ.\n\nϮⲁⲧⲑⲱⲗⲉⲃ ⲛ̀ⲥⲉⲙⲛⲏ: ϯⲟⲩⲣⲱ ⲛ̀ⲁ̀ⲗⲏⲑⲓⲛⲏ: ⲑⲁ ϯⲛⲓϣϯ ⲛ̀ⲧⲓⲙⲏ: ϯⲡⲁⲣⲑⲉⲛⲟⲥ ⲙ̀ⲙⲁⲥⲛⲟⲩϯ.\n\nϮⲡⲁⲣⲑⲉⲛⲟⲥ ⲙ̀ⲙⲁⲥⲛⲟⲩϯ: ⲑⲏⲉⲧⲁⲥⲓ̀ⲛⲓ ⲛⲁⲛ ⲙ̀Ⲫϯ: ⲉϥⲧⲁⲗⲏⲟⲩⲧ ⲉ̀ϫⲉⲛ ⲛⲉⲥⲙⲟϯ: ⲕⲁⲧⲁ ⲧⲉϥⲙⲉⲧⲟⲓⲕⲟⲛⲟⲙⲓⲁ.\n\nⲔⲁⲧⲁ ⲧⲉϥⲙⲉⲧⲟⲓⲕⲟⲛⲟⲙⲓⲁ: ⲛⲉⲙ ⲧⲉϥⲙⲉⲧⲛⲓϣϯ ⲛ̀ⲥⲟⲫⲓⲁ: ⲁⲥϥⲁⲓ ϧⲁⲣⲟϥ ⲛ̀ϫⲉ Ⲙⲁⲣⲓⲁ: ⲟⲩⲇⲉ ⲙ̀ⲡⲉϥⲥⲉⲛ ⲡⲉϥⲑ̀ⲣⲟⲛⲟⲥ.\n\nⲞⲩⲇⲉ ⲙ̀ⲡⲉϥⲥⲉⲛ ⲡⲉϥⲑ̀ⲣⲟⲛⲟⲥ: ⲥⲁⲡ̀ϣⲱⲓ ⲛ̀ⲛⲓⲁⲅⲅⲉⲗⲟⲥ: ⲉϥⲭⲏ ϧⲉⲛ ⲑ̀ⲛⲉϫⲓ ⲛ̀ϯⲡⲁⲣⲑⲉⲛⲟⲥ: ⲟⲩ ⲡⲉ ⲡⲁⲓϩⲱⲃ ⲉⲧⲟⲓ ⲛ̀ϣ̀ⲫⲏⲣⲓ.\n\nⲞⲩ ⲡⲉ ⲡⲁⲓϩⲱⲃ ⲉⲧⲟⲓ ⲛ̀ϣ̀ⲫⲏⲣⲓ: ⲛⲉⲙ ⲟⲩⲙⲩⲥⲧⲏⲣⲓⲟⲛ ⲛ̀ϫⲱⲣⲓ: ϫⲉ ⲁ̀Ⲫϯ ⲟⲩⲱⲣⲡ ⲙ̀ⲡⲉϥϣⲏⲣⲓ: ⲉⲑⲃⲉ ⲧⲉϥⲙⲉⲧⲁ̀ⲅⲁⲑⲟⲥ.\n\nⲈⲑⲃⲉ ⲧⲉϥⲙⲉⲧⲁ̀ⲅⲁⲑⲟⲥ: ⲁϥϭⲓⲥⲁⲣⲝ ϧⲉⲛ ϯⲡⲁⲣⲑⲉⲛⲟⲥ: ⲉⲑⲃⲉ ⲫⲁⲓ ⲥⲉⲣⲁϣⲓ ⲛⲉⲙⲁⲥ: ⲛ̀ϫⲉ ϯⲕ̀ⲧⲏⲥⲓⲥ ⲧⲏⲣⲥ ⲉⲩⲥⲟⲡ.\n\nⲦⲉⲛϯⲱ̀ⲟⲩ ⲛⲉ ⲱ̀ ⲑⲏⲉ̀ⲧⲉⲛϩⲟⲧ: ⲉⲧϥⲁⲓ ϧⲁ ⲡⲓⲗⲟⲅⲟⲥ ⲛ̀ⲧⲉ Ⲫ̀ⲓⲱⲧ: ϫⲉ ⲭⲉⲣⲉ ⲑⲏⲉⲑⲙⲉϩ ⲛ̀ϩ̀ⲙⲟⲧ: ⲟⲩⲟϩ Ⲡⲟ︦ⲥ︦ ϣⲟⲡ ⲛⲉⲙⲉ." },
    { language: 'english', text: "I will praise You O Lord of mercy, I will seek Your salvation, teach me according to Your mercy, forgive me for my ignorance.\n\nForgive me for my ignorance, enlighten my heart, that I may speak of the honor of this bride, the chaste and undefiled.\n\nThe chaste and undefiled, the true queen, with great honor, the Virgin Mother of God.\n\nThe Virgin Mother of God, who has brought us God, carried in her womb, according to His Economy.\n\nAccording to His Economy, and His great wisdom, Mary carried Him in her womb, while He did not leave His throne.\n\nWhile He did not leave His throne, which is above the angels, He was in the womb of the Virgin, a marvelous case.\n\nA marvelous case, and a powerful mystery, for God sent His Son, for the sake of His goodness.\n\nFor the sake of His goodness, He took flesh from the Virgin, wherefore the whole creation, rejoices with her.\n\nWe glorify you O faithful one, who carried the Word of the Father, \"Hail to you O full of grace, the Lord is with you.\"" },
    { language: 'arabic', text: "أسبحك يا رب الرحمة. واطلب خلاصك. افهمني كرحمتك. إغفر لي جهالتي.\n\nإغفر لي جهالتي. وأضئ قلبي. لكي انطق بكرامة هذه العروسة. غير الدنسة الهادئة.\n\nغير الدنسة الهادئة. الملكة الحقيقية. ذات الكرامة العظيمة. العذراء والدة الإله.\n\nالعذراء والدة الإله. التي أحضرت لنا. الله محمولاً. علي منكبيها كتدبيره.\n\nعلي منكبيها كتدبيره. وحكمتة العظيمة. حملته مرتمريم. ولم يفارق كرسيه.\n\nولم يفارق كرسيه. وهو فوق الملائكة. وهو كائن في بطن العذراء. فما هو هذا الامر العجيب.\n\nفما هو هذا الامر العجيب. والسر القوي. ان الله ارسل لنا ابنه. من اجل صلاحه.\n\nمن اجل صلاحه. تجسد من العذراء. من اجل هذا تفرح معها. كل المسكونة معاً.\n\nنمجدك ايتها الامينة. الحاملة كلمة الأب قائلين إفرحي يا ممتلئة نعمة. الرب معك" },
    { language: 'englishArabic', text: "Usabbihuka ya Rabb er-rahma, wa atlub khalasak. Afhimni ka-rahmatik. Ighfir li gahalati.\n\nIghfir li gahalati. Wa adi' qalbi. Likay antiqa bi-karamat hadhihi el-'arousa, ghayr ed-danisa el-hadi'a.\n\nGhayr ed-danisa el-hadi'a. El-malika el-haqeeqiyya. Dhat el-karama el-'azeema. El-'Adhra' walidat el-Ilah.\n\nEl-'Adhra' walidat el-Ilah. Allati ahdarat lana Allah mahmoulan 'ala mankibayha ka-tadbeerih.\n\n'Ala mankibayha ka-tadbeerih. Wa hikmatihi el-'azeema. Hamalathu Martmaryam, wa lam yufariq kursiyyah.\n\nWa lam yufariq kursiyyah. Wa huwa fawq el-mala'ika. Wa huwa ka'in fi batn el-'Adhra'. Fa-ma huwa hadha el-amr el-'ageeb?\n\nFa-ma huwa hadha el-amr el-'ageeb, was-sirr el-qawiyy? Anna Allah arsala lana ibnahu min agl salahih.\n\nMin agl salahih. Tagassada min el-'Adhra'. Min agl hadha tafrah ma'aha kull el-maskouna ma'an.\n\nNumaggiduki ayyatuha el-ameena, el-hamila kalimat el-Ab, qa'ileen: ifrahi ya mumtali'a ni'ma, er-Rabb ma'aki." },
  ] },
  { id: "vp-the-first-egyptian-interpretation", title: "The First Egyptian Interpretation", versions: [
    { language: 'coptic', text: "Ϯⲁⲧⲑⲱⲗⲉⲃ ⲛ̀ⲥⲉⲙⲛⲏ: ⲟⲩⲟϩ ⲉⲑⲟⲩⲁⲃ ⲙ̀ⲡⲁⲛⲁ̀ⲅⲓⲁ: ⲁ̀ ϯⲕ̀ⲧⲏⲥⲓⲥ ⲧⲏⲣⲥ ⲣⲁϣⲓ ⲛⲉⲙⲉ: ⲱ̀ ⲑⲏⲉⲑⲙⲉϩ ϧⲉⲛ ϯⲥⲟⲫⲓⲁ.\n\nϮⲁⲧⲑⲱⲗⲉⲃ ⲛ̀ⲥⲉⲙⲛⲏ: ⲓⲥ Ⲅⲁⲃⲣⲓⲏⲗ ⲥⲁϫⲓ ⲛⲉⲙⲉ: ϫⲉ ⲭⲉⲣⲉ ⲕⲉ ⲭⲁⲣⲓⲧⲱⲙⲉⲛⲏ: ⲟⲩⲟϩ Ⲡϭⲟⲓⲥ ϣⲟⲡ ⲛⲉⲙⲉ.\n\nϮⲁⲧⲑⲱⲗⲉⲃ ⲛ̀ⲥⲉⲙⲛⲏ: ⲱ̀ ϯⲟⲩⲣⲱ ⲑ̀ⲙⲁⲩ ⲙ̀Ⲡⲓⲟⲩⲣⲟ: ⲛⲓⲁⲅⲅⲉⲗⲟⲥ ⲣⲁϣⲓ ⲛⲉⲙⲉ: ⲉⲩϩⲱⲥ Ⲡⲟⲩⲣⲟ Ⲡⲓⲣⲉϥⲑⲁⲙⲓⲟ.\n\nϮⲁⲧⲑⲱⲗⲉⲃ ⲛ̀ⲥⲉⲙⲛⲏ: ⲧⲉⲛϭⲓⲥⲓ ⲙ̀ⲙⲟ ⲛⲉⲙ Ⲅⲁⲃⲣⲓⲏⲗ: ϫⲉ ⲭⲉⲣⲉ ⲕⲉ ⲭⲁⲣⲓⲧⲱⲙⲉⲛⲏ: Ⲙⲁⲣⲓⲁ ⲑ̀ⲙⲁⲩ ⲛ̀Ⲉⲙⲙⲁⲛⲟⲩⲏⲗ.\n\nϮⲁⲧⲑⲱⲗⲉⲃ ⲛ̀ⲥⲉⲙⲛⲏ: ⲧⲉⲛⲧⲁⲓⲟ ⲙ̀ⲙⲟ ⲛⲉⲙ ⲡⲓϩⲩⲙⲛⲟⲇⲟⲥ: ϫⲉ ⲁϥⲥⲁϫⲓ ⲛ̀ϩⲁⲛⲧⲁⲓⲟ: Ⲫⲛⲟⲩϯ ⲛ̀ⲧⲉ Ⲡⲓⲁⲓⲇⲓⲟⲥ.\n\nϮⲁⲧⲑⲱⲗⲉⲃ ⲛ̀ⲥⲉⲙⲛⲏ: ⲑ̀ⲙⲁⲩ ⲙ̀Ⲫⲛⲟⲩϯ ⲡⲓⲗⲟⲅⲟⲥ: ⲟⲩⲟϩ ⲛ̀ⲑⲟϥ ⲉⲧϣⲟⲡ ⲛⲉⲙⲉ: ⲁ̀ⲣⲉϣⲱⲡⲓ ⲛⲁϥ ⲛ̀ⲟⲩⲑ̀ⲣⲟⲛⲟⲥ.\n\nϮⲁⲧⲑⲱⲗⲉⲃ ⲛ̀ⲥⲉⲙⲛⲏ: ⲱ̀ ⲑⲏⲉⲧⲥ̀ⲙⲁⲣⲱⲟⲩⲧ ϧⲉⲛ ⲙⲁⲓ ⲛⲓⲃⲉⲛ: ⲧⲉⲛⲧⲁⲓⲟ ⲙ̀ⲙⲟ ⲛ̀ⲥⲏⲟⲩ ⲛⲓⲃⲉⲛ: ϣⲁ ⲉ̀ⲛⲉϩ ⲛ̀ⲧⲉ ⲡⲓⲉ̀ⲛⲉϩ.\n\nⲈⲑⲃⲉ ⲫⲁⲓ ⲧⲉⲛϩⲱⲥ ⲉ̀Ⲫⲛⲟⲩϯ: ⲫⲏⲉ̀ⲧⲁϥϭⲓⲥⲁⲣⲝ ⲉ̀ⲃⲟⲗ ⲛ̀ϧⲏϯ: ⲁϥⲉⲣⲣⲱⲙⲓ ⲙ̀ⲡⲉⲛⲣⲏϯ: ϣⲁⲧⲉⲛ ⲫ̀ⲛⲟⲃⲓ ⲙ̀ⲙⲁⲩⲁⲧϥ." },
    { language: 'english', text: "O chaste and undefiled, and holy saint, all the creation rejoices with you, O who are full of wisdom.\n\nO chaste and undefiled, behold Gabriel spoke to you, saying “Hail to you O full of grace, the Lord is with you.”\n\nO chaste and undefiled, O Queen Mother of the King, the angels rejoice with you, praising the King the Creator.\n\nO chaste and undefiled, we exalt you with Gabriel, saying “Hail to you O full of grace, Mary the Mother of Immanuel.”\n\nO chaste and undefiled, we honor you with the hymnist, for he spoke of the honor, of God the Eternal.\n\nO chaste and undefiled, the Mother of God the Logos, He who dwells with you, you became a throne for Him.\n\nO chaste and undefiled, O blessed one in every place, we honor you at all times, to the age of the ages.\n\nTherefore we praise God, who was incarnate of you, and became man like us, except for sin alone." },
    { language: 'arabic', text: "غير الدنسة الهادئة، والقديسة الطاهرة، كل الخليقة تفرح معكِ، أيتها الممتلئة حكمة.\n\nغير الدنسة الهادئة، ها هوذا غبريال تكلم معكِ، قائلاً \"السلام لكِ يا ممتلئة نعمة، الرب معكِ.\"\n\nغير الدنسة الهادئة، أيتها الملكة اُم الملك، الملائكة تفرح معكِ، مُسبحين الملك الخالق.\n\nغير الدنسة الهادئة، نعظمكِ مع غبريال قائلين، \"السلام لكِ يا ممتلئة نعمة، مريم اُم عمانوئيل.\"\n\nغير الدنسة الهادئة، نكرمكِ مع المرتِّل، لأنه تكلم بكرامة، الإله الأزلي.\n\nغير الدنسة الهادئة، اُم الله الكلمة، وهو كائن معكِ، قد صرتِ له كرسياً.\n\nغير الدنسة الهادئة، أيتها المباركة في كل مكان، نكرمكِ كل حين، على أبد الآبدين.\n\nفلهذا نسبِّح الله، الذي تجسَّد منكِ، وصار إنساناً مثلنا، ما خلا الخطية وحدها." },
    { language: 'englishArabic', text: "Ghayr ed-danisa el-hadi'a, wal-qiddeesa et-tahira, kull el-khaleeqa tafrah ma'aki, ayyatuha el-mumtali'a hikma.\n\nGhayr ed-danisa el-hadi'a, ha huwa Ghubriyal takallama ma'aki, qa'ilan: \"Es-salam laki ya mumtali'a ni'ma, er-Rabb ma'aki.\"\n\nGhayr ed-danisa el-hadi'a, ayyatuha el-malika umm el-malik, el-mala'ika tafrah ma'aki, musabbiheen el-malik el-khaliq.\n\nGhayr ed-danisa el-hadi'a, nu'azzimuki ma'a Ghubriyal qa'ileen: \"Es-salam laki ya mumtali'a ni'ma, Maryam umm 'Emmanu'eel.\"\n\nGhayr ed-danisa el-hadi'a, nukarrimuki ma'a el-murattil, li-annahu takallama bi-karama, el-Ilah el-azali.\n\nGhayr ed-danisa el-hadi'a, umm Allah el-Kalima, wa huwa ka'in ma'aki, qad sirti lahu kursiyyan.\n\nGhayr ed-danisa el-hadi'a, ayyatuha el-mubaraka fi kull makan, nukarrimuki kull heen, 'ala abad el-abideen.\n\nFa-li-hadha nusabbih Allah, alladhi tagassada minki, wa sara insanan mithlana, ma khala el-khatiyya wahdaha." },
  ] },
  { id: "vp-the-first-sahidic-interpretation", title: "The First Sahidic Interpretation", versions: [
    { language: 'coptic', text: "Ⲁⲝⲓⲁ ⲉ̀ⲁⲩⲙⲟⲩϯ ⲉ̀ⲣⲟⲥ: ϫⲉ ϯⲁⲧⲑⲱⲗⲉⲃ ⲛ̀ⲥⲉⲙⲛⲏ: Ⲙⲁⲣⲓⲁ ϯⲟⲩⲣⲱ ⲛ̀ⲁ̀ⲗⲏⲑⲓⲛⲉ: ϯⲙⲁϩⲥ̀ⲛⲟⲩϯ ⲛ̀ⲥ̀ⲕⲏⲛⲏ.\n\nϪⲉ ⲁ̀ Ⲡⲓⲡ̀ⲛⲉⲩⲙⲁ ⲙ̀ⲡⲁⲣⲁⲕⲗⲏⲧⲟⲛ: ⲓ̀ ⲉ̀ϫⲱⲥ ⲉ̀ⲃⲟⲗ ϩⲓⲧⲉⲛ Ⲫⲛⲟⲩϯ: ⲟⲩⲟϩ Ⲡϭⲟⲓⲥ ⲛ̀ⲛⲓⲉ̀ⲱⲛ: ⲁ̀ⲣⲉϥⲁⲓ ϧⲁⲣⲟϥ ⲉⲑⲃⲉ ⲡⲉⲛⲥⲱϯ.\n\nⲀϥⲓ̀ ⲛⲁⲛ ⲉ̀ⲃⲟⲗ ⲛ̀ϧⲏϯ: ⲛ̀ϫⲉ Ⲡⲓⲭ̀ⲣⲓⲥⲧⲟⲥ Ⲡⲓⲣⲉϥⲉⲣϩⲉⲙⲓ: ⲁϥⲥⲱϯ ⲙ̀ⲙⲟⲛ ⲉ̀ⲃⲟⲗ ϧⲉⲛ ⲟⲩϩⲟϯ: ⲛ̀ⲧⲉ ⲡⲓϫⲁϫⲓ ⲛ̀ⲧⲉ ϯⲙⲉⲧⲣⲱⲙⲓ.\n\nⲘⲁⲣⲉϥⲓ̀ ⲉ̀ϩ̀ⲣⲏⲓ ⲉ̀ϫⲱⲛ: ⲛ̀ϫⲉ ⲡⲉϥⲛⲁⲓ ⲛⲉⲙ ⲧⲉϥⲙⲉⲑⲙⲏⲓ: ⲉⲩⲉ̀ϣⲱⲡⲓ ⲉⲩⲧⲁϩⲟⲛ: ⲛ̀ⲑⲱⲟⲩ ⲡⲉ ⲡ̀ⲛⲟⲙϯ ⲙ̀ⲙⲏⲓ.\n\nⲈⲑⲃⲉ ⲫⲁⲓ ⲧⲉⲛϯⲱ̀ⲟⲩ ⲛⲉ: ⲉⲛⲱϣ ⲉ̀ⲃⲟⲗ ⲛⲉⲙ Ⲅⲁⲃⲣⲓⲏⲗ: ϫⲉ ⲭⲉⲣⲉ ⲕⲉ ⲭⲁⲣⲓⲧⲱⲙⲉⲛⲏ: Ⲙⲁⲣⲓⲁ ⲑ̀ⲙⲁⲩ ⲛ̀Ⲉⲙⲙⲁⲛⲟⲩⲏⲗ." },
    { language: 'english', text: "You are worthy to be called, the chaste and undefiled, Mary the true Queen, the second tabernacle.\n\nFor the Spirit of comfort, came upon her through God, the Lord of the ages, you carried Him for our salvation.\n\nOut of you He came to us, Christ the Governor, and saved us from the fear, of humanity’s enemy.\n\nLet His mercy and His truth, come upon us, that they may reach us, because they are true comfort.”\n\nTherefore we glorify you, proclaiming with Gabriel, “Hail to you O full of grace, Mary the Mother of Immanuel.”" },
    { language: 'arabic', text: "مستحقة أن تُدعى، غير الدنسة العفيفة، مريم الملكة الحقيقية، القبة الثانية.\n\nلأن الروح المعزي، حلَّ عليها من قِبَل الله، ورب الدهور، حملتِه من أجل خلاصنا.\n\nخرج لنا منكِ، المسيح المُدبِّر، وخلصنا من خوف، عدو البشر.\n\nفلتأتِ علينا، رحمته وعدله، وليدركانا، لأنهما العزاء الحقيقي.\n\nفلهذا نُمجدكِ، ونصرخ مع غبريال قائلين،\"السلام لكِ يا ممتلئة نعمة، مريم اُم عمانوئيل.\"" },
    { language: 'englishArabic', text: "Mustahiqqa an tud'a, ghayr ed-danisa el-'afeefa, Maryam el-malika el-haqeeqiyya, el-qubba eth-thaniya.\n\nLi-anna er-Rouh el-mu'azzi, halla 'alayha min qibal Allah, wa Rabb ed-dohour, hamaltihi min agl khalasina.\n\nKharaga lana minki, el-Maseeh el-mudabbir, wa khallasana min khawf, 'aduww el-bashar.\n\nFal-ta'ti 'alayna, rahmatuhu wa 'adluh, wal-yudrikana, li-annahuma el-'aza' el-haqeeqi.\n\nFa-li-hadha numaggiduki, wa nasrukh ma'a Ghubriyal qa'ileen: \"Es-salam laki ya mumtali'a ni'ma, Maryam umm 'Emmanu'eel.\"" },
  ] },
  { id: "vp-the-first-hymn-of-abou-el-saad-of-aboutig", title: "The First Hymn of Abou El-Saad of Aboutig", versions: [
    { language: 'english', text: "Who would be called the undefiled / other than Mary and her chastity / all my thoughts could not utter / her honorable standing.\n\nThis saint carried and gave birth / being a virgin in her nature / became a mother and a mistress / above the whole world.\n\nYou are highly exalted O Mary / and dignified above regard / and exceeded the regard of the martyrs / you are venerated above the righteous.\n\nYou defeated the armies of the enemies / through you we escaped the sea of fire / we venerate you O pure first-born / to the end of all generation.\n\nEvery living and breathing flesh / would come now and celebrate with us / with what utterance and chant / would loudly praise with us.\n\nHail to you O mother of mercy / we are your beloved pray acknowledge us / blessed are you O full of grace / before your Son intercede for us." },
    { language: 'arabic', text: "من هي تدعي غير الدنسة / إلا مريم بطهارتها / وجميع افكاري ملتمسة / ولم تنطق بكرامتها.\n\nحبلت وولدت هذه القديسة / وهي عذراء بطبيعتها / وصارت امَا ورئيسة / وفوق العالم رتبتها.\n\nعليت يا مريم جداً / وعلي شرفك فوق المقدار / وفقتِ مقدار الشهداء / وتفضلتِ علي الابرار.\n\nهزمتِ جيوش الاعداء / وبإبنك نجونا من بحر النار / نعظمك يا بكر وبتول / مدي العمر لآخر الأدهار.\n\nكل جسدٍ حي ونسمة / يجئُ الآن ويهنينا / بأي لغة وأي نغمة / بصوتٍ عالٍ يناغينا.\n\nالسلام لك يا ام الرحمة / نحن عبيدك جيرينا / طوباكِ يا مملوُة نعمة / عند ابنك الحبيب اشفعي فينا." },
    { language: 'englishArabic', text: "Man hiya tud'a ghayr ed-danisa / illa Maryam bi-taharatiha / wa gamee' afkari multamisa / wa lam tantiq bi-karamatiha.\n\nHabalat wa waladat hadhihi el-qiddeesa / wa hiya 'adhra' bi-tabee'atiha / wa sarat umman wa ra'eesa / wa fawq el-'alam rutbatuha.\n\n'Alayti ya Maryam giddan / wa 'ala sharafuki fawq el-miqdar / wa fuqti miqdar esh-shuhada' / wa tafaddalti 'ala el-abrar.\n\nHazamti guyoush el-a'da' / wa bi-ibniki nagawna min bahr en-nar / nu'azzimuki ya bikr wa batoul / mada el-'umr li-akhir el-adhar.\n\nKull gasadin hayy wa nasama / yagi' el-an wa yuhanneena / bi-ayy lugha wa ayy nagham / bi-sawtin 'alin yunagheena.\n\nEs-salam laki ya umm er-rahma / nahnu 'abeeduki geereena / toubaki ya mamlou'at ni'ma / 'ind ibniki el-habeeb ishfa'i feena." },
  ] },
  { id: "vp-first-hymn-of-cantor-gabriel-of-qay-a", title: "First Hymn of Cantor Gabriel of Qay A", versions: [
    { language: 'english', text: "I begin in the name of God the Father / the Son and the Holy Spirit: a Trinity / of one God, Lord of lords / Holy immortal Lord of Sabaoth.\n\nHoly immortal Lord of Sabaoth / holy immortal eternal / holy is He who resurrected us from death / and removed all deception from us.\n\nAnd removed all deception from us / and was incarnate from a pure virgin / the undefiled pride of generations / Mary the Lady of humanity.\n\nMary the Lady of humanity / of her the righteous fathers witnessed / Moses the prophet in the wilderness / saw a bush with flames in its midst.\n\nSaw a bush with flames in its midst / with an igniting ascending flame / and the bush saw no harm / Ezekiel was truthful in his vision.\n\nEzekiel was truthful in his vision / he said I saw in the East a gate / through it the most high King entered / and exited and on it a flowing veil.\n\nAnd exited and on it a flowing veil / like a pure first-born virgin / who carried Jesus the Lord of lords / and she is a pure virgin.\n\nAnd she is a pure virgin / she carried our master Christ / and exceeded the human nature / and the righteous and the just.\n\nAnd the righteous and the just / and all orders of light / and all the ranks of the angels / and all the heavenly legions.\n\nAnd all the heavenly legions / bow down to the One carried in your hands / and we all proclaim / hail to you and hail unto you.\n\nHail to you and hail unto you, we ask you O Mother of the Beloved, grant us to be in your fathers’ dwellings, Abraham Isaac and Jacob." },
    { language: 'arabic', text: "أبدي باسم الله الآب / والابن والروح القدس الثالوث / اله واحد رب الارباب. / قدوس الحي رب الصاباؤوت.\n\nقدوس الحي رب الصاباؤوت / قدوس الحي بغير زوال / قدوس مَن احيانا من الموت / وأَزَالَ عنَّا كل ضلال.\n\nوأَزَالَ عنَّا كل ضلال / وتجسد من بكر نقية / الغير دنسة فخر الاجيال / مريم سيدة البشرية.\n\nمريم سيدة البشرية / عنها شهد الآباء الابرار / موسى النبي في البرية / عاين عوسج في قلبه نار.\n\nعاين عوسج في قلبه نار / بلهيب صاعد باشتعال / وما مسَّ العوسج اى ضرر / وصدق في رؤياه حزقيال.\n\nوصدق في رؤياه حزقيال / قال إني رأَيت في المشرق باب / وفيه دخل الملك المُتعال / وخرج وعليه مسبول حجاب.\n\nوخرج وعليه مسبول حجاب / مثال بتول بكر نقية / حمَلت يسوع رب الارباب / وهي عذراء ببكورية.\n\nوهي عذراء ببكورية / حملت سيدنا بخريستوس / وفاقت طبع البشرية / نيم ني إثمي نيم ني ذيكيئوس.\n\nني إثمي نيم ني ذيكيئوس / وكل طقوس نورانية / وجميع طغمات ني أنجيلوس / وكل اجناد سمائية.\n\nوكل اجناد سمائية / تسجد للمحمول بين يديك / ونحن نصيح بالكلية / السلام لكِ ثم السلام إليك.\n\nالسلام لكِ ثم السلام إليك، ونسألك يا أم المحبوب، ان تحظينا في مظال اباءك، ابراهيم واسحق ويعقوب." },
    { language: 'englishArabic', text: "Abdi bism Allah el-Ab / wal-Ibn war-Rouh el-Qudus eth-thalouth / ilah wahid Rabb el-arbab / quddous el-hayy Rabb es-Saba'out.\n\nQuddous el-hayy Rabb es-Saba'out / quddous el-hayy bi-ghayr zawal / quddous man ahyana min el-mawt / wa azala 'anna kull dalal.\n\nWa azala 'anna kull dalal / wa tagassada min bikr naqiyya / el-ghayr danisa fakhr el-agyal / Maryam sayyidat el-bashariyya.\n\nMaryam sayyidat el-bashariyya / 'anha shahida el-aba' el-abrar / Mousa en-nabi fil-bariyya / 'ayana 'awsag fi qalbihi nar.\n\n'Ayana 'awsag fi qalbihi nar / bi-laheeb sa'id bi-ishti'al / wa ma massa el-'awsag ayy darar / wa sadaqa fi ru'yahu Hizqiyal.\n\nWa sadaqa fi ru'yahu Hizqiyal / qala inni ra'aytu fil-mashriq bab / wa feehi dakhala el-malik el-muta'al / wa kharaga wa 'alayhi masboul higab.\n\nWa kharaga wa 'alayhi masboul higab / mithal batoul bikr naqiyya / hamalat Yasou' Rabb el-arbab / wa hiya 'adhra' bi-boukouriyya.\n\nWa hiya 'adhra' bi-boukouriyya / hamalat sayyidana Pikhristos / wa faqat tab' el-bashariyya / nem ni-ethmi nem ni-dikeos.\n\nNi-ethmi nem ni-dikeos / wa kull touqous nouraniyya / wa gamee' tughmat ni-aggelos / wa kull agnad samawiyya.\n\nWa kull agnad samawiyya / tasgud lil-mahmoul bayna yadayki / wa nahnu nasee'h bil-kulliyya / es-salam laki thumma es-salam ilayki.\n\nEs-salam laki thumma es-salam ilayki, wa nas'aluki ya umm el-mahboub, an tahzeena fi mazall aba'ik, Ibraheem wa Ishaq wa Ya'qoub." },
  ] },
  { id: "vp-the-first-hymn-of-cantor-gabriel-of-qay-b", title: "The First Hymn of Cantor Gabriel of Qay B", versions: [
    { language: 'english', text: "I start with the name of the holy God, our Master the Judge and King, the Son of God in truth, who was born before the ages.\n\nI praise Mary the Virgin, the undefiled pride of the world, the Mother of Jesus Christ, the Light of the faith shone from her.\n\nYour womb carried the Holy One, and you bore Him to restore the man, Adam after he was captive, captured in the hands of Satan.\n\nThe Savior of the world, appeared from you in the body of a man, and He destroyed the power of the Devil, for all the servants of the King.\n\nBlessed are you O Virgin and Bride, O precious and valuable pearl, you surpassed the delight of the angels, and you were favored above every human.\n\nEvery rank and every order, magnify you at all times, and every living body and soul, sings hymns before you.\n\nHail to you O Mother of our Savior, we ask you O pure Virgin, to ask the Lord to bring us, to the harbor in peace." },
    { language: 'arabic', text: "أبدي بإسم الله القدوس، سيدنا الملك الديَّان، إبشيري إميفنوتي آليثوس، المولود قبل الأزمان.\n\nوأمدح مريم تي بارثينوس، غير الدنسة فخر الأكوان، إثماڤ إن إيسوس بيخريستوس، منها أشرق نورُ الإيمان.\n\nحملتْ أحشائكِ بي آجيوس، وولدتِه ليرد الإنسان، آدم بعد أن كان محبوس، مأسور في يد الشيطان.\n\nإبسوتير إممبي كوزموس، ظهر منكِ في شكل إنسان، وكسر قوة بي ذِيَّإيڤولوس، عن سائر خُدَّام الملك الديان.\n\nطوباكِ يا بكر وعروس، يا جوهر غالي الأثمان، قد فُقتِ بهاء ني أنجيلوس، وتفضلتِ عن كل إنسان.\n\nكل الطغمات وكل الطقوس، تُعظمكِ كلَّ الأزمان، وكل أجساد أحياء ونفوس، ترتِّل أمامِك بالألحان.\n\nالسلام لكِ يا اُم مخلصنا، ونسألكِ يا بكر نقية، تسألي الرب أن يوصِّلنا، إلى الميناء بطمأنينة." },
    { language: 'englishArabic', text: "Abdi bism Allah el-quddous, sayyiduna el-malik ed-dayyan, Epshēri em-Efnouti alēthōs, el-mawloud qabl el-azman.\n\nWa amdah Maryam Tiparthenos, ghayr ed-danisa fakhr el-akwan, ethmav en-Iēsous Pikhristos, minha ashraqa nour el-eeman.\n\nHamalat ahsha'uki Pi-agios, wa waladtihi li-yarudd el-insan, Adam ba'd an kana mahbous, ma'sour fi yad esh-shaytan.\n\nEpsōtēr empikosmos, zahara minki fi shakl insan, wa kasara quwwat Pidiavolos, 'an sa'ir khuddam el-malik ed-dayyan.\n\nToubaki ya bikr wa 'arous, ya gawhar ghali el-athman, qad fuqti baha' ni-aggelos, wa tafaddalti 'an kull insan.\n\nKull et-tughmat wa kull et-touqous, tu'azzimuki kull el-azman, wa kull agsad ahya' wa nufous, turattil amamiki bil-alhan.\n\nEs-salam laki ya umm mukhallisina, wa nas'aluki ya bikr naqiyya, tas'ali er-Rabb an yuwassilana, ila el-meena' bi-tuma'neena." },
  ] },
  { id: "vp-the-first-hymn-of-cantor-gabriel-of-qay-c", title: "The First Hymn of Cantor Gabriel of Qay C", versions: [
    { language: 'english', text: "The undefiled daughter of Joachim, pure from every blemish, Mary the pride of the world, noblest from among the races.\n\nFrom a noble root and an honored tribe, salvation came to us from her, she carried the great Mystery in her womb, the Son of God the Messiah.\n\nThe Son of God the Messiah, born of the Father before all ages, the One of the Trinity, the only Son of the unseen Father.\n\nHe came and was incarnate, from the pride of the world the Mother of the Light, and restored Adam after the misery, and He erased bitter slavery from him.\n\nAnd He erased bitter slavery from him, as He promised him with mercy, He fulfilled the promise and lit the light, after he was sitting in darkness.\n\nHe came to joy happiness and delight, through the Incarnation of the Son of God the Logos, and His dwelling in you O Mother of the Light, hail to you O Mother of mercy.\n\nHail to you O Mother of mercy, blessed are you O full of grace, the Lady of us all Mary, through her prayers and intercessions." },
    { language: 'arabic', text: "الغير دنسة إبنة يواقيم، نقية من كل الأدناس، زينة العالم م ر ي م، شريفة من خاصة الأجناس.\n\nمن أصل حسيب وسبط كريم، أتانا منها كل خلاص، حَملَتْ في أحشاءها سر عظيم، إبشيري إميفنوتي ماسياس.\n\nإبشيري إميفنوتي ماسياس، المولود من قبل كل الدهور، بي أوَّواي إيڤول خين تي إترياس، وحيد الآب الغير منظور.\n\nأف إي إيڤول آفيتشي ساريكس، من زينة العالم اُم النور، ورد آدم من بعد اليأس، ومحى عنه الرِق المسطور.\n\nومحى عنه الرِق المسطور، كما قد وعده بالرحمة، أوفاه الوعد وأنار النور، بعد أن كان جالساً في الظلمة.\n\nصار في بهجة وفرح وسرور، بتجسُّد إبن الله الكلمة، وحلولهِ فيكِ يا اُم النور، السلام لكِ يا اُم الرحمة.\n\nالسلام لكِ يا اُم الرحمة، طوباكِ يا ممتلئة نعمة، أووتين شويس إننيب ماريا، هيتين نيس طوڤه نيم نيس إبريسڤيِّا." },
    { language: 'englishArabic', text: "El-ghayr danisa ibnat Yowakeem, naqiyya min kull el-adnas, zeenat el-'alam M-R-Y-M, shareefa min khassat el-agnas.\n\nMin asl haseeb wa sibt kareem, atana minha kull khalas, hamalat fi ahsha'iha sirr 'azeem, Epshēri em-Efnouti Massias.\n\nEpshēri em-Efnouti Massias, el-mawloud min qabl kull ed-dohour, Pi-ouai evol khen Ti-etrias, waheed el-Ab el-ghayr manzour.\n\nAf-i evol aftshi sarx, min zeenat el-'alam umm en-nour, wa radda Adam min ba'd el-ya's, wa maha 'anhu er-riqq el-mastour.\n\nWa maha 'anhu er-riqq el-mastour, kama qad wa'adahu bir-rahma, awfahu el-wa'd wa anara en-nour, ba'd an kana galisan fiz-zulma.\n\nSara fi bahga wa farah wa sourour, bi-tagassud Ibn Allah el-Kalima, wa hulouluhu feeki ya umm en-nour, es-salam laki ya umm er-rahma.\n\nEs-salam laki ya umm er-rahma, toubaki ya mumtali'a ni'ma, Ouoh ten-tshois ennēb Maria, hiten nes-tovh nem nes-epresvia." },
  ] },
  { id: "vp-the-first-hymn-of-pope-abba-markos-viii", title: "The First Hymn of Pope Abba Markos VIII", versions: [
    { language: 'english', text: "I start with the name of the holy God, Creator of every age and time, whom all the orders praise, our Savior the Judge and King.\n\nHe created Adam and made Paradise, high above and raised without pillars, all the souls live in it, who please Him by works and faith.\n\nAnd He made in it every planted tree, budding different fruits of all kinds, this the holy Lord created, for Adam His servant the human.\n\nAnd He created Eve for him, by her Adam became joyful, she was created from his own flesh, from the rib of Adam the human.\n\nAnd He commanded them from His holy mouth, and said “Adam I order you O human, eat from the trees of Paradise, and this is the tree of the trials.\n\nBe far from it and its roots, do not eat of it or you will become naked, and you will die in flesh and spirit, you and Eve will become sad.”\n\nHail to you O Lady of virgins, O Mary the Virgin, Jesus Christ dwelt in your womb, and became our Savior." },
    { language: 'arabic', text: "أبدي بإسم الله القدوس، الخالق كل دهور وأزمان، له تسبِّح سائر كل طقوس، مخلصنا الملك الديان.\n\nخلق آدم وأنشأ الفردوس، عالٍ مرفوع بغير عمدان، تسكن فيه سائر كل نفوس، مَنْ كان يرضيه بأعمال وإيمان.\n\nوجعل فيه كل شجر مغروس، يطرح أثمار أصناف وألوان، هذا صنعه الرب القدوس، لأجل آدم عبده الإنسان.\n\nوخلق له حواء فصار مأنوس، بها آدم بقى فرحان، قد خُلِقَتْ من جسده الملموس، من ضلع آدم الإنسان.\n\nوأوصاهما من فمه القدوس، وقال لآدم \"أنا أوصيك يا إنسان، كُلْ من أشجار الفردوس، وهذه شجرة الإمتحان.\n\nإبعِد عنها دون كل غِروس، لا تأكل منها لئلا تصير عريان، وتموتا أرواحاً ونفوس، أنت وحواء تصيران في أحزان.\"\n\nالسلام لكِ يا ست الأبكار، يا مريم تي بارثينوس، يا مَنْ في أحشائكِ قد حلَّ وصار، مخلصنا إيسوس بيخريستوس." },
    { language: 'englishArabic', text: "Abdi bism Allah el-quddous, el-khaliq kull dohour wa azman, lahu tusabbih sa'ir kull touqous, mukhallisuna el-malik ed-dayyan.\n\nKhalaqa Adam wa ansha'a el-firdaws, 'alin marfou' bi-ghayr 'umdan, taskun feehi sa'ir kull nufous, man kana yurdeehi bi-a'mal wa eeman.\n\nWa ga'ala feehi kull shagar maghrous, yatrah athmar asnaf wa alwan, hadha sana'ahu er-Rabb el-quddous, li-agl Adam 'abdihi el-insan.\n\nWa khalaqa lahu Hawwa' fa-sara ma'nous, biha Adam baqa farhan, qad khuliqat min gasadihi el-malmous, min dil' Adam el-insan.\n\nWa awsahuma min fammihi el-quddous, wa qala li-Adam: \"Ana ouseek ya insan, kul min ashgar el-firdaws, wa hadhihi shagarat el-imtihan.\n\nIb'id 'anha doun kull el-ghurous, la ta'kul minha li'alla taseer 'uryan, wa tamouta arwahan wa nufous, anta wa Hawwa' taseeran fi ahzan.\"\n\nEs-salam laki ya sitt el-abkar, ya Maryam Tiparthenos, ya man fi ahsha'iki qad halla wa sar, mukhallisuna Iēsous Pikhristos." },
  ] },
  { id: "vp-the-first-hymn-of-el-bardanohee", title: "The First Hymn of El-Bardanohee", versions: [
    { language: 'english', text: "I open my mouth and speak, and glorify Mary the Virgin, she contained the great Mystery, the holy Lord dwelt in her.\n\nAs He has promised Adam, to come and return him to Paradise, He set the time and the promise was fulfilled, by the purity of the Virgin and Bride.\n\nHe took flesh from Mary’s womb, a perfect human tangible and seen, great in glory and honored, by the languages of angelic orders.\n\nHe revived Adam after he was nothing, and saved Him from the anguish of prisons, and returned him revered and honored, Adam and his sons in joy.\n\nBy the purity of her who became an ointment, treating every body and soul, Mary is the great treasure, chosen for the Lord Jesus.\n\nBy her the fortress of evil collapse, by the sign of the Cross, the blind saw and the mute spoke, from all kinds of races.\n\nHail to you O Mother of God, ask your Son on our behalf, to forgive us sinners, through your prayers and honored rank." },
    { language: 'arabic', text: "أنا أفتح فاي وأتكلم، واُمجِّد مريم تي بارثينوس، قد حَوَت السر الأعظم، سكن فيها الرب القدوس.\n\nكما كان قد وعد آدم، يجئ ويعيده إلى الفردوس، أوفى المدة والوعد أتم، بطهارة بكر وعروس.\n\nأخذ جسداً من جوف مريم، بَشَري كامل منظور ملموس، عظيم المجد ومُكرَّم، بلغات رُتب ني أنجليوس.\n\nأحيا آدم من بعد عدم، وتخلَّص من ضيق الحبوس، وأعاده مبجلاً ومُكرَّم، آدم وبنيه فرحان مأنوس.\n\nبطهارة مَنْ صارت مرهم، تداوي كل أجساد ونفوس، مريم هي كنز مُعظَّم، مختارة للرب إيسوس.\n\nوحصون الشرير به تُهدَم، برسم إشارة بيستاڤروس، بُرئ الأعمى ونطق الأبكم، من سائر الطوائف وكل الأجناس.\n\nالسلام لكِ يا اُم الإله، جيرينا قدام إبنِك، ليسامحنا نحن الخطاة، بصلاتِك وشرف جنسِك." },
    { language: 'englishArabic', text: "Ana aftah fai wa atakallam, wa umaggid Maryam Tiparthenos, qad hawat es-sirr el-a'zam, sakana feeha er-Rabb el-quddous.\n\nKama kana qad wa'ada Adam, yagi' wa yu'eedahu ila el-firdaws, awfa el-mudda wal-wa'd atamm, bi-taharat bikr wa 'arous.\n\nAkhadha gasadan min gawf Maryam, bashari kamil manzour malmous, 'azeem el-magd wa mukarram, bi-lughat rutab ni-aggelos.\n\nAhya Adam min ba'd 'adam, wa takhallasa min deeq el-hubous, wa a'adahu mubaggalan wa mukarram, Adam wa baneehi farhan ma'nous.\n\nBi-taharat man sarat marham, tudawi kull agsad wa nufous, Maryam hiya kanz mu'azzam, mukhtara lir-Rabb Iēsous.\n\nWa husoun esh-shirreer bihi tuhdam, bi-rasm isharat Pistavros, buri'a el-a'ma wa nataqa el-abkam, min sa'ir et-tawa'if wa kull el-agnas.\n\nEs-salam laki ya umm el-Ilah, geereena quddam ibnik, li-yusamihana nahnu el-khutah, bi-salatik wa sharaf ginsik." },
  ] },
  { id: "vp-the-second-greek-interpretation", title: "The Second Greek Interpretation", versions: [
    { language: 'coptic', text: "ⲀⲪϯ ⲟⲩⲱⲣⲡ ⲙ̀ⲡⲉϥⲙ̀ⲙⲁⲩⲁⲧϥ: ⲛ̀ⲗⲟⲅⲟⲥ ⲉⲕ ⲧⲟⲛ ⲁ̀ⲛⲱ̀ⲅⲉⲟⲥ: ⲛ̀ⲧⲉϥϯ ⲙ̀ⲫ̀ⲛⲟϩⲉⲙ ⲉ̀ⲃⲟⲗϩⲓⲧⲟⲧϥ: ⲓⲥ ⲧⲟⲛ ⲕⲟⲥⲙⲟⲛ ⲛ̀ⲕⲁⲧⲟ̀ⲅⲉⲟⲥ.\n\nⲈϣⲱⲡⲁϥϣⲁⲛⲉ̀ⲩⲇⲟⲕⲓⲥⲉⲛ: ⲕⲉ ⲉ̀ⲝⲁⲡⲉ̀ⲥⲧⲓⲗⲉⲛ ⲧⲟ ⲡ︦ⲛ︦ⲁ︦: ⲱ̀ⲥⲁⲩⲧⲱⲥ ⲏ̀ⲑⲉⲗⲓⲥⲉⲛ: ⲁϥⲉⲣϧⲏⲓⲃⲓ ⲉ̀ⲡⲉϥⲥⲕⲩ̀ⲛⲟⲙⲁ.\n\nⲈⲑⲃⲉ ⲡ̀ϫⲓⲛϭⲓⲥⲁⲣⲝ ⲙ̀ⲡⲉϥϣⲏⲣⲓ: ⲟ̀ ⲅⲉⲛⲛⲏⲧⲟⲥ ⲁⲕⲧⲓⲍⲟ̀ⲙⲉⲛⲟⲥ: ⲉ̀ⲧⲁ ⲛⲓⲡ̀ⲣⲟⲫⲏⲧⲏⲥ ⲧⲏⲣⲟⲩ ⲫⲓⲣⲓ: ⲉ̀ⲡⲉϥⲣⲁⲛ ⲇⲉⲇⲟⲝⲁⲍⲱⲙⲉⲛⲟⲥ.\n\nⲠⲁⲓⲣⲏϯ ⲧⲉⲛⲉⲣⲕⲩ̀ⲣⲓⲍⲓⲛ: ϧⲉⲛ ⲡⲉϥⲇⲟ̀ⲝⲓⲥ ⲉ̀ⲧⲓ ⲉⲕⲧⲉⲛⲱ̀ⲥ: ⲟⲩⲟϩ ⲧⲉⲛⲉⲣⲙⲁⲕⲁ̀ⲣⲓⲍⲓⲛ: ⲛ̀ⲧⲉϥⲙⲁⲩ ⲛ̀ⲥⲁⲃⲏ ⲙ̀ⲡⲁⲣⲑⲉⲛⲟⲥ.\n\nⲔⲉ ⲓ̀ⲡⲱⲙⲉⲛ ⲁⲛⲉⲩ ⲥⲩⲛⲧⲓⲥⲙⲟ̀ⲥ: ⲕⲉ ⲁ̀ⲛⲉⲙⲡⲟ̀ⲇⲓⲥⲧⲟⲥ ⲟ̀ⲗⲱⲛ: ⲧⲉⲛϯ ⲛⲉ ⲙ̀ⲡⲓⲭⲉⲣⲉⲧⲓⲥⲙⲟ̀ⲥ: ⲛⲉⲙ Ⲅⲁⲃⲣⲓⲏⲗ ⲡⲓⲁⲣⲭⲏⲁⲅⲅⲉ̀ⲗⲱⲛ.\n\nⲰ ⲑⲏⲉ̀ⲧⲁⲥⲙⲉⲥ ⲫⲓⲗⲁ̀ⲛⲑ̀ⲣⲱⲡⲟⲥ: ϧⲉⲛ ⲧⲉⲥⲕⲟⲓⲗⲓ̀ⲁⲥ ⲕⲁⲩⲭⲱ̀ⲙⲉⲛⲟⲥ: ϫⲉ ⲉ̀ⲃⲟⲗ ϩⲓⲧⲉⲛ ⲡⲉⲕⲁⲣⲡⲟ̀ⲥ: ⲁ̀ ⲡⲓⲟⲩϫⲁⲓ ⲧⲁϩⲉ ⲡⲉⲛⲅⲉ̀ⲛⲟⲥ.\n\nⲦⲉⲛϯⲱ̀ⲟⲩ ⲛⲉ ⲱ̀ ⲑⲏⲉⲧⲥⲙⲁⲙⲁⲧ: ϣⲁ ⲡⲓⲛⲓϥⲓ ⲛ̀ⲧⲉ ⲗⲉⲩⲧⲉⲟⲥ: ϫⲉ ⲁⲣⲉϫⲓⲙⲓ ⲅⲁⲣ ⲛ̀ⲟⲩϩ̀ⲙⲟⲧ: ϧⲁⲧⲉⲛ Ⲡⲉⲛⲟⲩϯ Ⲩⲓⲟⲥ Ⲑⲉⲟⲥ." },
    { language: 'english', text: "God has sent His only-begotten, the Word from above, to give salvation through Him, to the earthly world.\n\nWhen He became happy, He sent the Spirit, as He wished, He overshadowed His world.\n\nBecause of the Incarnation of His Son, who was born but not created, whom all the prophets spoke about, through His glorified name.\n\nLikewise we preach also, by His eternal glory, and we are elated, by His mother the wise Virgin.\n\nAnd we all say, without excuse or hindrance, \"We send unto you greeting, with Gabriel the archangel.\"\n\nO you who gave birth to the Lover of Mankind, in her proud womb, for through your fruit, salvation came to our race.\n\nWe glorify you O blessed one, until the last breath saying, \"You have found favor before, your God the Son of God.\"" },
    { language: 'arabic', text: "الله أرسل وحيده الكلمة من العلو. ليعطي النجاة للعالم الأرضي من قبله.\n\nإذ قد سر وأرسل الروح كما أراد وظلل مسكنه.\n\nمن أجل تجسد ابنه المولود غير المخلوق الذي كل الأنبياء أخبروا باسمه الممجد.\n\nكذلك نبشر أيضاً بمجده دائما ونغبط امه العذراء الحكيمة.\n\nونقول كلنا بغير عذر ولا مانع. نعطيك السلام مع غبريال رئيس الملائكة.\n\nيا التي ولدت محب البشر من احشاها المفتخر لأن من قبل ثمرتك قد ادرك الخلاص جنسنا.\n\nنمجدك ايتها المباركة إلى النفس الأخير لأنك وجدت نعمة عند إلهك ابن الله." },
    { language: 'englishArabic', text: "Allah arsala waheedahu el-Kalima min el-'ulou, li-yu'ti en-nagah lil-'alam el-ardi min qibalih.\n\nIdh qad surra wa arsala er-Rouh kama arada wa zallala maskanah.\n\nMin agl tagassud ibnihi el-mawloud ghayr el-makhlouq alladhi kull el-anbiya' akhbarou bi-ismihi el-mumaggad.\n\nKadhalika nubashshir aydan bi-magdihi da'iman wa nughabbit ummahu el-'Adhra' el-hakeema.\n\nWa naqoul kulluna bi-ghayr 'udhr wa la mani': nu'teeki es-salam ma'a Ghubriyal ra'ees el-mala'ika.\n\nYa allati waladti muhibb el-bashar min ahsha'iki el-muftakhar, li-anna min qibal thamaratik qad adraka el-khalas ginsana.\n\nNumaggiduki ayyatuha el-mubaraka ila en-nafas el-akheer li-annaki wagadti ni'ma 'ind ilahik Ibn Allah." },
  ] },
  { id: "vp-the-second-bohairic-interpretation-a", title: "The Second Bohairic Interpretation A", versions: [
    { language: 'coptic', text: "Ⲱⲟⲩ ⲛⲓⲃⲉⲛ ⲛⲉⲙ ⲧⲁⲓⲟ̀ ⲛⲓⲃⲉⲛ: ⲥⲉⲉⲣⲡ̀ⲣⲉⲡⲓ ⲛ̀ϯⲕⲁⲑⲁⲣⲟⲥ: ⲉⲧⲟⲓ ⲙ̀ⲡⲁⲣⲑⲉⲛⲟⲥ ⲛ̀ⲥⲏⲟⲩ ⲛⲓⲃⲉⲛ: Ⲙⲁⲣⲓⲁ ϯⲑⲉⲟ̀ⲧⲟⲕⲟⲥ.\n\nⲦⲉⲛⲉⲣⲙⲁⲕⲁⲣⲓⲍⲓⲛ ⲙ̀ⲙⲟ: ⲛⲉⲙ Ⲅⲁⲃⲣⲓⲏⲗ ⲡⲓⲁⲅⲅⲉⲗⲟⲥ: ϫⲉ ⲭⲉⲣⲉ ⲛⲉ ⲱ̀ ϯⲟⲩⲣⲱ: Ⲡⲟ︦ⲥ︦ ⲛⲉⲙⲉ ⲱ̀ ⲑⲏⲉⲑⲛⲉⲥⲱⲥ.\n\nϪⲉ ⲉ̀ⲃⲟⲗϩⲓⲧⲉⲛ ⲡⲉⲕⲁⲣⲡⲟⲥ: ⲁ̀ⲡⲓⲟⲩϫⲁⲓ ⲧⲁϩⲉ ⲡⲉⲛⲅⲉⲛⲟⲥ: ⲁ̀Ⲫϯ ϩⲟⲧⲡⲉⲛ ⲉ̀ⲣⲟϥ ⲟ̀ⲙⲱⲥ: ϩⲓⲧⲉⲛ ⲧⲉϥⲙⲉⲧⲁ̀ⲅⲁⲑⲟⲥ.\n\nⲦⲉⲛϯⲱⲟⲩ ⲛⲉ ⲱ̀ ⲑⲏⲉ̀ⲧⲉⲛϩⲟⲧ: ⲛⲉⲙ ⲡⲓⲁⲅⲅⲉⲗⲟⲥ ⲛ̀ⲧⲉ ⲡⲓⲥ̀ⲙⲟⲩ: ϫⲉ ⲭⲉⲣⲉ ⲕⲉ ⲭⲁⲣⲓⲧⲱⲙⲉⲛⲏ ⲱ̀ ⲑⲏⲉⲑⲙⲉϩ ⲛ̀ϩⲙⲟⲧ: ⲟⲩⲟϩ Ⲡⲟ︦ⲥ︦ ϣⲟⲡ ⲛⲉⲙⲉ." },
    { language: 'english', text: "All glory and honor, are due to the pure, Virgin at all times, Mary the Theotokos.\n\nWe bless you with, with Gabriel the angel saying, \"Hail to you O queen, the Lord is with you O beautiful one.\"\n\nBecause your yield saved our race, and reconciled us, again with God, out of His goodness.\n\nWe glorify you O trusted one, with the angel of blessing saying, \"Hail to you O full of grace, the Lord is with you.\"" },
    { language: 'arabic', text: "كل مجد وكل كرامة يليق بالنقية العذراء كل حين مريم والدة الإله.\n\nنعطيك الطوبى مع غبريال الملاك. قائلين السلام لك أيتها الملكة الرب معك أيتها الحسنة.\n\nلأن من ثمرتك الخلاص ادرك جنسنا والله قد صالحنا معه بصلاحه.\n\nنمجدك أيتها الأمينة قائلين مع ملاك البركة أفرحي أيتها الممتلئة نعمة . الرب معك." },
    { language: 'englishArabic', text: "Kull magd wa kull karama yaleequ bin-naqiyya el-'Adhra' kull heen Maryam walidat el-Ilah.\n\nNu'teeki et-touba ma'a Ghubriyal el-malak, qa'ileen: es-salam laki ayyatuha el-malika, er-Rabb ma'aki ayyatuha el-hasana.\n\nLi-anna min thamaratik el-khalas adraka ginsana, wa Allah qad salahana ma'ahu bi-salahih.\n\nNumaggiduki ayyatuha el-ameena qa'ileen ma'a malak el-baraka: ifrahi ayyatuha el-mumtali'a ni'ma, er-Rabb ma'aki." },
  ] },
  { id: "vp-the-second-bohairic-interpretation-b", title: "The Second Bohairic Interpretation B", versions: [
    { language: 'coptic', text: "Ⲃⲟⲛ ⲟⲩⲱ̀ϩⲉⲙ ⲛⲓⲃⲉⲛ ⲛ̀ⲛⲓⲉⲕⲕ̀ⲗⲏⲥⲓⲁ̀: ⲛⲉⲙ ⲛⲓϩⲱⲥ ⲛⲉⲙ ⲛⲓⲯⲁⲗⲓⲁ̀: ⲉⲩⲉⲣⲕⲟⲩϫⲓ ⲉϫⲉⲛ Ⲙⲁⲣⲓⲁ: ⲛⲉⲙ ⲡ̀ϭⲓⲥⲓ ⲛ̀ⲧⲉⲥⲇⲟⲝⲁⲥⲓⲁ̀.\n\nϪⲉ ⲉ̀ⲃⲟⲗϩⲓⲧⲉⲛ ⲡⲓⲕⲁⲣⲡⲟⲥ: ϧⲉⲛ ⲧⲉⲥⲛⲉϫⲓ ⲛ̀ⲕⲁⲑⲁⲣⲟⲥ: ⲁϥⲉⲣⲣⲉⲙϩⲉ ⲛ̀ϫⲉ ⲡⲉⲛⲅⲉⲛⲟⲥ: ⲉ̀ⲃⲟⲗϩⲁ ϯⲙⲉⲧⲃⲱⲕ ⲉⲧϩⲱⲟⲩ.\n\nⲦⲉⲛⲉⲣⲙⲁⲕⲁⲣⲓⲍⲓⲛ ⲙ̀ⲙⲟⲥ: ϧⲉⲛ ϩⲁⲛϩⲱⲇⲏ ⲛⲉⲙ ϩⲁⲛϩⲩⲙⲛⲟⲥ: ⲟⲩⲟϩ ⲧⲉⲛⲉ̀ⲣⲉⲧⲓⲛ ⲙ̀ⲙⲟⲥ: ⲉⲑⲣⲉⲥϯϩⲟ ⲉ̀ϩⲣⲏⲓ ⲉ̀ϫⲱⲛ.\n\nⲘⲁⲣⲉⲛϯⲱ̀ⲟⲩ ⲛ̀ϯⲁ̀ⲅⲓⲁ̀: ϧⲉⲛ ϩⲁⲛⲥ̀ⲙⲏ ⲛ̀ⲇⲟⲝⲟⲗⲟⲅⲓⲁ̀: ϫⲉ ⲭⲉⲣⲉ ⲣⲁϣⲓ ⲱ̀ Ⲙⲁⲣⲓⲁ: ⲟ̀ Ⲕⲩⲣⲓⲟⲥ ⲙⲉⲧⲁ ⲥⲟⲩ." },
    { language: 'english', text: "Every hymn in the churches, and praises and songs, they are not enough for Mary, and the greatness of her glory.\n\nFor through the Fruit, of her pure womb, our race was freed, from the bondage of the evil one.\n\nWe bless her, with praises and songs, and ask her, to pray on our behalf.\n\nLet us glorify the saint, in voice of glorification saying, \"Hail to you rejoice O Mary, the Lord is with you.\"" },
    { language: 'arabic', text: "كل مديح الكنائس والتسابيح والتراتيل هي قليلة على مريم وعظم مجدها.\n\nلأن من قبل ثمرة بطنها قد تحرر جنسنا من عبودية الشرير.\n\nنغبطها بتسابيح وتراتيل ونسألها أن تطلب عنا.\n\nفلنمجد القديسة بأصوات التمجيد قائلين السلام أفرحي يا مريم الرب معك." },
    { language: 'englishArabic', text: "Kull madeeh el-kana'is wat-tasabeeh wat-tarateel hiya qaleela 'ala Maryam wa 'izam magdiha.\n\nLi-anna min qibal thamarat batniha qad taharrara ginsana min 'oubudiyyat esh-shirreer.\n\nNughabbituha bi-tasabeeh wa tarateel wa nas'aluha an tatlub 'anna.\n\nFal-numaggid el-qiddeesa bi-aswat et-tamgeed qa'ileen: es-salam, ifrahi ya Maryam er-Rabb ma'aki." },
  ] },
  { id: "vp-the-second-coptic-mo-aqap-interpretation", title: "The Second Coptic Mo-‘aqap Interpretation", versions: [
    { language: 'coptic', text: "Ⲃⲱⲣⲡ ⲛⲏⲓ ⲙ̀ⲡⲉⲕⲛⲓϣϯ ⲛ̀ⲛⲁⲓ: Ⲡⲟ︦ⲥ︦ Ⲫϯ ⲛ̀ⲧⲉ ⲡⲁⲟⲩϫⲁⲓ: ⲟⲩⲇⲉ ⲙ̀ⲡⲉⲣⲭⲁⲣⲱⲕ ⲉ̀ⲣⲟⲓ: ϫⲉ ⲁⲩⲁ̀ϣⲁⲓ ⲛ̀ϫⲉ ⲛⲁⲛⲟⲃⲓ.\n\nϪⲉ ⲁⲩⲁϣⲁⲓ ⲛ̀ϫⲉ ⲛⲁⲛⲟⲃⲓ: ⲙ̀ⲙⲟⲛⲧⲏⲓ ⲛ̀ϩⲁⲛϩ̀ⲃⲏⲟⲩⲓ: ⲉ̀ⲛⲁⲛⲉⲩ ⲛⲉⲙ ϩⲁⲛⲉⲣⲙⲱⲟⲩⲓ̀: ⲙ̀ⲙⲟⲛⲧⲏⲓ ⲛ̀ⲟⲩⲡⲁⲣⲣⲏⲥⲓⲁ.\n\nⲘⲙⲟⲛⲧⲏⲓ ⲛ̀ⲟⲩⲡⲁⲣⲣⲏⲥⲓⲁ: ⲉ̀ⲃⲏⲗ ⲉ̀ϯⲛⲓϣϯ ⲙ̀ⲡ̀ⲣⲉⲥⲃⲓⲁ: ⲛ̀ⲧⲉ ⲧⲁⲟ︦ⲥ︦ ⲛ̀ⲛⲏⲃ Ⲙⲁⲣⲓⲁ: ϯⲥⲉⲙⲛⲉ ⲛ̀ⲕⲁⲑⲁⲣⲟⲥ.\n\nϮⲥⲉⲙⲛⲉ ⲛ̀ⲕⲁⲑⲁⲣⲟⲥ: ⲑⲏⲉ̀ⲧⲁⲩⲟⲩⲱⲣⲡ ϣⲁⲣⲟⲥ: ⲛ̀ϫⲉ Ⲅⲁⲃⲣⲓⲏⲗ ⲡⲓⲁⲅⲅⲉⲗⲟⲥ: ⲁϥⲉⲣⲭⲉⲣⲉⲧⲓⲍⲓⲛ ⲙ̀ⲙⲟⲥ.\n\nⲀϥⲉⲣⲭⲉⲣⲉⲧⲓⲍⲓⲛ ⲙ̀ⲙⲟⲥ: ϧⲉⲛ ⲫ̀ⲣⲁϣⲓ ⲛ̀ⲧⲉ ⲡⲓⲕⲟⲥⲙⲟⲥ: ⲙ̀ⲡⲁⲓⲣⲏϯ ⲉϥϫⲱ ⲙ̀ⲙⲟⲥ: ϫⲉ ⲭⲉⲣⲉ ⲑⲏⲉⲑⲙⲉϩ ⲛ̀ϩ̀ⲙⲟⲧ.\n\nϪⲉ ⲭⲉⲣⲉ ⲑⲏⲉⲑⲙⲉϩ ⲛ̀ϩ̀ⲙⲟⲧ: ⲭⲉⲣⲉ ⲛⲉ ⲱ̀ ⲑⲏⲉ̀ⲧⲉⲛϩⲟⲧ: ϫⲉ ⲁ̀ⲣⲉϫⲓⲙⲓ ⲅⲁⲣ ⲛ̀ⲟⲩϩ̀ⲙⲟⲧ: ϫⲉ ⲁ̀ⲣⲉϥⲁⲓ ϧⲁ ⲡⲓⲗⲟⲅⲟⲥ.\n\nϪⲉ ⲁ̀ⲣⲉϥⲁⲓ ϧⲁ ⲡⲓⲗⲟⲅⲟⲥ: Ⲡϣⲏⲣⲓ ⲛ̀ⲇⲏⲙⲓⲟⲩⲣⲅⲟⲥ: ⲉ̀ⲧⲉ ⲛ̀ⲑⲟϥ ⲡⲉ ⲡⲉⲕⲁⲣⲡⲟⲥ: ⲉ̀ⲧⲁϥⲁⲓⲧⲉⲛ ⲛ̀ⲣⲉⲙϩⲉ.\n\nⲈⲧⲁϥⲁⲓⲧⲉⲛ ⲛ̀ⲣⲉⲙϩⲉ: ⲉ̀ⲃⲟⲗϩⲁ ϯⲙⲉⲧⲃⲱⲕ ⲉⲧϩⲏ: ϫⲉ ⲛ̀ⲑⲟϥ ⲡⲉ Ⲡⲉⲛⲛⲟⲩϯ ⲓⲥϫⲉⲛ ϩⲏ: ⲁ̀ⲣⲉⲙⲁⲥϥ ⲥⲱⲙⲁⲧⲓⲕⲟⲥ.\n\nⲀⲣⲉⲙⲁⲥϥ ⲥⲱⲙⲁⲧⲓⲕⲟⲥ: ϩⲓϫⲉⲛ ⲡⲓⲕⲁϩⲓ ⲁϭⲛⲉ ⲡⲁⲑⲟⲥ: ⲁϥϩⲱⲧⲡ ⲉ̀ⲣⲟⲛ ⲛⲉⲙ ⲛⲉϥⲁⲅⲅⲉⲗⲟⲥ: ⲕⲁⲧⲁ ⲧⲉϥⲙⲉⲧⲁ̀ⲅⲁⲑⲟⲥ.\n\nⲦⲉⲛϯⲱ̀ⲟⲩ ⲛⲉ ⲱ̀ ⲑⲏⲉ̀ⲧⲉⲛϩⲟⲧ: ⲉⲧϥⲁⲓ ϧⲁ ⲡⲓⲗⲟⲅⲟⲥ ⲛ̀ⲧⲉ Ⲫ̀ⲓⲱⲧ: ϫⲉ ⲭⲉⲣⲉ ⲑⲏⲉⲑⲙⲉϩ ⲛ̀ϩ̀ⲙⲟⲧ: ⲟⲩⲟϩ Ⲡⲟ︦ⲥ︦ ϣⲟⲡ ⲛⲉⲙⲉ." },
    { language: 'english', text: "Send me your great mercy, O Lord God of my salvation, and do not abandon me, for my sins are many.\n\nFor my sins are many, and I have no good works, nor tears, for I have no pretext.\n\nFor I have no pretext, without the great intercessions, of my Lady Mary, the chaste and the pure.\n\nThe chaste and the pure, unto whom was sent, Gabriel the angel, and he greeted her.\n\nAnd he greeted her, with the gladness of the world, likewise saying, \"Hail to you O full of grace.\"\n\nHail to you O full of grace, hail to you O faithful one, you have found grace, for you carried the Word.\n\nFor you carried the Word, the Son of the Creator, this is He of your fruit, He saved us.\n\nHe saved us, from the old slavery, for He is our God of old, she gave birth to Him in the flesh.\n\nShe gave birth to Him in the flesh, on earth without pain, and He reconciled us with His angels, according to His goodness.\n\nWe glorify you O faithful one, who carried the Word of the Father, \"Hail to you O full of grace, the Lord is with you.\"" },
    { language: 'arabic', text: "إرسل لي عظيم رحمتك أيها الرب إله خلاصي ولا تسكت عني لأن خطاياي قد كثرت.\n\nلأن خطاياي قد كثرت: وليس لي أعمال صالحة. ولا دموع وليس لي دالة.\n\nوليس لي دالة: إلا عظم شفاعة سيدتي السيدة مرتمريم. العفيفة النقية.\n\nالعفيفة النقية: التي أرسل إليها غبريال الملاك وسلم عليها.\n\nوسلم عليها: بفرح العالم هكذا قائلاً: أفرحي يا ممتلئة نعمة.\n\nافرحي يا ممتلئة نعمة: السلام لك أيتها الأمينة لأنك قد وجدت نعمة لأنك حملت الكلمة.\n\nلأنك حملت الكلمة: الابن الخالق الذي هو ثمرتك الذي جعلنا أحراراً.\n\nالذي جعلنا أحراراً: من العبودية القديمة لأنه هو إلهنا منذ البدء ولدته جسدياً.\n\nولدته جسدياً: على الأرض من غير ألم وصالحنا مع ملائكته. كصلاحه.\n\nنمجدك ايتها الامينة. الحاملة كلمة الأب قائلين إفرحي يا ممتلئة نعمة. الرب معك" },
    { language: 'englishArabic', text: "Irsil li 'azeem rahmatik ayyuha er-Rabb ilah khalasi, wa la taskut 'anni li-anna khatayaya qad katharat.\n\nLi-anna khatayaya qad katharat: wa laysa li a'mal saliha, wa la dumou', wa laysa li dalla.\n\nWa laysa li dalla: illa 'izam shafa'at sayyidati es-sayyida Martmaryam, el-'afeefa en-naqiyya.\n\nEl-'afeefa en-naqiyya: allati arsala ilayha Ghubriyal el-malak wa sallama 'alayha.\n\nWa sallama 'alayha: bi-farah el-'alam hakadha qa'ilan: ifrahi ya mumtali'a ni'ma.\n\nIfrahi ya mumtali'a ni'ma: es-salam laki ayyatuha el-ameena li-annaki qad wagadti ni'ma, li-annaki hamalti el-Kalima.\n\nLi-annaki hamalti el-Kalima: el-Ibn el-khaliq alladhi huwa thamaratuki alladhi ga'alana ahraran.\n\nAlladhi ga'alana ahraran: min el-'oubudiyya el-qadeema, li-annahu huwa ilahuna mundhu el-bad', waladtihi gasadiyyan.\n\nWaladtihi gasadiyyan: 'ala el-ard min ghayr alam, wa salahana ma'a mala'ikatihi ka-salahih.\n\nNumaggiduki ayyatuha el-ameena, el-hamila kalimat el-Ab, qa'ileen: ifrahi ya mumtali'a ni'ma, er-Rabb ma'aki." },
  ] },
  { id: "vp-the-second-egyptian-interpretation", title: "The Second Egyptian Interpretation", versions: [
    { language: 'coptic', text: "Ⲧⲉⲛⲉⲣⲙⲁⲕⲁⲣⲓⲍⲓⲛ ⲛ̀ⲧⲉⲙⲉⲧⲛⲓϣϯ: ⲱ̀ Ⲙⲁⲣⲓⲁ ⲑ̀ⲙⲁⲩ ⲙ̀Ⲫⲛⲟⲩϯ: ϫⲉ ⲁϥϣⲁⲓ ⲛⲁⲛ ⲉ̀ⲃⲟⲗ ⲛ̀ϧⲏϯ: ⲛ̀ϫⲉ ⲡⲓⲧⲁⲗϭⲟ ⲛⲉⲙ ⲡⲓⲥⲱϯ.\n\nⲦⲉⲛⲉⲣⲙⲁⲕⲁⲣⲓⲍⲓⲛ ⲛ̀ⲧⲉⲙⲉⲧⲛⲓϣϯ: ⲱ̀ ϯⲫⲉ ⲙ̀ⲃⲉⲣⲓ ⲉⲧϩⲓϫⲉⲛ ⲡⲓⲕⲁϩⲓ: ϫⲉ ⲁϥϣⲁⲓ ⲛⲁⲛ ⲉ̀ⲃⲟⲗ ⲛ̀ϧⲏϯ: ⲫⲏⲉ̀ⲧⲁϥⲑⲁⲙⲓⲟ ⲛ̀ⲧ̀ⲫⲉ ⲛⲉⲙ ⲡ̀ⲕⲁϩⲓ.\n\nⲦⲉⲛⲉⲣⲙⲁⲕⲁⲣⲓⲍⲓⲛ ⲛ̀ⲧⲉⲙⲉⲧⲛⲓϣϯ: ⲱ̀ ϯⲥⲁⲃⲏ ⲙ̀ⲡⲁⲣⲑⲉⲛⲟⲥ: Ⲡϭⲟⲓⲥ ⲛⲉⲙⲉ ⲙ̀ⲡⲉⲣⲉⲣϩⲟϯ: ⲡⲉϫⲉ ⲡⲓⲁⲣⲭⲏⲁⲅⲅⲉⲗⲟⲥ.\n\nⲦⲉⲛⲉⲣⲙⲁⲕⲁⲣⲓⲍⲓⲛ ⲛ̀ⲧⲉⲙⲉⲧⲛⲓϣϯ: ⲱ̀ ϯⲡⲁⲣⲑⲉⲛⲟⲥ ⲉ̀ⲧⲉⲛϩⲟⲧ: ϫⲉ ⲟⲩϫⲟⲙ ⲛ̀ⲧⲉ Ⲡϭⲟⲓⲥ ⲁϥϣⲱⲡⲓ ⲛ̀ϧⲏϯ: ⲁ̀ⲣⲓϫ̀ⲫⲟ ⲙ̀ⲡⲓⲗⲟⲅⲟⲥ ⲛ̀ⲧⲉ Ⲫ̀ⲓⲱⲧ.\n\nⲦⲉⲛⲉⲣⲙⲁⲕⲁⲣⲓⲍⲓⲛ ⲛ̀ⲧⲉⲙⲉⲧⲛⲓϣϯ: ϫⲉ ⲉ̀ⲃⲟⲗ ϩⲓⲧⲉⲛ Ⲡⲉⲕⲁⲣⲡⲟⲥ: ⲁϥⲓ̀ ⲛ̀ϩ̀ⲙⲟⲧ ⲛⲉⲙ ⲟⲩⲥⲱϯ: ⲛⲉⲙ ⲟⲩϫⲁⲓ ⲧⲁϩⲉ ⲡⲉⲛⲅⲉⲛⲟⲥ.\n\nⲦⲉⲛⲉⲣⲙⲁⲕⲁⲣⲓⲍⲓⲛ ⲛ̀ⲧⲉⲙⲉⲧⲛⲓϣϯ: ⲱ̀ ⲡⲓⲉⲣⲫⲉⲓ ⲛ̀ⲁⲧⲃⲱⲗ ⲉ̀ⲃⲟⲗ: ⲧⲱⲃϩ ⲙ̀Ⲡϭⲟⲓⲥ ⲉⲑⲃⲉ ⲡⲉⲛⲥⲱϯ: ⲛ̀ⲧⲉϥⲭⲁ ⲛⲉⲛⲛⲟⲃⲓ ⲛⲁⲛ ⲉ̀ⲃⲟⲗ.\n\nⲈⲑⲃⲉ ⲫⲁⲓ ⲧⲉⲛϩⲱⲥ ⲉ̀Ⲫⲛⲟⲩϯ: ⲫⲏⲉ̀ⲧⲁϥϭⲓⲥⲁⲣⲝ ⲉ̀ⲃⲟⲗ ⲛ̀ϧⲏϯ: ⲁϥⲉⲣⲣⲱⲙⲓ ⲙ̀ⲡⲉⲛⲣⲏϯ: ϣⲁⲧⲉⲛ ⲫ̀ⲛⲟⲃⲓ ⲙ̀ⲙⲁⲩⲁⲧϥ." },
    { language: 'english', text: "We are blessed by your greatness, O Mary the Mother of God, for out of you healing and salvation, shone upon us.\n\nWe are blessed by your greatness, O new heaven that is on earth, for out of you the Creator of heaven and earth, shone upon us.\n\nWe are blessed by your greatness, O wise Virgin, “The Lord is with you do not fear,” the archangel said.\n\nWe are blessed by your greatness, O trusted Virgin, for the power of God is within you, you bore the Logos of the Father.\n\nWe are blessed by your greatness, for out of your Fruit, came grace and salvation, and the salvation came to our race.\n\nWe are blessed by your greatness, O indestructible sanctuary, ask the Lord for our salvation, and to forgive us our sins.\n\nTherefore we praise God, who was incarnate of you, and became man like us, except for sin alone." },
    { language: 'arabic', text: "نغبط عظمتكِ، يا مريم اُم الله، لأنه أشرق لنا منكِ، الشفاء والخلاص.\n\nنغبط عظمتكِ، أيتها السماء الجديدة التي على الأرض، لأنه أشرق لنا منكِ، الذي خلق السماء والأرض.\n\nنغبط عظمتكِ، أيتها العذراء الحكيمة، \"الرب معكِ لا تخافي،\" قال رئيس الملائكة.\n\nنغبط عظمتكِ، أيتها العذراء الأمينة، لأن قوة الرب صارت فيكِ، ولدتِ الكلمة الذي للآب.\n\nنغبط عظمتكِ، لأن من قِبَل ثمرتكِ، أتت نعمة وخلاص، والخلاص أدرك جنسنا.\n\nنغبط عظمتكِ، أيتها الهيكل غير المنحل، أُطلبي من الرب لأجل خلاصنا، وليغفر لنا خطايانا.\n\nفلهذا نسبِّح الله، الذي تجسَّد منكِ، وصار إنساناً مثلنا، ما خلا الخطية وحدها." },
    { language: 'englishArabic', text: "Nughabbit 'azamatik, ya Maryam umm Allah, li-annahu ashraqa lana minki, esh-shifa' wal-khalas.\n\nNughabbit 'azamatik, ayyatuha es-sama' el-gadeeda allati 'ala el-ard, li-annahu ashraqa lana minki, alladhi khalaqa es-sama' wal-ard.\n\nNughabbit 'azamatik, ayyatuha el-'Adhra' el-hakeema: \"Er-Rabb ma'aki la takhafi,\" qala ra'ees el-mala'ika.\n\nNughabbit 'azamatik, ayyatuha el-'Adhra' el-ameena, li-anna quwwat er-Rabb sarat feeki, waladti el-Kalima alladhi lil-Ab.\n\nNughabbit 'azamatik, li-anna min qibal thamaratik, atat ni'ma wa khalas, wal-khalas adraka ginsana.\n\nNughabbit 'azamatik, ayyatuha el-haykal ghayr el-munhall, utlubi min er-Rabb li-agl khalasina, wa li-yaghfir lana khatayana.\n\nFa-li-hadha nusabbih Allah, alladhi tagassada minki, wa sara insanan mithlana, ma khala el-khatiyya wahdaha." },
  ] },
  { id: "vp-the-second-sahidic-interpretation", title: "The Second Sahidic Interpretation", versions: [
    { language: 'coptic', text: "Ⲃⲟⲛ ⲛⲓⲃⲉⲛ ⲉⲣⲙⲁⲕⲁⲣⲓⲍⲓⲛ: ⲧⲉⲙⲉⲧⲛⲓϣϯ ⲱ̀ Ⲙⲁⲣⲓⲁ: ϫⲉ ⲁⲥⲙ̀ⲡ̀ϣⲁ ⲛ̀ⲭⲱⲣⲉⲩⲓⲛ: ⲉ̀ⲃⲟⲗ ϩⲓⲧⲉⲛ ⲛⲓⲡⲁⲣⲑⲉⲛⲟⲥ.\n\nⲀ̀ ⲡⲓⲟⲩϫⲁⲓ ⲧⲁϩⲟ ⲛ̀ⲭⲱⲗⲉⲙ: ⲉ̀ⲃⲟⲗ ϩⲓⲧⲟϯ ⲱ̀ ϯⲡⲁⲣⲑⲉⲛⲟⲥ: ϫⲉ ⲡⲓⲉ̀ⲥⲱⲟⲩ ⲉⲧⲥⲱⲣⲉⲙ: ⲁⲩⲧⲁⲥⲑⲟϥ ⲉ̀ⲡⲓⲡⲁⲣⲁⲇⲓⲥⲟⲥ.\n\nϤ̀ⲟⲓ ⲛ̀ϣ̀ⲫⲏⲣⲓ ⲁ̀ⲗⲏⲑⲱⲥ: ⲛ̀ϫⲉ ⲫ̀ⲣⲁⲛ ⲛ̀Ⲓⲏⲥⲟⲩⲥ Ⲡⲉⲥϣⲏⲣⲓ: ϫⲉ ⲁϥⲁⲓⲧⲉⲛ ⲙ̀ⲡⲓⲥⲧⲟⲥ: ϧⲉⲛ Ⲧⲉϥⲇⲓⲁⲑⲏⲕⲏ ⲙ̀ⲃⲉⲣⲓ.\n\nⲦⲉⲛϯ ⲛⲉ ⲙ̀ⲡⲓⲭⲉⲣⲉⲧⲓⲥⲙⲟⲥ: ⲱ̀ ϯⲡⲁⲣⲑⲉⲛⲟⲥ ⲛ̀ⲥⲁⲃⲉ: ⲛⲉⲙ Ⲅⲁⲃⲣⲓⲏⲗ ⲡⲓⲁⲅⲅⲉⲗⲟⲥ: ϫⲉ ⲣⲁϣⲓ ⲛⲉ Ⲡϭⲟⲓⲥ ⲛⲉⲙⲉ.\n\nⲈⲑⲃⲉ ⲫⲁⲓ ⲧⲉⲛϯⲱ̀ⲟⲩ ⲛⲉ: ⲉⲛⲱϣ ⲉ̀ⲃⲟⲗ ⲛⲉⲙ Ⲅⲁⲃⲣⲓⲏⲗ: ϫⲉ ⲭⲉⲣⲉ ⲕⲉ ⲭⲁⲣⲓⲧⲱⲙⲉⲛⲏ: Ⲙⲁⲣⲓⲁ ⲑ̀ⲙⲁⲩ ⲛ̀Ⲉⲙⲙⲁⲛⲟⲩⲏⲗ." },
    { language: 'english', text: "Everyone blesses, your greatness O Mary, for you became worthy of praises, from the virgins.\n\nSalvation came quickly, through you O Virgin, for He returned the lost lamb, to the Paradise.\n\nIt is truly wondrous, the name of Jesus her Son, for He made us believers, to His New Covenant.\n\nWe send greetings unto you, O wise Virgin, with Gabriel the angel saying, “Rejoice the Lord is with you.”\n\nTherefore we glorify you, proclaiming with Gabriel, “Hail to you O full of grace, Mary the Mother of Immanuel.”" },
    { language: 'arabic', text: "كل واحد يغبط، عظمتكِ يا مريم، لأنكِ إستحقيتِ المديح، من قِبَل العذارى.\n\nالخلاص قام سريعاً، من قِبَلِك أيتها العذراء، لأنه قد رُدَّ الخروف الضال، إلى الفردوس.\n\nهو عجيب حقيقي، إسم يسوع إبنها، لأنه صيَّرنا مؤمنين، بعهده الجديد.\n\nنعطيكِ السلام، أيتها العذراء الحكيمة، مع غبريال الملاك قائلين، \"الفرح لكِ الرب معكِ.\"\n\nفلهذا نُمجدكِ، ونصرخ مع غبريال قائلين،\"السلام لكِ يا ممتلئة نعمة، مريم اُم عمانوئيل.\"" },
    { language: 'englishArabic', text: "Kull wahid yughabbit, 'azamatiki ya Maryam, li-annaki istahaqqeti el-madeeh, min qibal el-'adhara.\n\nEl-khalas qama saree'an, min qibaliki ayyatuha el-'Adhra', li-annahu qad rudda el-kharouf ed-dall, ila el-firdaws.\n\nHuwa 'ageeb haqeeqi, ism Yasou' ibniha, li-annahu sayyarana mu'mineen, bi-'ahdihi el-gadeed.\n\nNu'teeki es-salam, ayyatuha el-'Adhra' el-hakeema, ma'a Ghubriyal el-malak qa'ileen: \"El-farah laki, er-Rabb ma'aki.\"\n\nFa-li-hadha numaggiduki, wa nasrukh ma'a Ghubriyal qa'ileen: \"Es-salam laki ya mumtali'a ni'ma, Maryam umm 'Emmanu'eel.\"" },
  ] },
  { id: "vp-the-second-hymn-of-abou-el-saad-of-aboutig", title: "The Second Hymn of Abou El-Saad of Aboutig", versions: [
    { language: 'english', text: "I open my mouth with parables / and utter by evening and day / of your glory O Mary / Isaiah has spoken in the prophecy.\n\nA first-born of generations / gives birth to the righteous shepherd / He sent to you with Gabriel / peace, favor and joy.\n\nFor through the One born / of your womb O virgin / the first Adam was restored / to paradise once more.\n\nReconciliation through you came to be / between the world and the Omnipotent / He completed His promised mystery / by the oration of the gospel bearers.\n\nExalted are you and respected / for you became the Mother of our Lord / for through Him the wrath was lifted / from the world and we were spared.\n\nHail to you O mother of mercy / we are your beloved pray acknowledge us / blessed are you O full of grace / before your Son intercede for us." },
    { language: 'arabic', text: "انا افتح فاي بالأمثال / وأنطق كل مساء وصباح / بمجدك يا مريم قد قال / أشعياء في السفر وباح.\n\nبِكر في عقب الاجيال / تلد الراعي أصل كل صلاح / وهو ارسل لكِ مع غبريال / السلام والطوبى والافراح.\n\nلانًّ من قبل المولود / من احشاكِ ايتها العذراء / رجع آدم الاول مردود / الي الفردوس دفعة اخري.\n\nوصار الصلح بك الموجود / بين العالم وصاحب القدرة / وأكمل سره المعهود / علي السنة اصحاب البشري.\n\nعظيمة انتِ ومحترمة / لأنك صرتِ ام بارينا / لأن بإبنك زالت النقمة / عن العالم وانعتقنا.\n\nالسلام لك يا ام الرحمة / نحن عبيدك جيرينا / طوباكِ يا مملوُة نعمة / عند ابنك الحبيب اشفعي فينا." },
    { language: 'englishArabic', text: "Ana aftah fai bil-amthal / wa antiq kull masa' wa sabah / bi-magdiki ya Maryam qad qal / Asha'ya fis-sifr wa bah.\n\nBikr fi 'aqib el-agyal / talid er-ra'i asl kull salah / wa huwa arsala laki ma'a Ghubriyal / es-salam wat-touba wal-afrah.\n\nLi-anna min qibal el-mawloud / min ahsha'iki ayyatuha el-'Adhra' / raga'a Adam el-awwal mardoud / ila el-firdaws daf'a ukhra.\n\nWa sara es-sulh biki el-mawgoud / bayna el-'alam wa sahib el-qudra / wa akmala sirrahu el-ma'houd / 'ala alsinat ashab el-bushra.\n\n'Azeema anti wa muhtarama / li-annaki sirti umm bareena / li-anna bi-ibniki zalat en-niqma / 'an el-'alam wan'ataqna.\n\nEs-salam laki ya umm er-rahma / nahnu 'abeeduki geereena / toubaki ya mamlou'at ni'ma / 'ind ibniki el-habeeb ishfa'i feena." },
  ] },
  { id: "vp-second-hymn-of-cantor-gabriel-of-qay-a", title: "Second Hymn of Cantor Gabriel of Qay A", versions: [
    { language: 'english', text: "All the orders exalt you / and all generations venerate you / and the orders and the authorities / greet you with Gabriel.\n\nGreet you with Gabriel / the great archangel / when the Lord fulfilled His promise perfectly / sent from His good Father.\n\nSent from His good Father / to a virgin called Mary / announcing the incarnation of Jesus / His birth with the great mystery.\n\nHis birth with the great mystery / he came to her saying blessed are you / your Lord sent me to you with peace / choosing you since your infancy.\n\nChoosing you since your infancy / He willed and determined to abide in you / He who created and formed you / will be carried in your arms.\n\nWill be carried in your arms / He who sits upon the creatures; / and who is related to you and called / the barren Elizabeth.\n\nThe barren Elizabeth / today is with child with a renowned boy / for six whole months / for there is no difficult matter for God.\n\nFor there is no difficult matter for God / since anything God wills is to become / believe and accept this news from me / so Mary answered him harmoniously.\n\nMary answered him harmoniously / saying behold the handmaiden of the Lord / let your message be / for in so the Lord willed and was pleased.\n\nFor in so the Lord willed and was pleased / and we all greet you / blessed are you O splendor of all ranks / hail to you and hail unto you.\n\nHail to you and hail unto you, we ask you O Mother of the Beloved, grant us to be in your fathers’ dwellings, Abraham Isaac and Jacob." },
    { language: 'arabic', text: "تعظمك كل الطغمات / وتطوبكِ كل الاجيال / وكل المراتب والقوَّات / تعطيك السلام مع غبريال.\n\nتعطيك السلام مع غبريال / بي نيشتي اِن أرشي انجيلوس / حين تم الاله وعده بكمال / آف اوأورب انجى افيوت بي أغاثوس.\n\nآف اوأورب انجى افيوت بي أغاثوس. / الي عذراء تدعي مريم / يبشرها بحلول إيسوس / وميلاده بالسر الأعظم.\n\nوميلاده بالسر الأعظم / أتاها قائلاً طوباكِ / ربكِ ارسلني لك بسلام / واختارك من سن صباك.\n\nواختارك من سن صباك / شاءَ وأراد ان يسكن فيكِ / الذي خلقَكِ وأَنشاكِ / يصير محمولاً علي ذراعيكِ.\n\nيصير محمولاً علي ذراعيكِ / الجالس فوق الحيوانات / ومن تدعي بالنسب إليك / العاقر أليصابات.\n\nالعاقر أليصابات / اليوم حُبلي بغلام شهير / لها ستة اشهر بثبات / وليس عند الله امر عسير.\n\nوليس عند الله امر عسير / ومهما اراد الرب يكون / صدِّقي واقبلي مني التبشير / فجاوبته مريم باتزان.\n\nفجاوبته مريم باتزان / قائلة هأنذا عبده الرب / كقولك لي يا رسول يكون / لهذا أراد الرب وأحبَّ.\n\nلهذا أراد الرب وأحبَّ / ونحن الكل نحييك / طوباك يا زين كل رتب / السلام لكِ ثم السلام إليك.\n\nالسلام لكِ ثم السلام إليك، ونسألك يا أم المحبوب، ان تحظينا في مظال اباءك، ابراهيم واسحق ويعقوب." },
    { language: 'englishArabic', text: "Tu'azzimuki kull et-tughmat / wa tutawwibuki kull el-agyal / wa kull el-maratib wal-quwwat / tu'teeki es-salam ma'a Ghubriyal.\n\nTu'teeki es-salam ma'a Ghubriyal / Pinishti en-arkhē-aggelos / heena tamma el-Ilah wa'dahu bi-kamal / af-ouōrp enje Efiōt Pi-agathos.\n\nAf-ouōrp enje Efiōt Pi-agathos / ila 'adhra' tud'a Maryam / yubashshiruha bi-houloul Iēsous / wa meeladihi bis-sirr el-a'zam.\n\nWa meeladihi bis-sirr el-a'zam / ataha qa'ilan toubaki / Rabbuki arsalani laki bi-salam / wakhtaraki min sinn sibaki.\n\nWakhtaraki min sinn sibaki / sha'a wa arada an yaskun feeki / alladhi khalaqaki wa ansha'aki / yaseer mahmoulan 'ala dhira'ayki.\n\nYaseer mahmoulan 'ala dhira'ayki / el-galis fawq el-hayawanat / wa man tud'a bin-nasab ilayki / el-'aqir Aleesabat.\n\nEl-'aqir Aleesabat / el-yawm hubla bi-ghulam shaheer / laha sittat ashhur bi-thabat / wa laysa 'ind Allah amr 'aseer.\n\nWa laysa 'ind Allah amr 'aseer / wa mahma arada er-Rabb yakoun / saddiqi waqbali minni et-tabsheer / fa-gawabathu Maryam bi-ittizan.\n\nFa-gawabathu Maryam bi-ittizan / qa'ila ha-anadha 'abdat er-Rabb / ka-qawlika li ya rasoul yakoun / li-hadha arada er-Rabb wa ahabb.\n\nLi-hadha arada er-Rabb wa ahabb / wa nahnu el-kull nuhayyeeki / toubaki ya zayn kull rutab / es-salam laki thumma es-salam ilayki.\n\nEs-salam laki thumma es-salam ilayki, wa nas'aluki ya umm el-mahboub, an tahzeena fi mazall aba'ik, Ibraheem wa Ishaq wa Ya'qoub." },
  ] },
  { id: "vp-the-second-hymn-of-cantor-gabriel-of-qay-b", title: "The Second Hymn of Cantor Gabriel of Qay B", versions: [
    { language: 'english', text: "All the orders exalt you, O Mary the Mother of the Honored One, the Lord of powers sent to you, Gabriel the messenger angel.\n\nWhen He fulfilled His promise in truth, to Adam and fulfilled what was said, and what was written in all prophecies, Moses Isaiah and Ezekiel.\n\n“He who sits above the creatures, will come in the end of generations, be incarnate from the Virgin in truth, and the seal was shut and locked.”\n\nAll of them spoke with these words, and about Mary they gave proverbs, in symbols expressions and visions, true and certain prophecies.\n\nMoses saw a bush in truth, with fire ignited within it, and explained those visions, our honored Master was incarnate.\n\nAnd Ezekiel saw visions, a door highly raised in the east, the Lord of powers entered it, and the door was shut and locked.\n\nHail to you O Mother of our Savior, we ask you O pure Virgin, to ask the Lord to bring us, to the harbor in peace." },
    { language: 'arabic', text: "تعظمكِ كل الطغمات، يا مريم يا اُم ذي الجلال، أرسل لكِ رب القوات، ملاك البُشرى غبريال.\n\nحين أكمل وعده بثبات، إلى آدم وكمل ما قال، وذكروا في كل النبوات، موسى وأشعياء وحزقيال.\n\n\"الجالس فوق المخلوقات، سوف يأتي في عَقِب الأجيال، يتجسد من عذراء بثبات، والختم مصون وعليه أقفال.\"\n\nكل منهم قال كلمات، وعن مريم ضُربت أمثال، رمزاً وعبارة ومثالات، نبوات حق بغير جدال.\n\nموسى عاين عليقة بثبات، في قلبه نار تشعل إشعال، وقد فسَّر تلك الرؤيات، تجسُّد سيدنا ذو الجلال.\n\nوأيضاً حزقيال رأى رؤيات، باباً في المشرق مرتفعاً عال، والداخل فيه رب القوات، باباً مختوم وعليه أقفال.\n\nالسلام لكِ يا اُم مخلصنا، ونسألكِ يا بكر نقية، تسألي الرب أن يوصِّلنا، إلى الميناء بطمأنينة." },
    { language: 'englishArabic', text: "Tu'azzimuki kull et-tughmat, ya Maryam ya umm dhil-galal, arsala laki Rabb el-quwwat, malak el-bushra Ghubriyal.\n\nHeena akmala wa'dahu bi-thabat, ila Adam wa kammala ma qal, wa dhakarou fi kull en-nubouwat, Mousa wa Asha'ya wa Hizqiyal.\n\n\"El-galis fawq el-makhlouqat, sawfa ya'ti fi 'aqib el-agyal, yatagassad min 'adhra' bi-thabat, wal-khatm masoun wa 'alayhi aqfal.\"\n\nKull minhum qala kalimat, wa 'an Maryam duribat amthal, ramzan wa 'ibara wa mithalat, nubouwat haqq bi-ghayr gidal.\n\nMousa 'ayana 'ulleeqa bi-thabat, fi qalbiha nar tash'al ish'al, wa qad fassara tilka er-ru'yat, tagassud sayyidina dhul-galal.\n\nWa aydan Hizqiyal ra'a ru'yat, baban fil-mashriq murtafi'an 'al, wad-dakhil feehi Rabb el-quwwat, baban makhtoum wa 'alayhi aqfal.\n\nEs-salam laki ya umm mukhallisina, wa nas'aluki ya bikr naqiyya, tas'ali er-Rabb an yuwassilana, ila el-meena' bi-tuma'neena." },
  ] },
  { id: "vp-the-second-hymn-of-cantor-gabriel-of-qay-c", title: "The Second Hymn of Cantor Gabriel of Qay C", versions: [
    { language: 'english', text: "All the orders exalt you, O Mary the Mother of the Holy, the Lord of powers sent to you, Gabriel the archangel.\n\nWith peace and blessings and honor, to announce the dwelling of Jesus, in your womb O you who exceeded the orders, and the seal is shut pure and guarded.\n\nAnd the seal is shut pure and guarded, it was covered by the Father’s veil, and you are a virgin and celibate Bride, and the Lord of lords dwelt in you.\n\nHe who sits upon His throne, and in your womb He is covered with a veil, whom the ranks and orders worship, “Holy O Lord and holy.”\n\nHoly O Lord and holy, they sing and chant in tunes, before the throne of the Lord of lords, Jesus the Son of God the Word.\n\nCome O you who are scholars, and praise today with more concern, and bless the Mother of the Father’s only Son, saying “Hail to You O Mother of mercy.”\n\nHail to you O Mother of mercy, blessed are you O full of grace, the Lady of us all Mary, through her prayers and intercessions." },
    { language: 'arabic', text: "تعظمكِ كل الطغمات، يا مريم اُم القدوس، أرسل لكِ رب القوات، غبريال بي أرشي أنجيلوس.\n\nبالسلام والطوبى والكرامات، وبشَّركِ بحلول إيسوس، في أحشائكِ يا مَنْ فُقتِ الطغمات، والخاتم مصون طاهر محروس.\n\nوالخاتم مصون طاهر محروس، مسبول عليه حجاب الآب، وأنتِ عذراء بكر وعروس، وقد حل فيكِ رب الأرباب.\n\nصار جالساً فوق بيف إثرونوس، وفي بطنِك مستور بحجاب، مَنْ تسجد له طغمات وطقوس، \"إكؤواب إبشويس أوؤه إكؤواب.\"\n\nإكؤواب إبشويس أوؤه إكؤواب، ويصيحون بأصوات ونغمة، أمام كرسي رب الأرباب، يسوع إبن الله الكلمة.\n\nتعالوا يا ذوى الألباب، نصيح اليوم بأزيَد هِمَّة، ونُطوِّب اُم وحيد الآب، \"السلام لكِ يا اُم الرحمة.\"\n\nالسلام لكِ يا اُم الرحمة، طوباكِ يا ممتلئة نعمة، أووتين شويس إننيب ماريا، هيتين نيس طوڤه نيم نيس إبريسڤيِّا." },
    { language: 'englishArabic', text: "Tu'azzimuki kull et-tughmat, ya Maryam umm el-quddous, arsala laki Rabb el-quwwat, Ghubriyal Pi-arkhē-aggelos.\n\nBis-salam wat-touba wal-karamat, wa bashsharaki bi-houloul Iēsous, fi ahsha'iki ya man fuqti et-tughmat, wal-khatim masoun tahir mahrous.\n\nWal-khatim masoun tahir mahrous, masboul 'alayhi higab el-Ab, wa anti 'adhra' bikr wa 'arous, wa qad halla feeki Rabb el-arbab.\n\nSara galisan fawq pef-ethronos, wa fi batniki mastour bi-higab, man tasgud lahu tughmat wa touqous: \"Ekouab Eptshois ouoh ekouab.\"\n\nEkouab Eptshois ouoh ekouab, wa yaseehoun bi-aswat wa nagham, amam kursi Rabb el-arbab, Yasou' Ibn Allah el-Kalima.\n\nTa'alou ya dhawi el-albab, nasee'h el-yawm bi-azyad himma, wa nutawwib umm waheed el-Ab: \"Es-salam laki ya umm er-rahma.\"\n\nEs-salam laki ya umm er-rahma, toubaki ya mumtali'a ni'ma, Ouoh ten-tshois ennēb Maria, hiten nes-tovh nem nes-epresvia." },
  ] },
  { id: "vp-the-second-hymn-of-pope-abba-markos-viii", title: "The Second Hymn of Pope Abba Markos VIII", versions: [
    { language: 'english', text: "All the orders exalt you, O Mary the Virgin, you have received every honor, and exceeded the ranks of the angels.\n\nThe Lord of powers commanded Adam, about a tree in Paradise, he disobeyed his Lord and transgressed, through the deception of the defiled Devil.\n\nHe lived in the serpent, the devious one in Paradise, it spoke with temptations, and deceived Eve with tricks saying.\n\n“The God Lord of heavens, commanded you from His holy mouth, do not eat fruits of the tree, but those words are for you foisted.\n\nAnd I say to you indeed, go and eat of those roots, become with Adam gods, like the holy Lord.”\n\nEve was happy by these words, of the mouth of the possessed snake, she was overwhelmed and went to the tree, with their desires they ate the fruit.\n\nHail to you O Lady of virgins, O Mary the Virgin, Jesus Christ dwelt in your womb, and became our Savior." },
    { language: 'arabic', text: "تعظمكِ كل الطغمات، يا مريم تي بارثينوس، قد نلتِ كل الكرامات، وفُقتِ رتب ني أنجيلوس.\n\nآدم أوصاه رب القوات، عن شجرة كانت في الفردوس، خالف ربه وصنع الزلات، بغواية الشيطان المنجوس.\n\nسكن في الحية بخداعات، كانت أحيل مَنْ في الفردوس، فصارت تتكلم بغوايات، وأطغت حواء بحيل وعكوس.\n\nقالت \"الإله رب السموات، أوصاكما من فمه القدوس، لا تأكلا من الشجرة ثمرات، وهذا كلام عندكما مدسوس.\n\nوأنا أقول لكِ حقاً بثبات، أمضيا وكُلا من تلك الغروس، تصيري أنتِ وآدم آلهة، شبيهة بالرب القدوس.\"\n\nفرحت حواء بهذه الكلمات، من فم الثعبان الملبوس، ومضت إلى الشجرة وطغت، وأكلا من الثمرة بشهوات النفوس.\n\nالسلام لكِ يا ست الأبكار، يا مريم تي بارثينوس، يا مَنْ في أحشائكِ قد حلَّ وصار، مخلصنا إيسوس بيخريستوس." },
    { language: 'englishArabic', text: "Tu'azzimuki kull et-tughmat, ya Maryam Tiparthenos, qad nilti kull el-karamat, wa fuqti rutab ni-aggelos.\n\nAdam awsahu Rabb el-quwwat, 'an shagara kanat fil-firdaws, khalafa rabbahu wa sana'a ez-zallat, bi-ghiwayat esh-shaytan el-mangous.\n\nSakana fil-hayya bi-khida'at, kanat ahyal man fil-firdaws, fa-sarat tatakallam bi-ghiwayat, wa atghat Hawwa' bi-hiyal wa 'ukous.\n\nQalat: \"El-Ilah Rabb es-samawat, awsakuma min fammihi el-quddous, la ta'kula min esh-shagara thamarat, wa hadha kalam 'indakuma madsous.\n\nWa ana aqoul laki haqqan bi-thabat, imdiya wa kula min tilka el-ghurous, taseeri anti wa Adam aliha, shabeeha bir-Rabb el-quddous.\"\n\nFarihat Hawwa' bi-hadhihi el-kalimat, min fam eth-thu'ban el-malbous, wa madat ila esh-shagara wa taghat, wa akala min eth-thamara bi-shahawat en-nufous.\n\nEs-salam laki ya sitt el-abkar, ya Maryam Tiparthenos, ya man fi ahsha'iki qad halla wa sar, mukhallisuna Iēsous Pikhristos." },
  ] },
  { id: "vp-the-second-hymn-of-el-bardanohee", title: "The Second Hymn of El-Bardanohee", versions: [
    { language: 'english', text: "We magnify you O Mother of the Light, O Mother of the honored King, you received happiness and joy, which were sent to you from the Father.\n\nThe Being before all ages, sent to you Gabriel, the Logos became sealed in your womb, for nine full and perfect months.\n\nHe fulfilled His promise to Adam, and appeared from you in the end of time, and saved him from his captivity, when he was imprisoned and secured.\n\nWe were saved from all evil, and you fulfilled every proverb, and the Lamp of light shone within us, the eternal and honored Logos.\n\nAnd became seen flesh with us, and taught us the sayings, and took us to the Paradise in happiness, in eternal joy that never fades.\n\nHail to you O Mother of God, ask your Son on our behalf, to forgive us sinners, through your prayers and honored rank." },
    { language: 'arabic', text: "نعظمكِ يا اُم النور، يا والدة الملك ذي الجلال، قد نلتِ فرحاً وسرور، من عند الآب جالِك مرسال.\n\nالكائن قبل كل الدهور، أرسل لكِ غبريال، وصار الكلمة في أحشائكِ مستور، تسعة شهور عدة بكمال.\n\nأوفى لآدم وعده المنظور، وظهر منكِ في عَقِب الأجيال، عتقه بعد أن كان مأسور، مسجون متروس عليه أقفال.\n\nخلصنا من كل شرور، وفسَّرتي كل الأمثال، وأضاء فينا مصباح النور، الكلمة الأزلي ذو الجلال.\n\nوصار بشري معنا منظور، وعلَّمنا وأوضح الأقوال، وأدخلنا الفردوس بسرور، بفرح دائم من غير زوال.\n\nالسلام لكِ يا اُم الإله، جيرينا قدام إبنِك، ليسامحنا نحن الخطاة، بصلاتِك وشرف جنسِك." },
    { language: 'englishArabic', text: "Nu'azzimuki ya umm en-nour, ya walidat el-malik dhil-galal, qad nilti farahan wa sourour, min 'ind el-Ab galiki mirsal.\n\nEl-ka'in qabl kull ed-dohour, arsala laki Ghubriyal, wa sara el-Kalima fi ahsha'iki mastour, tis'at shuhour 'iddatan bi-kamal.\n\nAwfa li-Adam wa'dahu el-manzour, wa zahara minki fi 'aqib el-agyal, 'ataqahu ba'd an kana ma'sour, masgoun matrous 'alayhi aqfal.\n\nKhallasana min kull shurour, wa fassarti kull el-amthal, wa ada'a feena misbah en-nour, el-Kalima el-azali dhul-galal.\n\nWa sara bashari ma'ana manzour, wa 'allamana wa awdaha el-aqwal, wa adkhalana el-firdaws bi-sourour, bi-farah da'im min ghayr zawal.\n\nEs-salam laki ya umm el-Ilah, geereena quddam ibnik, li-yusamihana nahnu el-khutah, bi-salatik wa sharaf ginsik." },
  ] },
  { id: "vp-the-third-greek-interpretation", title: "The Third Greek Interpretation", versions: [
    { language: 'coptic', text: "Ⲣⲁⲙⲁ Ⲫϯ ⲛ̀ⲑⲟ ϩⲱⲓ Ⲙⲁⲣⲓⲁ: ⲡⲉϫⲓⲛⲙⲓⲥⲓ ⲁ̀ⲛⲉⲣⲙⲏ̀ⲛⲉⲩⲧⲟⲥ: ⲱ̀ ϯⲥⲉⲙⲛⲉ ⲙ̀ⲙⲁⲣⲅⲁⲣⲓⲧⲁⲣⲓ̀ⲁ: ⲕⲉ ⲏ̀ ⲕⲟ̀ⲣⲏ Ⲑⲉⲟⲩ ⲡ̀ⲛⲉ̀ⲩⲥⲧⲟⲥ.\n\nϪⲉ ⲁ̀ⲣⲉⲙⲟⲣϯ ϧⲉⲛ ϯⲥⲟⲫⲓⲁ̀: ⲛ̀ⲧⲉ Ⲡⲟ︦ⲥ︦ ⲕⲉ ⲭⲁⲣⲓⲧⲱⲙⲉ̀ⲛⲏ: ⲁ̀ⲣⲉⲙⲁⲥϥ ⲁϭⲛⲉ ⲥⲩⲛⲁ̀ⲫⲓⲁ: ⲧⲉⲡⲁⲣⲑⲉⲛⲓⲁ̀ ⲫⲩⲗⲁⲧⲧⲟⲙⲉ̀ⲛⲏ.\n\nⲆⲓⲁ̀ ⲥⲟⲩ ⲉⲩⲫⲏⲙⲓ̀ⲥⲱⲙⲉⲛ: ⲱ̀ ⲝⲩ̀ⲗⲟⲛ ⲍⲱⲏ̀ⲥ ⲛ̀ⲁ̀ⲇⲟⲗⲟⲥ: ⲕⲉ ⲕ̀ⲣⲁ̀ⲍⲱⲙⲉⲛ ⲉⲩⲫⲩⲓ̀ⲥⲱⲙⲉⲛ: ϧⲉⲛ ⲟⲩⲗⲁⲥ ⲉϥϣⲉⲡϣⲱⲡ ⲉⲩⲗⲁⲗⲟⲥ.\n\nϨⲱⲥ ⲙⲁⲛϣⲉⲗⲉⲧ ⲛ̀ⲁⲧⲧⲁⲕⲟ: ⲁⲠⲓⲡ︦ⲛ︦ⲁ︦ ⲉ︦ⲑ︦ⲩ︦ ⲓ̀ ⲉ̀ⲡⲓⲫ̀ⲟⲓ̀ⲧⲏⲥⲓⲥ: ϫⲉ ⲁ̀ⲣⲉϣⲱⲡⲓ ⲛ̀ⲟⲩⲡ̀ⲣⲟⲥⲧⲟ̀ⲕⲟ: ⲧⲟⲩ ⲕⲟⲥⲙⲟⲩ ⲡⲉⲣⲁ̀ⲧⲱⲛ ⲧⲏⲥ ⲅⲏⲥ.\n\nⲞⲩⲟϩ ⲟⲩϫⲟⲙ ⲛ̀ⲧⲉ ⲫⲏⲉⲧϭⲟⲥⲓ: ⲉⲑⲛⲁⲉⲣϧⲏⲓⲃⲓ ⲉ̀ⲣⲟ Ⲙⲁⲣⲓⲁ: ⲱ̀ ⲗⲩ̀ⲧⲣⲱⲥⲓⲥ ⲛ̀ⲧⲉ ⲛⲏⲉⲧϧⲟⲥⲓ: ⲟⲓ ⲉⲛ ⲫⲓⲗⲁⲕⲏ ⲟⲓ ⲉⲛ ⲝⲟⲣⲓⲁ̀.\n\nϪⲉ ⲁ̀ⲣⲉϫ̀ⲫⲟ ⲙ̀ⲡⲓⲁⲗⲏⲑⲓⲛⲟ̀ⲥ: Ⲩⲓⲟⲥ Ⲑⲉⲟⲥ ⲫⲁ ⲡⲓⲣⲁⲛ ⲉⲧϭⲉϩ: ⲉⲧⲁϥⲛⲁϩⲙⲉⲛ ⲉⲕ ⲧⲱⲛ ⲇⲉⲓⲛⲟ̀ⲥ: ⲫⲱϥ ⲡⲉ ⲡⲓⲱ̀ⲟⲩ ϣⲁ ⲛⲓⲉ̀ⲛⲉϩ.\n\nⲦⲉⲛϯⲱ̀ⲟⲩ ⲛⲉ ⲱ̀ ⲑⲏⲉⲧⲥⲙⲁⲙⲁⲧ: ϣⲁ ⲡⲓⲛⲓϥⲓ ⲛ̀ⲧⲉ ⲗⲉⲩⲧⲉⲟⲥ: ϫⲉ ⲁⲣⲉϫⲓⲙⲓ ⲅⲁⲣ ⲛ̀ⲟⲩϩ̀ⲙⲟⲧ: ϧⲁⲧⲉⲛ Ⲡⲉⲛⲟⲩϯ Ⲩⲓⲟⲥ Ⲑⲉⲟⲥ." },
    { language: 'english', text: "You are God’s chariot O Mary, and your birth is indescribable, O chaste pearl, the girl who is full of God.\n\nFor you were girdled of the wisdom, of God O full of grace, you bore Him without the seed of man, and your virginity is sealed.\n\nBecause of you we praise, the Branch of life, without deception proclaiming, in an elegant tongue and beautiful manner.\n\nAs a bride without blemish, the Holy Spirit came and dwelled on you, for you became the hope, of the world and all the earth.\n\nAnd the power of the Most High overshadowed you, O Mary the rescue of those in tribulations, those who are in prisons, and those who are exiled.\n\nFor you gave birth to the true One, the Son of God of the exalted name, who rescued us from the tribulations, glory be to Him unto the ages.\n\nWe glorify you O blessed one, until the last breath saying, \"You have found favor before, your God the Son of God.\"" },
    { language: 'arabic', text: "أنت هي مركبة الله يا مريم. وميلادك لا يفسر يا جوهرة عفيفة وفتاة متنفسة بالله.\n\nلأنك أشتملت بحكمة الرب ايتها الممتلئة نعمة ولدته بغير مباضعة وبتوليتك محفوظة.\n\nمن أجلك نمدح يا عود الحياة التي بغير غش ونصرخ قائلين بلسان ماهر حسن المنطق.\n\nمثل خدر بغير فساد الروح القدس قد أتي وحل عليك. لأنك صرت رجاء العالم وأقطار الأرض.\n\nوقوة العلي ظللتك يا مريم يا نجاة المتعوبين والذين في السجون والذين في النفي.\n\nلأنك ولدت الحقيقي ابن الله ذو الاسم المرتفع الذي نجانا من المعاطب له المجد إلى الآباد.\n\nنمجدك ايتها المباركة إلى النفس الأخير لأنك وجدت نعمة عند إلهك ابن الله." },
    { language: 'englishArabic', text: "Anti hiya markabat Allah ya Maryam. Wa meeladuki la yufassar ya gawhara 'afeefa wa fatat mutanaffisa billah.\n\nLi-annaki ishtamalti bi-hikmat er-Rabb ayyatuha el-mumtali'a ni'ma, waladtihi bi-ghayr mubada'a wa batouliyyatuki mahfouza.\n\nMin aglik namdah ya 'oud el-hayah allati bi-ghayr ghishsh, wa nasrukh qa'ileen bi-lisan mahir hasan el-mantiq.\n\nMithl khidr bi-ghayr fasad, er-Rouh el-Qudus qad ata wa halla 'alayki, li-annaki sirti raga' el-'alam wa aqtar el-ard.\n\nWa quwwat el-'Ali zallalatki ya Maryam, ya nagat el-mat'oubeen wal-ladheena fis-sougoun wal-ladheena fin-nafy.\n\nLi-annaki waladti el-haqeeqi Ibn Allah dha el-ism el-murtafi', alladhi naggana min el-ma'atib, lahu el-magd ila el-abad.\n\nNumaggiduki ayyatuha el-mubaraka ila en-nafas el-akheer li-annaki wagadti ni'ma 'ind ilahik Ibn Allah." },
  ] },
  { id: "vp-the-third-bohairic-interpretation-a", title: "The Third Bohairic Interpretation A", versions: [
    { language: 'coptic', text: "Ⲁⲗⲏⲑⲱⲥ ⲧⲉⲟⲓ ⲛ̀ϩⲩⲕⲁⲛⲟⲥ: ⲱ̀ ϯϣⲉⲗⲉⲧ ⲙ̀ⲡⲁⲛⲁ̀ⲅⲓⲁ̀: ϫⲉ ⲁⲣⲉϣⲱⲡⲓ ⲛ̀ⲟⲩⲡⲩⲣⲅⲟⲥ: ⲙ̀ⲡⲓⲟⲩⲁⲓ ⲉ̀ⲃⲟⲗϧⲉⲛ ϯⲧ̀ⲣⲓⲁⲥ.\n\nϨⲱⲥ ⲙⲁⲛϣⲉⲗⲉⲧ ⲛ̀ⲁⲧⲧⲁⲕⲟ: ⲁ̀ Ⲡⲓⲡ︦ⲛ︦ⲁ︦ ⲉ︦ⲑ︦ⲩ︦ ⲓ̀ ⲉ̀ϫⲱ: ⲟⲩⲟϩ ⲟⲩϫⲟⲙ ⲛ̀ⲧⲉ ⲫⲏⲉⲧϭⲟⲥⲓ: ⲉⲑⲛⲁⲉⲣϧⲏⲓⲃⲓ ⲉ̀ⲣⲟ Ⲙⲁⲣⲓⲁ.\n\nϪⲉ ⲁ̀ⲣⲉϫ̀ⲫⲟ ⲙ̀ⲡⲓⲁ̀ⲗⲏⲑⲓⲛⲟ̀ⲥ: ⲛ̀ⲗⲟⲅⲟⲥ ⲛ̀ϣⲏⲣⲓ ⲛ̀ⲧⲉ Ⲫ̀ⲓⲱⲧ: Ⲓⲏ︦ⲥ︦ Ⲡⲭ︦ⲥ︦ ⲡⲓⲁⲓⲇⲓⲟⲥ: ⲉⲧⲁϥϣⲱⲡⲓ ⲛⲁⲛ ⲛ̀ⲟⲩⲙⲁⲛⲫⲱⲧ.\n\nⲦⲉⲛϯⲱⲟⲩ ⲛⲉ ⲱ̀ ⲑⲏⲉ̀ⲧⲉⲛϩⲟⲧ: ⲛⲉⲙ ⲡⲓⲁⲅⲅⲉⲗⲟⲥ ⲛ̀ⲧⲉ ⲡⲓⲥ̀ⲙⲟⲩ: ϫⲉ ⲭⲉⲣⲉ ⲕⲉ ⲭⲁⲣⲓⲧⲱⲙⲉⲛⲏ ⲱ̀ ⲑⲏⲉⲑⲙⲉϩ ⲛ̀ϩⲙⲟⲧ: ⲟⲩⲟϩ Ⲡⲟ︦ⲥ︦ ⲛⲉⲙⲉ." },
    { language: 'english', text: "Truly you are more worthy, O all-holy bride, for you became a palace, to One of the Trinity.\n\nLike a bride without blemish, the Holy Spirit dwelled in you, and the power of the High One, overshadowed you O Mary.\n\nFor you have borne the true One, the Word of the Father, Jesus Christ himself, who became for us a help.\n\nWe glorify you O trusted one, with the angel of blessing saying, \"Hail to you O full of grace, the Lord is with you.\"" },
    { language: 'arabic', text: "حقاً استوجبت ايتها العروسة ذات كل قدس لأنك صرت قصرا للواحد من الثالوث\n\nمثل عروس بغير فساد. الروح القدس حل عليك وقوة العلي تظللك يا مريم.\n\nلأنك ولدت الحقيقي الكلمة ابن الاب يسوع المسيح الأزلي الذي صار لنا ملجاء.\n\nنمجدك أيتها الأمينة قائلين مع ملاك البركة أفرحي أيتها الممتلئة نعمة . الرب معك." },
    { language: 'englishArabic', text: "Haqqan istawgabti ayyatuha el-'arousa dhat kull quds, li-annaki sirti qasran lil-wahid min eth-thalouth.\n\nMithl 'arous bi-ghayr fasad, er-Rouh el-Qudus halla 'alayki wa quwwat el-'Ali tuzalliluki ya Maryam.\n\nLi-annaki waladti el-haqeeqi el-Kalima Ibn el-Ab Yasou' el-Maseeh el-azali alladhi sara lana malga'an.\n\nNumaggiduki ayyatuha el-ameena qa'ileen ma'a malak el-baraka: ifrahi ayyatuha el-mumtali'a ni'ma, er-Rabb ma'aki." },
  ] },
  { id: "vp-the-third-bohairic-interpretation-b", title: "The Third Bohairic Interpretation B", versions: [
    { language: 'coptic', text: "Ⲅⲁⲃⲣⲓⲏⲗ ⲡⲓϥⲁⲓϣⲉⲛⲛⲟⲩϥⲓ: ⲡⲓⲣⲉϥⲁ̀ⲙⲟⲛⲓ ⲛ̀ϯⲥⲏϥⲓ: ⲛ̀ⲑⲟϥ ⲅⲁⲣ ⲁϥϩⲓϣⲉⲛⲛⲟⲩϥⲓ: ⲉ̀Ⲙⲁⲣⲓⲁ ϯⲟⲩⲣⲱ.\n\nϪⲉ ⲭⲉⲣⲉ ⲕⲉ ⲭⲁⲣⲓⲧⲱⲙⲉⲛⲏ: ⲧⲉⲥ̀ⲙⲁⲣⲱⲟⲩⲧ ϧⲉⲛ ⲛϩⲓⲟ̀ⲙⲓ: ⲱ̀ ⲡ̀ϣⲟⲩϣⲟⲩ ϯⲟⲓⲕⲟⲩⲙⲉⲛⲏ: ⲟ̀ Ⲕⲩⲣⲓⲟⲥ ⲉⲧⲁ ⲥⲟⲩ.\n\nⲚⲑⲟ ⲡⲉ ⲡⲓⲙⲁⲛϣⲉⲗⲉⲧ: ⲛ̀ⲧⲉ Ⲫϯ ⲡⲓⲣⲉϥϣⲉⲛϩⲏⲧ: ⲟⲩⲟϩ ⲧⲉⲥⲩⲅⲅⲉⲛⲏⲥ Ⲉ̀ⲗⲏⲥⲁⲃⲉⲧ: Ⲡⲓⲡ︦ⲛ︦ⲁ︦ ⲉ︦ⲑ︦ⲩ︦ ⲓ̀ ⲉ̀ϫⲱ.\n\nⲘⲁⲣⲉⲛϯⲱ̀ⲟⲩ ⲛ̀ϯⲁ̀ⲅⲓⲁ̀: ϧⲉⲛ ϩⲁⲛⲥ̀ⲙⲏ ⲛ̀ⲇⲟⲝⲟⲗⲟⲅⲓⲁ̀: ϫⲉ ⲭⲉⲣⲉ ⲣⲁϣⲓ ⲱ̀ Ⲙⲁⲣⲓⲁ: ⲟ̀ Ⲕⲩⲣⲓⲟⲥ ⲙⲉⲧⲁ ⲥⲟⲩ." },
    { language: 'english', text: "Gabriel the announcer, the bearer of the sword, he also announced to, Mary the queen saying.\n\n\"Hail to you O full of grace, blessed are you among women, O bride of the world, the Lord is with you.\"\n\nYou are the bride, of God the Compassionate, and your relative Elizabeth, the Holy Spirits dwells in you.\n\nLet us glorify the saint, in voice of glorification saying, \"Hail to you rejoice O Mary, the Lord is with you.\"" },
    { language: 'arabic', text: "غبريال المبشر الماسك السيف هو بشر أيضاً مريم الملكة قائلاً\n\nافرحي يا ممتلئة نعمة مباركة أنت في النساء يا فخر المسكونة الرب معك.\n\nانت هي عروسة الله الرؤوف ونسيبتك اليصابات الروح القدس يحل عليك\n\nفلنمجد القديسة بأصوات التمجيد قائلين السلام أفرحي يا مريم الرب معك." },
    { language: 'englishArabic', text: "Ghubriyal el-mubashshir el-masik es-sayf huwa bashshara aydan Maryam el-malika qa'ilan:\n\nIfrahi ya mumtali'a ni'ma, mubaraka anti fin-nisa', ya fakhr el-maskouna, er-Rabb ma'aki.\n\nAnti hiya 'arousat Allah er-ra'ouf, wa naseebatuki Aleesabat, er-Rouh el-Qudus yahillu 'alayki.\n\nFal-numaggid el-qiddeesa bi-aswat et-tamgeed qa'ileen: es-salam, ifrahi ya Maryam er-Rabb ma'aki." },
  ] },
  { id: "vp-the-third-coptic-mo-aqap-interpretation", title: "The Third Coptic Mo-‘aqap Interpretation", versions: [
    { language: 'coptic', text: "Ⲅⲉ ⲅⲁⲣ ⲛ̀ⲑⲟⲕ ⲟⲩⲣⲉϥϣⲉⲛϩⲏⲧ: Ⲡⲟ︦ⲥ︦ Ⲫϯ ⲡⲓⲛⲁⲏⲧ: ⲁ̀ⲛⲟⲕ ⲟⲩⲣⲱⲙⲓ ⲛ̀ⲁⲧϩⲏⲧ: ⲟⲩⲣⲉϥⲉⲣⲛⲟⲃⲓ ⲉ̀ⲙⲁϣⲱ.\n\nⲞⲩⲣⲉϥⲉⲣⲛⲟⲃⲓ ⲉ̀ⲙⲁϣⲱ: ⲉϥⲙⲉϩ ⲙ̀ⲙⲉⲧⲣⲉϥϩⲓⲡ̀ϩⲟ: ⲁⲗⲗⲁ ⲁⲓⲭⲁϩ̀ⲑⲏⲓ ⲉ̀ⲡⲉⲕϩⲟ: ⲙⲟⲓ ⲛⲏⲓ ⲛ̀ⲟⲩⲙⲉⲧⲁ̀ⲛⲟⲓⲁ.\n\nⲘⲟⲓ ⲛⲏⲓ ⲛ̀ⲟⲩⲙⲉⲧⲁ̀ⲛⲟⲓⲁ: ⲟⲩⲟϩ ⲥⲱⲗϫ ⲛ̀ⲛⲁⲁ̀ⲛⲟⲙⲓⲁ̀: ϩⲓⲧⲉⲛ ⲡⲓϣ̀ⲗⲏⲗ ⲛ̀ϯⲁ̀ⲅⲓⲁ: ϯϣⲉⲗⲉⲧ ⲛ̀ⲁⲧⲅⲁⲙⲟⲥ.\n\nϮϣⲉⲗⲉⲧ ⲛ̀ⲁⲧⲅⲁⲙⲟⲥ: ⲉ̀ⲧⲁ Ⲡⲓⲡ︦ⲛ︦ⲁ︦ ⲙ̀ⲡⲁⲣⲁⲕⲗⲏⲧⲟⲛ: ⲓ̀ ⲉ̀ϫⲱⲥ ⲁϥⲥⲟⲃϯ ⲙ̀ⲙⲟⲥ: ⲉ̀ⲟⲩⲙⲁⲛ̀ϣⲱⲡⲓ ⲛ̀ⲧⲉ ⲡⲓⲛⲩⲙⲫⲓⲟⲥ.\n\nⲈⲟⲩⲙⲁⲛ̀ϣⲱⲡⲓ ⲛ̀ⲧⲉ ⲡⲓⲛⲩⲙⲫⲓⲟⲥ: ⲉ̀ⲧⲉ ⲛ̀ⲑⲟϥ ⲡⲉ ⲡⲓⲗⲟⲅⲟⲥ: Ⲡⲉⲛⲛⲟⲩϯ ⲛ̀ⲁ̀ⲗⲏⲑⲓⲛⲟⲥ: ⲫ̀ⲣⲉϥⲑⲁⲙⲓⲟ ⲛ̀ⲛⲓⲭ̀ⲣⲟⲛⲟⲥ.\n\nⲪⲣⲉϥⲑⲁⲙⲓⲟ ⲛ̀ⲛⲓⲭ̀ⲣⲟⲛⲟⲥ: ⲁϥⲓ̀ ⲁϥⲉⲣⲥⲱⲙⲁⲧⲓⲕⲟⲥ: ϣⲁ ⲛ̀ⲧⲉϥⲛⲁϩⲙⲉⲛ ϧⲁ ⲡⲉϥⲗⲁⲟⲥ: ϫⲉ ⲛ̀ⲑⲟϥ ⲡⲉ Ⲡⲉⲛⲟⲩⲣⲟ.\n\nϪⲉ ⲛ̀ⲑⲟϥ ⲡⲉ Ⲡⲉⲛⲟⲩⲣⲟ: ⲙ̀ⲙⲟⲛ ϧⲁⲉ̀ ⲉ̀ⲧⲉϥⲙⲉⲧⲟⲩⲣⲟ: ⲉϥⲙⲏⲛ ⲉ̀ⲃⲟⲗ ⲉϥⲉ̀ⲣⲟⲩⲣⲟ: ⲉ̀ϫⲉⲛ ⲡ̀ⲏⲓ ⲛ̀Ⲓⲁⲕⲱⲃ ϣⲁ ⲉ̀ⲛⲉϩ.\n\nⲦⲉⲛϯⲱ̀ⲟⲩ ⲛⲉ ⲱ̀ ⲑⲏⲉ̀ⲧⲉⲛϩⲟⲧ: ⲉⲧϥⲁⲓ ϧⲁ ⲡⲓⲗⲟⲅⲟⲥ ⲛ̀ⲧⲉ Ⲫ̀ⲓⲱⲧ: ϫⲉ ⲭⲉⲣⲉ ⲑⲏⲉⲑⲙⲉϩ ⲛ̀ϩ̀ⲙⲟⲧ: ⲟⲩⲟϩ Ⲡⲟ︦ⲥ︦ ⲛⲉⲙⲉ." },
    { language: 'english', text: "For You are merciful, O Lord God the compassionate, I am an ignorant man, and a very sinful one.\n\nAnd a very sinful one, full of hypocrisy, I take refuge in You, grant me repentance.\n\nGrant me repentance, for my iniquities, through the prayers of the holy, the pure bride.\n\nThe pure bride, over whom the Spirit came, He prepared her to be, a place for the bridegroom.\n\nA place for the bridegroom, which is the Word, our true God, the Creator of the ages.\n\nThe Creator of the ages, came and took flesh, to save us His people, for He is our King.\n\nFor He is our King, and His kingdom shall have no end, He will always reign, over the house of Jacob forever.\n\nWe glorify you O faithful one, who carried the Word of the Father, \"Hail to you O full of grace, the Lord is with you.\"" },
    { language: 'arabic', text: "لأنك أنت متحنن أيها الرب الإله الرحوم وأنا انسان جاهل وخاطئ جداً.\n\nوخاطئ جداً ومملوء نفاقا لكني توكلت على وجهك اعطني توبة.\n\nأعطني توبة: وامح آثامي بصلاة القديسة العروس التي بغير زواج.\n\nالعروس التي بغير زواج: التي الروح المعزي حل عليها وأعدها مسكنا للختن.\n\nمسكناً للختن: الذي هو الكلمة إلهنا الحقيقي خالق الدهور.\n\nخالق الدهور: أتي وتجسد حتى نجانا نحن شعبه لأنه هو ملكنا.\n\nلأنه هو ملكنا: وليس لملكه انقضاء دائما يملك على ببيت يعقوب إلى الأبد.\n\nنمجدك ايتها الامينة. الحاملة كلمة الأب قائلين إفرحي يا ممتلئة نعمة. الرب معك" },
    { language: 'englishArabic', text: "Li-annaka anta mutahannin ayyuha er-Rabb el-Ilah er-rahoum, wa ana insan gahil wa khati' giddan.\n\nWa khati' giddan wa mamlou' nifaqan, lakinni tawakkaltu 'ala waghik, a'tini tawba.\n\nA'tini tawba: wamhu athami bi-salat el-qiddeesa el-'arous allati bi-ghayr zawag.\n\nEl-'arous allati bi-ghayr zawag: allati er-Rouh el-mu'azzi halla 'alayha wa a'addaha maskanan lil-khatan.\n\nMaskanan lil-khatan: alladhi huwa el-Kalima ilahuna el-haqeeqi khaliq ed-dohour.\n\nKhaliq ed-dohour: ata wa tagassada hatta naggana nahnu sha'bahu li-annahu huwa malikuna.\n\nLi-annahu huwa malikuna: wa laysa li-mulkihi inqida', da'iman yamliku 'ala bayt Ya'qoub ila el-abad.\n\nNumaggiduki ayyatuha el-ameena, el-hamila kalimat el-Ab, qa'ileen: ifrahi ya mumtali'a ni'ma, er-Rabb ma'aki." },
  ] },
  { id: "vp-the-third-egyptian-interpretation", title: "The Third Egyptian Interpretation", versions: [
    { language: 'coptic', text: "Ϩⲱⲥ ⲙⲁⲛ̀ϣⲉⲗⲉⲧ ⲛ̀ⲁⲧⲧⲁⲕⲟ: ⲁ̀ Ⲡⲓⲡ̀ⲛⲉⲩⲙⲁ ⲉⲑⲟⲩⲁⲃ ⲙ̀ⲡⲁⲣⲁⲕⲗⲏⲧⲟⲛ: ⲓ̀ ⲉ̀ϫⲱ ⲁϥⲥⲟⲃϯ ⲙ̀ⲙⲟ: ⲉ̀ⲟⲩⲙⲁ ⲛ̀ϣⲱⲡⲓ ⲛ̀ⲧⲉ ⲡⲓⲛⲩⲙⲫⲓⲟⲥ.\n\nϨⲱⲥ ⲙⲁⲛ̀ϣⲉⲗⲉⲧ ⲛ̀ⲁⲧⲧⲁⲕⲟ: ϫⲉ ⲁ̀ⲣⲉϫ̀ⲫⲟ ⲙ̀ⲡⲓⲁ̀ⲗⲏⲑⲓⲛⲟⲥ: ⲛ̀ⲗⲟⲅⲟⲥ ⲛ̀Ϣⲏⲣⲓ ⲛ̀ⲧⲉ Ⲫ̀ⲓⲱⲧ: ⲛ̀ⲣⲉϥⲧⲁⲛϧⲟ ⲛ̀ⲟⲩⲙⲟⲟⲩⲥⲓⲟⲥ.\n\nϨⲱⲥ ⲙⲁⲛ̀ϣⲉⲗⲉⲧ ⲛ̀ⲁⲧⲧⲁⲕⲟ: ⲱ̀ Ⲙⲁⲣⲓⲁ ϯⲟⲩⲣⲱ: ⲟⲩϫⲟⲙ ⲛ̀ⲧⲉ Ⲫⲏⲉⲧϭⲟⲥⲓ ⲉⲑⲛⲁⲉⲣϧⲏⲓⲃⲓ ⲉ̀ⲣⲟ: ϫⲉ ⲫⲏⲉ̀ⲧⲁⲣⲉⲙⲁⲥϥ ⲟⲩⲣⲉϥϭⲣⲟ ⲡⲉ.\n\nϨⲱⲥ ⲙⲁⲛ̀ϣⲉⲗⲉⲧ ⲛ̀ⲁⲧⲧⲁⲕⲟ: ⲛⲉⲙ ⲟⲩⲙⲁ ⲛ̀ⲣⲉϥⲭⲁ ⲛⲟⲃⲓ ⲉ̀ⲃⲟⲗ: ⲁϥⲧ̀ⲥⲁⲃⲟⲛ ⲙ̀ⲡ̀ⲧⲁⲕⲟ: ⲡⲓⲁⲣⲭⲏ ⲛⲉⲙ ⲡⲓϫⲱⲕ ⲉ̀ⲃⲟⲗ.\n\nϨⲱⲥ ⲙⲁⲛ̀ϣⲉⲗⲉⲧ ⲛ̀ⲁⲧⲧⲁⲕⲟ: ⲱ̀ Ⲙⲁⲣⲓⲁ ϯⲑⲉⲟ̀ⲧⲟⲕⲟⲥ: ϫⲉ ⲁ̀ⲣⲉⲙⲓⲥⲓ ⲙ̀ⲡⲓⲙⲟⲛⲟⲅⲉⲛⲏⲥ: ⲡⲓⲟⲩⲣⲟ Ⲡϭⲟⲓⲥ ⲛ̀ϯⲕ̀ⲧⲏⲥⲓⲥ.\n\nϨⲱⲥ ⲙⲁⲛ̀ϣⲉⲗⲉⲧ ⲛ̀ⲁⲧⲧⲁⲕⲟ: ⲁ̀ ⲡⲓⲇⲏⲙⲓⲟⲩⲣⲅⲟⲥ ϣⲉⲡ ⲙ̀ⲙⲟⲥ: ⲟⲩⲟϩ ⲁϥϣⲱⲡⲓ ⲥⲁϧⲟⲩⲛ ⲙ̀ⲙⲟⲥ: ⲁϥⲛⲁϩⲙⲉⲛ ⲉ̀ⲃⲟⲗ ϩⲁ ⲡⲓⲣⲉϥⲧⲁⲕⲟ.\n\nⲈⲑⲃⲉ ⲫⲁⲓ ⲧⲉⲛϩⲱⲥ ⲉ̀Ⲫⲛⲟⲩϯ: ⲫⲏⲉ̀ⲧⲁϥϭⲓⲥⲁⲣⲝ ⲉ̀ⲃⲟⲗ ⲛ̀ϧⲏϯ: ⲁϥⲉⲣⲣⲱⲙⲓ ⲙ̀ⲡⲉⲛⲣⲏϯ: ϣⲁⲧⲉⲛ ⲫ̀ⲛⲟⲃⲓ ⲙ̀ⲙⲁⲩⲁⲧϥ." },
    { language: 'english', text: "Like a bridal chamber without blemish, the Holy Spirit of comfort, came upon you and prepared you, as a dwelling for the Bridegroom.\n\nLike a bridal chamber without blemish, you gave birth to the True One, the Logos Son of the Father, the Life-Giver and co-essential.\n\nLike a bridal chamber without blemish, O Mary the Queen, the power of the Most High overshadow you, for He whom you bore is the Victorious.\n\nLike a bridal chamber without blemish, and the place of forgiveness, He taught us about destruction, from its beginning to end.\n\nLike a bridal chamber without blemish, O Mary the Theotokos, for you have given birth to the only-begotten, the King the Lord of all the creation.\n\nLike a bridal chamber without blemish, the Creator accepted her, and dwelt in her, and delivered us from destruction.\n\nTherefore we praise God, who was incarnate of you, and became man like us, except for sin alone." },
    { language: 'arabic', text: "كخدر بغير فساد، الروح القدس المعزي، حل عليكِ وأعدكِ، مسكناً للختن.\n\nكخدر بغير فساد، ولدتِ الحقيقي، الكلمة إبن الآب، المحيي المساوي في الجوهر.\n\nكخدر بغير فساد، يا مريم الملكة، وقوة العليْ تظللكِ، لأن الذي ولدتِه هو الغالب.\n\nكخدر بغير فساد، وموضع الغفران، قد عرَّفنا الضرر، من البداية إلى النهاية.\n\nكخدر بغير فساد، يا مريم والدة الإله، لأنكِ ولدتِ الوحيد، الملك رب كل الخليقة.\n\nكخدر بغير فساد، الخالق قد قَبِلَها، وسكن فيها، ونجانا من المهلك.\n\nفلهذا نسبِّح الله، الذي تجسَّد منكِ، وصار إنساناً مثلنا، ما خلا الخطية وحدها." },
    { language: 'englishArabic', text: "Ka-khidr bi-ghayr fasad, er-Rouh el-Qudus el-mu'azzi, halla 'alayki wa a'addaki, maskanan lil-khatan.\n\nKa-khidr bi-ghayr fasad, waladti el-haqeeqi, el-Kalima Ibn el-Ab, el-muhyi el-musawi fil-gawhar.\n\nKa-khidr bi-ghayr fasad, ya Maryam el-malika, wa quwwat el-'Ali tuzalliluki, li-anna alladhi waladtihi huwa el-ghalib.\n\nKa-khidr bi-ghayr fasad, wa mawdi' el-ghufran, qad 'arrafana ed-darar, min el-bidaya ila en-nihaya.\n\nKa-khidr bi-ghayr fasad, ya Maryam walidat el-Ilah, li-annaki waladti el-waheed, el-malik Rabb kull el-khaleeqa.\n\nKa-khidr bi-ghayr fasad, el-khaliq qad qabilaha, wa sakana feeha, wa naggana min el-muhlik.\n\nFa-li-hadha nusabbih Allah, alladhi tagassada minki, wa sara insanan mithlana, ma khala el-khatiyya wahdaha." },
  ] },
  { id: "vp-the-third-sahidic-interpretation", title: "The Third Sahidic Interpretation", versions: [
    { language: 'coptic', text: "Ϣⲟⲙⲧ ⲛ̀Ϯⲧ̀ⲣⲓⲁⲥ ⲉⲑⲟⲩⲁⲃ: Ⲡⲉⲛⲛⲟⲩϯ ϧⲁ ⲛⲓⲡⲓⲥⲧⲟⲥ: ⲙⲁⲣⲉⲛϫⲟⲥ ϫⲉ ⲭ̀ⲟⲩⲁⲃ ⲭ̀ⲟⲩⲁⲃ: ⲭ̀ⲟⲩⲁⲃ ⲡⲓⲁ̀ⲭⲱⲣⲓⲧⲟⲥ.\n\nⲠⲓⲟⲩⲁⲓ ⲉ̀ⲃⲟⲗ ϧⲉⲛ Ϯⲧ̀ⲣⲓⲁⲥ: ⲁϥϭⲓⲥⲁⲣⲝ ϧⲉⲛ ϯⲡⲁⲣⲑⲉⲛⲟⲥ: ⲛ̀ⲑⲟϥ ⲡⲉ Ⲓⲏⲥⲟⲩⲥ Ⲙⲁⲥⲓⲁⲥ: ϣⲁ ⲛ̀ⲧⲉϥⲥⲱϯ ⲙ̀ⲡⲉⲛⲅⲉⲛⲟⲥ.\n\nⲠⲓⲙⲁ ⲛ̀ϣⲉⲗⲉⲧ ⲛ̀ⲕⲁⲑⲁⲣⲟⲥ: Ⲙⲁⲣⲓⲁ ϯⲑⲉⲟ̀ⲧⲟⲕⲟⲥ: ⲁ̀ Ⲡⲓⲡ̀ⲛⲉⲩⲙⲁ ⲙ̀ⲡⲁⲣⲁⲕⲗⲏⲧⲟⲛ: ⲙⲁϩⲧⲉⲛ ⲙ̀ⲡⲁⲣⲑⲉⲛⲓⲕⲟⲥ.\n\nⲰⲟⲩⲛⲓⲁⲧϥ ⲙ̀ⲡⲓⲗⲁⲟⲥ: ⲉ̀ⲧⲉ ⲫ̀ⲣⲁⲛ ⲙ̀Ⲡϣⲏⲣⲓ ϧⲉⲛ ⲣⲱⲟⲩ: ⲉϥⲉ̀ϣⲱⲡⲓ ⲛ̀ⲕ̀ⲗⲏⲣⲟⲛⲟⲙⲟⲥ: ϧⲉⲛ ⲑ̀ⲙⲉⲧⲟⲩⲣⲟ ⲙ̀ⲡⲉϥⲱ̀ⲟⲩ.\n\nⲈⲑⲃⲉ ⲫⲁⲓ ⲧⲉⲛϯⲱ̀ⲟⲩ ⲛⲉ: ⲉⲛⲱϣ ⲉ̀ⲃⲟⲗ ⲛⲉⲙ Ⲅⲁⲃⲣⲓⲏⲗ: ϫⲉ ⲭⲉⲣⲉ ⲕⲉ ⲭⲁⲣⲓⲧⲱⲙⲉⲛⲏ: Ⲙⲁⲣⲓⲁ ⲑ̀ⲙⲁⲩ ⲛ̀Ⲉⲙⲙⲁⲛⲟⲩⲏⲗ." },
    { language: 'english', text: "Three is the Holy Trinity, our God we the believers, let us say “Holy holy, holy is the Infinite One.”\n\nThe One of the Trinity, was incarnate of the Virgin, He is Jesus the Messiah, that He may save our race.\n\nThe pure bridal chamber, Mary the Theotokos, the Spirit of comfort, filled us with celibacy.\n\nBlessed are the people, that the name of the Son is in their mouths, for they will become heirs, in the kingdom of His glory.\n\nTherefore we glorify you, proclaiming with Gabriel, “Hail to you O full of grace, Mary the Mother of Immanuel.”" },
    { language: 'arabic', text: "ثلاثة هو الثالوث القدوس، إلهنا نحن المؤمنين، فلنقل قدوس قدوس، قدوس غير المحوى.\n\nالواحد من الثالوث، تجسد من العذراء، الذي هو يسوع ماسيا، حتى خلَّص جنسنا.\n\nالخدر الطاهرة، مريم والدة الإله، الروح المعزي، قد ملأنا بالبتولية.\n\nطوبى للشعب الذي، إسم الإبن في أفواههم، فإنه يكون وارثاً، في ملكوت مجده.\n\nفلهذا نُمجدكِ، ونصرخ مع غبريال قائلين،\"السلام لكِ يا ممتلئة نعمة، مريم اُم عمانوئيل.\"" },
    { language: 'englishArabic', text: "Thalatha huwa eth-thalouth el-quddous, ilahuna nahnu el-mu'mineen, fal-naqoul quddous quddous, quddous ghayr el-muhwa.\n\nEl-wahid min eth-thalouth, tagassada min el-'Adhra', alladhi huwa Yasou' Massia, hatta khallasa ginsana.\n\nEl-khidr et-tahira, Maryam walidat el-Ilah, er-Rouh el-mu'azzi, qad mala'ana bil-batouliyya.\n\nTouba lish-sha'b alladhi, ism el-Ibn fi afwahihim, fa-innahu yakoun warithan, fi malakout magdih.\n\nFa-li-hadha numaggiduki, wa nasrukh ma'a Ghubriyal qa'ileen: \"Es-salam laki ya mumtali'a ni'ma, Maryam umm 'Emmanu'eel.\"" },
  ] },
  { id: "vp-the-third-hymn-of-abou-el-saad-of-aboutig", title: "The Third Hymn of Abou El-Saad of Aboutig", versions: [
    { language: 'english', text: "Like an unblemished bride / you received the Holy Spirit unto you / the omnipotent Lord willed and desired / to be carried upon your arms.\n\nHe put on flesh like all flesh / and came to be nursed from your milk / and after the birth had taken place / you were a virgin and the words were fulfilled.\n\nFor you bore the only-begotten of the Father / who was born before all ages / the perpetual One of all times / true God of true God Light of Light.\n\nCome and behold O you wise / how the invisible appeared / and how the revered wondrous mighty One / was carried by Mary the Virgin for nine months.\n\nCome let us ask the God of greatness / for His great goodness to give us / a peaceful and wholesome life / and save us from the enemies’ snares.\n\nHail to you O mother of mercy / we are your beloved pray acknowledge us / blessed are you O full of grace / before your Son intercede for us." },
    { language: 'arabic', text: "مثل عروسة بغير فساد / قبلت الروح القدس إليكِ / اله القدرة شاء وأراد / ان يكون محمولاً على ذراعيكِ.\n\nاتحد بجسداً مثل الاجساد / وصار يرضع من لبن ثديَيكِ / وصرت من بعد الميلاد / بتولاً وتم القول عليك.\n\nلأنك ولدتِ وحيد الآب / المولود من كل الدهور / الدائم علي آخر الاحقاب / اله من اله حق نور من نور.\n\nتعالوا انظروا يا ذوي الألباب / كيف ظهر منك الغير منظور / وكيف العجيب العزيز المهاب / حَمَلتهُ مريم البكر تسعة شهور\n\nتعالوا نسأل اله العظمة / من عظم جوده ان يعطينا / حياةً هنيئة وسالمة / ومن كيد الاعداء ينجينا.\n\nالسلام لك يا ام الرحمة / نحن عبيدك جيرينا / طوباكِ يا مملوُة نعمة / عند ابنك الحبيب اشفعي فينا." },
    { language: 'englishArabic', text: "Mithl 'arousa bi-ghayr fasad / qabilti er-Rouh el-Qudus ilayki / ilah el-qudra sha'a wa arad / an yakoun mahmoulan 'ala dhira'ayki.\n\nIttahada bi-gasadin mithl el-agsad / wa sara yarda' min laban thadyayki / wa sirti min ba'd el-meelad / batoulan wa tamma el-qawl 'alayki.\n\nLi-annaki waladti waheed el-Ab / el-mawloud min kull ed-dohour / ed-da'im 'ala akhir el-ahqab / ilah min ilah haqq, nour min nour.\n\nTa'alou unzurou ya dhawi el-albab / kayfa zahara minki el-ghayr manzour / wa kayfa el-'ageeb el-'azeez el-mahab / hamalathu Maryam el-bikr tis'at shuhour.\n\nTa'alou nas'al ilah el-'azama / min 'izam goudihi an yu'teena / hayatan hanee'a wa salima / wa min kayd el-a'da' yungeena.\n\nEs-salam laki ya umm er-rahma / nahnu 'abeeduki geereena / toubaki ya mamlou'at ni'ma / 'ind ibniki el-habeeb ishfa'i feena." },
  ] },
  { id: "vp-third-hymn-of-cantor-gabriel-of-qay-a", title: "Third Hymn of Cantor Gabriel of Qay A", versions: [
    { language: 'english', text: "Like a choicest bride / and the groom has beheld her great splendor / and has approached her with purity / and He is the One who formed her.\n\nAnd He is the One who formed her / and favored her above every human / He came and dwelt inside her / and was born of her the Son of Man.\n\nAnd was born of her the Son of Man / as the Scriptures have proclaimed / and prophesied from the early ages / and has fulfilled what righteous David said.\n\nAnd has fulfilled what the righteous David said / that the King has seen your beauty / the words were completed and declared publicly / the God of gods became your Son.\n\nThe God of gods became your Son / who provided His people in the wilderness / you delivered and suckled Him / the provider of all humanity.\n\nThe provider of all humanity / born in the beginning of ages / you carried Him O pure virgin / He who exists in the Father’s bosom.\n\nHe who exists in the Father’s bosom / one hypostasis of the Trinity / has come in your womb and was veiled / uniting divinity with humanity.\n\nUniting divinity with humanity / and was born and named Jesus / who came and bestowed on us the kingdom / through His baptism from the forerunner.\n\nThrough His baptism from the forerunner / had come upon us with the pledge / fasted, prayed and fulfilled the law / He broke for us the trap of Satan.\n\nHe broke for us the trap of Satan / and we became counted through you / and we say with all Christians / hail to you and hail unto you.\n\nHail to you and hail unto you, we ask you O Mother of the Beloved, grant us to be in your fathers’ dwellings, Abraham Isaac and Jacob." },
    { language: 'arabic', text: "مثل عروسة مختارة / والعريس عاين عظم بهاها / وإليها أقبل بطهارة / وهو الذي قد أَنشاها.\n\nوهو الذي قد أَنشاها / وفَضَّلها عن كل الناس / أَتي وسكن في احشاءها / وولد منها إبن الانسان\n\nوولد منها إبن الانسان / كما شهدت عنها الاسفار / وتنبأت من قدم الازمان. / وكَمُلَ ما قال داود البار.\n\nوكَمُلَ ما قال داود البار / ان الملك قد اشتهي حسنكِ / وتمّ القول في وضح النهار / اله الالهه صار ابنك.\n\nاله الالهه صار ابنك / مَن عالَ شعبه في البرية / ولدتِيٍه ورضع لبنك / مدبر كل البشرية.\n\nمدبر كل البشرية / المولود ازلياً قبل الاحقاب / حملته يا بكر نقية / وهو كائن في حضن الآب.\n\nوهو كائن في حضن الآب / اقنوم واحد من ثالوث / صار في بطنك مستور بحجاب / واتَّحَد اللاهوت بالناسوت.\n\nواتَّحَد اللاهوت بالناسوت / وصار مولود وسمي إيسوس / تفضََّلَ وأَورثنا الملكوت / بعماده من بي ابروذروموس.\n\nبعمادة من بي ابروذروموس / قد جاء علينا بالعربون / صام وصلي وأكمل الناموس / وكسر عنًّا فخ الاركون.\n\nوكسر عنًّا فخ الاركون / وصرنا محسوبين عليكِ / ونقول مع كل المسيحيين / السلام لكِ ثم السلام إليك.\n\nالسلام لكِ ثم السلام إليك، ونسألك يا أم المحبوب، ان تحظينا في مظال اباءك، ابراهيم واسحق ويعقوب." },
    { language: 'englishArabic', text: "Mithl 'arousa mukhtara / wal-'arees 'ayana 'izam bahaha / wa ilayha aqbala bi-tahara / wa huwa alladhi qad ansha'aha.\n\nWa huwa alladhi qad ansha'aha / wa faddalaha 'an kull en-nas / ata wa sakana fi ahsha'iha / wa wulida minha Ibn el-insan.\n\nWa wulida minha Ibn el-insan / kama shahidat 'anha el-asfar / wa tanabba'at min qidam el-azman / wa kamula ma qal Dawoud el-barr.\n\nWa kamula ma qal Dawoud el-barr / anna el-malik qad ishtaha husnaki / wa tamma el-qawl fi wadah en-nahar / Ilah el-aliha sara ibnaki.\n\nIlah el-aliha sara ibnaki / man 'ala sha'bahu fil-bariyya / waladtihi wa radi'a labanaki / mudabbir kull el-bashariyya.\n\nMudabbir kull el-bashariyya / el-mawloud azaliyyan qabl el-ahqab / hamaltihi ya bikr naqiyya / wa huwa ka'in fi hudn el-Ab.\n\nWa huwa ka'in fi hudn el-Ab / uqnoum wahid min thalouth / sara fi batniki mastour bi-higab / wattahada el-lahout bin-nasout.\n\nWattahada el-lahout bin-nasout / wa sara mawloud wa summiya Iēsous / tafaddala wa awrathana el-malakout / bi-'imadihi min Pi-prodromos.\n\nBi-'imadihi min Pi-prodromos / qad ga'a 'alayna bil-'arboun / sama wa salla wa akmala en-namous / wa kasara 'anna fakhkh el-arkhon.\n\nWa kasara 'anna fakhkh el-arkhon / wa sirna mahsoubeen 'alayki / wa naqoul ma'a kull el-maseehiyyeen / es-salam laki thumma es-salam ilayki.\n\nEs-salam laki thumma es-salam ilayki, wa nas'aluki ya umm el-mahboub, an tahzeena fi mazall aba'ik, Ibraheem wa Ishaq wa Ya'qoub." },
  ] },
  { id: "vp-the-third-hymn-of-cantor-gabriel-of-qay-b", title: "The Third Hymn of Cantor Gabriel of Qay B", versions: [
    { language: 'english', text: "Like a chosen Bride, pure of all blemish, accepted in her womb with purity, the Father’s only Son Jesus the Messiah.\n\nI open my mouth with zeal, and say “O holy of holies, O golden censer and lampstand, in the hands of father Zacharias.\n\nAnd Aaron’s chosen rod, before Moses the prophet, his rod blossomed in purity, as the people witnessed.”\n\nThat was a symbol and a parable, to the Incarnation of your Son the Messiah, from your womb O chosen one, the One of the Trinity.\n\nYour father David the prophet, said with the organ and harp, “The Lord chose you with purity, the Creator of souls appeared from you.”\n\nBlessed are you O chosen one, blessed are you O holy of holies, rescue us from every loss, and deliver away every blemish.\n\nHail to you O Mother of our Savior, we ask you O pure Virgin, to ask the Lord to bring us, to the harbor in peace." },
    { language: 'arabic', text: "كمثل عروس مختارة، نقية من كل الأدناس، قَبَلتْ في أحشاءها بطهارة، وحيد الآب إيسوس ماسياس.\n\nوأنا أفتح فمي بجسارة، وأقول يا قدس الأقداس، يا شورية ذهب ومنارة، في يد الأب زاخرياس.\n\nوعصاة هرون المختارة، أمام مويسيس بي إبروفيتيس، عصاته أزهرت بطهارة، كما شهدوا كل الناس.\n\nوذلك رمز وعبارة، لتجسُّد إبنِك ماسياس، من جوف أحشائكِ يا مختارة، بي أوؤاي إيڤول خين تي إترياس.\n\nقال بالأرغن والقيثارة، أبوك داڤيد بي إبروفيتيس، \"والرب إختارِك بطهارة، وظهر منكِ باري النفوس.\"\n\nطوباكِ طوباكِ يا مختارة، طوباكِ يا قدس الأقداس، غيثينا من كل خسارة، وإبعدي عنا سائر الأدناس.\n\nالسلام لكِ يا اُم مخلصنا، ونسألكِ يا بكر نقية، تسألي الرب أن يوصِّلنا، إلى الميناء بطمأنينة." },
    { language: 'englishArabic', text: "Ka-mithl 'arous mukhtara, naqiyya min kull el-adnas, qabilat fi ahsha'iha bi-tahara, waheed el-Ab Iēsous Massias.\n\nWa ana aftah fammi bi-gasara, wa aqoul ya quds el-aqdas, ya shouriyat dhahab wa manara, fi yad el-ab Zakharias.\n\nWa 'asat Haroun el-mukhtara, amam Mōusēs pi-profētēs, 'asatuhu azharat bi-tahara, kama shahidou kull en-nas.\n\nWa dhalika ramz wa 'ibara, li-tagassud ibniki Massias, min gawf ahsha'iki ya mukhtara, Pi-ouai evol khen Ti-etrias.\n\nQala bil-arghan wal-qeethara, abouki Dauid pi-profētēs: \"War-Rabb ikhtaraki bi-tahara, wa zahara minki bari en-nufous.\"\n\nToubaki toubaki ya mukhtara, toubaki ya quds el-aqdas, gheetheena min kull khasara, wab'idi 'anna sa'ir el-adnas.\n\nEs-salam laki ya umm mukhallisina, wa nas'aluki ya bikr naqiyya, tas'ali er-Rabb an yuwassilana, ila el-meena' bi-tuma'neena." },
  ] },
  { id: "vp-the-third-hymn-of-cantor-gabriel-of-qay-c", title: "The Third Hymn of Cantor Gabriel of Qay C", versions: [
    { language: 'english', text: "As a first-born Bride and a pure one, accepted the Holy Spirit and He came, within your human womb, with His divinity like a coal of fire.\n\nAll the ranks of the high places, worship before His throne with reverence, and all the human tongues, praise Him day and night.\n\nAnd worship His holy name, the mighty Lord of the high throne, chose your beauty O Mother of Jesus, and took chosen flesh from you.\n\nHe who sits upon His throne, you carried on your hands and He became, a suckling like those of the world, and He is the Being throughout the ages.\n\nHe who granted us grace, and was baptized by the forerunner, and given us the pledge of mercy, and He is the Mighty and holy King.\n\nHe fasted prayed and perfected the Law, with no need for Himself who is great, He was born of you and named Jesus, hail to you O Mother of mercy.\n\nHail to you O Mother of mercy, blessed are you O full of grace, the Lady of us all Mary, through her prayers and intercessions." },
    { language: 'arabic', text: "كعروس بكر ونقية، قبلتِ الروح القدس وصار، في جوف أحشائكِ اللحمية، بلاهوته مثل جمر النار.\n\nكل الطقوس العلوية، تسجد قدام كرسيه بوقار، جميع ألسنة البشرية، تسبحه ليلاً ونهار.\n\nوتسجد لإسمه القدوس، رب العرش المولى الجبار، إختار حسنِك يا اُم إيسوس، وأخد منكِ ناسوت مختار.\n\nالجالس فوق بيف إثرونوس، حملتِه بين يديكِ وصار، رضيعاً كسائر بي كوزموس، وهو الكائن مدى الأدهار.\n\nمَنْ جاد علينا بالنعمة، وتعمَّد من بي إبروذروموس، وأعطانا عربون الرحمة، وهو المولى الملك القدوس.\n\nصام وصلى وأكمل الناموس، وهو الغير محتاج ذو العظمة، ووُلد منكِ وسُمِّيَ إيسوس، السلام لكِ يا اُم الرحمة.\n\nالسلام لكِ يا اُم الرحمة، طوباكِ يا ممتلئة نعمة، أووتين شويس إننيب ماريا، هيتين نيس طوڤه نيم نيس إبريسڤيِّا." },
    { language: 'englishArabic', text: "Ka-'arous bikr wa naqiyya, qabilti er-Rouh el-Qudus wa sar, fi gawf ahsha'iki el-lahmiyya, bi-lahoutihi mithl gamr en-nar.\n\nKull et-touqous el-'ulwiyya, tasgud quddam kursiyyihi bi-waqar, gamee' alsinat el-bashariyya, tusabbihuhu laylan wa nahar.\n\nWa tasgud li-ismihi el-quddous, Rabb el-'arsh el-mawla el-gabbar, ikhtara husnaki ya umm Iēsous, wa akhadha minki nasout mukhtar.\n\nEl-galis fawq pef-ethronos, hamaltihi bayna yadayki wa sar, radee'an ka-sa'ir pikosmos, wa huwa el-ka'in mada el-adhar.\n\nMan gada 'alayna bin-ni'ma, wa ta'ammada min Pi-prodromos, wa a'tana 'arboun er-rahma, wa huwa el-mawla el-malik el-quddous.\n\nSama wa salla wa akmala en-namous, wa huwa el-ghayr muhtag dhul-'azama, wa wulida minki wa summiya Iēsous, es-salam laki ya umm er-rahma.\n\nEs-salam laki ya umm er-rahma, toubaki ya mumtali'a ni'ma, Ouoh ten-tshois ennēb Maria, hiten nes-tovh nem nes-epresvia." },
  ] },
  { id: "vp-the-third-hymn-of-pope-abba-markos-viii", title: "The Third Hymn of Pope Abba Markos VIII", versions: [
    { language: 'english', text: "You became a Bride O Virgin, to the only King of glory, to whom is the might and authority, He came to us in a human flesh.\n\nAdam disobeyed and ate the fruit, so he was thrown out naked, outside from the Paradise, to the land of misery.\n\nHe was sad and he wept and sighed, he was captured by the Devil, he threw him in the bottom of Hades, the fiery place of torment.\n\nAnd many sufferings and distress, for him and every man thereafter, and his race became an example, humiliated with sorrows.\n\nThe Almighty Lord planned His Economy, to restore him to Paradise again, He sent Gabriel with the good news, to Mary the pride of the world.\n\nHe greeted her with happiness, he spoke to her with his tongue saying, “The Lord is with you O Virgin, you will accept a spiritual pregnancy.”\n\nMary answered him saying, “I do not know a man,” Gabriel told her the news, of the dwelling of the only Son.\n\nHail to you O Lady of virgins, O Mary the Virgin, Jesus Christ dwelt in your womb, and became our Savior." },
    { language: 'arabic', text: "صرتِ عروساً يا عذراء، لملك المجد الوحداني، له كل السلطان والقدرة، أتانا بجسد إنساني.\n\nآدم خالف وأكل الثمرة، فخرج مطروداً عريانِ، من الفردوس إلى برَّا، لأرض الشقاء صار تعبانِ.\n\nحزيناً يبكي في حسرة، مأسور في رق الشيطانِ، قد أخذه ورماه في حفرة، في قاع جحيم فيه نيرانِ.\n\nوعذاب أليم قاسي بكثرة، صار له ولكل إنسانِ، ونسله قد صاروا عِبرة، مذلولين بالأحزانِ.\n\nدبَّر تدبيره ربُّ القدرة، ليردَّه للفردوس ثاني، فأرسل غبريال بالبُشرى، لمريم فخر الأكوانِ.\n\nوأعطاها سلامه بمسرة، خاطبها بفمٍ ولسانِ، قال \"الرب معكِ يا عذراء، تقبلين حبَلاً روحاني.\"\n\nجاوبته مريم في الحضرة، قالت \"ليس لي معرفة بإنسانِ،\" غبريال أعطاها الخبرة، بحلول الإبن الوحداني.\n\nالسلام لكِ يا ست الأبكار، يا مريم تي بارثينوس، يا مَنْ في أحشائكِ قد حلَّ وصار، مخلصنا إيسوس بيخريستوس." },
    { language: 'englishArabic', text: "Sirti 'arousan ya 'Adhra', li-malik el-magd el-wahdani, lahu kull es-sultan wal-qudra, atana bi-gasad insani.\n\nAdam khalafa wa akala eth-thamara, fa-kharaga matroudan 'uryani, min el-firdaws ila barra, li-ard esh-shaqa' sara ta'bani.\n\nHazeenan yabki fi hasra, ma'sour fi riqq esh-shaytani, qad akhadhahu wa ramahu fi hufra, fi qa' gaheem feehi neerani.\n\nWa 'adhab aleem qasi bi-kathra, sara lahu wa li-kull insani, wa nasluhu qad sarou 'ibra, madhlouleen bil-ahzani.\n\nDabbara tadbeerahu Rabb el-qudra, li-yaruddahu lil-firdaws thani, fa-arsala Ghubriyal bil-bushra, li-Maryam fakhr el-akwani.\n\nWa a'taha salamahu bi-masarra, khatabaha bi-famin wa lisani, qala: \"Er-Rabb ma'aki ya 'Adhra', taqbaleena habalan rouhani.\"\n\nGawabathu Maryam fil-hadra, qalat: \"Laysa li ma'rifa bi-insani,\" Ghubriyal a'taha el-khibra, bi-houloul el-Ibn el-wahdani.\n\nEs-salam laki ya sitt el-abkar, ya Maryam Tiparthenos, ya man fi ahsha'iki qad halla wa sar, mukhallisuna Iēsous Pikhristos." },
  ] },
  { id: "vp-the-third-hymn-of-el-bardanohee", title: "The Third Hymn of El-Bardanohee", versions: [
    { language: 'english', text: "O true Bride indeed, the Holy Spirit came upon you, you carried the eternal Logos, our Savior Jesus Christ.\n\nYou bore Him O pure first-born, and the womb was sealed shut, you erased away the eternal grief, and exceeded the ranks of the angels.\n\nYou kept invisible mysteries, you became a heaven for the Lord Jesus, and of you the divine Logos, came and opened for us the Paradise.\n\nHe completed the salvation of mankind, He gave life to all the souls, you are the light of every creation, that enlightens those who are sitting.\n\nHe takes away every sin, of the Christian people, Eve became captive, through the deception of the Devil.\n\nFor five thousand years, and five hundred according to the writings, was deceitful darkness, upon the superior and subordinate.\n\nAnd now she returned in peace, through your purity O Virgin Mary, she came into bright light, with your presence O Mother of Christ.\n\nHail to you O Mother of God, ask your Son on our behalf, to forgive us sinners, through your prayers and honored rank." },
    { language: 'arabic', text: "أيتها العروس الحقيقية، حلَّ عليكِ روح القدوس، حملتِ الكلمة الأزلية، مخلصنا إيسوس بيخريستوس.\n\nوولدتِه يا بكر نقية، والخاتم محفوظ محروس، نزعتِ الغمة الأبدية، وفُقتِ رُتب ني أنجيلوس.\n\nصنتِ أسراراً خفية، صرتِ سماءً للرب إيسوس، ومنكِ الكلمة الإلهية، أتى وفتح لنا الفردوس.\n\nأكمل خلاص البشرية، أعطى الحياة لكل النفوس، أنتِ نور كل بَرِيَة، أضاء على كل الجلوس.\n\nهو مَحِي كل خطية، عن شعب إننيخ ريستيَّانوس، وحواء كانت مسبية، بغواية شيطان منجوس.\n\nخمسة آلاف عام متوالية، وخمسمائة بعدد منصوص، كانت ظلمة مغشية، على الرئيس والمرؤوس.\n\nوالآن عادت بطمأنينة، بطُهركِ يا مريم تي بارثينوس، دخلت أنوار مضيئة، بوجودِك يا اُم بيخريستوس.\n\nالسلام لكِ يا اُم الإله، جيرينا قدام إبنِك، ليسامحنا نحن الخطاة، بصلاتِك وشرف جنسِك." },
    { language: 'englishArabic', text: "Ayyatuha el-'arous el-haqeeqiyya, halla 'alayki Rouh el-quddous, hamalti el-Kalima el-azaliyya, mukhallisuna Iēsous Pikhristos.\n\nWa waladtihi ya bikr naqiyya, wal-khatim mahfouz mahrous, naza'ti el-ghumma el-abadiyya, wa fuqti rutab ni-aggelos.\n\nSunti asraran khafiyya, sirti sama'an lir-Rabb Iēsous, wa minki el-Kalima el-ilahiyya, ata wa fataha lana el-firdaws.\n\nAkmala khalas el-bashariyya, a'ta el-hayah li-kull en-nufous, anti nour kull bariyya, ada'a 'ala kull el-guloos.\n\nHuwa mahi kull khatiyya, 'an sha'b en-ekhristianos, wa Hawwa' kanat masbiyya, bi-ghiwayat shaytan mangous.\n\nKhamsat alaf 'am mutawaliya, wa khamsumi'a bi-'adad mansous, kanat zulma mughashshiya, 'ala er-ra'ees wal-mar'ous.\n\nWal-an 'adat bi-tuma'neena, bi-tuhriki ya Maryam Tiparthenos, dakhalat anwar mudee'a, bi-wugoudiki ya umm Pikhristos.\n\nEs-salam laki ya umm el-Ilah, geereena quddam ibnik, li-yusamihana nahnu el-khutah, bi-salatik wa sharaf ginsik." },
  ] },
  { id: "vp-the-fourth-greek-interpretation", title: "The Fourth Greek Interpretation", versions: [
    { language: 'coptic', text: "Ⲕⲩⲣⲓⲉ ⲧⲓⲥ ⲟ̀ⲙⲓⲟⲥ ⲥⲓ: ⲉⲛ ⲑⲉⲉⲓ̀ⲥ ⲛⲉⲙ ⲛⲓϭⲓⲥⲉⲩ: ⲇⲟⲝⲁ ⲥⲓ ϧⲉⲛ ⲛⲏⲉⲧϭⲟⲥⲓ: ⲕⲁⲓ ⲏ̀ ⲅⲏ ϣⲁⲧ̀ϧⲁⲉ̀ ⲛ̀ⲛⲓⲥⲏⲟⲩ.\n\nⲘⲏ ⲁⲛ ϧⲉⲛ ϯⲡⲁⲣⲁ̀ⲕⲗⲏⲥⲓⲥ: ⲟⲩⲇⲉ ⲧⲁ ⲉⲣⲅⲁⲧⲁ ⲟ̀ⲥⲓⲁ: ⲁⲕⲟⲩⲱⲛϩ ⲛⲁⲛ ⲛ̀ⲉ̀ⲡⲓⲕⲗⲏⲥⲓⲥ: ⲙ̀ⲡⲓϭⲱⲣⲡ ⲛ̀ⲧⲉ ⲧⲉⲕⲉⲝⲟⲩⲥⲓⲁ.\n\nⲠⲗⲏⲛ ϧⲉⲛ ⲛⲉⲕⲛⲁⲓ ⲁⲕⲧⲁⲛϧⲟⲛ: ⲁⲕϣⲁⲛⲓ̀ ⲛⲁⲛ ⲙ̀ⲫ̀ⲣⲏϯ ⲛ̀ⲟⲩⲣⲱⲙⲓ: ⲁⲩⲑⲱⲛ ⲛⲓⲉ̀ⲡⲓⲥⲧⲓⲙⲏ̀ ⲁⲣⲭⲱⲛ: ⲉ̀ⲣⲟⲩ ⲥⲩⲛⲁⲙⲁ ⲕⲁⲧⲁ ⲫ̀ⲧⲱⲙⲓ.\n\nⲤⲓ ⲡ̀ⲣⲉⲡⲓ ⲩ̀ⲙⲛⲟⲥ ⲉⲕⲧⲉⲛⲟⲥ: ⲛⲉⲙ Ⲡⲉⲕⲓⲱⲧ ⲉⲧⲁϥⲧⲁⲟⲩⲟⲕ: ⲱ̀ ⲫⲏⲉⲧ ϧⲉⲛ ⲑ̀ⲛⲉϫⲓ ⲛ̀ϯⲡⲁⲣⲑⲉⲛⲟⲥ: ⲁϥϭⲓ ⲛ̀ⲟⲩⲙⲟⲣⲫⲏ ⲙ̀ⲃⲱⲕ.\n\nⲢⲱⲙⲓ ⲛⲓⲃⲉⲛ ⲫ̀ⲑⲟⲅⲅⲟ̀ⲙⲉⲛⲟⲥ: ⲉⲕ ⲧⲟⲛ ⲕⲟⲥⲙⲟⲛ ⲃⲓⲱⲧⲓⲕⲟⲛ: ⲁⲩϫⲟⲥ ϫⲉ ⲛ̀ⲑⲟ ⲅⲁⲣ ⲡⲉ ⲡⲓⲅⲉⲛⲟⲥ: ⲛⲉⲙ ϯⲛⲟⲩⲛⲓ ⲛ̀Ⲇⲁⲩⲓⲇⲓⲕⲟⲛ.\n\nϪⲉ ⲁ̀ⲣⲉⲙⲓⲥⲓ ⲙ̀ⲡⲁⲛⲧⲁ̀ⲛⲁⲝ: ⲡⲉⲛⲛⲏⲃ Ⲡⲉⲛⲥⲱⲧⲏⲣ Ⲓⲏ︦ⲥ︦ Ⲡⲭ︦ⲥ︦: ⲡⲓⲙⲟⲛⲟⲅⲉⲛⲏⲥ ⲕⲁⲧⲁ ⲥⲁⲣⲝ: ⲉⲑⲃⲉ ⲧⲉⲛⲙⲉⲧⲉⲗⲁ̀ⲭⲓⲥⲧⲟⲥ.\n\nⲦⲉⲛϯⲱ̀ⲟⲩ ⲛⲉ ⲱ̀ ⲑⲏⲉⲧⲥⲙⲁⲙⲁⲧ: ϣⲁ ⲡⲓⲛⲓϥⲓ ⲛ̀ⲧⲉ ⲗⲉⲩⲧⲉⲟⲥ: ϫⲉ ⲁⲣⲉϫⲓⲙⲓ ⲅⲁⲣ ⲛ̀ⲟⲩϩ̀ⲙⲟⲧ: ϧⲁⲧⲉⲛ Ⲡⲉⲛⲟⲩϯ Ⲩⲓⲟⲥ Ⲑⲉⲟⲥ." },
    { language: 'english', text: "O Lord who is like You, among the gods and lords, glory to You in the highest, and on earth to the end of time.\n\nNot with supplications, nor righteous deeds, You showed us the mystery, of the declaration of Your authority.\n\nBut through Your mercy You revived us, You came to us like a Man, so where are the intellectual leaders, that they may speak together befittingly.\n\nTo You is the praise forever, with Your Father who sent You, O You who dwelt in the Virgin’s womb, took a servant’s form.\n\nEvery human who can speak, in the living world, said “You are the offspring, and the root of David.”\n\nFor you gave birth to the Head of all, our Master and Savior Jesus Christ, the only-begotten in flesh, for the sake of our weakness.\n\nWe glorify you O blessed one, until the last breath saying, \"You have found favor before, your God the Son of God.\"" },
    { language: 'arabic', text: "يا رب من يشبهك في الآلهة والأرباب. المجد لك في الأعالي وعلى الأرض إلى آخر الأزمان.\n\nليس بابتهال ولا أعمال بارة. أظهرت لنا سر اعلان سلطانك.\n\nلكن بمراحمك أحييتنا أذ أتيت إلينا مثل إنسان فأين هم الرؤساء ذوو الألباب ليقولوا معا كما يليق.\n\nلك ينبغي التسبيح دائما. مع أبيك الذي أرسلك يا الذي من بطن العذراء أخذ شكل العبد.\n\nكل إنسان ناطق في العالم الحيوي قال أنك أنت هي الجنس والأصل الداوودي.\n\nلأنك ولدت ملك الكل سيدنا ومخلصنا يسوع المسيح الوحيد بالجسد من أجل مسكنتنا.\n\nنمجدك ايتها المباركة إلى النفس الأخير لأنك وجدت نعمة عند إلهك ابن الله." },
    { language: 'englishArabic', text: "Ya Rabb man yushbihuka fil-aliha wal-arbab. El-magd lak fil-a'ali wa 'ala el-ard ila akhir el-azman.\n\nLaysa bi-ibtihal wa la a'mal barra, azharta lana sirr i'lan sultanik.\n\nLakin bi-marahimik ahyaytana idh ateita ilayna mithl insan; fa-ayna hum er-ru'asa' dhawou el-albab li-yaqoulou ma'an kama yaleeq:\n\nLaka yanbaghi et-tasbeeh da'iman, ma'a abeeka alladhi arsalak, ya alladhi min batn el-'Adhra' akhadha shakl el-'abd.\n\nKull insan natiq fil-'alam el-hayawi qala annaki anti hiya el-gins wal-asl ed-Dawoudi.\n\nLi-annaki waladti malik el-kull sayyidana wa mukhallisana Yasou' el-Maseeh el-waheed bil-gasad min agl maskanatina.\n\nNumaggiduki ayyatuha el-mubaraka ila en-nafas el-akheer li-annaki wagadti ni'ma 'ind ilahik Ibn Allah." },
  ] },
  { id: "vp-the-fourth-bohairic-interpretation-a", title: "The Fourth Bohairic Interpretation A", versions: [
    { language: 'coptic', text: "Ⲛ̀ⲑⲟ ⲅⲁⲣ ⲡⲉ ⲡⲓⲅⲉⲛⲟⲥ: ⲛⲉⲙ ϯⲛⲟⲩⲛⲓ ⲛ̀ⲧⲉ Ⲇⲁⲩⲓⲇ: ϯⲥⲉⲙⲛⲉ ⲛ̀ⲕⲁⲑⲁⲣⲟⲥ: Ⲙⲁⲣⲓⲁ ⲑ̀ⲙⲁⲩ ⲙ̀ⲡⲓⲙⲉⲛⲣⲓⲧ.\n\nⲠⲓⲙⲟⲛⲟⲅⲉⲛⲏⲥ ⲉ̀ⲃⲟⲗϧⲉⲛ Ⲫ̀ⲓⲱⲧ: ⲁ̀ⲣⲉϫ̀ⲫⲟϥ ⲥⲱⲙⲁⲧⲓⲕⲟⲥ: ϧⲉⲛ ⲡ̀ϯⲙⲁϯ ⲙ̀Ⲡⲉϥⲓⲱⲧ: ⲛⲉⲙ Ⲡⲓⲡ︦ⲛ︦ⲁ︦ ⲙ̀ⲡⲁⲣⲁⲕⲗⲏⲧⲟⲛ.\n\nⲒⲏ︦ⲥ︦ Ⲡⲭ︦ⲥ︦ Ⲡϣⲏⲣⲓ ⲙ̀Ⲫϯ: ⲁϥϣⲟⲩⲱϥ ⲉ̀ⲃⲟⲗ ⲙ̀ⲙⲓⲛⲙ̀ⲙⲟϥ: ⲁϥϭⲓ ⲛ̀ⲟⲩⲙⲟⲣⲫⲏ ⲙ̀ⲃⲱⲕ ⲛ̀ϧⲏϯ: ϣⲁ ⲛ̀ⲧⲉϥϩⲟⲧⲡⲉⲛ ⲉ̀ⲣⲟϥ.\n\nⲦⲉⲛϯⲱⲟⲩ ⲛⲉ ⲱ̀ ⲑⲏⲉ̀ⲧⲉⲛϩⲟⲧ: ⲛⲉⲙ ⲡⲓⲁⲅⲅⲉⲗⲟⲥ ⲛ̀ⲧⲉ ⲡⲓⲥ̀ⲙⲟⲩ: ϫⲉ ⲭⲉⲣⲉ ⲕⲉ ⲭⲁⲣⲓⲧⲱⲙⲉⲛⲏ ⲱ̀ ⲑⲏⲉⲑⲙⲉϩ ⲛ̀ϩⲙⲟⲧ: ⲟⲩⲟϩ Ⲡⲟ︦ⲥ︦ ϣⲟⲡ ⲛⲉⲙⲉ." },
    { language: 'english', text: "You are the offspring, and root of David, the pure and chaste, Mary the Mother of the Beloved.\n\nThe only-begotten of the Father, you gave birth to Him in the flesh, with the pleasure of His Father, and the Spirit of comfort.\n\nJesus Christ the Son of God, He descended of His own will, and took from you a servant’s form, and we were united with Him.\n\nWe glorify you O trusted one, with the angel of blessing saying, \"Hail to you O full of grace, the Lord is with you.\"" },
    { language: 'arabic', text: "أنت هي جنس واصل داود أيتها العفيفة النقية مريم أم الحبيب.\n\nالوحيد من الآب ولدته جسدياً. بمسرة أبيه والروح المعزي.\n\nيسوع المسيح ابن الله تنازل بذاته وأخذ شكل العبد منك حتى أتصلنا به.\n\nنمجدك أيتها الأمينة قائلين مع ملاك البركة أفرحي أيتها الممتلئة نعمة . الرب معك." },
    { language: 'englishArabic', text: "Anti hiya gins wa asl Dawoud ayyatuha el-'afeefa en-naqiyya Maryam umm el-habeeb.\n\nEl-waheed min el-Ab waladtihi gasadiyyan, bi-masarrat abeehi war-Rouh el-mu'azzi.\n\nYasou' el-Maseeh Ibn Allah tanazala bi-dhatihi wa akhadha shakl el-'abd minki hatta ittasalna bih.\n\nNumaggiduki ayyatuha el-ameena qa'ileen ma'a malak el-baraka: ifrahi ayyatuha el-mumtali'a ni'ma, er-Rabb ma'aki." },
  ] },
  { id: "vp-the-fourth-bohairic-interpretation-b", title: "The Fourth Bohairic Interpretation B", versions: [
    { language: 'coptic', text: "Ⲇⲓⲕⲉⲟⲥ ϧⲉⲛ ⲟⲩⲙⲉⲑⲙⲏⲓ: Ⲙⲁⲣⲓⲁ ϯϣⲉⲗⲉⲧ ⲙ̀ⲙⲏⲓ: ⲛ̀ⲑⲟ ⲡⲉ ⲡ̀ⲅⲉⲛⲟⲥ ⲛ̀ⲛⲓⲑ̀ⲙⲏⲓ: ⲛⲉⲙ ϯⲛⲟⲩⲛⲓ ⲙ̀ⲡ̀ⲣⲟⲫⲏⲧⲓⲕⲟⲛ.\n\nⲈⲑⲃⲉ ⲫⲁⲓ ⲁϥⲥⲱⲧⲡ ⲙ̀ⲙⲟⲥ: ⲁϥⲉⲣⲁ̀ⲅⲓⲁ̀ⲍⲓⲛ ⲙ̀ⲙⲟⲥ: ⲉⲑⲣⲉϥϣⲱⲡⲓ ⲥⲁϧⲟⲩⲛ ⲙ̀ⲙⲟⲥ: ⲛ̀ϫⲉ ⲡⲓⲗⲟⲅⲟⲥ ⲛ̀ⲧⲉ Ⲫ̀ⲓⲱⲧ.\n\nⲀⲥⲙⲓⲥⲓ ⲙ̀ⲙⲟϥ ϧⲉⲛ ⲟⲩⲙⲉⲑⲙⲏⲓ: ϫⲉ ⲛ̀ⲑⲟϥ ⲟⲩⲛⲟⲩϯ ⲛ̀ⲧⲁⲫ̀ⲙⲏⲓ: ⲁϥⲉⲣⲣⲱⲙⲓ ⲉⲑⲃⲉ ⲡⲓϩⲉⲓ: ⲛ̀ⲧⲉ Ⲁⲇⲁⲙ ⲡⲓϣⲟⲣⲡ ⲛ̀ⲣⲱⲙⲓ.\n\nⲘⲁⲣⲉⲛϯⲱ̀ⲟⲩ ⲛ̀ϯⲁ̀ⲅⲓⲁ̀: ϧⲉⲛ ϩⲁⲛⲥ̀ⲙⲏ ⲛ̀ⲇⲟⲝⲟⲗⲟⲅⲓⲁ̀: ϫⲉ ⲭⲉⲣⲉ ⲣⲁϣⲓ ⲱ̀ Ⲙⲁⲣⲓⲁ: ⲟ̀ Ⲕⲩⲣⲓⲟⲥ ⲙⲉⲧⲁ ⲥⲟⲩ." },
    { language: 'english', text: "Truly indeed, O Mary the true Bride, you are the offspring of the just, and the prophetic root.\n\nTherefore He chose her, and sanctified her, that He may dwell in her, the Logos of the Father.\n\nShe gave birth to Him in truth, for He is the true God, He became man because of the fall, of Adam the first man.\n\nLet us glorify the saint, in voice of glorification saying, \"Hail to you rejoice O Mary, the Lord is with you.\"" },
    { language: 'arabic', text: "حقاً بالحقيقة مريم العروسة الحقيقية أنت هي جنس الأبرار وأصل الأنبياء.\n\nفلهذا اختارها وقدسها لكي يسكن فيها كلمة الآب.\n\nولدته بالحقيقة لأنه هو إلهنا الحقاني صار إنسان لأجل سقطة آدم الإنسان الأول.\n\nفلنمجد القديسة بأصوات التمجيد قائلين السلام أفرحي يا مريم الرب معك." },
    { language: 'englishArabic', text: "Haqqan bil-haqeeqa Maryam el-'arousa el-haqeeqiyya, anti hiya gins el-abrar wa asl el-anbiya'.\n\nFa-li-hadha ikhtaraha wa qaddasaha likay yaskun feeha kalimat el-Ab.\n\nWaladtihi bil-haqeeqa li-annahu huwa ilahuna el-haqqani sara insanan li-agl saqtat Adam el-insan el-awwal.\n\nFal-numaggid el-qiddeesa bi-aswat et-tamgeed qa'ileen: es-salam, ifrahi ya Maryam er-Rabb ma'aki." },
  ] },
  { id: "vp-the-fourth-coptic-mo-aqap-interpretation", title: "The Fourth Coptic Mo-‘aqap Interpretation", versions: [
    { language: 'coptic', text: "Ⲇⲉⲥⲡⲟⲧⲁ ⲡⲓⲣⲉϥⲉⲣϩⲉⲙⲓ: ⲛ̀ⲑⲟⲕ ⲅⲁⲣ ⲡⲉ ⲫⲏⲉⲧⲉⲙⲓ: ⲉ̀ϯⲙⲉⲧϫⲱⲃ ⲛ̀ⲧⲉ ϯⲙⲉⲧⲣⲱⲙⲓ: ϫⲉ ⲛ̀ⲑⲟⲕ ⲁⲕⲑⲁⲙⲓⲟⲓ.\n\nϪⲉ ⲛ̀ⲑⲟⲕ ⲁⲕⲑⲁⲙⲓⲟⲓ: ⲟⲩⲟϩ ⲕ̀ⲥⲱⲟⲩⲛ ⲙ̀ⲙⲟⲓ: ϯⲧⲱⲃϩ ⲙ̀ⲙⲟⲕ ⲥⲱⲧⲉⲙ ⲉ̀ⲣⲟⲓ: ⲙⲁϩ̀ⲑⲏⲕ ⲉ̀ⲧⲁⲃⲟⲏⲑⲓⲁ.\n\nⲘⲁϩ̀ⲑⲏⲕ ⲉ̀ⲧⲁⲃⲟⲏⲑⲓⲁ: ⲭⲱ ⲛⲏⲓ ⲉ̀ⲃⲟⲗ ⲛ̀ⲛⲁⲁ̀ⲛⲟⲙⲓⲁ: ⲉⲑⲃⲉ ϯϩⲓⲉ̀ⲃⲓ ⲛ̀ⲁⲧⲕⲁⲕⲓⲁ: Ⲙⲁⲣⲓⲁ ϯⲑⲉⲟ̀ⲧⲟⲕⲟⲥ.\n\nⲘⲁⲣⲓⲁ ϯⲑⲉⲟ̀ⲧⲟⲕⲟⲥ: ϯⲛⲟⲩⲛⲓ ⲛⲉⲙ ⲡⲓⲅⲉⲛⲟⲥ: ⲛ̀ⲧⲉ Ⲇⲁⲩⲓⲇ ⲡⲓϩⲩⲙⲛⲟⲇⲟⲥ: ⲫ̀ⲙⲁⲛϣⲱⲡⲓ ⲛ̀ⲧⲉ ⲡⲓⲧⲟⲩⲃⲟ.\n\nⲪⲙⲁⲛϣⲱⲡⲓ ⲛ̀ⲧⲉ ⲡⲓⲧⲟⲩⲃⲟ: ⲛⲉⲙ ⲑ̀ⲙⲁⲩ ⲙ̀ⲡⲓⲣⲉϥⲑⲁⲙⲓⲟ: Ⲡⲉⲛⲛⲟⲩϯ ⲉ̀ⲧⲁϥⲑⲉⲃⲓⲟ: ⲁϥϭⲓ ⲛ̀ⲟⲩⲙⲟⲣⲫⲏ ⲙ̀ⲃⲱⲕ.\n\nⲀϥϭⲓ ⲛ̀ⲟⲩⲙⲟⲣⲫⲏ ⲙ̀ⲃⲱⲕ: ϣⲁ ⲛ̀ⲧⲉϥⲥⲱϯ ⲙ̀ⲡⲉϥⲃⲱⲕ: Ⲁⲇⲁⲙ ⲛⲉⲙ ⲛⲏⲉⲧⲟⲓ ⲙ̀ⲃⲱⲕ: ⲕⲁⲧⲁ ⲡⲉϥⲛⲁⲓ ⲁϥⲛⲟϩⲉⲙ ⲙ̀ⲙⲱⲟⲩ.\n\nⲔⲁⲧⲁ ⲡⲉϥⲛⲁⲓ ⲁϥⲛⲟϩⲉⲙ ⲙ̀ⲙⲱⲟⲩ: ⲉ̀ⲃⲟⲗϩⲁ ϯⲙⲉⲧⲃⲱⲕ ⲉⲧϩⲱⲟⲩ: ⲙ̀ⲫⲏⲉⲧⲁϥⲉⲣⲟ︦ⲥ︦ ⲉ̀ⲣⲱⲟⲩ: ⲉⲑⲃⲉ ⲡ̀ⲥⲟϭⲛⲓ ⲙ̀ⲡⲓϩⲟϥ.\n\nⲈⲑⲃⲉ ⲡ̀ⲥⲟϭⲛⲓ ⲙ̀ⲡⲓϩⲟϥ: Ⲁⲇⲁⲙ ⲡⲓϣⲟⲣⲡ ⲁϥϩⲓⲟⲩⲓ̀ ⲙ̀ⲙⲟϥ: ⲉⲑⲃⲉ Ⲙⲁⲣⲓⲁ ⲁⲩⲧⲁⲥⲑⲟϥ: ⲉ̀ⲧⲉϥⲁⲣⲭⲏ ⲛ̀ⲕⲉⲥⲟⲡ.\n\nⲦⲉⲛϯⲱ̀ⲟⲩ ⲛⲉ ⲱ̀ ⲑⲏⲉ̀ⲧⲉⲛϩⲟⲧ: ⲉⲧϥⲁⲓ ϧⲁ ⲡⲓⲗⲟⲅⲟⲥ ⲛ̀ⲧⲉ Ⲫ̀ⲓⲱⲧ: ϫⲉ ⲭⲉⲣⲉ ⲑⲏⲉⲑⲙⲉϩ ⲛ̀ϩ̀ⲙⲟⲧ: ⲟⲩⲟϩ Ⲡⲟ︦ⲥ︦ ϣⲟⲡ ⲛⲉⲙⲉ." },
    { language: 'english', text: "O Master and provider, You are full of knowledge, of the weakness of mankind, for You have created me.\n\nFor You have created me, and You know me, I entreat You to hear me, be unto me a help.\n\nBe unto me a help, forgive me my iniquities, for the sake of the unblemished lamb, Mary the Theotokos.\n\nMary the Theotokos, from the root and descendants, of David the psalmist, the place of purity.\n\nThe place of purity, and the mother of the Creator, our God humbled Himself, and took the form of a servant.\n\nAnd took the form of a servant, to save His servants, Adam and those who were in slavery, He saved them according to His mercy.\n\nHe saved them according to His mercy, from bitter slavery, from the one who had made himself master over them, through the deceit of the serpent.\n\nThrough the deceit of the serpent, the first Adam fell, and through Mary was restored again, to his authority.\n\nWe glorify you O faithful one, who carried the Word of the Father, \"Hail to you O full of grace, the Lord is with you.\"" },
    { language: 'arabic', text: "أيها السيد المدبر أنت تعرف بضعف البشرية لأنك أنت خلقتني.\n\nلأنك انت خلقتني وتعرفني أطلب إليك اسمعني واصغ لمعونتي.\n\nوأصغ لمعونتي: وأغفر لي آثامي من أجل النعجة التي بلا شر مريم والدة الإله.\n\nمريم والدة الإله: أصل وجنس داود المرتل مسكن الطهارة.\n\nمسكن الطهارة: وأم الخالق إلهنا الذي اتضع واخذ شكل العبد.\n\nوأخذ شكل العبد: حتى خلص عبده آدم والمستعبدين كرحمته خلصهم.\n\nكرحمته خلصهم: من العبودية الرديئة التي لمن قد ساد عليهم من أجل مشورة الحية.\n\nمن أجل مشورة الحية: آدم الأول قد سقط ومن أجل مريم قد رجع إلى رئاسته دقعة أخري.\n\nنمجدك ايتها الامينة. الحاملة كلمة الأب قائلين إفرحي يا ممتلئة نعمة. الرب معك" },
    { language: 'englishArabic', text: "Ayyuha es-sayyid el-mudabbir, anta ta'rif bi-da'f el-bashariyya li-annaka anta khalaqtani.\n\nLi-annaka anta khalaqtani wa ta'rifuni, atlub ilayka isma'ni wa asghi li-ma'ounati.\n\nWa asghi li-ma'ounati: waghfir li athami min agl en-na'ga allati bila sharr Maryam walidat el-Ilah.\n\nMaryam walidat el-Ilah: asl wa gins Dawoud el-murattil, maskan et-tahara.\n\nMaskan et-tahara: wa umm el-khaliq ilahina alladhi ittada'a wa akhadha shakl el-'abd.\n\nWa akhadha shakl el-'abd: hatta khallasa 'abdahu Adam wal-musta'badeen; ka-rahmatihi khallasahum.\n\nKa-rahmatihi khallasahum: min el-'oubudiyya er-radee'a allati li-man qad sada 'alayhim min agl mashourat el-hayya.\n\nMin agl mashourat el-hayya: Adam el-awwal qad saqata, wa min agl Maryam qad raga'a ila ri'asatihi daf'a ukhra.\n\nNumaggiduki ayyatuha el-ameena, el-hamila kalimat el-Ab, qa'ileen: ifrahi ya mumtali'a ni'ma, er-Rabb ma'aki." },
  ] },
  { id: "vp-the-fourth-egyptian-interpretation", title: "The Fourth Egyptian Interpretation", versions: [
    { language: 'coptic', text: "Ⲛ̀ⲑⲟ ⲅⲁⲣ ⲡⲉ ⲡⲓⲅⲉⲛⲟⲥ: ⲛⲉⲙ ϯⲛⲟⲩⲛⲓ ⲙ̀ⲡⲓϩⲩⲙⲛⲟⲇⲟⲥ: Ⲇⲁⲩⲓⲇ ⲡ̀ⲟⲩⲣⲟ ⲡⲓⲓⲉⲣⲟⲯⲁⲗⲧⲏⲥ: Ⲫⲓⲱⲧ ⲙ̀Ⲡⲭ︦ⲥ︦ ⲕⲁⲧⲁ ⲥⲁⲣⲝ.\n\nⲚ̀ⲑⲟ ⲅⲁⲣ ⲡⲉ ⲡⲓⲅⲉⲛⲟⲥ: ⲛⲉⲙ ϯⲛⲟⲩⲛⲓ ⲛ̀Ⲓⲱⲁⲕⲓⲙ ⲡⲓⲙⲉⲛⲣⲓⲧ: ⲙⲁϯϩⲟ ⲉ̀ϩ̀ⲣⲏⲓ ⲉ̀ϫⲱⲛ ⲱ̀ ϯⲡⲁⲣⲑⲉⲛⲟⲥ: ⲉϥⲛⲁⲥⲱⲧⲉⲙ ⲉ̀ⲣⲟ ⲛ̀ϫⲉ Ⲡϭⲟⲓⲥ Ⲫⲛⲟⲩϯ.\n\nⲚ̀ⲑⲟ ⲅⲁⲣ ⲡⲉ ⲡⲓⲅⲉⲛⲟⲥ: ⲛⲉⲙ ϯⲛⲟⲩⲛⲓ ⲛ̀ⲛⲓⲇⲓⲕⲉⲟⲥ: ⲁ̀ⲣⲉⲙⲓⲥⲓ ⲛⲁⲛ ⲙ̀ⲡⲓⲙⲟⲛⲟⲅⲉⲛⲏⲥ: Ⲡⲉⲛⲟⲩⲣⲟ Ⲓⲏⲥⲟⲩⲥ Ⲡⲓⲭ̀ⲣⲓⲥⲧⲟⲥ.\n\nⲚ̀ⲑⲟ ⲅⲁⲣ ⲡⲉ ⲡⲓⲅⲉⲛⲟⲥ: ⲛⲉⲙ ϯⲛⲟⲩⲛⲓ ⲛ̀ⲛⲓⲕⲁⲑⲁⲣⲟⲥ: ⲁ̀ⲣⲉϣⲱⲡⲓ ⲛ̀ⲟⲩⲑ̀ⲣⲟⲛⲟⲥ: ⲙ̀Ⲡⲓⲭ̀ⲣⲓⲥⲧⲟⲥ Ⲩⲓⲟⲥ Ⲑⲉⲟⲥ.\n\nⲚ̀ⲑⲟ ⲅⲁⲣ ⲡⲉ ⲡⲓⲅⲉⲛⲟⲥ: ⲛⲉⲙ ⲑ̀ⲛⲟⲩⲛⲓ ⲛ̀ⲇⲁⲩⲓⲇⲓⲕⲟⲛ: ⲁ̀ⲣⲉ ϣⲱⲡⲓ ⲛⲁⲛ ⲛ̀ⲟⲩⲡ̀ⲣⲟⲥⲧⲁⲧⲏⲥ: ⲛⲁϩⲣⲉⲛ Ⲫϯ ⲡⲓⲇⲉⲥⲡⲟⲧⲏⲥ.\n\nⲚ̀ⲑⲟ ⲅⲁⲣ ⲡⲉ ⲡⲓⲅⲉⲛⲟⲥ: ⲛⲉⲙ ϯⲃⲱ ⲛ̀ⲁ̀ⲗⲟⲗⲓ ⲛ̀ⲕⲁⲑⲁⲣⲟⲥ: ⲉ̀ⲧⲉ ⲙ̀ⲡⲟⲩⲉⲣⲟⲩⲱⲓ ⲙ̀ⲙⲟⲥ: ⲉⲑⲙⲉϩ ⲙ̀ⲡ̀ⲱⲛϧ ⲙ̀ⲡⲓⲕⲟⲥⲙⲟⲥ.\n\nⲚ̀ⲑⲟ ⲅⲁⲣ ⲡⲉ ⲡⲓⲅⲉⲛⲟⲥ: ⲛⲉⲙ ϯⲛⲟⲩⲛⲓ ⲉⲧⲥ̀ⲙⲁⲣⲱⲟⲩⲧ: ⲁ̀ⲣⲉⲙⲓⲥⲓ ⲙ̀ⲡⲓⲗⲟⲅⲟⲥ: Ⲡϣⲏⲣⲓ ⲛ̀ⲧⲉ Ⲫ̀ⲓⲱⲧ.\n\nⲈⲑⲃⲉ ⲫⲁⲓ ⲧⲉⲛϩⲱⲥ ⲉ̀Ⲫⲛⲟⲩϯ: ⲫⲏⲉ̀ⲧⲁϥϭⲓⲥⲁⲣⲝ ⲉ̀ⲃⲟⲗ ⲛ̀ϧⲏϯ: ⲁϥⲉⲣⲣⲱⲙⲓ ⲙ̀ⲡⲉⲛⲣⲏϯ: ϣⲁⲧⲉⲛ ⲫ̀ⲛⲟⲃⲓ ⲙ̀ⲙⲁⲩⲁⲧϥ." },
    { language: 'english', text: "You are the offspring, and root of the hymnist, King David the psalmist, the Father of Christ in the flesh.\n\nYou are the offspring, and root of the beloved Joachim, pray for us O Virgin, that the Lord God may hear you.\n\nYou are the offspring, and the root of the righteous, you bore for us the only-begotten, our King Jesus Christ,\n\nYou are the offspring, and the root of the pure ones, you became a throne, for Christ the Son of God.\n\nYou are the offspring, and the root of David, you became an intercessor for us, before God our Master.\n\nYou are the offspring, and the pure vine, that was not toiled, full of the life of the world.\n\nYou are the offspring, and the blessed root, you gave birth to the Logos, the Son of the Father.\n\nTherefore we praise God, who was incarnate of you, and became man like us, except for sin alone." },
    { language: 'arabic', text: "أنتِ هي جنس، وأصل المرتل داود، الملك الحسن في الترتيل، أب المسيح بالجسد.\n\nأنتِ هي جنس، وأصل يواقيم الحبيب، أُطلبيعنا أيتها العذراء، فيسمع لكِ الرب الإله.\n\nأنتِ هي جنس، وأصل الصديقين، ولدتِ لنا الوحيد، ملكنا يسوع المسيح.\n\nأنتِ هي جنس، وأصل الأتقياء، صرتِ كرسياً، للمسيح إبن الله.\n\nأنتِ هي جنس، والأصل الداوودي، صرتِ لنا شفيعة، عند الله السيد.\n\nأنتِ هي جنس، والكرمة النقية، التي لم تُفَلَّح، الممتلئة من حياة العالم.\n\nأنتِ هي جنس، والأصل المبارك، ولدتِ الكلمة، إبن الآب.\n\nفلهذا نسبِّح الله، الذي تجسَّد منكِ، وصار إنساناً مثلنا، ما خلا الخطية وحدها." },
    { language: 'englishArabic', text: "Anti hiya gins, wa asl el-murattil Dawoud, el-malik el-hasan fit-tarteel, ab el-Maseeh bil-gasad.\n\nAnti hiya gins, wa asl Yowakeem el-habeeb, utlubi 'anna ayyatuha el-'Adhra', fa-yasma' laki er-Rabb el-Ilah.\n\nAnti hiya gins, wa asl es-siddeeqeen, waladti lana el-waheed, malikana Yasou' el-Maseeh.\n\nAnti hiya gins, wa asl el-atqiya', sirti kursiyyan, lil-Maseeh Ibn Allah.\n\nAnti hiya gins, wal-asl ed-Dawoudi, sirti lana shafee'a, 'ind Allah es-sayyid.\n\nAnti hiya gins, wal-karma en-naqiyya, allati lam tufallah, el-mumtali'a min hayat el-'alam.\n\nAnti hiya gins, wal-asl el-mubarak, waladti el-Kalima, Ibn el-Ab.\n\nFa-li-hadha nusabbih Allah, alladhi tagassada minki, wa sara insanan mithlana, ma khala el-khatiyya wahdaha." },
  ] },
  { id: "vp-the-fourth-sahidic-interpretation", title: "The Fourth Sahidic Interpretation", versions: [
    { language: 'coptic', text: "Ⲇⲁⲩⲓⲇ ⲡ̀ⲟⲩⲣⲟ ⲟⲩⲟϩ ⲡⲓⲡ̀ⲣⲟⲫⲏⲧⲏⲥ: ⲁϥⲉⲣⲥⲩⲙⲙⲉⲛⲓⲛ ⲉⲑⲃⲏϯ: ⲱ̀ Ⲙⲁⲣⲓⲁ ϯⲡ̀ⲣⲟⲥⲧⲁⲧⲏⲥ: ⲑ̀ⲙⲁⲩ ⲙ̀ⲡⲓⲗⲟⲅⲟⲥ ⲛ̀ⲛⲟⲩϯ.\n\nⲐⲛⲟⲩⲛⲓ ⲛ̀Ⲓⲉⲥⲥⲉ ⲛⲉⲙ Ⲇⲁⲩⲓⲇ: ⲕⲁⲧⲁ ⲡ̀ⲥⲁϫⲓ ⲛ̀Ⲏⲥⲁⲏ̀ⲁⲥ: ⲧⲁⲫ̀ⲙⲏⲓ ⲁϭⲛⲉ ϩ̀ⲗⲓ ⲛ̀ϣⲟⲩⲓⲧ: ⲁⲥⲓ̀ⲛⲓ ⲛⲁⲛ ⲙ̀Ⲙⲁⲥⲓⲁⲥ.\n\nⲠⲓⲁⲧⲁⲣⲭⲏ ⲛⲉⲙ ⲡⲓⲁⲧϫⲱⲕ: ⲡⲓⲗⲟⲅⲟⲥ ⲛ̀ⲧⲉ Ⲫ̀ⲓⲱⲧ: ⲁϥϭⲓ ⲛ̀ⲟⲩⲙⲟⲣⲫⲏ ⲙ̀ⲃⲱⲕ: ϣⲁ ⲛ̀ⲧⲉϥⲧⲁⲗϭⲟ ⲛ̀ⲛⲉⲛⲉⲣϧⲟⲧ.\n\nⲈⲑⲃⲉ ⲫⲁⲓ ⲧⲉⲛϯⲱ̀ⲟⲩ ⲛⲉ: ⲉⲛⲱϣ ⲉ̀ⲃⲟⲗ ⲛⲉⲙ Ⲅⲁⲃⲣⲓⲏⲗ: ϫⲉ ⲭⲉⲣⲉ ⲕⲉ ⲭⲁⲣⲓⲧⲱⲙⲉⲛⲏ: Ⲙⲁⲣⲓⲁ ⲑ̀ⲙⲁⲩ ⲛ̀Ⲉⲙⲙⲁⲛⲟⲩⲏⲗ." },
    { language: 'english', text: "David the king and prophet, gave signs concerning you, O Mary the intercessor, the Mother of God the Logos.\n\nThe root of Jesse and David, according to the saying of Isaiah, truly without any blunders, she bore for us the Messiah.\n\nHe who is without beginning or end, the Logos of the Father, He took a servant’s form, that He may heal our wounds.\n\nTherefore we glorify you, proclaiming with Gabriel, “Hail to you O full of grace, Mary the Mother of Immanuel.”" },
    { language: 'arabic', text: "داود الملك والنبي، قد أشار من أجلكِ، يا مريم الشفيعة، اُم الإله الكلمة.\n\nأصل يسى وداود، كقول أشعياء، حقاً بغير أشياء باطلة، ولدتْ لنا ماسياً.\n\nغير المبتدئ وغير المنتهي، كلمة الآب، أخذ شكل العبد، حتى شفى جراحاتنا.\n\nفلهذا نُمجدكِ، ونصرخ مع غبريال قائلين،\"السلام لكِ يا ممتلئة نعمة، مريم اُم عمانوئيل.\"" },
    { language: 'englishArabic', text: "Dawoud el-malik wan-nabi, qad ashara min aglik, ya Maryam esh-shafee'a, umm el-Ilah el-Kalima.\n\nAsl Yassa wa Dawoud, ka-qawl Asha'ya, haqqan bi-ghayr ashya' batila, waladat lana Massia.\n\nGhayr el-mubtadi' wa ghayr el-muntahi, kalimat el-Ab, akhadha shakl el-'abd, hatta shafa garahatina.\n\nFa-li-hadha numaggiduki, wa nasrukh ma'a Ghubriyal qa'ileen: \"Es-salam laki ya mumtali'a ni'ma, Maryam umm 'Emmanu'eel.\"" },
  ] },
  { id: "vp-the-fourth-hymn-of-abou-el-saad-of-aboutig", title: "The Fourth Hymn of Abou El-Saad of Aboutig", versions: [
    { language: 'english', text: "You are the known race / originating from David’s tribe / through you the reconciling is revealed / through you the promised vow is fulfilled.\n\nLike rain falling on wool / I mean the born Son / His servants thousands and myriads / bow down before Him in adoration.\n\nThe only-begotten of the Father descended / and took flesh to save us / He promised and wished to fulfill the vow / and was born of Mary and came to us.\n\nHe humbly took a bondservant’s form / and suffered for our sins / and was called the second Adam / and restored the first Adam to us.\n\nBecause of this oath / you Mary had chosen us / and we the assembled multitudes / exalt you O Mother of our Lord.\n\nHail to you O mother of mercy / we are your beloved pray acknowledge us / blessed are you O full of grace / before your Son intercede for us." },
    { language: 'arabic', text: "انت هي الجنس المعروف / من أصل قبيلة داود / وصار الصلح بكِ مكشوف / وبكِ تمَّ الوعد الموعود.\n\nمثل مطر ينزل علي الصوف / اعني هو الابن المولود / وخُدامه ربوات وألوف / تخر أمام وجهة بسجود.\n\nوحيد الآب نزَلَ و أخذ / جسداً حتي نجانا / وعد و أراد يتم الوعد / و وُلدَ من مريم و أتانا.\n\nتواضعَ و أخدَ شكل العبد / وتألم لاجل خطايانا / وَسُمىَّ آدم الثاني و ردَّ / آدم الاول أبانا.\n\nبحق قسم تلك القسمة / و انتِ قد اخترتينا / و نحن الجموع الملتئمة / نعظمكِ يا أم بارينا.\n\nالسلام لك يا ام الرحمة / نحن عبيدك جيرينا / طوباكِ يا مملوُة نعمة / عند ابنك الحبيب اشفعي فينا." },
    { language: 'englishArabic', text: "Anti hiya el-gins el-ma'rouf / min asl qabeelat Dawoud / wa sara es-sulh biki makshouf / wa biki tamma el-wa'd el-maw'oud.\n\nMithl matar yanzil 'ala es-souf / a'ni huwa el-Ibn el-mawloud / wa khuddamuhu rabawat wa ulouf / takhirru amam waghihi bi-sougoud.\n\nWaheed el-Ab nazala wa akhadha / gasadan hatta naggana / wa'ada wa arada yutimm el-wa'd / wa wulida min Maryam wa atana.\n\nTawada'a wa akhadha shakl el-'abd / wa ta'allama li-agl khatayana / wa summiya Adam eth-thani wa radd / Adam el-awwal abana.\n\nBi-haqq qasama tilka el-qisma / wa anti qad ikhtarteena / wa nahnu el-gumou' el-multa'ima / nu'azzimuki ya umm bareena.\n\nEs-salam laki ya umm er-rahma / nahnu 'abeeduki geereena / toubaki ya mamlou'at ni'ma / 'ind ibniki el-habeeb ishfa'i feena." },
  ] },
  { id: "vp-fourth-hymn-of-cantor-gabriel-of-qay-a", title: "Fourth Hymn of Cantor Gabriel of Qay A", versions: [
    { language: 'english', text: "O chosen honored descendant / from a pure spotless elect tribe / O daughter of the righteous David / the good chanter with a gripping voice.\n\nThe good chanter with a gripping voice / who artfully praises your beauty / says the Lord of Sabaoth / He willed and loved the gates of Zion.\n\nHe willed and loved the gates of Zion / above all the houses of Jacob / and adorned you with the hidden mystery; / all that was written of you was fulfilled.\n\nAll that was written of you was fulfilled / and what the righteous fathers have prophesied / of the Economy of the revered King / and His appearance from beyond all ages.\n\nAnd his appearance from beyond all ages / they spoke of existent testimonies / of your childbearing O beauty of firstlings / for nine complete months.\n\nFor nine complete months / you conceived the worshipped King / Isaiah the prophet has said behold / a virgin shall conceive and give birth to a Son.\n\nA virgin shall conceive and give birth to a Son / and call His name Immanuel / God with us presently here / Savior of His people Israel.\n\nSavior of His people Israel / from the snares of the opposing demons / the words and sayings were completed / and we have become joyful by you.\n\nAnd we have become joyful by you / we are the Christians / and we the assembled people / exalt you O Mother of the Holy.\n\nExalt you O Mother of the Holy / and kneel down between your hands / proclaiming and saying / hail to you and hail unto you.\n\nHail to you and hail unto you, we ask you O Mother of the Beloved, grant us to be in your fathers’ dwellings, Abraham Isaac and Jacob." },
    { language: 'arabic', text: "يا نسل مكرم مختار / من سبط نقي طاهر مغبوط / يا ابنة داود البار / حسن التراتيل وشجي الصوت.\n\nحسن التراتيل وشجي الصوت. المادح في حسنكِ بفنون / يقول رب الصاباؤوت / شاء وأحب ابواب صهيون.\n\nشاء وأحب ابواب صهيون / عن كل مساكن آل يعقوب / وزانكِ بالسر المكنون / وكَمُلَ عنكِ ما هو مكتوب.\n\nوكَمُلَ عنكِ ما هو مكتوب / وما تنبأ به الآباء الابرار / عن تدبير الملك المرهوب / وظهوره في عقب الادهار.\n\nوظهوره في عقب الادهار / نطقوا بشهادات موجودة / عن حَبَََلِكِ يا زين الابكار / تسعة شهور معدودة.\n\nتسعة شهور معدودة / حبلتِ بالملك المعبود / اشعياء النبي قال ها هوذا / عذراء تحبل و تلد ابنا.\n\nعذراء تحبل و تلد ابنا / يدعى اسمه عمانوئيل / الله معنا حاضر موجود / مخلص شعبه اسرائيل.\n\nمخلص شعبه اسرائيل / من كيد الاعداء الشياطين / وتَّم القول وكَمُلَ ما قيل / ونحن بكِ صرنا فرحين.\n\nو نحن بكِ صرنا فرحين / انون خاني إخريستيانوس / ونحن الشعوب المجتمعين / نعظمك يا ام القدوس.\n\nنعظمك يا ام القدوس / وننحني بين يديكِ / إنوش إﭬول إنجو إموس / السلام لكِ ثم السلام إليكِ /\n\nالسلام لكِ ثم السلام إليك، ونسألك يا أم المحبوب، ان تحظينا في مظال اباءك، ابراهيم واسحق ويعقوب." },
    { language: 'englishArabic', text: "Ya nasl mukarram mukhtar / min sibt naqiyy tahir maghbout / ya ibnat Dawoud el-barr / hasan et-tarateel wa shagiy es-sawt.\n\nHasan et-tarateel wa shagiy es-sawt / el-madih fi husniki bi-founoun / yaqoul Rabb es-Saba'out / sha'a wa ahabba abwab Sahyoun.\n\nSha'a wa ahabba abwab Sahyoun / 'an kull masakin al Ya'qoub / wa zanaki bis-sirr el-maknoun / wa kamula 'anki ma huwa maktoub.\n\nWa kamula 'anki ma huwa maktoub / wa ma tanabba'a bihi el-aba' el-abrar / 'an tadbeer el-malik el-marhoub / wa zuhourihi fi 'aqib el-adhar.\n\nWa zuhourihi fi 'aqib el-adhar / nataqou bi-shahadat mawgouda / 'an habaliki ya zayn el-abkar / tis'at shuhour ma'douda.\n\nTis'at shuhour ma'douda / habalti bil-malik el-ma'boud / Asha'ya en-nabi qala ha huwa dha / 'adhra' tahbal wa talid ibnan.\n\n'Adhra' tahbal wa talid ibnan / yud'a ismuhu 'Emmanu'eel / Allah ma'ana hadir mawgoud / mukhallis sha'bihi Isra'eel.\n\nMukhallis sha'bihi Isra'eel / min kayd el-a'da' esh-shayateen / wa tamma el-qawl wa kamula ma qeel / wa nahnu biki sirna fariheen.\n\nWa nahnu biki sirna fariheen / anon khan-ekhristianos / wa nahnu esh-shu'oub el-mugtami'een / nu'azzimuki ya umm el-quddous.\n\nNu'azzimuki ya umm el-quddous / wa nanhani bayna yadayki / en-oush evol en-jō emmos / es-salam laki thumma es-salam ilayki.\n\nEs-salam laki thumma es-salam ilayki, wa nas'aluki ya umm el-mahboub, an tahzeena fi mazall aba'ik, Ibraheem wa Ishaq wa Ya'qoub." },
  ] },
  { id: "vp-the-fourth-hymn-of-cantor-gabriel-of-qay-b", title: "The Fourth Hymn of Cantor Gabriel of Qay B", versions: [
    { language: 'english', text: "You are the honored descendant, from the root of the blessed father, from a pure and great tribe, that was chosen by the high God.\n\nDavid your father who spoke, in his psalms explaining with songs, “Behold the great King, will come in the form of a Man.\n\nThat He may renew us after we were nothing, and destroy the snare of the Devil, He will descend as rain on clouds,” I refer to the only Son.\n\nBlessed are you O Mary, blessed are you O sanctuary, you contained the great Mystery, and carried the true Light.\n\nWhich tongue can speak about this, and explain your nature, if we say the throne you are greater, for the throne is also illuminated.\n\nAnd you are a human from Adam’s race, and carried the King the Judge, in your womb He dwelt, and you bore Him as a naked Child.\n\nHail to you O Mother of our Savior, we ask you O pure Virgin, to ask the Lord to bring us, to the harbor in peace." },
    { language: 'arabic', text: "أنتِ هي نسل مكرم، من نسل الآب الطوباوي، من سبط نقيٍ ومعظَّم، إختاره الرب الفوقاني.\n\nداود أبوكِ المتكلم، في مزموره يشرح بأغاني، ها هوذا الملك الأعظم، يأتي في صورة إنسانِ.\n\nليجدِّدنا من بعد عدم، ويبطل كيد الشيطانِ، ينزل كالقطر بغير غمام، أعني هو الإبن الوحداني.\n\nطوباكِ طوباكِ يا مريم، طوباكِ يا هيكل منصانِ، قد حويتِ السر الأعظم، وحملتِ النور الحقاني.\n\nأي لسان يقدر أن يتكلم، ولوصفِك يشرح بمعاني، أن قلنا الكرسي فأنتِ أعظم، لأن الكرسي نوراني.\n\nوأنتِ بشر من نسل آدم، وحملتِ الملك الديانِ، في جوف أحشائكِ صار قائم، وولدتِه طفل عريانِ.\n\nالسلام لكِ يا اُم مخلصنا، ونسألكِ يا بكر نقية، تسألي الرب أن يوصِّلنا، إلى الميناء بطمأنينة." },
    { language: 'englishArabic', text: "Anti hiya nasl mukarram, min nasl el-ab et-toubawi, min sibt naqiyyin wa mu'azzam, ikhtarahu er-Rabb el-fawqani.\n\nDawoud abouki el-mutakallim, fi mazmourihi yashrah bi-aghani: ha huwa dha el-malik el-a'zam, ya'ti fi sourat insani.\n\nLi-yugaddidana min ba'd 'adam, wa yubtil kayd esh-shaytani, yanzil kal-qatr bi-ghayr ghamam, a'ni huwa el-Ibn el-wahdani.\n\nToubaki toubaki ya Maryam, toubaki ya haykal munsani, qad hawayti es-sirr el-a'zam, wa hamalti en-nour el-haqqani.\n\nAyy lisan yaqdir an yatakallam, wa li-wasfiki yashrah bi-ma'ani; in qulna el-kursi fa-anti a'zam, li-anna el-kursi nourani.\n\nWa anti bashar min nasl Adam, wa hamalti el-malik ed-dayyani, fi gawf ahsha'iki sara qa'im, wa waladtihi tifl 'uryani.\n\nEs-salam laki ya umm mukhallisina, wa nas'aluki ya bikr naqiyya, tas'ali er-Rabb an yuwassilana, ila el-meena' bi-tuma'neena." },
  ] },
  { id: "vp-the-fourth-hymn-of-cantor-gabriel-of-qay-c", title: "The Fourth Hymn of Cantor Gabriel of Qay C", versions: [
    { language: 'english', text: "You are the honored descendant, the pure and blessed seed, from a pure and great tribe, that was chosen by the Lord of hosts.\n\nDavid your father who spoke of, the glory of the One of the Trinity, “The great King will come, and give us life after death.”\n\nAnd give us life after death, and renew us after we were nothing, as the saying of the blessed father, “The Lord has sworn and will not repent.”\n\nAnd dwelt with the divine hypostasis, in the womb of the Virgin Mary, and appeared united with humanity, and was likened to the great high priest.\n\nAnd was likened to the great high priest, Melchizedek and fulfilled His service, and was baptized in the Jordan, and granted us the pledge of grace.\n\nLet us come to glorify and honor, and proclaim with sayings and songs, “Blessed are you O Mary, hail to you O Mother of mercy.”\n\nHail to you O Mother of mercy, blessed are you O full of grace, the Lady of us all Mary, through her prayers and intercessions." },
    { language: 'arabic', text: "أنتِ هي جنس مكرم، ونسل نقي طاهر مغبوط، من سبط نقي ومعظَّم، إختاره رب الصباؤوت.\n\nداود أبوكِ المتكلم، بمجد الواحد من الثالوث، قال \"سوف يأتي الملك الأعظم، ويحيينا من بعد الموت.\"\n\nويحيينا من بعد الموت، ويجدِّدنا من بعد عدم، كما قال الأب المغبوط، \"أقسم الرب ولم يندم.\"\n\nوحل بأُقنوم اللاهوت، في أحشاء البكر البتول مريم، وظهر متحداً بالناسوت، وتمثَّل بالحَبر الأعظم.\n\nوتمثَّل الحَبر الأعظم، ملكيصادق وأوفى الخدمة، وتعمَّد في الأردن وأنعم، علينا بعربون النعمة.\n\nتعالوا نمجد ونكرم، ونصيح بأصوات ونغمة، ونقول \"طوباكِ يا مريم، السلام لكِ يا اُم الرحمة.\"\n\nالسلام لكِ يا اُم الرحمة، طوباكِ يا ممتلئة نعمة، أووتين شويس إننيب ماريا، هيتين نيس طوڤه نيم نيس إبريسڤيِّا." },
    { language: 'englishArabic', text: "Anti hiya gins mukarram, wa nasl naqiyy tahir maghbout, min sibt naqiyy wa mu'azzam, ikhtarahu Rabb es-Saba'out.\n\nDawoud abouki el-mutakallim, bi-magd el-wahid min eth-thalouth, qala: \"Sawfa ya'ti el-malik el-a'zam, wa yuhyeena min ba'd el-mawt.\"\n\nWa yuhyeena min ba'd el-mawt, wa yugaddidana min ba'd 'adam, kama qala el-ab el-maghbout: \"Aqsama er-Rabb wa lam yandam.\"\n\nWa halla bi-uqnoum el-lahout, fi ahsha' el-bikr el-batoul Maryam, wa zahara muttahidan bin-nasout, wa tamaththala bil-habr el-a'zam.\n\nWa tamaththala bil-habr el-a'zam, Malki-Sadeq wa awfa el-khidma, wa ta'ammada fil-Urdun wa an'am, 'alayna bi-'arboun en-ni'ma.\n\nTa'alou numaggid wa nukarrim, wa nasee'h bi-aswat wa nagham, wa naqoul: \"Toubaki ya Maryam, es-salam laki ya umm er-rahma.\"\n\nEs-salam laki ya umm er-rahma, toubaki ya mumtali'a ni'ma, Ouoh ten-tshois ennēb Maria, hiten nes-tovh nem nes-epresvia." },
  ] },
  { id: "vp-the-fourth-hymn-of-pope-abba-markos-viii", title: "The Fourth Hymn of Pope Abba Markos VIII", versions: [
    { language: 'english', text: "You are the chosen descendant, from the blessed house of David, with your presence O pure one, Adam became happy.\n\nThe Eternal and Mighty dwelt in you, the only Son and Logos, you carried Him O Lady of the first-born, nine full months.\n\nYou bore Him in Bethlehem, as a young naked Child, and placed Him in a manger, wrapped in clothes as a human.\n\nIn the presence of Salome and the carpenter, Joseph the blessed elder, and others came to Him with joy, the shepherds worshiped Him.\n\nAnd His star shone like fire, in the east it was illuminating, and they saw Him in those regions, and the wise men came to Him.\n\nWith expensive gifts / gold, myrrh, and frankincense / the star was shining day and night / to lead them to the place.\n\nWhere the Omniscient dwelt, the Begotten the Creator of the ages, they worship Him with joy and adoration, and beheld the enlightened glory.\n\nHail to you O Lady of virgins, O Mary the Virgin, Jesus Christ dwelt in your womb, and became our Savior." },
    { language: 'arabic', text: "أنتِ هي الجنس المختار، من بيت داود الطوباني، بوجودكِ يا طُهر الأطهار، آدم بكِ قد صار فرحانِ.\n\nسكن فيكِ الأزلي الجبار، الإبن الكلمة الوحداني، وحملتِه يا ست الأبكار، تسعة شهور من غير نقصانِ.\n\nوولدتِه في بيت لحم إجهار، كطفل صغير عريانِ، ووضعتيه في مزود أبقار، ملفوف بخرق كالإنسانِ.\n\nبحضور سالومى والنجار، الشيخ يوسف الطوباني، وأتوا إليه بفرح ووقار، وسجدوا له الرعيانِ.\n\nوظهر نجمه يشعل كالنار، في المشرق زاهي نوراني، ونظروه في تلك الأقطار، ومجوس قصدوا إليه بأمانِ.\n\nومعهم هدايا غالية المقدار، ذهباً ومراً ولبانِ، والنجم يسير ليلاً ونهار، معهم يرشدهم أعيانِ.\n\nإلى حيث كان عالِم الأسرار، المولود خالق الأزمانِ، وسجدوا له بفرح ووقار، وعاينوا المجد النوراني.\n\nالسلام لكِ يا ست الأبكار، يا مريم تي بارثينوس، يا مَنْ في أحشائكِ قد حلَّ وصار، مخلصنا إيسوس بيخريستوس." },
    { language: 'englishArabic', text: "Anti hiya el-gins el-mukhtar, min bayt Dawoud et-toubani, bi-wugoudiki ya tuhr el-at-har, Adam biki qad sara farhani.\n\nSakana feeki el-azali el-gabbar, el-Ibn el-Kalima el-wahdani, wa hamaltihi ya sitt el-abkar, tis'at shuhour min ghayr nuqsani.\n\nWa waladtihi fi Bayt Lahm ighar, ka-tifl sagheer 'uryani, wa wada'teehi fi mizwad abqar, malfouf bi-khiraq kal-insani.\n\nBi-hudour Salomi wan-naggar, esh-shaykh Yousef et-toubani, wa atou ilayhi bi-farah wa waqar, wa sagadou lahu er-ru'yani.\n\nWa zahara nagmuhu yash'al kan-nar, fil-mashriq zahi nourani, wa nazarouhu fi tilka el-aqtar, wa magous qasadou ilayhi bi-amani.\n\nWa ma'ahum hadaya ghaliyat el-miqdar, dhahaban wa murran wa libani, wan-nagm yaseer laylan wa nahar, ma'ahum yurshiduhum a'yani.\n\nIla haythu kana 'alim el-asrar, el-mawloud khaliq el-azmani, wa sagadou lahu bi-farah wa waqar, wa 'ayanou el-magd en-nourani.\n\nEs-salam laki ya sitt el-abkar, ya Maryam Tiparthenos, ya man fi ahsha'iki qad halla wa sar, mukhallisuna Iēsous Pikhristos." },
  ] },
  { id: "vp-the-fourth-hymn-of-el-bardanohee", title: "The Fourth Hymn of El-Bardanohee", versions: [
    { language: 'english', text: "You are the heir and descendant, of the house of prophecy and reverence, your holy father David, he spoke about you in sayings.\n\nYou bore for us the beloved Jesus, Light of Light a revered God, and we were granted what is needed, through your conception with Immanuel.\n\nBy His will the heaven stands, and the firmament day and night, He was in your womb covered, Gabriel announced to you.\n\nYour milk nourished the Awesome One, He was nursed by you with great love, and before you Adam was captive, by the Devil in sadness.\n\nAbraham Isaac and Jacob, were with him captives for a long time, by your purity the Scriptures were fulfilled, they returned with joy and happiness.\n\nThey were saved by the beloved Jesus, before Him Michael worships, He shed His Blood for us, for the salvation of His servants at all times.\n\nHail to you O Mother of God, ask your Son on our behalf, to forgive us sinners, through your prayers and honored rank." },
    { language: 'arabic', text: "أنتِ هي الجنس المنسوب، بيت النبوة والتبجيل، أبوكِ داود طاهر محسوب، كم تكلم فيكِ بأقوال.\n\nولدتِ لنا يسوع المحبوب، نور من نور إله جليل، وبلغنا بكِ المطلوب، بميلادِك عمانوئيل.\n\nالذي بأمره السماء منصوب، وفَلَكٌ يخدم نهار وليل، صار في جوف أحشائكِ محجوب، كما بشركِ به جبرائيل.\n\nصار لبنِك في فم المرهوب، يرضع بفمِه بحب جليل، وآدم من قَبْلِكِ كان مسلوب، مع الشيطان حزين ذليل.\n\nوإبراهيم وإسحق ويعقوب، معه مأسورين زمان طويل، بطهارتِك تم المكتوب، عادوا فرحين بالتهليل.\n\nعُتِقوا بيسوع المحبوب، قدامه يسجد ميخائيل، وجعل دمه عنا مسكوب، لخلاص عبيده جيلاً بعد جيل.\n\nالسلام لكِ يا اُم الإله، جيرينا قدام إبنِك، ليسامحنا نحن الخطاة، بصلاتِك وشرف جنسِك." },
    { language: 'englishArabic', text: "Anti hiya el-gins el-mansoub, bayt en-nubouwa wat-tabgeel, abouki Dawoud tahir mahsoub, kam takallama feeki bi-aqwal.\n\nWaladti lana Yasou' el-mahboub, nour min nour ilah galeel, wa balaghna biki el-matloub, bi-meeladiki 'Emmanu'eel.\n\nAlladhi bi-amrihi es-sama' mansoub, wa falakun yakhdim nahar wa layl, sara fi gawf ahsha'iki mahgoub, kama bashsharaki bihi Gibra'eel.\n\nSara labanuki fi fam el-marhoub, yarda' bi-fammihi bi-hubb galeel, wa Adam min qabliki kana masloub, ma'a esh-shaytan hazeen dhaleel.\n\nWa Ibraheem wa Ishaq wa Ya'qoub, ma'ahu ma'soureen zaman taweel, bi-taharatiki tamma el-maktoub, 'adou fariheen bit-tahleel.\n\n'Utiqou bi-Yasou' el-mahboub, quddamahu yasgud Mikha'eel, wa ga'ala damahu 'anna maskoub, li-khalas 'abeedihi geelan ba'd geel.\n\nEs-salam laki ya umm el-Ilah, geereena quddam ibnik, li-yusamihana nahnu el-khutah, bi-salatik wa sharaf ginsik." },
  ] },
  { id: "vp-the-fifth-greek-interpretation", title: "The Fifth Greek Interpretation", versions: [
    { language: 'coptic', text: "Ⲓⲥ ϩⲏⲡⲡⲉ Ⲡⲟ︦ⲥ︦ ⲫⲏⲉ̀ⲧⲁϥϣⲁⲛϣ: ⲛ̀ⲛⲉⲓⲟϯ ϧⲉⲛ ⲡⲓⲇ̀ⲣⲩⲙⲟⲥ: ⲁϥⲛⲁϩⲙⲟⲩ ⲉ̀ⲃⲟⲗϩⲁ ⲛⲓⲟⲩⲱⲛϣ: ⲉⲧϩⲱⲗⲉⲙ ⲛ̀ⲧⲉ ⲡⲓⲇⲟⲕⲓⲙⲟⲥ.\n\nⲀϥⲧⲉⲙⲙⲱⲟⲩ ⲙ̀ⲡⲓⲙⲁⲛⲛⲁ ⲧⲏⲣⲟⲩ: ⲁϥⲧ̀ⲥⲱⲟⲩ ⲙ̀ⲡⲓⲙⲱⲟⲩ ϧⲉⲛ ⲟⲩⲕⲟϩ ⲙ̀ⲡⲉⲧⲣⲁ: ⲟⲩⲟϩ ⲁϥϭⲱⲣⲡ ⲉ̀ⲛⲟⲩⲡ̀ⲣⲉⲥⲃⲩⲧⲉⲣⲟⲩ: ⲛⲉⲙ ⲛⲟⲩⲙⲓⲕⲣⲱⲛ ⲥⲓⲙⲓⲱⲛ ⲫⲉⲇⲣⲁ.\n\nⲀϥⲥⲱⲧⲡ ⲙ̀ⲙⲟ ⲛ̀ⲟⲩⲧⲟⲣⲟⲥ ⲛⲁϥ: Ⲁⲇⲁⲙ ⲧⲟⲩ ⲅⲏⲓⲛⲟⲩ ⲑⲩⲅⲁⲧⲏⲣ: ⲉⲑⲣⲉϥ ⲥⲱϯ ⲛ̀ⲛⲏⲉⲧⲁⲩⲣⲁⲛⲁϥ: ϫⲉ ⲭⲉⲣⲉ ⲛⲩⲙⲫⲏⲧⲟⲩ Ⲡⲁⲧⲏⲣ.\n\nⲀⲣⲉϣⲱⲡⲓ ⲛ̀ⲟⲩⲫⲉ ⲙ̀ⲙⲁϩⲥ̀ⲛⲟⲩϯ: ⲉⲧⲥⲟⲃϯ ⲉ̀ⲡⲓⲟⲩⲱⲓⲛⲓ ⲙ̀ⲙⲏⲓ: ⲁϥϣⲁⲓ ⲛ̀ϧⲏϯ ⲱ̀ ϯⲙⲁⲥⲛⲟⲩϯ: ⲛ̀ϫⲉ ⲡⲓⲣⲏ ⲛ̀ⲧⲉ ϯⲙⲉⲑⲙⲏⲓ.\n\nⲀⲣⲉϫ̀ⲫⲟϥ ϩⲓⲧⲉⲛ ⲟⲩⲡ̀ⲣⲟⲫⲏⲧⲓⲁ̀: ⲁϭⲛⲉ ϫ̀ⲣⲟϫ ⲟⲩⲇⲉ ⲫ̀ⲑⲁⲣⲥⲓⲁⲛ: ⲕⲉ ⲱⲥ ⲁⲩⲧⲱⲥ ⲧⲏⲥ ⲁⲗⲏⲑⲓⲁ̀: ⲭⲱⲣⲓⲥ ⲇⲓⲭ̀ⲟⲥⲧⲁⲥⲓⲁⲛ.\n\nϦⲉⲛ ⲕⲉⲛϥ ⲙ̀Ⲡⲉϥⲓⲱⲧ ⲫⲁ ⲡⲓⲱ̀ⲟⲩ: ⲙⲁⲣⲉⲛϩⲱⲥ ⲉ̀ⲣⲟϥ ϩⲱⲥ Ⲑⲉⲟⲥ: ⲟⲩⲟϩ ⲛ̀ⲧⲉⲛϫⲱ ⲛⲁϥ ⲛⲉⲙ ⲧⲉϥⲙⲁⲩ: ϩⲱⲥ ⲣⲱⲙⲓ ⲛ̀ⲕⲁⲗⲱⲥ ⲇⲓⲕⲉⲟⲥ.\n\nⲦⲉⲛϯⲱ̀ⲟⲩ ⲛⲉ ⲱ̀ ⲑⲏⲉⲧⲥⲙⲁⲙⲁⲧ: ϣⲁ ⲡⲓⲛⲓϥⲓ ⲛ̀ⲧⲉ ⲗⲉⲩⲧⲉⲟⲥ: ϫⲉ ⲁⲣⲉϫⲓⲙⲓ ⲅⲁⲣ ⲛ̀ⲟⲩϩ̀ⲙⲟⲧ: ϧⲁⲧⲉⲛ Ⲡⲉⲛⲟⲩϯ Ⲩⲓⲟⲥ Ⲑⲉⲟⲥ." },
    { language: 'english', text: "Behold the God who sustained, your fathers in the wilderness, and delivered them from the ravenous, wolves of the tempter.\n\nHe fed all of them manna, and gave them water out of a rock, and declared to their elders, and their youth delightful miracles.\n\nHe chose you as a dwelling for Himself, O daughter of the earthly Adam, that He may save those who pleased Him, therefore rejoice O Bride of the Father.\n\nYou became a second heaven, prepared for the true Light, He shone from you O Mother of God, the Sun of Righteousness.\n\nYou gave birth to Him with prophecy, without seed or corruption, and He is truly as He was, without separation.\n\nFrom the bosom of His glorified Father, let us praise Him as God, and hymn Him with His Mother, as a good and righteous Man.\n\nWe glorify you O blessed one, until the last breath saying, \"You have found favor before, your God the Son of God.\"" },
    { language: 'arabic', text: "ها هوذا الرب الذي أعال آبائك في البرية وأنقذهم من ذائب المجرب الخاطفة.\n\nوأطعمهم المن جميعاً وسقاهم الماء من صخرة صماء. ثم أعلن لمشائخهم وشبانهم آيات بهية.\n\nاختارك مسكنا له يا إبنه آدم الأرضي ليخلص الذين أرضوه فأفرحي يا عروسة الآب.\n\nصرت سماء ثانية معدة للنور الحقيقي وأشرق منك يا والدة الإله شمس البر.\n\nولدته بالنبوة بغير زرع ولا فساد وهو بالحقيقية كما هو بغير افتراق.\n\nفي حضن ابيه الممجد فلنسبحه كإله ونمدحه مع أمه كإنسان صالح صديق.\n\nنمجدك ايتها المباركة إلى النفس الأخير لأنك وجدت نعمة عند إلهك ابن الله." },
    { language: 'englishArabic', text: "Ha huwa dha er-Rabb alladhi a'ala aba'aki fil-bariyya wa anqadhahum min dhi'ab el-mugarrib el-khatifa.\n\nWa at'amahum el-mann gamee'an wa saqahum el-ma' min sakhra samma'. Thumma a'lana li-mashayikhihim wa shubbanihim ayat bahiyya.\n\nIkhtaraki maskanan lahu ya ibnat Adam el-ardi li-yukhallis alladheena arda'ouh; fa-ifrahi ya 'arousat el-Ab.\n\nSirti sama'an thaniya mu'adda lin-nour el-haqeeqi, wa ashraqa minki ya walidat el-Ilah shams el-birr.\n\nWaladtihi bin-nubouwa bi-ghayr zar' wa la fasad, wa huwa bil-haqeeqa kama huwa bi-ghayr iftiraq.\n\nFi hudn abeehi el-mumaggad; fal-nusabbihuhu ka-ilah wa namdahuhu ma'a ummihi ka-insan salih siddeeq.\n\nNumaggiduki ayyatuha el-mubaraka ila en-nafas el-akheer li-annaki wagadti ni'ma 'ind ilahik Ibn Allah." },
  ] },
  { id: "vp-the-fifth-bohairic-interpretation-a", title: "The Fifth Bohairic Interpretation A", versions: [
    { language: 'coptic', text: "Ⲛⲓⲫⲏⲟⲩⲓ ⲥⲉϩⲱⲥ ⲉ̀ⲣⲟ: ⲱ̀ ⲑⲏⲉⲑⲙⲉϩ ⲛ̀ⲉⲩⲗⲟⲩⲅⲓⲁ: ⲑⲏⲉⲧⲧⲟⲩⲃⲏⲟⲩⲧ ⲛ̀ⲁⲧⲧⲁⲕⲟ: ϯⲁ̀ⲅⲓⲁ ⲙ̀ⲙⲏⲓ Ⲙⲁⲣⲓⲁ.\n\nⲀⲣⲉϣⲱⲡⲓ ⲛ̀ⲟⲩⲫⲉ ⲙ̀ⲙⲁϩⲥ̀ⲛⲟⲩϯ: ϩⲓϫⲉⲛ ⲡⲓⲕⲁϩⲓ ⲟⲩⲙⲉⲑⲙⲏⲓ: ϫⲉ ⲁϥϣⲁⲓ ⲛⲁⲛ ⲉ̀ⲃⲟⲗ ⲛ̀ϧⲏϯ: ⲛ̀ϫⲉ ⲡⲓⲣⲏ ⲛ̀ⲧⲉ ϯⲙⲉⲑⲙⲏⲓ.\n\nⲀⲣⲉϫ̀ⲫⲟϥ ϩⲓⲧⲉⲛ ⲟⲩⲡ̀ⲣⲟⲫⲏⲧⲓⲁ̀: ⲁϭⲛⲉ ϫ̀ⲣⲟϫ ⲛ̀ⲁⲧⲧⲁⲕⲟ: ⲟⲩⲇⲉ ⲅⲁⲙⲟⲥ ⲟⲩⲇⲉ ⲥⲩⲛⲟⲩⲥⲓⲁ̀: ϩⲱⲥ ⲇⲩⲙⲓⲟⲩⲣⲅⲟⲥ ⲟⲩⲟϩ ⲛ̀ⲟⲩⲣⲟ.\n\nⲦⲉⲛϯⲱⲟⲩ ⲛⲉ ⲱ̀ ⲑⲏⲉ̀ⲧⲉⲛϩⲟⲧ: ⲛⲉⲙ ⲡⲓⲁⲅⲅⲉⲗⲟⲥ ⲛ̀ⲧⲉ ⲡⲓⲥ̀ⲙⲟⲩ: ϫⲉ ⲭⲉⲣⲉ ⲕⲉ ⲭⲁⲣⲓⲧⲱⲙⲉⲛⲏ ⲱ̀ ⲑⲏⲉⲑⲙⲉϩ ⲛ̀ϩⲙⲟⲧ: ⲟⲩⲟϩ Ⲡⲟ︦ⲥ︦ ϣⲟⲡ ⲛⲉⲙⲉ." },
    { language: 'english', text: "The heavens praise you, O who are full of blessing, the undefiled pure one, the true Saint Mary.\n\nYou became a second heaven, on earth in truth, for out of you the Sun of Righteousness, shone upon us.\n\nYou gave birth to Him with prophecy, without seed or corruption, nor marriage or a [man’s] seed, as a Creator and King.\n\nWe glorify you O trusted one, with the angel of blessing saying, \"Hail to you O full of grace, the Lord is with you.\"" },
    { language: 'arabic', text: "السموات تسبحك أيتها المملوءة بركة الطاهرة بغير فساد القديسة الحقيقية مرتمريم.\n\nصرت سماء ثانية على الأرض حقاً لأنه أشرق لنا منك شمس البر\n\nولدته بالنبوة بغير زرع ولا فساد ولا زواج ولا مباضعة كخالق وملك.\n\nنمجدك أيتها الأمينة قائلين مع ملاك البركة أفرحي أيتها الممتلئة نعمة . الرب معك." },
    { language: 'englishArabic', text: "Es-samawat tusabbihuki ayyatuha el-mamlou'a baraka, et-tahira bi-ghayr fasad, el-qiddeesa el-haqeeqiyya Martmaryam.\n\nSirti sama'an thaniya 'ala el-ard haqqan, li-annahu ashraqa lana minki shams el-birr.\n\nWaladtihi bin-nubouwa bi-ghayr zar' wa la fasad wa la zawag wa la mubada'a, ka-khaliq wa malik.\n\nNumaggiduki ayyatuha el-ameena qa'ileen ma'a malak el-baraka: ifrahi ayyatuha el-mumtali'a ni'ma, er-Rabb ma'aki." },
  ] },
  { id: "vp-the-fifth-bohairic-interpretation-b", title: "The Fifth Bohairic Interpretation B", versions: [
    { language: 'coptic', text: "Ⲉⲣⲉ ⲛⲁⲥ̀ⲫⲟⲧⲟⲩ ⲱ̀ Ⲙⲁⲣⲓⲁ: ⲃⲉⲃⲓ ⲛ̀ⲟⲩⲥ̀ⲙⲟⲩ ⲛⲉⲙ ⲟⲩⲥⲟⲫⲓⲁ: ϩⲓⲛⲁ ⲛ̀ⲧⲁϫⲱ ⲛ̀ϯⲡⲟⲗⲏⲧⲓⲁ: ϯⲫⲉ ⲙ̀ⲃⲉⲣⲓ ⲉⲧϩⲓϫⲉⲛ ⲡⲓⲕⲁϩⲓ.\n\nϪⲉ ⲁϥϣⲁⲓ ⲛⲁⲛ ⲉ̀ⲃⲟⲗ ⲛ̀ϧⲏϯ: ⲛ̀ϫⲉ ⲡⲓⲟⲩϫⲁⲓ ⲛⲉⲙ ⲡⲓⲥⲱϯ: ϧⲉⲛ ⲡⲉϥⲟⲩⲱϣ ⲛⲉⲙ ⲡⲉϥϯⲙⲁϯ: ⲁϥⲓ̀ⲟⲩⲟϩ ⲁϥⲥⲱϯ ⲙ̀ⲙⲟⲛ.\n\nⲀⲣⲉϫ̀ⲫⲟϥ ⲱ̀ ϯⲡⲁⲛⲁ̀ⲅⲓⲁ: ⲕⲁⲧⲁ ⲡ̀ⲥⲁϫⲓ ⲛ̀ϯⲡ̀ⲣⲟⲫⲏⲧⲓⲁ: ⲁϭⲛⲉ ϫ̀ⲣⲟϫ ⲟⲩⲇⲉ ⲥⲩⲛⲩⲥⲓⲁ: ϧⲉⲛ ⲟⲩϩⲱⲃ ⲙ̀ⲡⲁⲣⲁⲇⲟⲝⲟⲛ.\n\nⲘⲁⲣⲉⲛϯⲱ̀ⲟⲩ ⲛ̀ϯⲁ̀ⲅⲓⲁ̀: ϧⲉⲛ ϩⲁⲛⲥ̀ⲙⲏ ⲛ̀ⲇⲟⲝⲟⲗⲟⲅⲓⲁ̀: ϫⲉ ⲭⲉⲣⲉ ⲣⲁϣⲓ ⲱ̀ Ⲙⲁⲣⲓⲁ: ⲟ̀ Ⲕⲩⲣⲓⲟⲥ ⲙⲉⲧⲁ ⲥⲟⲩ." },
    { language: 'english', text: "My lips O Mary, overflow with praise and wisdom, that I may speak of the virtues, of the new heaven on earth.\n\nFor out of you they shone upon us, salvation and deliverance, for out of His own will and pleasure, He came and saved us.\n\nYou bore Him O all-holy one, as the saying of the prophecy, without marriage or a [man’s] seed, with a miraculous act.\n\nLet us glorify the saint, in voice of glorification saying, \"Hail to you rejoice O Mary, the Lord is with you.\"" },
    { language: 'arabic', text: "شفتاي يا مريم تفيض سبحا وحكمة لكي أنطق بفضائل السماء الجديدة على الأرض.\n\nلأنه اشرق لنا منك الخلاص والنجاة لأنه بمسرته وإرادته أتي وخلصنا.\n\nولدته أيتها القديسة كقول النبوة بغير زرع ولا مباضعة بعمل معجز.\n\nفلنمجد القديسة بأصوات التمجيد قائلين السلام أفرحي يا مريم الرب معك." },
    { language: 'englishArabic', text: "Shafatayya ya Maryam tafeed sabhan wa hikma likay antiqa bi-fada'il es-sama' el-gadeeda 'ala el-ard.\n\nLi-annahu ashraqa lana minki el-khalas wan-nagah, li-annahu bi-masarratihi wa iradatihi ata wa khallasana.\n\nWaladtihi ayyatuha el-qiddeesa ka-qawl en-nubouwa bi-ghayr zar' wa la mubada'a bi-'amal mu'giz.\n\nFal-numaggid el-qiddeesa bi-aswat et-tamgeed qa'ileen: es-salam, ifrahi ya Maryam er-Rabb ma'aki." },
  ] },
  { id: "vp-the-fifth-coptic-mo-aqap-interpretation", title: "The Fifth Coptic Mo-‘aqap Interpretation", versions: [
    { language: 'coptic', text: "Ⲉⲑⲃⲉ ⲡⲉⲕⲣⲁⲛ Ⲡⲟ︦ⲥ︦ ⲙ̀ⲡⲉⲣϫⲱⲛⲧ: ϣⲁⲉ̀ⲛⲉϩ ⲉ̀ϫⲉⲛ ⲡⲉⲕⲥⲱⲛⲧ: ⲁⲗⲗⲁ ⲕⲁⲧⲁ ⲡⲉⲕⲛⲁⲓ ϫⲟⲩϣⲧ: ϧⲉⲛ ⲫ̀ⲃⲁⲗ ⲛ̀ⲛⲉⲕⲕⲙⲉⲧϣⲉⲛϩⲏⲧ.\n\nϦⲉⲛ ⲫ̀ⲃⲁⲗ ⲛ̀ⲛⲉⲕⲙⲉⲧϣⲉⲛϩⲏⲧ: ϫⲟⲩϣⲧ ⲉ̀ⲣⲟⲓ ⲱ̀ ⲡⲓⲛⲁⲏⲧ: ⲁ̀ⲣⲓⲟⲩⲱⲓⲛⲓ ⲙ̀ⲡⲁϩⲏⲧ: ⲙⲁϩϥ ⲉ̀ⲃⲟⲗϧⲉⲛ ⲧⲉⲕⲥⲟⲫⲓⲁ.\n\nⲘⲁϩϥ ⲉ̀ⲃⲟⲗϧⲉⲛ ⲧⲉⲕⲥⲟⲫⲓⲁ: ⲉⲑⲣⲓϫⲱ ⲛ̀ⲛⲓⲉⲩⲫⲏⲙⲓⲁ: ⲛ̀ⲧⲉ ⲧⲁⲟ︦ⲥ︦ ⲛ̀ⲁⲧⲕⲁⲕⲓⲁ: Ⲙⲁⲣⲓⲁ ϯϣⲉⲗⲉⲧ ⲙ̀ⲙⲏⲓ.\n\nⲘⲁⲣⲓⲁ ϯϣⲉⲗⲉⲧ ⲙ̀ⲙⲏⲓ: ϯⲫⲉ ⲙ̀ⲙⲁϩⲃ︦ϯ︦ ⲛ̀ⲧⲁⲫ̀ⲙⲏⲓ: ⲉ̀ⲧⲁ ⲡⲓⲣⲏ ⲛ̀ⲧⲉ ϯⲙⲉⲑⲙⲏⲓ: ⲁϥϣⲁⲓ ⲛⲁⲛ ⲉ̀ⲃⲟⲗ ⲛ̀ϧⲏⲧⲥ.\n\nⲀϥϣⲁⲓ ⲛⲁⲛ ⲉ̀ⲃⲟⲗ ⲛ̀ϧⲏⲧⲥ: ⲛ̀ϫⲉ ⲫⲏⲉ̀ⲧⲁϥⲉⲣϩⲏⲧⲥ: ⲁϥⲑⲁⲙⲓⲟ ⲛ̀ϯⲕ̀ⲧⲏⲥⲓⲥ ⲧⲏⲣⲥ: ⲉ̀ⲧⲉ ⲛ̀ⲑⲟϥ ⲡⲉ Ⲓⲏ︦ⲥ︦ Ⲡⲭ︦ⲥ︦.\n\nⲈⲧⲉ ⲛ̀ⲑⲟϥ ⲡⲉ Ⲓⲏ︦ⲥ︦ Ⲡⲭ︦ⲥ︦: ⲡⲓⲣⲏ ⲛ̀ⲧⲉ ϯⲙⲉⲑⲙⲏⲓ ⲁ̀ⲗⲏⲑⲱⲥ: ⲉ̀ⲧⲁϥϣⲁⲓ ⲛ̀ⲛⲓⲡⲓⲥⲧⲟⲥ: ⲉ̀ⲃⲟⲗϧⲉⲛ ⲑ̀ⲛⲉϫⲓ ⲛ̀ϯⲡⲁⲣⲑⲉⲛⲟⲥ.\n\nⲈ̀ⲃⲟⲗϧⲉⲛ ⲑ̀ⲛⲉϫⲓ ⲛ̀ϯⲡⲁⲣⲑⲉⲛⲟⲥ: ⲁⲩϫ̀ⲫⲟϥ ⲁϭⲛⲉ ⲡⲁⲑⲟⲥ: ⲁϥⲛⲟϩⲉⲙ ⲙ̀ⲡⲉϥⲗⲁⲟⲥ: ⲉ̀ⲃⲟⲗϧⲉⲛ ⲧ̀ϫⲓϫ ⲛ̀ⲧⲉ ⲛⲟⲩϫⲁϫⲓ.\n\nⲦⲉⲛϯⲱ̀ⲟⲩ ⲛⲉ ⲱ̀ ⲑⲏⲉ̀ⲧⲉⲛϩⲟⲧ: ⲉⲧϥⲁⲓ ϧⲁ ⲡⲓⲗⲟⲅⲟⲥ ⲛ̀ⲧⲉ Ⲫ̀ⲓⲱⲧ: ϫⲉ ⲭⲉⲣⲉ ⲑⲏⲉⲑⲙⲉϩ ⲛ̀ϩ̀ⲙⲟⲧ: ⲟⲩⲟϩ Ⲡⲟ︦ⲥ︦ ϣⲟⲡ ⲛⲉⲙⲉ." },
    { language: 'english', text: "For the sake of Your name Lord do not be angry, with Your people forever, but look down according to Your mercy, with Your merciful eyes.\n\nWith Your merciful eyes, look upon me O merciful, enlighten my heart, and fill me with Your wisdom.\n\nAnd fill me with your wisdom, to sing praises, unto my unblemished Lady, Mary the true bride.\n\nMary the true bride, the true second heaven, from which the Sun of Righteousness, shone over us.\n\nShone over us, He who has begun, He created all creation, this is Jesus Christ.\n\nThis is Jesus Christ, the true Sun of Righteousness, who has shone upon the faithful, from the womb of the virgin.\n\nFrom the womb of the Virgin, He was born without pain, and He saved His people, from the arm of their enemies.\n\nWe glorify you O faithful one, who carried the Word of the Father, \"Hail to you O full of grace, the Lord is with you.\"" },
    { language: 'arabic', text: "من أجل اسمك يا رب لا تغضب إلى الأبد على خليقتك لكن برحمتك أنظر بعين رافتك.\n\nبعين رافتك أنظر إلى أيها الرحوم وأضيء قلبي واملأه من حكمتك.\n\nواملأه من حكمتك: لكي أقول مدائح سيدتي التي بغير شر مريم العروسة الحقيقة.\n\nمريم العروسة الحقيقة: السماء الثانية الحقيقة التي شمس البر أشرق لنا منها.\n\nأشرق لنا منها: الذي ابتداء فخلق البرية كلها الذي هو يسوع المسيح.\n\nالذي هو يسوع المسيح: شمس البر بالحقيقة الذي اشرق للمؤمنين من بطن العذراء.\n\nمن بطن العذراء: ولد بغير ألم وخلص شعبه من يد أعدائهم.\n\nنمجدك ايتها الامينة. الحاملة كلمة الأب قائلين إفرحي يا ممتلئة نعمة. الرب معك" },
    { language: 'englishArabic', text: "Min agl ismika ya Rabb la taghdab ila el-abad 'ala khaleeqatik, lakin bi-rahmatik unzur bi-'ayn ra'fatik.\n\nBi-'ayn ra'fatik unzur ilayya ayyuha er-rahoum, wa adi' qalbi wamla'hu min hikmatik.\n\nWamla'hu min hikmatik: likay aqoul mada'ih sayyidati allati bi-ghayr sharr, Maryam el-'arousa el-haqeeqiyya.\n\nMaryam el-'arousa el-haqeeqiyya: es-sama' eth-thaniya el-haqeeqiyya allati shams el-birr ashraqa lana minha.\n\nAshraqa lana minha: alladhi ibtida'an khalaqa el-bariyya kullaha, alladhi huwa Yasou' el-Maseeh.\n\nAlladhi huwa Yasou' el-Maseeh: shams el-birr bil-haqeeqa alladhi ashraqa lil-mu'mineen min batn el-'Adhra'.\n\nMin batn el-'Adhra': wulida bi-ghayr alam wa khallasa sha'bahu min yad a'da'ihim.\n\nNumaggiduki ayyatuha el-ameena, el-hamila kalimat el-Ab, qa'ileen: ifrahi ya mumtali'a ni'ma, er-Rabb ma'aki." },
  ] },
  { id: "vp-the-fifth-egyptian-interpretation", title: "The Fifth Egyptian Interpretation", versions: [
    { language: 'coptic', text: "Ⲁⲣⲉϣⲱⲡⲓ ⲛ̀ⲟⲩⲙⲁϩⲥ̀ⲛⲟⲩϯ ⲙ̀ⲫⲉ: ⲙ̀ⲫⲏⲉ̀ⲧⲁϥⲑⲁⲙⲓⲟ ⲛ̀ⲧ̀ⲫⲉ ⲛⲉⲙ ⲡ̀ⲕⲁϩⲓ: ⲧⲉⲧⲁⲓⲏⲟⲩⲧ ⲉ̀ϩⲟⲧⲉ ⲧ̀ⲫⲉ: ⲛⲉⲙ ⲛⲏⲉⲧϣⲟⲡ ϩⲓϫⲉⲛ ⲡⲓⲕⲁϩⲓ.\n\nⲀⲣⲉϣⲱⲡⲓ ⲛ̀ⲟⲩⲙⲁϩⲥ̀ⲛⲟⲩϯ ⲙ̀ⲫⲉ: ⲛⲉⲙ ⲛ̀ⲟⲩⲑ̀ⲣⲟⲛⲟⲥ ⲙ̀Ⲫϯ: ⲫⲏⲉ̀ⲧⲁϥⲓ̀ ⲉ̀ⲡⲉⲥⲏⲧ ⲉ̀ⲃⲟⲗ ϧⲉⲛ ⲧ̀ⲫⲉ: ⲁϥϭⲓⲥⲁⲣⲝ ⲉ̀ⲃⲟⲗ ϧⲉⲛ ⲧⲉⲛⲉϫⲓ.\n\nⲀⲣⲉϣⲱⲡⲓ ⲛ̀ⲟⲩⲙⲁϩⲥ̀ⲛⲟⲩϯ ⲙ̀ⲫⲉ: ⲱ̀ Ⲙⲁⲣⲓⲁ ϯⲫⲉ ⲙ̀ⲃⲉⲣⲓ: ⲁϥϣⲁⲓ ⲛⲁⲛ ⲉ̀ⲃⲟⲗ ⲛ̀ϧⲏϯ: ⲛ̀ϫⲉ ⲡⲓⲣⲏ ⲛ̀ⲧⲉ ϯⲇⲓⲕⲉⲟ̀ⲥⲩⲛⲏ.\n\nⲀⲣⲉϣⲱⲡⲓ ⲛ̀ⲟⲩⲙⲁϩⲥ̀ⲛⲟⲩϯ ⲙ̀ⲫⲉ: ⲙ̀ⲫⲏⲉⲑⲙⲟϩ ⲛ̀ⲧ̀ⲫⲉ ⲛⲉⲙ ⲡ̀ⲕⲁϩⲓ: ⲁϥⲧⲁⲥⲑⲟ ⲛ̀ⲛⲉⲛϫ̀ⲫⲉ: ϧⲉⲛ ⲟⲩⲉⲣϣⲓϣⲓ ⲛ̀ⲟⲩⲁ̀ⲙⲁϩⲓ.\n\nⲀⲣⲉϣⲱⲡⲓ ⲛ̀ⲟⲩⲙⲁϩⲥ̀ⲛⲟⲩϯ ⲙ̀ⲫⲉ: ⲙ̀ⲫⲏⲉ̀ⲧⲁⲣⲉ ⲛⲓⲁⲅⲅⲉⲗⲟⲥ: ⲉ̀ⲧⲉⲣϩⲟϯ ϧⲁⲧⲉϥϩⲏ: ⲁ̀ⲣⲉⲙⲓⲥⲓ ⲙ̀ⲙⲟϥ ⲁϭⲛⲉ ⲅⲁⲙⲟⲥ.\n\nⲀⲣⲉϣⲱⲡⲓ ⲛ̀ⲟⲩⲙⲁϩⲥ̀ⲛⲟⲩϯ ⲙ̀ⲫⲉ: ⲙ̀ⲫⲏⲉ̀ⲧⲁⲣⲉϫ̀ⲫⲟϥ ⲕⲁⲧⲁ ⲥⲁⲣⲝ: ⲁⲩⲉⲣⲡ̀ⲣⲟⲫⲏⲧⲉⲩⲓⲛ ⲓⲥϫⲉⲛ ϩⲏ: ⲉⲑⲃⲉ Ⲙⲁⲣⲓⲁ ϯⲡⲁⲣⲑⲉⲛⲟⲥ.\n\nⲀⲣⲉϣⲱⲡⲓ ⲛ̀ⲟⲩⲙⲁϩⲥ̀ⲛⲟⲩϯ ⲙ̀ⲫⲉ: ⲙ̀ⲫⲏⲉ̀ⲧⲁϥⲓ̀ ⲁϥⲥⲱϯ ⲙ̀ⲙⲟⲛ: ⲁϥⲛⲟϩⲉⲙ ⲛ̀ⲛⲉⲛⲯⲩⲭⲏ: ⲉ̀ⲃⲟⲗ ϧⲉⲛ ⲡ̀ⲧⲁⲕⲟ ⲛ̀ⲛⲓⲇⲉⲙⲱⲛ.\n\nⲈⲑⲃⲉ ⲫⲁⲓ ⲧⲉⲛϩⲱⲥ ⲉ̀Ⲫⲛⲟⲩϯ: ⲫⲏⲉ̀ⲧⲁϥϭⲓⲥⲁⲣⲝ ⲉ̀ⲃⲟⲗ ⲛ̀ϧⲏϯ: ⲁϥⲉⲣⲣⲱⲙⲓ ⲙ̀ⲡⲉⲛⲣⲏϯ: ϣⲁⲧⲉⲛ ⲫ̀ⲛⲟⲃⲓ ⲙ̀ⲙⲁⲩⲁⲧϥ." },
    { language: 'english', text: "You became a second heaven, for Him who created heaven and earth, you are honored higher than the heaven, and all those who dwell on earth.\n\nYou became a second heaven, and a throne to God, who came down from heaven, and was incarnate in your womb.\n\nYou became a second heaven, O Mary the new heaven, for out of you the Sun of truth, shone upon us.\n\nYou became a second heaven, to Him who fills heaven and earth, He returned our gift, with majestic authority.\n\nYou became a second heaven, to Him whom the angels fear, and you gave birth to Him, without marriage.\n\nYou became a second heaven, to Him whom you bore in the flesh, and it was prophesied from the beginning, concerning the Virgin Mary.\n\nYou became a second heaven, to Him who came and saved us, and delivered our souls, from the destruction of the demons.\n\nTherefore we praise God, who was incarnate of you, and became man like us, except for sin alone." },
    { language: 'arabic', text: "صرتِ سماء ثانية، للذي خلق السماء والأرض، أنتِ مكرمة أفضل من السماء، وكل السكان على الأرض.\n\nصرتِ سماء ثانية، وكرسياً لله، الذي نزل من السماء، وأخذ جسداً من بطنكِ.\n\nصرتِ سماء ثانية، يا مريم السماء الجديدة، لأنه أشرق لنا منكِ، شمس العدل.\n\nصرتِ سماء ثانية، للذي يملأ السماء والأرض، ورد مكسبنا، بسلطان عزيز.\n\nصرتِ سماء ثانية، للذي تخافه الملائكة، وولدتِه، بغير زواج.\n\nصرتِ سماء ثانية، للذي ولدتِه بالجسد، ومنذ البدء قد تنبأوا، من أجل مريم العذراء.\n\nصرتِ سماء ثانية، للذي أتى وخلصنا، وخلص نفوسنا، من هلاك الشياطين.\n\nفلهذا نسبِّح الله، الذي تجسَّد منكِ، وصار إنساناً مثلنا، ما خلا الخطية وحدها." },
    { language: 'englishArabic', text: "Sirti sama'an thaniya, lilladhi khalaqa es-sama' wal-ard, anti mukarrama afdal min es-sama', wa kull es-sukkan 'ala el-ard.\n\nSirti sama'an thaniya, wa kursiyyan lillah, alladhi nazala min es-sama', wa akhadha gasadan min batniki.\n\nSirti sama'an thaniya, ya Maryam es-sama' el-gadeeda, li-annahu ashraqa lana minki, shams el-'adl.\n\nSirti sama'an thaniya, lilladhi yamla' es-sama' wal-ard, wa radda maksabana, bi-sultan 'azeez.\n\nSirti sama'an thaniya, lilladhi takhafuhu el-mala'ika, wa waladtihi, bi-ghayr zawag.\n\nSirti sama'an thaniya, lilladhi waladtihi bil-gasad, wa mundhu el-bad' qad tanabba'ou, min agl Maryam el-'Adhra'.\n\nSirti sama'an thaniya, lilladhi ata wa khallasana, wa khallasa nufousana, min halak esh-shayateen.\n\nFa-li-hadha nusabbih Allah, alladhi tagassada minki, wa sara insanan mithlana, ma khala el-khatiyya wahdaha." },
  ] },
  { id: "vp-the-fifth-sahidic-interpretation", title: "The Fifth Sahidic Interpretation", versions: [
    { language: 'coptic', text: "Ⲉⲣⲉ ⲡ̀ⲧⲁⲓⲟ ⲛ̀ϯⲑⲉⲟ̀ⲧⲟⲕⲟⲥ: ⲉ̀ϩⲟⲧⲉ ⲛⲓⲧⲁⲅⲙⲁ ⲛ̀ⲧⲉ ⲛⲓⲫⲏⲟⲩⲓ: ⲟⲩⲟϩ ϯⲥⲁⲣⲝ ⲛ̀ⲛⲟⲩϫ: ⲁϥⲥⲁⲡ̀ϣⲱⲓ ⲉ̀ϫⲉⲛ ⲛⲓⲫⲏⲟⲩⲓ.\n\nϪⲉ ⲫⲏⲉ̀ⲧⲁϥⲑⲁⲙⲓⲟ ⲛ̀ⲧ̀ⲫⲉ ⲛⲉⲙ ⲡ̀ⲕⲁϩⲓ: ⲁϥⲓ̀ ⲁϥϣⲱⲡⲓ ϧⲉⲛ ⲧⲉⲛⲉϫⲓ: ⲛ̀ϩ̀ⲣⲏⲓ ϧⲉⲛ ⲟⲩϫⲓϫ ⲉⲥⲁ̀ⲙⲁϩⲓ: ⲁϥⲥⲟⲧⲧⲉⲛ ϧⲉⲛ ⲛⲉⲛϫⲁϫⲓ.\n\nⲀϥϣⲁⲓ ⲛⲁⲛ ⲥⲱⲙⲁⲧⲓⲕⲟⲥ: ⲛ̀ϫⲉ Ⲓⲏⲥⲟⲩⲥ Ⲡϣⲏⲣⲓ ⲙ̀Ⲫϯ: ⲉ̀ⲃⲟⲗ ϧⲉⲛ ϯⲑⲉⲟ̀ⲧⲟⲕⲟⲥ: ⲟⲩⲟϩ ⲁϥⲭⲱ ⲛⲁⲛ ⲛ̀ⲛⲉⲛⲛⲟⲃⲓ ⲉ̀ⲃⲟⲗ.\n\nⲀⲣⲉϫ̀ⲫⲟϥ ⲁϭⲛⲉ ⲥ̀ⲡⲉⲣⲙⲁ ⲛ̀ⲣⲱⲙⲓ: ϩⲱⲥ ⲣⲱⲙⲓ ⲛ̀Ⲇⲏⲙⲓⲟⲩⲣⲅⲟⲥ: ⲟⲩⲟϩ ⲁϥⲱ̀ⲗⲓ ⲛ̀ⲛⲉⲛⲥⲁϩⲟⲩⲓ̀: ϧⲉⲛ ⲧ̀ϫⲟⲙ ⲛ̀ⲧⲉ ⲡⲓⲥ̀ⲧⲁⲩⲣⲟⲥ.\n\nⲈⲑⲃⲉ ⲫⲁⲓ ⲧⲉⲛϯⲱ̀ⲟⲩ ⲛⲉ: ⲉⲛⲱϣ ⲉ̀ⲃⲟⲗ ⲛⲉⲙ Ⲅⲁⲃⲣⲓⲏⲗ: ϫⲉ ⲭⲉⲣⲉ ⲕⲉ ⲭⲁⲣⲓⲧⲱⲙⲉⲛⲏ: Ⲙⲁⲣⲓⲁ ⲑ̀ⲙⲁⲩ ⲛ̀Ⲉⲙⲙⲁⲛⲟⲩⲏⲗ." },
    { language: 'english', text: "The honor of the Theotokos became, higher than the heavenly orders, and the exiled body, ascended to the heavens.\n\nFor He who created heaven and earth, came and dwelt in your womb, and with a strong hand, He saved us from our enemies.\n\nJesus the Son of God, shined for us in the flesh from the Theotokos, and He forgave us our sins.\n\nYou bore Him without man’s seed, as a Man and He is the Creator, and He took away our curse, through the power of the Cross.\n\nTherefore we glorify you, proclaiming with Gabriel, “Hail to you O full of grace, Mary the Mother of Immanuel.”" },
    { language: 'arabic', text: "صارت كرامة والدة الإله، أفضل من الطغمات السمائية، والجسد الكثيف، صعد إلى السموات.\n\nلأن الذي خلق السماء والأرض، أتى وحل في بطنكِ، وبيدٍ عزيزة، خلصنا من أعدائنا.\n\nأشرق لنا متجسداً، يسوع إبن الله، من والدة الإله، وغفر لنا خطايانا.\n\nولدتِه بغير زرع بشر، كإنسان وهو الخالق، ورفع لعناتنا، بقوة الصليب.\n\nفلهذا نُمجدكِ، ونصرخ مع غبريال قائلين،\"السلام لكِ يا ممتلئة نعمة، مريم اُم عمانوئيل.\"" },
    { language: 'englishArabic', text: "Sarat karamat walidat el-Ilah, afdal min et-tughmat es-samawiyya, wal-gasad el-katheef, sa'ida ila es-samawat.\n\nLi-anna alladhi khalaqa es-sama' wal-ard, ata wa halla fi batniki, wa bi-yadin 'azeeza, khallasana min a'da'ina.\n\nAshraqa lana mutagassidan, Yasou' Ibn Allah, min walidat el-Ilah, wa ghafara lana khatayana.\n\nWaladtihi bi-ghayr zar' bashar, ka-insan wa huwa el-khaliq, wa rafa'a la'anatina, bi-quwwat es-saleeb.\n\nFa-li-hadha numaggiduki, wa nasrukh ma'a Ghubriyal qa'ileen: \"Es-salam laki ya mumtali'a ni'ma, Maryam umm 'Emmanu'eel.\"" },
  ] },
  { id: "vp-the-fifth-hymn-of-abou-el-saad-of-aboutig", title: "The Fifth Hymn of Abou El-Saad of Aboutig", versions: [
    { language: 'english', text: "The second heaven what became / on earth, is also / Virgin Mary, who was chosen / and became our intercessor willingly.\n\nAll the creation was illuminated by her / from her, the Sun of Righteousness shone / by this testimony, they indicated / the elders of the past times.\n\nShe bore Him as the prophecy witnessed / that He will be born without the seed of man / without corruption she bore Him / nine months, then He was known.\n\nThe creation is pleased with its promise / and worships before Him who appeared / and offers greeting to her who has found / all grace before the Lover of Mankind.\n\nWhat shall I call you O vine / you gave us to drink of your nectar / you became an intercessor and care-giver / for us and all who belong to us.\n\nHail to you O mother of mercy / we are your beloved pray acknowledge us / blessed are you O full of grace / before your Son intercede for us." },
    { language: 'arabic', text: "السماء الثانية التي صارت / علي الارض فهي ايضاً / مريم العذراء التي اختيرت / وصارت وسيطة لنا بالرضى.\n\nكل البرية بها استنارت / ومنها شمس البر أضاء / وبهذا التحقيق أشارت / شيوخ الزمان الذي قد مضى.\n\nولدته كالنبوة التي شهدت / انه يولد من غير زرع بشر / ومن غير فساد حملته مدة / تسعة شهور ثم اشتهر.\n\nتسر الخليقة بما قد وُعدت / وتسجد أمام الذي قد ظهر / وتعطي السلام للتي قد وجدت / كل نعمة امام محب البشر.\n\nبماذا أدعوك أيتها الكرمة / عصيرك منة سقيتينا / وصرت وسيلة ومهتمة / بنا و لسائر مالنا.\n\nالسلام لك يا ام الرحمة / نحن عبيدك جيرينا / طوباكِ يا مملوُة نعمة / عند ابنك الحبيب اشفعي فينا." },
    { language: 'englishArabic', text: "Es-sama' eth-thaniya allati sarat / 'ala el-ard fa-hiya aydan / Maryam el-'Adhra' allati ukhtirat / wa sarat waseeta lana bir-rida.\n\nKull el-bariyya biha istanarat / wa minha shams el-birr ada'a / wa bi-hadha et-tahqeeq asharat / shuyoukh ez-zaman alladhi qad mada.\n\nWaladathu kan-nubouwa allati shahidat / annahu youlad min ghayr zar' bashar / wa min ghayr fasad hamalathu muddat / tis'at shuhour thumma ishtahar.\n\nTusarru el-khaleeqa bima qad wu'idat / wa tasgud amam alladhi qad zahar / wa tu'ti es-salam lillati qad wagadat / kull ni'ma amam muhibb el-bashar.\n\nBi-madha ad'ouki ayyatuha el-karma / 'aseeruki mannan saqayteena / wa sirti waseela wa muhtamma / bina wa li-sa'ir ma lana.\n\nEs-salam laki ya umm er-rahma / nahnu 'abeeduki geereena / toubaki ya mamlou'at ni'ma / 'ind ibniki el-habeeb ishfa'i feena." },
  ] },
  { id: "vp-fifth-hymn-of-cantor-gabriel-of-qay-a", title: "Fifth Hymn of Cantor Gabriel of Qay A", versions: [
    { language: 'english', text: "The second bodily heaven / you were called O dome of lights / the Rational Sun of Righteousness / your light shines in the world.\n\nYour light shines in the world / on earth and in heaven / blessed are you O beauty of first-born / you bore God Lord of hosts.\n\nYou bore God Lord of hosts / you became our intercessor willingly / how many witnessed of this sign / the elders of the past times.\n\nThe elders of the past times / spoke through witnesses and proverbs saying / He will change His wrath by His will / and come in the fullness of time.\n\nAnd come in the fullness of time / born of the pure first-born Virgin / and He shall be called Immanuel / the Savior of the world.\n\nThe Savior of the world / our true God / and our good Savior / who came and saved us.\n\nWho came and saved us / by His human birth / He granted unto us the promise / by the bathing of the second birth.\n\nBy the bathing of the second birth / we the Christians / all cry with songs and hymns / proclaiming and saying.\n\nProclaiming and saying / we ask you O flower of fragrance / open to us the gate of paradise / and save us from fire and suffering.\n\nAnd save us from fire and suffering / for we are counted for you / blessed are you, O mother of the only-begotten of the Father / hail to you and hail unto you.\n\nHail to you and hail unto you, we ask you O Mother of the Beloved, grant us to be in your fathers’ dwellings, Abraham Isaac and Jacob." },
    { language: 'arabic', text: "سماء ثانية جسدانية / دعيت يا قبة الانوار / شمس البر العقلية / ضياؤها شارق في الاقطار.\n\nضياؤها شارق في الاقطار / علي الارض وفي السموات / طوباك يا زينة الابكار / حملت الاله رب القوات.\n\nحملت الاله رب القوات / و صرتِ وسيطة لنا بالرضى / كما شهد علي الآيات / شيوخ الزمان الذي قد مضى.\n\nشيوخ الزمان الذي قد مضى / نطقوا بشهادات وأمثال وقالوا / سوف يُبدَّل غضبُه بالرضى / ويأتي في عقب الاجيال.\n\nويأتي في عقب الاجيال / المولود من بكر بتول تي بارثينوس / أفموتي إي بيف ران جي إمانوئيل / إبسوتي إم بي كوزموس.\n\nإبسوتي إم بي كوزموس / بين نوتي إن آليثينوس / بين سوتير إن أغاثوس / في إيطاف إي آف سوتي إممون.\n\nفي إيطاف إي آف سوتي إممون / بيملاده الإنساني / قد جاد علينا بالعربون / بحميم الميلاد الثاني.\n\nبحميم الميلاد الثاني / آنون خاني إخريستيانوس / و نحن نصيح بتراتيل و ألحان / إن أوش إيفول إن جو إمموس.\n\nإن أوش إيفول إن جو إمموس / و نسألك يا زهرة الاطياب / إفتحي لنا باب الفردوس / وجيرينا من النار و عذاب.\n\nوجيرينا من النار وعذاب / لأننا محسوبين عليك / طوباك يا أم وحيد الآب / السلام لكِ ثم السلام عليك.\n\nالسلام لكِ ثم السلام إليك، ونسألك يا أم المحبوب، ان تحظينا في مظال اباءك، ابراهيم واسحق ويعقوب." },
    { language: 'englishArabic', text: "Sama' thaniya gasadaniyya / du'eeti ya qubbat el-anwar / shams el-birr el-'aqliyya / diya'uha shariq fil-aqtar.\n\nDiya'uha shariq fil-aqtar / 'ala el-ard wa fis-samawat / toubaki ya zeenat el-abkar / hamalti el-Ilah Rabb el-quwwat.\n\nHamalti el-Ilah Rabb el-quwwat / wa sirti waseeta lana bir-rida / kama shahida 'ala el-ayat / shuyoukh ez-zaman alladhi qad mada.\n\nShuyoukh ez-zaman alladhi qad mada / nataqou bi-shahadat wa amthal wa qalou / sawfa yubaddal ghadabuhu bir-rida / wa ya'ti fi 'aqib el-agyal.\n\nWa ya'ti fi 'aqib el-agyal / el-mawloud min bikr batoul Tiparthenos / afmouti e-pefran je Emmanouēl / Epsōtēr empikosmos.\n\nEpsōtēr empikosmos / pen-Nouti en-alēthinos / pen-Sōtēr en-agathos / fē-etaf-i af-sōti emmon.\n\nFē-etaf-i af-sōti emmon / bi-meeladihi el-insani / qad gada 'alayna bil-'arboun / bi-hameem el-meelad eth-thani.\n\nBi-hameem el-meelad eth-thani / anon khan-ekhristianos / wa nahnu nasee'h bi-tarateel wa alhan / en-oush evol en-jō emmos.\n\nEn-oush evol en-jō emmos / wa nas'aluki ya zahrat el-atyab / iftahi lana bab el-firdaws / wa geereena min en-nar wal-'adhab.\n\nWa geereena min en-nar wal-'adhab / li-annana mahsoubeen 'alayki / toubaki ya umm waheed el-Ab / es-salam laki thumma es-salam 'alayki.\n\nEs-salam laki thumma es-salam ilayki, wa nas'aluki ya umm el-mahboub, an tahzeena fi mazall aba'ik, Ibraheem wa Ishaq wa Ya'qoub." },
  ] },
  { id: "vp-the-fifth-hymn-of-cantor-gabriel-of-qay-b", title: "The Fifth Hymn of Cantor Gabriel of Qay B", versions: [
    { language: 'english', text: "The second heaven that became, a dwelling for the Lord of hosts, the first-born that was chosen, from all the creation.\n\nAll minds were puzzled, in describing you O Lady of the creation, and the elders witnessed to you, and prophesied with signs.\n\nThe creation was enlightened through you, after it was in darkness, and when your mother Eve became, the cause of error and suffering.\n\nThrough your presence O you who became, a throne for the Lord of hosts, she was saved through your Son and she won, and the curse was loosened.\n\nThe heat was cooled down, of Hades for all the fathers, and everyone came with the purity, of your Son in the highest ranks.\n\nHelp us O you who enlightened, the world after it was in darkness, and rescue us from every torment, on the hour we are counted with the dead.\n\nHail to you O Mother of our Savior, we ask you O pure Virgin, to ask the Lord to bring us, to the harbor in peace." },
    { language: 'arabic', text: "السماء الثانية التي صارت، مسكناً لرب القوات، البكر التي أُختيرت، من دون سائر المخلوقات.\n\nكل الألباب قد إحتارت، في وصفِك يا سيدة المخلوقات، كما شهدت عنكِ وأشارت، شيوخ وتنبأوا بنبوات.\n\nكل البَرِيَة بكِ أنارت، من بعد أن كانوا في ظلمات، واُمكِ حواء التي صارت، من سبب الزلة في عذابات.\n\nبوجودكِ يا مَنْ قد صارت، كرسياً لرب القوات، عُتِقَتْ بإبنكِ وفازت، وإنحلت عنها اللعنات.\n\nقد إنطفأت كل حرارة، جهنم عن كل الأبوات، والكل صاروا بطهارة، إبنكِ في أعلا الدرجات.\n\nجيرينا يا مَنْ قد أنارت، الأكوان من بعد الظلمات، وغيثينا من كل مرارة، ساعة نُعَدُّ مع الأموات.\n\nالسلام لكِ يا اُم مخلصنا، ونسألكِ يا بكر نقية، تسألي الرب أن يوصِّلنا، إلى الميناء بطمأنينة." },
    { language: 'englishArabic', text: "Es-sama' eth-thaniya allati sarat, maskanan li-Rabb el-quwwat, el-bikr allati ukhtirat, min doun sa'ir el-makhlouqat.\n\nKull el-albab qad ihtarat, fi wasfiki ya sayyidat el-makhlouqat, kama shahidat 'anki wa asharat, shuyoukh wa tanabba'ou bi-nubouwat.\n\nKull el-bariyya biki anarat, min ba'd an kanou fi zulumat, wa ummuki Hawwa' allati sarat, min sabab ez-zalla fi 'adhabat.\n\nBi-wugoudiki ya man qad sarat, kursiyyan li-Rabb el-quwwat, 'utiqat bi-ibniki wa fazat, wanhallat 'anha el-la'anat.\n\nQad intafa'at kull harara, gahannam 'an kull el-abawat, wal-kull sarou bi-tahara, ibniki fi a'la ed-daragat.\n\nGeereena ya man qad anarat, el-akwan min ba'd ez-zulumat, wa gheetheena min kull marara, sa'at nu'addu ma'a el-amwat.\n\nEs-salam laki ya umm mukhallisina, wa nas'aluki ya bikr naqiyya, tas'ali er-Rabb an yuwassilana, ila el-meena' bi-tuma'neena." },
  ] },
  { id: "vp-the-fifth-hymn-of-cantor-gabriel-of-qay-c", title: "The Fifth Hymn of Cantor Gabriel of Qay C", versions: [
    { language: 'english', text: "You were called the second heaven, and the rational Sun of Righteousness, that shone on earth and was enlightened, through the dwelling of the eternal Word.\n\nThe elders of the past times, spoke with prophetic signs saying, “His wrath will be replaced with acceptance, and He will be born from a pure Virgin.\n\nHe will be born from a pure Virgin, from an honored root of the forefathers, a perfect and pure Virgin, from the tribe of David.”\n\nAll the high ranks, and the orders and the hosts, cry out with heavenly words, before Him who was born from you.\n\nBefore Him who was born from you, they sing and chant in tunes, and with spiritual glorification and worship, before the throne of the Lord of greatness.\n\nBlessed are you O daughter of David, blessed are you O full of grace, blessed are you O Mother of the Worshiped, hail to you O Mother of mercy.\n\nHail to you O Mother of mercy, blessed are you O full of grace, the Lady of us all Mary, through her prayers and intercessions." },
    { language: 'arabic', text: "سُميتِ سماء ثانية أيضاً، وشمس البر العقلية، أشرق بالنور على الأرض وأضاء، بحلول الكلمة الأزلية.\n\nشيوخ الزمان الذي قد مضى، نطقوا بشهادات نبوية، وقالوا \"سوف يُبدَّل غضبه بالرضى، ويولد من بكر نقية.\n\nويولد من بكر نقية، من أصل حسيب آباء وجدود، بكر طاهرة بالكلية، تُنسب لقبيلة داود.\"\n\nكل الطغمات العلوية، وكل طقوس وكل جنود، يصيحون بلغات سمائية، قدام مَنْ صار منكِ مولود.\n\nقدام مَنْ صار منكِ مولود، يصيحون بأصوات ونغمة، وتمجيد روحاني وسجود، قدام كرسي رب العظمة.\n\nطوباكِ يا إبنة داود، طوباكِ يا مملوءة نعمة، طوباكِ يا اُم المعبود، السلام لكِ يا اُم الرحمة.\n\nالسلام لكِ يا اُم الرحمة، طوباكِ يا ممتلئة نعمة، أووتين شويس إننيب ماريا، هيتين نيس طوڤه نيم نيس إبريسڤيِّا." },
    { language: 'englishArabic', text: "Summeeti sama'an thaniya aydan, wa shams el-birr el-'aqliyya, ashraqa bin-nour 'ala el-ard wa ada'a, bi-houloul el-Kalima el-azaliyya.\n\nShuyoukh ez-zaman alladhi qad mada, nataqou bi-shahadat nabawiyya, wa qalou: \"Sawfa yubaddal ghadabuhu bir-rida, wa youlad min bikr naqiyya.\n\nWa youlad min bikr naqiyya, min asl haseeb aba' wa gudoud, bikr tahira bil-kulliyya, tunsab li-qabeelat Dawoud.\"\n\nKull et-tughmat el-'ulwiyya, wa kull touqous wa kull gunoud, yaseehoun bi-lughat samawiyya, quddam man sara minki mawloud.\n\nQuddam man sara minki mawloud, yaseehoun bi-aswat wa nagham, wa tamgeed rouhani wa sougoud, quddam kursi Rabb el-'azama.\n\nToubaki ya ibnat Dawoud, toubaki ya mamlou'at ni'ma, toubaki ya umm el-ma'boud, es-salam laki ya umm er-rahma.\n\nEs-salam laki ya umm er-rahma, toubaki ya mumtali'a ni'ma, Ouoh ten-tshois ennēb Maria, hiten nes-tovh nem nes-epresvia." },
  ] },
  { id: "vp-the-fifth-hymn-of-pope-abba-markos-viii", title: "The Fifth Hymn of Pope Abba Markos VIII", versions: [
    { language: 'english', text: "You truly became a second heaven, you carried the Lord of hosts, O Mary the pride of women, He truly and firmly dwelt in you.\n\nAnd appeared from you as a Man, one Person of the Trinity, He was nursed from your milk, and hid His divinity from the Devil.\n\nHerod became weary, for His sake he put to death, all male children who lived, in the houses of Bethlehem.\n\nAnd the spiritual angel of the Lord, came to Joseph and called him, in his sleep saying “O man, hurry before the night passes.\n\nTake the Child and flee, with His Mother to be saved from death, by King Herod the deceiver, and go to the land of Egypt.\n\nLeave now to those cities, until his reign ends, you can come and return, when the hated one is destroyed.”\n\nAnd Joseph was not lazy, he quickly took a colt, and sat the Virgin upon it, with Him who cares for the creation.\n\nHail to you O Lady of virgins, O Mary the Virgin, Jesus Christ dwelt in your womb, and became our Savior." },
    { language: 'arabic', text: "صرتِ سماء حقاً ثاني، حملتِ رب الصباؤوت، يا مريم فخر النساءِ، سكن فيكِ حقاً بثبوت.\n\nوظهر منكِ شبه إنسانِ، أُقنوماً واحداً من ثالوث، ورضع من ثدييكِ، وعن الشيطان أخفى اللاهوت.\n\nهيرودس قد صار حيرانِ، من أجله قد أمر بالموت، لجميع الأطفال الصبيانِ، سُكان بيت لحم وكل البيوت.\n\nوملاك الرب الروحاني، مضى ليوسف وناداه بالصوت، في النوم قائلاً له \"يا إنسانِ، قم بسرعة لما الليل يفوت.\n\nخذ الطفل وصِرْ هربانِ، أنت واُمه تنجو من الموت، من هيرودس الملك الخوانِ، وكن إلى أرض مصر مبعوث.\n\nوأمضِ إلى تلك البلدانِ، لما يفنى مُلكُه ويفوت، تعال وإرجع بالثاني، لمَّا يهلك ذلك الممقوت.\"\n\nويوسف كان غير كسلانِ، بسرعة أخذ أتاناً كان مربوط، وأجلسَ العذراء على الأتانِ، ومعها مَنْ للخلق يقوت.\n\nالسلام لكِ يا ست الأبكار، يا مريم تي بارثينوس، يا مَنْ في أحشائكِ قد حلَّ وصار، مخلصنا إيسوس بيخريستوس." },
    { language: 'englishArabic', text: "Sirti sama'an haqqan thani, hamalti Rabb es-Saba'out, ya Maryam fakhr en-nisa'i, sakana feeki haqqan bi-thubout.\n\nWa zahara minki shibh insani, uqnouman wahidan min thalouth, wa radi'a min thadyayki, wa 'an esh-shaytan akhfa el-lahout.\n\nHeeroudus qad sara hayrani, min aglihi qad amara bil-mawt, li-gamee' el-atfal es-sibyani, sukkan Bayt Lahm wa kull el-buyout.\n\nWa malak er-Rabb er-rouhani, mada li-Yousef wa nadahu bis-sawt, fin-nawm qa'ilan lahu: \"Ya insani, qum bi-sur'a lamma el-layl yafout.\n\nKhudh et-tifl wa sir harbani, anta wa ummuhu tangou min el-mawt, min Heeroudus el-malik el-khawwani, wa kun ila ard Masr mab'outh.\n\nWamdi ila tilka el-buldani, lamma yafna mulkuhu wa yafout, ta'ala warga' bith-thani, lamma yahlak dhalika el-mamqout.\"\n\nWa Yousef kana ghayr kaslani, bi-sur'a akhadha atanan kana marbout, wa aglasa el-'Adhra' 'ala el-atani, wa ma'aha man lil-khalq yaqout.\n\nEs-salam laki ya sitt el-abkar, ya Maryam Tiparthenos, ya man fi ahsha'iki qad halla wa sar, mukhallisuna Iēsous Pikhristos." },
  ] },
  { id: "vp-the-fifth-hymn-of-el-bardanohee", title: "The Fifth Hymn of El-Bardanohee", versions: [
    { language: 'english', text: "You became a second heaven in truth, O Mary the holy of holies, the Sun of truth shone from you, you bore for us your Son the Messiah.\n\nThe vow and promise were fulfilled, as Moses explained about you, He shed His Blood for His people, He died and rose during the dawn.\n\nAnd the Devil’s legion was destroyed, he lost mercy and became depressed, he became an enemy of all creatures, he scatters his evil among the people.\n\nMary truly defeated him, he became trampled under the feet, and Adam was saved from his captivity, through your Son’s Blood O holy of holies.\n\nAll the tongues are worthy, to praise you with the Messiah, in Bethlehem you had contractions, and gave birth to the Creator of all the souls.\n\nYou wrapped Him in clothes, He who measured the heaven, He shed His Blood for us, and made it mixed in the chalice.\n\nHail to you O Mother of God, ask your Son on our behalf, to forgive us sinners, through your prayers and honored rank." },
    { language: 'arabic', text: "صرتِ سماء ثانية بالحق، يا مريم يا قدس الأقداس، شمس العدل منكِ أشرق، ولدتِ لنا إبنِك ماسياس.\n\nتم القسم والوعد صدق، كما شرح فيكِ مويسيس، وعن شعبه دمه أهرق، مات وقام سحَر الأغلاس.\n\nوجيش الشيطان قد إنسحق، عَدِمَ الرحمة وغلبه اليأس، وصار عدواً لكل الخلق، يلقي شره ما بين الناس.\n\nهزمتهِ يا مريم بالحق، وصار مرمياً مطروحاً منداس، وأسيره آدم إنعتق، بدم إبنِك يا قدس الأقداس.\n\nكل الألسن تستحق، تمجدكِ مع ماسياس، وفي بيت لحم أتاكِ الطلق، ولدتِ خالق كل الأنفاس.\n\nولفيتي المولود بخِرق، وكامل السماء بشبره منقاس، وجعل دمه عنا مُهرق، في الصينية ممزوجاً في الكأس.\n\nالسلام لكِ يا اُم الإله، جيرينا قدام إبنِك، ليسامحنا نحن الخطاة، بصلاتِك وشرف جنسِك." },
    { language: 'englishArabic', text: "Sirti sama'an thaniya bil-haqq, ya Maryam ya quds el-aqdas, shams el-'adl minki ashraq, waladti lana ibnaki Massias.\n\nTamma el-qasam wal-wa'd sadaq, kama sharaha feeki Mōusēs, wa 'an sha'bihi damahu ahraq, mata wa qama sahar el-aghlas.\n\nWa gaysh esh-shaytan qad insahaq, 'adima er-rahma wa ghalabahu el-ya's, wa sara 'aduwwan li-kull el-khalq, yulqi sharrahu ma bayna en-nas.\n\nHazamteehi ya Maryam bil-haqq, wa sara marmiyyan matrouhan mundas, wa aseeruhu Adam in'ataq, bi-dam ibniki ya quds el-aqdas.\n\nKull el-alsun tastahiqq, tumaggiduki ma'a Massias, wa fi Bayt Lahm ataki et-talq, waladti khaliq kull el-anfas.\n\nWa laffayti el-mawloud bi-khiraq, wa kamil es-sama' bi-shibrihi munqas, wa ga'ala damahu 'anna muhraq, fis-seeniyya mamzougan fil-ka's.\n\nEs-salam laki ya umm el-Ilah, geereena quddam ibnik, li-yusamihana nahnu el-khutah, bi-salatik wa sharaf ginsik." },
  ] },
  { id: "vp-the-sixth-greek-interpretation", title: "The Sixth Greek Interpretation", versions: [
    { language: 'coptic', text: "Ⲥⲟⲙⲥ ⲟⲩⲟϩ ⲙⲁⲓⲁ̀ⲧⲉⲛ ⲑⲏⲛⲟⲩ: ϧⲉⲛ ⲛⲁⲓⲙⲩⲥⲧⲏⲣⲓⲟⲛ ⲉⲧϩⲏⲡ: ⲧⲉⲧⲉⲛϫⲉⲙⲟⲩ ⲉ̀ϯⲡⲁⲣⲑⲉⲛⲟⲥ: ⲟⲩⲙⲩⲧⲏⲣ Ⲭⲣⲓⲥⲧⲟⲩ Ⲑⲉⲟⲩ Ⲡⲉⲛⲛⲏⲃ.\n\nⲈⲑⲃⲉⲟⲩ ⲡⲉϫⲉ ⲡⲓⲇⲩⲛⲁⲧⲟⲥ: ⲙ̀ⲡⲉϥⲃⲱⲕ Ⲙⲱⲩ̀ⲥⲏⲥ ⲡⲟⲓⲏ̀ⲥⲟⲛ: ⲛ̀ⲟⲩⲥ̀ⲕⲩⲛⲏ ⲛⲉⲙ ⲟⲩⲕⲓⲃⲱⲧⲟⲥ: ⲟⲩⲟϩ ⲗⲁⲗⲱⲥ ϧⲉⲛ ⲡⲓⲭ̀ⲣⲩⲥⲟⲛ.\n\nⲀⲣⲓϩⲱⲃ ⲙⲉⲛ ⲛ̀ⲟⲩⲕⲁⲡⲥⲁⲕⲏⲥ: ⲉ̀ⲡⲓⲙⲁⲛⲛⲁ ⲧⲩⲡⲟⲛ ⲧⲁ ⲉ̀ⲡⲓⲅⲉⲓⲁ̀: ⲭⲁⲧⲟⲩ ⲁⲩⲧⲟⲩⲥ ⲛⲉⲙ ⲛⲓⲡ̀ⲗⲁⲕⲏⲥ: ϧⲉⲛ ⲑ̀ⲙⲏϯ ⲛ̀ϯⲥ̀ⲕⲩⲛⲟⲡⲓⲅⲉⲓⲁ.\n\nⲚⲁⲓ ⲧⲏⲣⲟⲩ ⲁⲩϣⲱⲡⲓ ⲛ̀ⲧⲩⲡⲓⲕⲟⲛ: ⲉ̀ϯⲡⲁⲛⲁ̀ⲅⲓⲁ ⲁ̀ⲙⲟⲗⲩⲛⲧⲟⲥ: ⲏ̀ ⲥ̀ⲕⲩⲛⲟⲙⲁ ⲁⲛⲑ̀ⲣⲟⲡⲓⲕⲟⲛ: Ⲙⲁⲣⲓⲁ ⲡⲓⲙⲁⲛⲛⲁ ⲡⲉ Ⲡⲭ︦ⲥ︦.\n\nⲠⲟⲩⲣⲟ ⲛ̀ⲧⲉ ⲡ̀ⲱ̀ⲟⲩ Ⲓⲏ︦ⲥ︦ ⲡⲓⲙⲓⲥⲓ: ⲉⲕ ⲧⲟⲛ ⲁⲣⲣⲏⲕⲧⲟⲥ ⲧⲟⲓ̀ⲭⲟⲥ: ⲁϥⲓ̀ ⲉ̀ⲡⲓⲕⲟⲥⲙⲟⲥ ⲉ̀ⲃⲟⲗϧⲉⲛ ⲡ̀ϭⲓⲥⲓ: ⲥⲩⲙ ⲡⲁⲧⲣⲓ ⲁ̀ⲛⲉⲩⲧⲟⲓ̀ⲭⲟⲥ.\n\nⲠⲓⲡⲁⲣⲁⲇⲓⲥⲟⲥ ⲉϣⲗⲏⲗⲟⲩⲓ̀: ϫⲉ ⲁϥⲓ̀ ⲁϥⲉⲣϣ̀ⲫⲏⲣ ⲛⲉⲙⲁⲛ: ⲁ̀ⲛⲟⲛ ϧⲁ ⲛⲓⲁ̀ⲡⲟⲣⲟⲥ ⲛ̀ⲥ̀ⲃⲱⲟⲩⲓ̀: ⲟⲩⲟϩ ⲁϥϣⲉⲛϩⲏⲧ ⲁϥⲥⲱϯ ⲙ̀ⲙⲟⲛ.\n\nⲦⲉⲛϯⲱ̀ⲟⲩ ⲛⲉ ⲱ̀ ⲑⲏⲉⲧⲥⲙⲁⲙⲁⲧ: ϣⲁ ⲡⲓⲛⲓϥⲓ ⲛ̀ⲧⲉ ⲗⲉⲩⲧⲉⲟⲥ: ϫⲉ ⲁⲣⲉϫⲓⲙⲓ ⲅⲁⲣ ⲛ̀ⲟⲩϩ̀ⲙⲟⲧ: ϧⲁⲧⲉⲛ Ⲡⲉⲛⲟⲩϯ Ⲩⲓⲟⲥ Ⲑⲉⲟⲥ." },
    { language: 'english', text: "Look and contemplate / upon these hidden mysteries / that are for the Virgin / the Mother of Christ, our God and Master.\n\nWhy did the Strong One say, to His servant Moses to make, a tabernacle and an ark, and a layer of gold on them.\n\nAnd make a vessel for the manna, a symbol for the earthly ones, and place it with the tablets, in the midst of the tabernacle.\n\nThese all were symbols, for the all-holy one, the human and pure tabernacle, Mary and the Manna is the Christ.\n\nThe King of glory Jesus the Begotten, from the invincible barrier, He came to the world from the high places, and He is with the Father without separation.\n\nThe Paradise rejoiced, for He came and participated with us, we who lack understanding, and He had compassion on us and saved us.\n\nWe glorify you O blessed one, until the last breath saying, \"You have found favor before, your God the Son of God.\"" },
    { language: 'arabic', text: "انظروا وتأملوا في هذه الأسرار الخفية. تجدونها على العذراء أم المسيح الإله سيدنا.\n\nلماذا قال القوى لعبده موسي أصنع قبة وتابوتاً وصفحة بالذهب.\n\nوأعمل قسطاً للمن مثالاً للأرضيين . وضعها مع الألواح في وسط المظال\n\nهذه كلها كانت مثالاً لذات كل القدس القبة الناسوتية الطاهرة مريم والمن هو المسيح.\n\nملك المجد يسوع المولود من السرور المنيع أتي إلى العالم من العلا وهو مع الآب بغير افتراق.\n\nالفردوس يتهلل لأنه قد جاء وأشترك معنا نحن الناقصين الفهم وتحنن وخلصنا.\n\nنمجدك ايتها المباركة إلى النفس الأخير لأنك وجدت نعمة عند إلهك ابن الله." },
    { language: 'englishArabic', text: "Unzurou wa ta'ammalou fi hadhihi el-asrar el-khafiyya, tagidounaha 'ala el-'Adhra' umm el-Maseeh el-Ilah sayyidina.\n\nLi-madha qala el-qawiyy li-'abdihi Mousa: isna' qubba wa tabouthan wa saffihu bidh-dhahab.\n\nWa'mal qistan lil-mann mithalan lil-ardiyyeen. Wada'aha ma'a el-alwah fi wasat el-mazall.\n\nHadhihi kulluha kanat mithalan li-dhat kull el-quds el-qubba en-nasoutiyya et-tahira Maryam, wal-mann huwa el-Maseeh.\n\nMalik el-magd Yasou' el-mawloud min es-sourour el-manee', ata ila el-'alam min el-'ula wa huwa ma'a el-Ab bi-ghayr iftiraq.\n\nEl-firdaws yatahallal li-annahu qad ga'a washtaraka ma'ana nahnu en-naqiseen el-fahm, wa tahannana wa khallasana.\n\nNumaggiduki ayyatuha el-mubaraka ila en-nafas el-akheer li-annaki wagadti ni'ma 'ind ilahik Ibn Allah." },
  ] },
  { id: "vp-the-sixth-bohairic-interpretation-a", title: "The Sixth Bohairic Interpretation A", versions: [
    { language: 'coptic', text: "Ⲏⲗⲓⲁⲃ ⲛⲉⲙ Ⲍⲟⲣⲟⲃⲁⲃⲉⲗ: ⲛⲁⲩⲉⲣϩⲱⲃ ϧⲉⲛ ϯⲥ̀ⲕⲩⲛⲏ: ϧⲉⲛ ⲟⲩⲣⲁϣⲓ ⲛⲉⲙ ⲟⲩⲑⲉⲗⲏⲗ: ⲛⲉⲙ ⲟⲩⲛⲓϣϯ ⲛ̀ⲧⲓⲙⲏ.\n\nⲀⲩⲭⲱ ⲛ̀ⲛⲓⲡ̀ⲗⲁⲝ ⲛ̀ⲱ̀ⲛⲓ ⲛ̀ϧⲏⲧⲥ: ⲛⲉⲙ ⲡⲓⲥ̀ⲧⲁⲙⲛⲟⲥ ⲛⲉⲙ ϯⲗⲩⲭⲛⲓⲁ: ⲛⲉⲙ ϯϣⲟⲩⲣⲏ ⲉⲑⲙⲉϩ ⲛ̀ϫⲉⲃⲥ: ⲛⲉⲙ ϯⲕⲉⲃⲁⲕⲧⲏⲣⲓⲁ.\n\nⲈϥⲟⲓ ⲛ̀ⲧⲩⲡⲟⲥ Ⲡϣⲏⲣⲓ ⲙ̀Ⲫϯ: ⲉ̀ⲧⲁϥⲓ̀ ⲁϥϣⲱⲡⲓ ϧⲉⲛ Ⲙⲁⲣⲓⲁ: ⲟⲩⲟϩ ⲁϥϯⲛⲁⲛ ⲛ̀ⲟⲩⲥⲱϯ: ⲛⲉⲙ ϯⲕⲉⲉ̀ⲗⲉⲩⲑⲉⲣⲓⲁ.\n\nⲦⲉⲛϯⲱⲟⲩ ⲛⲉ ⲱ̀ ⲑⲏⲉ̀ⲧⲉⲛϩⲟⲧ: ⲛⲉⲙ ⲡⲓⲁⲅⲅⲉⲗⲟⲥ ⲛ̀ⲧⲉ ⲡⲓⲥ̀ⲙⲟⲩ: ϫⲉ ⲭⲉⲣⲉ ⲕⲉ ⲭⲁⲣⲓⲧⲱⲙⲉⲛⲏ ⲱ̀ ⲑⲏⲉⲑⲙⲉϩ ⲛ̀ϩⲙⲟⲧ: ⲟⲩⲟϩ Ⲡⲟ︦ⲥ︦ ϣⲟⲡ ⲛⲉⲙⲉ." },
    { language: 'english', text: "Eliab and Zebulun, were working on the tabernacle, with joy and happiness, and greatness of honor.\n\nThey placed the tablets of stone in it, and the vessel and lampstand, and the censer full of coal, and also the rod.\n\nA symbol of the Son of God, who came and dwelt in Mary, and granted us salvation, and freedom.\n\nWe glorify you O trusted one, with the angel of blessing saying, \"Hail to you O full of grace, the Lord is with you.\"" },
    { language: 'arabic', text: "إلياب وزروبابل كانا يعملان في القبة بفرح وتهليل وعظم كرامة.\n\nوضعا ألواح الحجارة فيها والقسط والمنارة والمجمرة مملوءة جمرا والعصاة أيضاً\n\nمثالاً الابن الله الذي أتي وحل قي مريم وأعطانا الخلاص والحرية.\n\nنمجدك أيتها الأمينة قائلين مع ملاك البركة أفرحي أيتها الممتلئة نعمة . الرب معك." },
    { language: 'englishArabic', text: "Elyab wa Zoroubabel kana ya'malan fil-qubba bi-farah wa tahleel wa 'izam karama.\n\nWada'a alwah el-higara feeha wal-qist wal-manara wal-mighmara mamlou'a gamran wal-'asa aydan.\n\nMithalan li-Ibn Allah alladhi ata wa halla fi Maryam wa a'tana el-khalas wal-hurriyya.\n\nNumaggiduki ayyatuha el-ameena qa'ileen ma'a malak el-baraka: ifrahi ayyatuha el-mumtali'a ni'ma, er-Rabb ma'aki." },
  ] },
  { id: "vp-the-sixth-bohairic-interpretation-b", title: "The Sixth Bohairic Interpretation B", versions: [
    { language: 'coptic', text: "Ⲍⲉⲟϣ ⲛ̀ϫⲉ ⲛⲉⲉⲩⲫⲟⲙⲓⲁ: ⲛⲉⲙ ⲛ̀ϭⲓⲥⲓ ⲛ̀ⲧⲉ ⲡⲟⲗⲓⲧⲓⲁ: ⲱ̀ ϯϣⲉⲗⲉⲧ ⲙ̀ⲙⲏⲓ Ⲙⲁⲣⲓⲁ: ϯⲥ̀ⲕⲩⲛⲏ ⲛ̀ⲕⲁⲑⲁⲣⲟⲥ.\n\nⲪⲏⲁⲧⲥⲏⲟⲩ ⲱ̀ ϯⲡⲁⲣⲑⲉⲛⲟⲥ: ⲁϥⲥⲱⲧⲡ ⲙ̀ⲙⲟ ϧⲁϫⲱⲟⲩ ⲛ̀ⲛⲓⲭ̀ⲣⲟⲛⲟⲥ: ⲉⲑⲣⲉϣⲱⲡⲓ ⲛⲁϥ ⲛ̀ⲟⲩⲑ̀ⲣⲟⲛⲟⲥ: ⲱ̀ ⲡⲓϩⲁⲣⲙⲁ ⲛ̀ⲛⲟⲏ̀ⲧⲉ.\n\nⲦⲉϭⲟⲥⲓ ⲉ̀ϯⲕⲓⲃⲱⲧⲟⲥ: ⲛⲉⲙ ⲛⲓⲡ̀ⲗⲁⲝ ⲛⲉⲙ ⲡⲓⲥ̀ⲧⲁⲙⲛⲟⲥ: ⲉⲑⲃⲉ ⲫⲁⲓ ⲡⲓⲡⲁⲣⲁⲇⲓⲥⲟⲥ: ⲉϥⲣⲁϣⲓ ⲉϥⲉϣⲗⲏⲗⲟⲩⲓ.\n\nϪⲉ ⲁ̀Ⲫϯ ⲛ̀Ⲁⲃⲣⲁⲁⲙ: ⲁϥⲥⲟⲩⲧⲱⲛ ⲧⲉϥⲟⲩⲓ̀ⲛⲁⲙ: ⲛⲓⲙⲏϣ ⲉⲩⲁ̀ⲙⲟⲛⲓ ⲛⲉⲙ Ⲁⲇⲁⲙ: ⲁϥⲟ̀ⲗⲟⲩ ⲉ̀ϧⲟⲩⲛ ⲉ̀ⲣⲟϥ.\n\nⲘⲁⲣⲉⲛϯⲱ̀ⲟⲩ ⲛ̀ϯⲁ̀ⲅⲓⲁ̀: ϧⲉⲛ ϩⲁⲛⲥ̀ⲙⲏ ⲛ̀ⲇⲟⲝⲟⲗⲟⲅⲓⲁ̀: ϫⲉ ⲭⲉⲣⲉ ⲣⲁϣⲓ ⲱ̀ Ⲙⲁⲣⲓⲁ: ⲟ̀ Ⲕⲩⲣⲓⲟⲥ ⲙⲉⲧⲁ ⲥⲟⲩ." },
    { language: 'english', text: "Many are your hymns, and exalted are your virtues, O Mary the true Bride, the pure tabernacle.\n\nHe who is timeless O Virgin, chose you before time, that you may become a throne for Him, O rational chariot.\n\nYou are exalted more than the ark, and the tablets and the vessel, therefore the Paradise, rejoiced and became glad.\n\nFor the God of Abraham, stretched His right hand, and those who were held with Adam, He raised them to Himself.\n\nLet us glorify the saint, in voice of glorification saying, \"Hail to you rejoice O Mary, the Lord is with you.\"" },
    { language: 'arabic', text: "كثيرة هي مدائحك ومتعالية فضائلك أيتها العروسة الحقانية مريم القبة النقية.\n\nغير الزمني أيتها العذراء اختارك من قبل الأزمان لتصيري له كرسيا أيتها المركبة العقلية.\n\nتعاليت عن التابوت والألواح والقسط من أجل هذا الفردوس يفرح ويتهلل.\n\nلأن إله إبراهيم بسط يمينه والجمع الممسوك مع آدم رفعه إليه.\n\nفلنمجد القديسة بأصوات التمجيد قائلين السلام أفرحي يا مريم الرب معك." },
    { language: 'englishArabic', text: "Katheera hiya mada'ihuki wa muta'aliya fada'iluki ayyatuha el-'arousa el-haqqaniyya Maryam el-qubba en-naqiyya.\n\nGhayr ez-zamani ayyatuha el-'Adhra' ikhtaraki min qabl el-azman li-taseeri lahu kursiyyan ayyatuha el-markaba el-'aqliyya.\n\nTa'alayti 'an et-tabouth wal-alwah wal-qist; min agl hadha el-firdaws yafrah wa yatahallal.\n\nLi-anna ilah Ibraheem basata yameenahu, wal-gam' el-mamsouk ma'a Adam rafa'ahu ilayh.\n\nFal-numaggid el-qiddeesa bi-aswat et-tamgeed qa'ileen: es-salam, ifrahi ya Maryam er-Rabb ma'aki." },
  ] },
  { id: "vp-the-sixth-coptic-mo-aqap-interpretation", title: "The Sixth Coptic Mo-‘aqap Interpretation", versions: [
    { language: 'coptic', text: "Ⲍⲉⲟϣ ⲛ̀ϫⲉ ⲛⲁⲡⲁⲣⲁⲡ̀ⲧⲱⲙⲁ: ⲛⲉⲙ ⲡ̀ⲑⲱⲗⲉⲃ ⲛ̀ⲧⲉ ⲡⲁⲥⲱⲙⲁ: ⲉⲩⲉⲣⲕⲟⲩϫⲓ ⲛ̀ϫⲉ ⲛⲁⲕⲁⲑⲁⲣⲧⲱⲙⲁ: Ⲡⲁⲛⲟⲩϯ ⲙ̀ⲡⲉⲣⲭⲁϯ ⲛ̀ⲥⲱⲕ.\n\nⲠⲁⲛⲟⲩϯ ⲙ̀ⲡⲉⲣⲭⲁⲧ ⲛ̀ⲥⲱⲕ: ⲁⲗⲗⲁ ⲙⲁⲧⲁⲥⲑⲟⲓ ϩⲁⲣⲟⲕ: ⲛ̀ⲧⲁⲓ̀ⲣⲓ ⲙ̀ⲡⲉⲧⲉϩⲛⲁⲕ: ⲉⲑⲃⲉ ⲑⲏⲉ︦ⲑ︦ⲩ︦ ⲛ̀ⲧⲁⲕ.\n\nⲈⲑⲃⲉ ⲑⲏⲉ︦ⲑ︦ⲩ︦ ⲛ̀ⲧⲁⲕ: Ⲙⲁⲣⲓⲁ ⲫ̀ⲙⲁⲛ̀ⲉⲙⲧⲟⲛ ⲙ̀ⲙⲟⲕ: ⲉ̀ⲧⲁⲕϩⲟⲛϩⲉⲛ ⲙ̀Ⲙⲱⲩ̀ⲥⲏⲥ ⲡⲉⲕⲃⲱⲕ: ⲁϥⲑⲁⲙⲓⲟ ⲙ̀ⲡⲉⲥⲧⲩⲡⲟⲥ.\n\nⲀϥⲑⲁⲙⲓⲟ ⲙ̀ⲡⲉⲥⲧⲩⲡⲟⲥ: ⲕⲁⲧⲁ ⲡⲉⲕϩⲟⲛϩⲉⲛ ⲕⲁⲗⲱⲥ: ϫⲉ ⲁϥⲑⲁⲙⲓⲟ ⲛ̀ⲟⲩⲕⲓⲃⲱⲧⲟⲥ: ϧⲉⲛ ϩⲁⲛϣⲉ ⲙ̀ⲡⲁⲩⲕⲓⲛⲟⲛ.\n\nϦⲉⲛ ϩⲁⲛϣⲉ ⲙ̀ⲡⲁⲩⲕⲓⲛⲟⲛ: ⲛⲉⲙ ⲡⲓⲥ̀ⲧⲁⲙⲛⲟⲥ ⲛ̀ⲛⲟⲩⲃ ⲇⲉⲟⲛ: ⲛⲉⲙ ϯⲗⲩⲭⲛⲓⲁ ⲛ̀ⲕⲁⲗⲁⲙⲟⲛ: ⲛⲉⲙ ϯϣⲟⲩⲣⲏ ⲛⲉⲙ ⲛⲓⲥ̀ⲕⲉⲩⲟⲥ.\n\nⲚⲉⲙ ϯϣⲟⲩⲣⲏ ⲛⲉⲙ ⲛⲓⲥ̀ⲕⲉⲩⲟⲥ: ⲉⲧⲭⲏ ϧⲉⲛ ϯⲕⲓⲃⲱⲧⲟⲥ: ⲁ̀ ⲛⲁⲓ ⲧⲏⲣⲟⲩ ⲉⲣⲧⲩⲡⲟⲥ: ⲉⲑⲃⲉ ϯⲑⲉⲟ̀ⲧⲟⲕⲟⲥ.\n\nⲈⲑⲃⲉ ϯⲑⲉⲟ̀ⲧⲟⲕⲟⲥ: ⲁⲩⲟⲩⲱⲛ ⲙ̀ⲡⲓⲡⲁⲣⲁⲇⲓⲥⲟⲥ: ϫⲉ ⲁ̀Ⲡⲟ︦ⲥ︦ ⲛⲁⲓ ϧⲁ ⲡⲉϥⲗⲁⲟⲥ: ⲁϥⲓ̀ ⲟⲩⲟϩ ⲁϥⲥⲱϯ ⲙ̀ⲙⲟⲛ.\n\nⲦⲉⲛϯⲱ̀ⲟⲩ ⲛⲉ ⲱ̀ ⲑⲏⲉ̀ⲧⲉⲛϩⲟⲧ: ⲉⲧϥⲁⲓ ϧⲁ ⲡⲓⲗⲟⲅⲟⲥ ⲛ̀ⲧⲉ Ⲫ̀ⲓⲱⲧ: ϫⲉ ⲭⲉⲣⲉ ⲑⲏⲉⲑⲙⲉϩ ⲛ̀ϩ̀ⲙⲟⲧ: ⲟⲩⲟϩ Ⲡⲟ︦ⲥ︦ ϣⲟⲡ ⲛⲉⲙⲉ." },
    { language: 'english', text: "Many are my iniquities, and the impurities of my body, and few are my virtues, O my God do not turn away from me.\n\nO my God do not turn away from me, but bring me back to You, to do Your will, for the sake of Your saint.\n\nFor the sake of Your saint, Mary Your resting place, concerning whom You ordered Your servant Moses, to make a symbol of.\n\nTo make a symbol of, according to Your good command, for he made a tabernacle, out of almond wood.\n\nOut of almond wood, and also a golden vessel, and a lampstand with a rod, the censer and the barrels.\n\nThe censer and the barrels, that were placed in the tabernacle, are all symbols, because of the Theotokos.\n\nBecause of the Theotokos, paradise has been reopened, for the Lord was merciful to His people, He came and saved us.\n\nWe glorify you O faithful one, who carried the Word of the Father, \"Hail to you O full of grace, the Lord is with you.\"" },
    { language: 'arabic', text: "كثيرة هي زلاتي ودنس جسدي وقليلة هي فضائلي . يا إلهي لا تتركني عنك (لا ترفضني).\n\nيا إلهي لا تتركني عنك بل ردني إليك لأصنع إرادتك من أجل قديستك.\n\nمن أجل قديستك: مريم موضع راحتك التي امرت موسي عبدك صنع مثالها.\n\nصنع مثالها: كأمرك جيداً لأنه صنع تابوتاً من خشب اللوز.\n\nمن خشب اللوز: والقسط الذهب أيضاً والمنارة ذات السيقان (القصبات) والمجمرة والأواني.\n\nوالمجمرة والأواني: الموضوعة في التابوت هؤلاء كلها مثال لوالدة الإله.\n\nمثال لوالدة الإله: فتح الفردوس لأن الرب رحم شعبه أتي وخلصنا\n\nنمجدك ايتها الامينة. الحاملة كلمة الأب قائلين إفرحي يا ممتلئة نعمة. الرب معك" },
    { language: 'englishArabic', text: "Katheera hiya zallati wa danas gasadi, wa qaleela hiya fada'ili. Ya ilahi la tatrukni 'ank (la tarfudni).\n\nYa ilahi la tatrukni 'ank, bal ruddani ilayk li-asna' iradatak min agl qiddeesatik.\n\nMin agl qiddeesatik: Maryam mawdi' rahatik, allati amarta Mousa 'abdak sun' mithaliha.\n\nSun' mithaliha: ka-amrika gayyidan, li-annahu sana'a tabouthan min khashab el-lawz.\n\nMin khashab el-lawz: wal-qist edh-dhahab aydan wal-manara dhat es-seeqan (el-qasabat) wal-mighmara wal-awani.\n\nWal-mighmara wal-awani: el-mawdou'a fit-tabouth, ha'ula' kulluha mithal li-walidat el-Ilah.\n\nMithal li-walidat el-Ilah: fataha el-firdaws li-anna er-Rabb rahima sha'bahu, ata wa khallasana.\n\nNumaggiduki ayyatuha el-ameena, el-hamila kalimat el-Ab, qa'ileen: ifrahi ya mumtali'a ni'ma, er-Rabb ma'aki." },
  ] },
  { id: "vp-the-sixth-egyptian-interpretation", title: "The Sixth Egyptian Interpretation", versions: [
    { language: 'coptic', text: "Ϯⲥ̀ⲕⲏⲛⲏ ⲑⲏⲉ̀ⲧⲟⲩⲙⲟⲩϯ ⲉ̀ⲣⲟⲥ: ϫⲉ ⲑⲏⲉⲑⲟⲩⲁⲃ ⲛ̀ⲧⲉ ⲛⲏⲉⲑⲟⲩⲁⲃ: ⲉ̀ⲣⲉ ϯⲕⲓⲃⲱⲧⲟⲥ ⲛ̀ϧⲏⲧⲥ: ⲉⲥⲗⲁⲗⲏⲟⲩⲧ ⲛ̀ⲛⲟⲩⲃ ⲛ̀ⲕⲁⲑⲁⲣⲟⲥ.\n\nϮⲥ̀ⲕⲏⲛⲏ ⲑⲏⲉ̀ⲧⲟⲩⲙⲟⲩϯ ⲉ̀ⲣⲟⲥ: ϫⲉ ⲡⲓⲉⲣⲫⲉⲓ ⲛ̀ⲕⲁⲑⲁⲣⲟⲥ: ⲁ̀ⲣⲉ Ⲫⲛⲟⲩϯ ⲥⲁϧⲟⲩⲛ ⲙ̀ⲙⲟⲥ: ⲉ̀ⲧⲉ Ⲙⲁⲣⲓⲁ ϯⲡⲁⲣⲑⲉⲛⲟⲥ.\n\nϮⲥ̀ⲕⲏⲛⲏ ⲑⲏⲉ̀ⲧⲟⲩⲙⲟⲩϯ ⲉ̀ⲣⲟⲥ: ϫⲉ ⲡⲓⲙⲁ ⲛ̀ⲭⲁⲛⲟⲃⲓ ⲉ̀ⲃⲟⲗ: ⲡⲉ Ⲙⲁⲣⲓⲁ ϯⲡⲁⲣⲑⲉⲛⲟⲥ: ⲑⲏⲉⲧϫⲱⲗϩ ⲉⲥⲥⲉⲗⲥⲱⲗ ⲙ̀ⲙⲟⲥ.\n\nϮⲥ̀ⲕⲏⲛⲏ ⲑⲏⲉ̀ⲧⲟⲩⲙⲟⲩϯ ⲉ̀ⲣⲟⲥ: ϫⲉ ⲡⲓⲙⲁⲛⲛⲁ ⲛⲉⲙ ⲡⲓⲥ̀ⲧⲁⲙⲛⲟⲥ: ⲛⲉⲙ ⲛⲓⲡ̀ⲗⲁⲝ ⲛ̀ⲱ̀ⲛⲓ ϩⲓϫⲱⲥ: ⲉ̀ⲣⲉ ⲡⲓⲛⲟⲙⲟⲥ ⲥ̀ϧⲏⲟⲩⲧ ⲉ̀ϫⲱⲥ.\n\nϮⲥ̀ⲕⲏⲛⲏ ⲑⲏⲉ̀ⲧⲟⲩⲙⲟⲩϯ ⲉ̀ⲣⲟⲥ: ϫⲉ ⲑⲏⲉⲑⲙⲉϩ ϧⲉⲛ ϯⲥⲟⲫⲓⲁ: ϩⲓⲧⲉⲛ ⲛⲓϯϩⲟ ⲛ̀ⲧⲉ ⲑ̀ⲙⲁⲩ ϯⲡⲁⲣⲑⲉⲛⲟⲥ: Ⲡⲁϭⲟⲓⲥ ⲭⲱ ⲛⲏⲓ ⲛ̀ⲛⲁⲁ̀ⲛⲟⲙⲓⲁ.\n\nϮⲥ̀ⲕⲏⲛⲏ ⲑⲏⲉ̀ⲧⲟⲩⲙⲟⲩϯ ⲉ̀ⲣⲟⲥ: ϫⲉ ⲡⲓϩⲁⲣⲙⲁ ⲛ̀ⲭⲉⲣⲟⲩⲃⲓⲙⲓⲕⲟⲛ: ⲡⲉ Ⲙⲁⲣⲓⲁ ϯⲡⲁⲣⲑⲉⲛⲟⲥ: ⲧ̀ϣⲉⲣⲓ ⲙ̀ⲡ̀ⲟⲩⲣⲟ ⲉ̀ⲛⲉⲥⲉⲃⲱⲛ.\n\nⲈⲑⲃⲉ ⲫⲁⲓ ⲧⲉⲛϩⲱⲥ ⲉ̀Ⲫⲛⲟⲩϯ: ⲫⲏⲉ̀ⲧⲁϥϭⲓⲥⲁⲣⲝ ⲉ̀ⲃⲟⲗ ⲛ̀ϧⲏϯ: ⲁϥⲉⲣⲣⲱⲙⲓ ⲙ̀ⲡⲉⲛⲣⲏϯ: ϣⲁⲧⲉⲛ ⲫ̀ⲛⲟⲃⲓ ⲙ̀ⲙⲁⲩⲁⲧϥ." },
    { language: 'english', text: "The tabernacle which is called, the holy of holies, it contains the ark, overlaid with pure gold.\n\nThe tabernacle which is called, the pure sanctuary, and God is within, she is the Virgin Mary.\n\nThe tabernacle which is called, the place of forgiveness, she is the Virgin Mary, who is adorned and decorated.\n\nThe tabernacle which is called, the manna and the vessel, and the stone tablets are upon it, on them the Law was written.\n\nThe tabernacle which is called, who is full of wisdom, through the prayers of the Virgin Mother, O my Lord forgive me my iniquities.\n\nThe tabernacle which is called, the cherubimic chariot, who is the Virgin Mary, the daughter of the king within.\n\nTherefore we praise God, who was incarnate of you, and became man like us, except for sin alone." },
    { language: 'arabic', text: "القبة التي يدعونها، قدس الأقداس، فيها التابوت، مصفح بالذهب النقي.\n\nالقبة التي يدعونها، الهيكل النقي، والله داخلها، هي مريم العذراء.\n\nالقبة التي يدعونها، موضع الغفران، هي مريم العذراء، المشتملة المزينة.\n\nالقبة التي يدعونها، المَنَّ والقسط، وألواح الحجارة التي عليها، وفيها الناموس مكتوب.\n\nالقبة التي يدعونها، الممتلئة من الحكمة، بطلبات الاُم العذراء، يا ربي إغفر لي آثامي.\n\nالقبة التي يدعونها، المركبة الشاروبيمية، هي مريم العذراء، إبنة الملك من داخل.\n\nفلهذا نسبِّح الله، الذي تجسَّد منكِ، وصار إنساناً مثلنا، ما خلا الخطية وحدها." },
    { language: 'englishArabic', text: "El-qubba allati yad'ounaha, quds el-aqdas, feeha et-tabouth, musaffah bidh-dhahab en-naqiyy.\n\nEl-qubba allati yad'ounaha, el-haykal en-naqiyy, wa Allah dakhilaha, hiya Maryam el-'Adhra'.\n\nEl-qubba allati yad'ounaha, mawdi' el-ghufran, hiya Maryam el-'Adhra', el-mushtamila el-muzayyana.\n\nEl-qubba allati yad'ounaha, el-mann wal-qist, wa alwah el-higara allati 'alayha, wa feeha en-namous maktoub.\n\nEl-qubba allati yad'ounaha, el-mumtali'a min el-hikma, bi-talabat el-umm el-'Adhra', ya Rabbi ighfir li athami.\n\nEl-qubba allati yad'ounaha, el-markaba esh-sharoubeemiyya, hiya Maryam el-'Adhra', ibnat el-malik min dakhil.\n\nFa-li-hadha nusabbih Allah, alladhi tagassada minki, wa sara insanan mithlana, ma khala el-khatiyya wahdaha." },
  ] },
  { id: "vp-the-sixth-sahidic-interpretation", title: "The Sixth Sahidic Interpretation", versions: [
    { language: 'coptic', text: "Ϣⲁϣϥ ⲛ̀ⲧⲁⲅⲙⲁ ⲉⲧϧⲉⲛ ⲡ̀ϭⲓⲥⲓ: ⲛⲁ ⲛⲓⲫⲏⲟⲩⲓ ⲛⲉⲙ ⲟⲩⲣⲁⲛⲟⲥ: ⲉⲩⲉⲣϩⲩⲙⲛⲟⲥ ⲉ̀ⲡⲓⲙⲓⲥⲓ: ⲉ̀ⲃⲟⲗ ϧⲉⲛ ϯⲡⲁⲛⲁ̀ⲅⲓⲁ ⲙ̀ⲡⲁⲣⲑⲉⲛⲟⲥ.\n\nⲦⲉϭⲟⲥⲓ ⲛ̀ϯⲥ̀ⲕⲏⲛⲏ ⲛ̀ϩⲟⲩⲓϯ: ⲑⲏⲉ̀ⲧⲉ Ⲙⲱⲩ̀ⲥⲏⲥ ⲑⲁⲙⲓⲟⲥ: ϫⲉ Ⲓⲏⲥⲟⲩⲥ Ⲡϣⲏⲣⲓ ⲙ̀Ⲫⲛⲟⲩϯ: ⲁϥϣⲱⲡⲓ ⲥⲁϧⲟⲩⲛ ⲙ̀ⲙⲟⲥ.\n\nⲀ Ⲡⲓⲥ̀ⲣⲁⲏⲗ ⲛⲉⲙ ⲛⲉϥϩ̀ⲃⲏⲟⲩⲓ: ⲁϥϣⲉⲛⲁϥ ⲛ̀ϫⲉ ⲡⲓⲥⲏⲟⲩ: ϫⲉ ⲁϥϭⲱϧⲉⲙ ⲛ̀ⲛⲓⲙⲓⲧⲱⲟⲩⲓ: ⲁⲩⲕⲟⲧⲟⲩ ⲉ̀ⲟⲩⲙⲉⲧⲉ̀ⲫ̀ⲗⲏⲟⲩ.\n\nⲀⲗⲗⲁ ⲁ̀ⲛⲟⲛ ϧⲁ ⲛⲓⲡⲓⲥⲧⲟⲥ: ⲁⲛⲉⲣⲕ̀ⲗⲏⲣⲟⲛⲟⲙⲓⲛ ⲙ̀ⲙⲁⲩ: ϫⲉ ⲁⲛⲛⲁϩϯ ϧⲉⲛ Ⲡⲭ︦ⲥ︦: ⲛⲉⲙ ⲧⲉϥⲙⲉⲧϩⲉⲗⲡⲓⲥ ⲧⲉⲛϫⲟⲩϣⲧ ⲙ̀ⲙⲁⲩ.\n\nⲈⲑⲃⲉ ⲫⲁⲓ ⲧⲉⲛϯⲱ̀ⲟⲩ ⲛⲉ: ⲉⲛⲱϣ ⲉ̀ⲃⲟⲗ ⲛⲉⲙ Ⲅⲁⲃⲣⲓⲏⲗ: ϫⲉ ⲭⲉⲣⲉ ⲕⲉ ⲭⲁⲣⲓⲧⲱⲙⲉⲛⲏ: Ⲙⲁⲣⲓⲁ ⲑ̀ⲙⲁⲩ ⲛ̀Ⲉⲙⲙⲁⲛⲟⲩⲏⲗ." },
    { language: 'english', text: "Seven orders in the highest, heavenly with the heavenly ones, praising the Begotten, of the all-holy Virgin.\n\nExalted more than the first tabernacle, that was made by Moses, for Jesus the Son of God, has dwelt within her.\n\nThe time has passed, from Israel and his deeds, for he defiled the ways, and returned to vanities.\n\nBut we are the faithful, became heirs, for we believed in Christ, and await His hope.\n\nTherefore we glorify you, proclaiming with Gabriel, “Hail to you O full of grace, Mary the Mother of Immanuel.”" },
    { language: 'arabic', text: "سبع طغمات في العلاء، سمائية مع السمائين، يسبحون المولود، من القديسة البتول.\n\nمرتفعة عن القبة الأولى، التي صنعها موسى، لأن يسوع إبن الله، قد حل داخلها.\n\nقد مضى زمان إسرائيل، وأعماله، لأنه قد نجَّس الطرق، ورجع للباطل.\n\nلكن نحن المؤمنين، صرنا وارثين، لأننا آمنَّا بالمسيح، وننتظر رجاءه.\n\nفلهذا نُمجدكِ، ونصرخ مع غبريال قائلين،\"السلام لكِ يا ممتلئة نعمة، مريم اُم عمانوئيل.\"" },
    { language: 'englishArabic', text: "Sab' tughmat fil-'ula', samawiyya ma'a es-samawiyyeen, yusabbihoun el-mawloud, min el-qiddeesa el-batoul.\n\nMurtafi'a 'an el-qubba el-oula, allati sana'aha Mousa, li-anna Yasou' Ibn Allah, qad halla dakhilaha.\n\nQad mada zaman Isra'eel, wa a'maluh, li-annahu qad naggasa et-turuq, wa raga'a lil-batil.\n\nLakin nahnu el-mu'mineen, sirna waritheen, li-annana amanna bil-Maseeh, wa nantazir raga'ah.\n\nFa-li-hadha numaggiduki, wa nasrukh ma'a Ghubriyal qa'ileen: \"Es-salam laki ya mumtali'a ni'ma, Maryam umm 'Emmanu'eel.\"" },
  ] },
  { id: "vp-the-sixth-hymn-of-abou-el-saad-of-aboutig", title: "The Sixth Hymn of Abou El-Saad of Aboutig", versions: [
    { language: 'english', text: "The tabernacle, and its vessels / Moses completed their making / the ark was placed in it / overlaid with pure gold.\n\nThe interpreters were perplexed / about the explanations / of the tablets and their contents / with the pot containing the precious manna.\n\nThe true tabernacle / that is Mary the Virgin / she is exalted above all humans / and carried the great mystery.\n\nThe exalted ranks / could not comprehend / all human tongues / were silent and could not speak.\n\nMary is the pride of the nations / she protects us in the world / an ark, she is diligent / to take us to the Harbor.\n\nHail to you O mother of mercy / we are your beloved pray acknowledge us / blessed are you O full of grace / before your Son intercede for us." },
    { language: 'arabic', text: "القبة و أوانيها / موسي كملها تطريز / والتابوت موضوع فيها / مطلي بالذهب الإبريز.\n\nوالألواح وما فيها / القسط وفيه المن عزيز / وعن تفسير معانيها / إحتاروا أهل التمييز.\n\nالقبة الحقيقية / أعني هي العذراء مريم / فاقت طبع البشرية / و قد حوت السر الأعظم.\n\nو الطغمات العلوية / تكل ولم تقدر تفهم / جميع ألسنة البشرية / فهي تصمت لم تتكلم.\n\nمريم هي فخر الأمة / و هي في العالم تحمينا / سفينة و صارت مهتمة بنا / توصلنا إلي المينا.\n\nالسلام لك يا ام الرحمة / نحن عبيدك جيرينا / طوباكِ يا مملوُة نعمة / عند ابنك الحبيب اشفعي فينا." },
    { language: 'englishArabic', text: "El-qubba wa awaneeha / Mousa kammalaha tatreez / wat-tabouth mawdou' feeha / matli bidh-dhahab el-ibreez.\n\nWal-alwah wa ma feeha / el-qist wa feehi el-mann 'azeez / wa 'an tafseer ma'aneeha / ihtarou ahl et-tamyeez.\n\nEl-qubba el-haqeeqiyya / a'ni hiya el-'Adhra' Maryam / faqat tab' el-bashariyya / wa qad hawat es-sirr el-a'zam.\n\nWat-tughmat el-'ulwiyya / takill wa lam taqdir tafham / gamee' alsinat el-bashariyya / fa-hiya tasmut lam tatakallam.\n\nMaryam hiya fakhr el-umma / wa hiya fil-'alam tahmeena / safeena wa sarat muhtamma bina / tuwassilna ila el-meena.\n\nEs-salam laki ya umm er-rahma / nahnu 'abeeduki geereena / toubaki ya mamlou'at ni'ma / 'ind ibniki el-habeeb ishfa'i feena." },
  ] },
  { id: "vp-sixth-hymn-of-cantor-gabriel-of-qay-a", title: "Sixth Hymn of Cantor Gabriel of Qay A", versions: [
    { language: 'english', text: "The tabernacle which was made / with human hands / the vessels in it were placed / he decorated with beautiful forms.\n\nHe decorated with beautiful forms / and adorned with varieties and colors / Moses the prophet in the wilderness / in it, the ark of the Lord Judge.\n\nIn it, the ark of the Lord Judge / the tablets of the covenant their contents / and a golden precious pot / and the rational manna hidden in it.\n\nAnd the rational manna hidden in it / a symbol of the hidden mystery / who is hidden in the bosom of the Father / came with His divinity in Zion.\n\nCame with His divinity in Zion / that is the true tabernacle / as prophesied about by the prophets / with symbols and prophetic witnesses.\n\nWith symbols and prophetic witnesses / that is the tabernacle and its meaning / symbol of the pure first-born virgin / of the coming of the divinity in her.\n\nOf the coming of the divinity in her / a mysterious great mystery / a virgin carried in her arms / whom the seraphim worship.\n\nWhom the seraphim worship / and cannot behold Him / you carried Him, O Mary / as a child, you raised Him.\n\nAs a child, you raised Him / the Creator of creation with power / restored Adam and his children / to Paradise once again.\n\nTo Paradise once again / we all bless you / saying, blessed are you O virgin / hail to you, and hail unto you.\n\nHail to you and hail unto you, we ask you O Mother of the Beloved, grant us to be in your fathers’ dwellings, Abraham Isaac and Jacob." },
    { language: 'arabic', text: "القبة المصنوعة / صناعة أيادي بشرية / و أواني فيها موضوعة / زينها بأشكال بهية.\n\nزينها بأشكال بهية / و طرزها بأصناف و ألوان / موسي النبي في البرية / فيها تابوت الرب الديان.\n\nفيها تابوت الرب الديان / وألواح العهد و ما تحويه / وقسط ذهب غالي الأثمان / والمن العقلي مخفي فيه.\n\nو المن العقلي مخفي فيه / إشارة إلي السر المكتوب / من هو محجوب في حضن إبيه / حل بلاهوته في صهيون.\n\nحل بلاهوته في صهيون / أعني القبة الحقيقية / كما تنبأ عنها المتنبئون / برموز و شهادات نبوية.\n\nبرموز و شهادات نبوية / اعني القبة و معانيها / مثال عذراء بكر نقية / بحلول سر اللاهوت فيها.\n\nبحلول سر اللاهوت فيها / بأمر عجيب و سر عظيم / عذراء حملت بين يديها / من تسجد له السيرافيم.\n\nمن تسجد له السيرافيم / ولا يستطيعون النظر إليه / حملتهِ يا م ر ي م / وكمثل غلام قد ربيتيه.\n\nو كمثل غلام قد ربيتيه / مكون الأكوان بالقدرة / رد آدم و بنيه / إلي الفردوس دفعة أخري.\n\nإلي الفردوس دفعة أخرى / ونحن الكل نطوبك / ونقول طوباكِ يا عذراء / السلام لكِ ثم السلام عليك.\n\nالسلام لكِ ثم السلام إليك، ونسألك يا أم المحبوب، ان تحظينا في مظال اباءك، ابراهيم واسحق ويعقوب." },
    { language: 'englishArabic', text: "El-qubba el-masnou'a / sina'at ayadi bashariyya / wa awani feeha mawdou'a / zayyanaha bi-ashkal bahiyya.\n\nZayyanaha bi-ashkal bahiyya / wa tarrazaha bi-asnaf wa alwan / Mousa en-nabi fil-bariyya / feeha tabouth er-Rabb ed-dayyan.\n\nFeeha tabouth er-Rabb ed-dayyan / wa alwah el-'ahd wa ma tahweeh / wa qist dhahab ghali el-athman / wal-mann el-'aqli makhfi feeh.\n\nWal-mann el-'aqli makhfi feeh / ishara ila es-sirr el-maktoub / man huwa mahgoub fi hudn abeeh / halla bi-lahoutihi fi Sahyoun.\n\nHalla bi-lahoutihi fi Sahyoun / a'ni el-qubba el-haqeeqiyya / kama tanabba'a 'anha el-mutanabbi'oun / bi-roumouz wa shahadat nabawiyya.\n\nBi-roumouz wa shahadat nabawiyya / a'ni el-qubba wa ma'aneeha / mithal 'adhra' bikr naqiyya / bi-houloul sirr el-lahout feeha.\n\nBi-houloul sirr el-lahout feeha / bi-amr 'ageeb wa sirr 'azeem / 'adhra' hamalat bayna yadayha / man tasgud lahu es-Serafeem.\n\nMan tasgud lahu es-Serafeem / wa la yastatee'oun en-nazar ilayh / hamaltihi ya M-R-Y-M / wa ka-mithl ghulam qad rabbayteeh.\n\nWa ka-mithl ghulam qad rabbayteeh / mukawwin el-akwan bil-qudra / radda Adam wa baneeh / ila el-firdaws daf'a ukhra.\n\nIla el-firdaws daf'a ukhra / wa nahnu el-kull nutawwibuki / wa naqoul toubaki ya 'Adhra' / es-salam laki thumma es-salam 'alayki.\n\nEs-salam laki thumma es-salam ilayki, wa nas'aluki ya umm el-mahboub, an tahzeena fi mazall aba'ik, Ibraheem wa Ishaq wa Ya'qoub." },
  ] },
  { id: "vp-the-sixth-hymn-of-cantor-gabriel-of-qay-b", title: "The Sixth Hymn of Cantor Gabriel of Qay B", versions: [
    { language: 'english', text: "The tabernacle that is under time, that was completed by Moses, was decorated with overlaid gold, as the prophet witnessed.\n\nAlso the tablets of the covenant, the Law on it was for the people, a hidden matter and a sign, to the Coming of the Messiah.\n\nThe true tabernacle, I refer to the holy of holies, the blessed first-born, of whom salvation was conceived.\n\nO spiritual tabernacle, rescue us when we drink the cup, that is inevitable for all humans, during the hour when we stop breathing.\n\nYour womb has carried, the One of the Trinity, with a bodily nature, you bore Him like all humans.\n\nHe perfected the human nature, as the saying of the evangelist, except for sin alone, and He shed His Blood for us.\n\nHail to you O Mother of our Savior, we ask you O pure Virgin, to ask the Lord to bring us, to the harbor in peace." },
    { language: 'arabic', text: "القبة الزمنية، التي أكملها مويسيس، زيَّنها بذهب مطليَّة، كما شهد بي إبروفيتيس.\n\nوأيضاً الألواح العهدية، شرائعها كانت للناس، رمزاً وعبارة مخفيَّة، إشارة لظهور ماسياس.\n\nالقبة الحقيقية، أعني هي قدس الأقداس، البكر الطوبانية، المولود منها كل خلاص.\n\nيا قبة نفسانية، غيثينا عند شرب الكأس، المحتوم على البشرية، في ساعة تنقطع الأنفاس.\n\nحَمَلتْ أحشائكِ اللحمية، بي أوؤايْ إيڤول خين تي إترياس، بطبيعة جسدانية، وولدتِه شبه جميع الناس.\n\nوأكمل كل ما للبشرية، كقول بي إيڤ أنجيليستيس، ما خلا فِعِل الخطية، وأهرق دمه عنا في الكأس.\n\nالسلام لكِ يا اُم مخلصنا، ونسألكِ يا بكر نقية، تسألي الرب أن يوصِّلنا، إلى الميناء بطمأنينة." },
    { language: 'englishArabic', text: "El-qubba ez-zamaniyya, allati akmalaha Mōusēs, zayyanaha bi-dhahab matliyya, kama shahida pi-profētēs.\n\nWa aydan el-alwah el-'ahdiyya, shara'i'uha kanat lin-nas, ramzan wa 'ibara makhfiyya, ishara li-zuhour Massias.\n\nEl-qubba el-haqeeqiyya, a'ni hiya quds el-aqdas, el-bikr et-toubaniyya, el-mawloud minha kull khalas.\n\nYa qubba nafsaniyya, gheetheena 'ind shurb el-ka's, el-mahtoum 'ala el-bashariyya, fi sa'a tanqati' el-anfas.\n\nHamalat ahsha'uki el-lahmiyya, Pi-ouai evol khen Ti-etrias, bi-tabee'a gasadaniyya, wa waladtihi shibh gamee' en-nas.\n\nWa akmala kull ma lil-bashariyya, ka-qawl pi-evangelistēs, ma khala fi'l el-khatiyya, wa ahraqa damahu 'anna fil-ka's.\n\nEs-salam laki ya umm mukhallisina, wa nas'aluki ya bikr naqiyya, tas'ali er-Rabb an yuwassilana, ila el-meena' bi-tuma'neena." },
  ] },
  { id: "vp-the-sixth-hymn-of-cantor-gabriel-of-qay-c", title: "The Sixth Hymn of Cantor Gabriel of Qay C", versions: [
    { language: 'english', text: "The tabernacle that is under time, that was completed by Moses, the prophet in the wilderness, he overlaid it with chosen gold.\n\nAnd the tablets of the covenant, as the interpreters have testified, and the lampstand shining with light, and the vessel of the precious manna.\n\nThe vessel of the precious manna, and a censer full of coals, overlaid with chosen gold, as testified by the chosen fathers.\n\nAs a symbol and a sign, I refer to the dome pride of virgins, and also the vessel of the precious manna, is the Begotten before all ages.\n\nIs the Begotten before all ages, the Word of the eternal Father, came and took chosen flesh, from Mary the branch of grace.\n\nThe sayings of the chosen ones were fulfilled, and the prophecies of the ancient fathers, and we all proclaim openly, “Hail to you O Mother of mercy.”\n\nHail to you O Mother of mercy, blessed are you O full of grace, the Lady of us all Mary, through her prayers and intercessions." },
    { language: 'arabic', text: "القبة الزمنية، التي قد أكملها تطريز، موسى النبي في البرية، وطلاها بالذهب الإبريز.\n\nوألواح العهد المسمية، كما شهدوا أهل التمييز، ومنارة بالنور مضيئة، وفيها قسط المَنَّ عزيز.\n\nوفيه قسط المَنَّ عزيز، وشورية تحمل جمر النار، مطليَّة بالذهب الإبريز، كما شهد الآباء الأخيار.\n\nكمثال وعبارة مع تمييز، أعني القبة زين الأبكار، وكذلك قسط المَنَّ عزيز، المولود من بدء الأدهار.\n\nالمولود من بدء الأدهار، من الآب الأزلي الكلمة، أتى وأخذ ناسوتاً مختار، من مريم عنقود النعمة.\n\nوتحقق ما نطق به الأخيار، وتنبأوا به الآباء القدماء، ونحن الكل نصيح إجهار، \"السلام لكِ يا اُم الرحمة.\"\n\nالسلام لكِ يا اُم الرحمة، طوباكِ يا ممتلئة نعمة، أووتين شويس إننيب ماريا، هيتين نيس طوڤه نيم نيس إبريسڤيِّا." },
    { language: 'englishArabic', text: "El-qubba ez-zamaniyya, allati qad akmalaha tatreez, Mousa en-nabi fil-bariyya, wa talaha bidh-dhahab el-ibreez.\n\nWa alwah el-'ahd el-musammiyya, kama shahidou ahl et-tamyeez, wa manara bin-nour mudee'a, wa feeha qist el-mann 'azeez.\n\nWa feehi qist el-mann 'azeez, wa shouriyya tahmil gamr en-nar, matliyya bidh-dhahab el-ibreez, kama shahida el-aba' el-akhyar.\n\nKa-mithal wa 'ibara ma'a tamyeez, a'ni el-qubba zayn el-abkar, wa kadhalika qist el-mann 'azeez, el-mawloud min bad' el-adhar.\n\nEl-mawloud min bad' el-adhar, min el-Ab el-azali el-Kalima, ata wa akhadha nasoutan mukhtar, min Maryam 'unqoud en-ni'ma.\n\nWa tahaqqaqa ma nataqa bihi el-akhyar, wa tanabba'a bihi el-aba' el-qudama', wa nahnu el-kull nasee'h ighar: \"Es-salam laki ya umm er-rahma.\"\n\nEs-salam laki ya umm er-rahma, toubaki ya mumtali'a ni'ma, Ouoh ten-tshois ennēb Maria, hiten nes-tovh nem nes-epresvia." },
  ] },
  { id: "vp-the-sixth-hymn-of-pope-abba-markos-viii", title: "The Sixth Hymn of Pope Abba Markos VIII", versions: [
    { language: 'english', text: "The prophetic tabernacle, was decorated by Moses with colors, he overlaid it with gold, and seven lamps shined on it.\n\nAnd the tablets of the covenant, written by the finger of the Judge, and he placed a bright lampstand, and a golden vessel with the manna in it.\n\nA decree upon the Israelites, a testimony of Judgment Day, and this is a symbolic sign, about you O protected sanctuary.\n\nO Mary the pure first-born, you became a tabernacle for forgiveness, God the Creator of the universe, decorated you with splendid lights.\n\nJoseph came with you, to the Egyptian cities, with the Creator of the creation, a Child carried in your hands.\n\nAll the idols were destroyed, before Him in every place, and Egypt was protected, and the worship of idols ceased to be.\n\nHail to you O Lady of virgins, O Mary the Virgin, Jesus Christ dwelt in your womb, and became our Savior." },
    { language: 'arabic', text: "القبة النبوية، زيَّنها موسى بكل ألوان، وجعلها بذهب مطليَّة، وسبعة سُرُج أيضاً ينيران.\n\nوالألواح العهدية، مكتوبة بأصبع الديان، وجعل فيها منارة مضيئة، وقسط ذهب فيه المَنَّ بيان.\n\nعلى بني الإسرائيلية، شهادة يوم نصب الميزان، وذلك إشارة رمزية، عليكِ يا هيكل منصان.\n\nيا مريم يا بكر نقية، قد صرتِ قبة للغفران، وزيَّنكِ بأنوار بهية، الإله منشئ الأكوان.\n\nوإلى الديار المصرية، مضى بكِ يوسف الإنسان، ومعكِ خالق كل البَرِية، طفلاً محمولاً على اليدان.\n\nبادَت الأصنام بالكلية، من قدامه في كل مكان، وصارت أرض مصر محميَّة، وزالت عنها عبادة الأوثان.\n\nالسلام لكِ يا ست الأبكار، يا مريم تي بارثينوس، يا مَنْ في أحشائكِ قد حلَّ وصار، مخلصنا إيسوس بيخريستوس." },
    { language: 'englishArabic', text: "El-qubba en-nabawiyya, zayyanaha Mousa bi-kull alwan, wa ga'alaha bi-dhahab matliyya, wa sab'at surug aydan yuneeran.\n\nWal-alwah el-'ahdiyya, maktouba bi-isba' ed-dayyan, wa ga'ala feeha manara mudee'a, wa qist dhahab feehi el-mann bayan.\n\n'Ala bani el-Isra'eeliyya, shahada yawm nasb el-meezan, wa dhalika ishara ramziyya, 'alayki ya haykal munsan.\n\nYa Maryam ya bikr naqiyya, qad sirti qubbatan lil-ghufran, wa zayyanaki bi-anwar bahiyya, el-Ilah munshi' el-akwan.\n\nWa ila ed-diyar el-Masriyya, mada biki Yousef el-insan, wa ma'aki khaliq kull el-bariyya, tiflan mahmoulan 'ala el-yadan.\n\nBadat el-asnam bil-kulliyya, min quddamihi fi kull makan, wa sarat ard Masr mahmiyya, wa zalat 'anha 'ibadat el-awthan.\n\nEs-salam laki ya sitt el-abkar, ya Maryam Tiparthenos, ya man fi ahsha'iki qad halla wa sar, mukhallisuna Iēsous Pikhristos." },
  ] },
  { id: "vp-the-sixth-hymn-of-el-bardanohee", title: "The Sixth Hymn of El-Bardanohee", versions: [
    { language: 'english', text: "The prophetic tabernacle, Moses completed with all art, and after it was built, he overlaid it with fine gold.\n\nHe put in it a bright lampstand, and seven lamps shining on it, and the tablets of the covenant, and a golden vessel with the protected manna in it. vessel\n\nThat is a symbolic sign, of Mary the daughter of Zion, she is the true tabernacle, and God of the firmament dwelt in her.\n\nMoses also saw a revelation, fire in a bush with branches, with high flames, and the leaves did not burn.\n\nHe said “This is a pure first-born, a hidden Mystery dwelt in her, carrying the fire of the Divinity, for the salvation of mankind.\n\nShe will become a spiritual heaven, humanity and divinity will unite, and the flesh will not burn, from the coal of the hidden Divinity.”\n\nYou are great and splendid, O Mary Aaron’s censer, you protected hidden mysteries, the coal of the Divinity was in your womb.\n\nHail to you O Mother of God, ask your Son on our behalf, to forgive us sinners, through your prayers and honored rank." },
    { language: 'arabic', text: "القبة النبوية، موسى كملها بكل فنون، وبعد أن صارت مبنية، طلاها بالذهب الموزون.\n\nوجعل فيها منارة مضيئة، وسبعة سُرُج أيضاً ينيرون، والألواح العهدية، وقسط ذهب فيه المَنَّ مصون.\n\nوذلك إشارة رمزية، على مريم إبنة صهيون، هي القبة الحقيقية، وداخلها إله الكون.\n\nنظر موسى أيضاً رؤيا، ناراً في عوسج بغصون، تتوقد متعالية، والأوراق لا يحترقون.\n\nقال \"هذه بكر نقية، سكن فيها سر مكنون، تحمل نار اللاهوتية، لأجل خلاص البشريون.\n\nتصير سماء نفسانية، لاهوت وناسوت يتحدون، ولم تحترق البشرية، من جمر اللاهوت المكنون.\"\n\nعظيمة جداً وبهية، يا مريم شورية هرون، صُنتِ أسراراً خفية، جمر اللاهوت في أحشائكِ مصون.\n\nالسلام لكِ يا اُم الإله، جيرينا قدام إبنِك، ليسامحنا نحن الخطاة، بصلاتِك وشرف جنسِك." },
    { language: 'englishArabic', text: "El-qubba en-nabawiyya, Mousa kammalaha bi-kull founoun, wa ba'd an sarat mabniyya, talaha bidh-dhahab el-mawzoun.\n\nWa ga'ala feeha manara mudee'a, wa sab'at surug aydan yuneeroun, wal-alwah el-'ahdiyya, wa qist dhahab feehi el-mann masoun.\n\nWa dhalika ishara ramziyya, 'ala Maryam ibnat Sahyoun, hiya el-qubba el-haqeeqiyya, wa dakhilaha ilah el-kawn.\n\nNazara Mousa aydan ru'ya, naran fi 'awsag bi-ghusoun, tatawaqqad muta'aliya, wal-awraq la yahtariqoun.\n\nQala: \"Hadhihi bikr naqiyya, sakana feeha sirr maknoun, tahmil nar el-lahoutiyya, li-agl khalas el-bashariyyoun.\n\nTaseer sama'an nafsaniyya, lahout wa nasout yattahidoun, wa lam tahtariq el-bashariyya, min gamr el-lahout el-maknoun.\"\n\n'Azeema giddan wa bahiyya, ya Maryam shouriyyat Haroun, sunti asraran khafiyya, gamr el-lahout fi ahsha'iki masoun.\n\nEs-salam laki ya umm el-Ilah, geereena quddam ibnik, li-yusamihana nahnu el-khutah, bi-salatik wa sharaf ginsik." },
  ] },
  { id: "vp-the-seventh-greek-interpretation", title: "The Seventh Greek Interpretation", versions: [
    { language: 'coptic', text: "Ⲁⲣⲓⲝⲁⲧⲉ ⲛⲉⲙⲏⲓ ⲙ̀ⲫⲟⲟⲩ: ⲧⲱ Ⲑⲉⲟⲩ ⲉⲛ ⲉⲩⲭⲁⲣⲓⲥⲧⲓⲁ: ⲁⲛⲓⲟⲩⲓ ⲛ̀ⲉ̀ⲡⲉⲛⲟⲩⲥ ⲛⲉⲙ ⲡ̀ⲱ̀ⲟⲩ: ⲉ̀ϯⲟⲩⲣⲱ ⲛ̀ⲧⲉ ϯⲁ̀ⲣⲓⲥⲧⲓⲁ.\n\nⲀϫⲟⲥ ϫⲉ ⲁ̀Ⲡⲟ︦ⲥ︦ ⲉⲩⲇⲟⲕⲓⲥⲉⲛ: ⲛ̀ϧⲏϯ ⲕⲁⲧⲁⲫⲩ̀ⲅⲓⲟⲛ: ⲧⲓ ⲟ̀ⲛⲟⲙⲁ ⲥⲟⲩ ⲓ̀ⲡⲱⲙⲉⲛ: ⲱ̀ ⲑⲏⲉⲧϭⲟⲥⲓ ⲉ̀ⲛⲓⲅⲓⲟⲛ.\n\nⲞⲩⲣⲁⲛⲟⲛ ⲕⲉ ⲑ̀ⲣⲟⲛⲟⲛ ⲉ̀ⲡⲓⲅⲏ̀: ⲟ̀ⲧⲓ ⲧⲟⲛ ⲁ̀ⲭⲱⲣⲓⲧⲟⲛ: ⲉⲭⲱⲣⲉ̀ⲥⲁⲥ ⲕⲉ ⲕⲁⲗⲏ ⲡⲩⲅⲏ̀: ⲡⲗⲁⲥⲧⲏ̀ⲥⲁⲥ ⲧⲟⲛ ⲁⲣⲣⲏⲧⲟⲛ.\n\nⲬⲉⲣⲟⲩⲃⲓⲙ ⲥⲉ ⲕⲁⲗⲉ̀ⲥⲱⲙⲉⲛ: ⲟ̀ⲧⲓ ⲧⲟⲛ ⲁ̀ⲯⲏⲗⲁ ⲫⲏⲥⲓⲥ: ⲉ̀ⲃⲁⲥⲧⲁⲥ ⲕⲉ ⲁ̀ⲥⲱⲙⲉⲛ: ϧⲉⲛ ⲟⲩⲁⲑⲗⲏⲥⲓⲥ ⲡⲁⲣⲁ̀ⲫⲩⲥⲓⲥ.\n\nⲔ̀ⲗⲏⲑⲓⲥⲁ ⲙⲏⲧⲏⲣ Ⲑⲉⲟⲩ: ⲡⲓⲟⲩⲣⲟ ⲙ̀ⲙⲏⲓ ⲛ̀ⲉ̀ⲧⲁⲍⲟⲛ: ⲕⲁⲣⲇⲓⲁⲥ ⲕⲉ ⲛⲉⲫⲣⲟⲩⲥ ⲇⲓⲕⲉⲟⲩ: ϧⲉⲛ ⲟⲩϩⲱⲃ ⲙ̀ⲡⲁⲣⲁⲇⲟⲝⲟⲛ.\n\nⲈⲙⲙⲁⲛⲟⲩⲏⲗ ⲫⲏⲉ̀ⲧⲁⲣⲉⲙⲁⲥϥ: ⲉⲑⲃⲉ ⲫⲁⲓ ⲁϥⲁ̀ⲣⲉϩ ⲉ̀ⲣⲟ: ⲧⲉⲛϩⲱⲥ ⲉ̀ⲣⲟϥ ⲧⲉⲛⲉⲣϩⲟⲩⲟ̀ ϭⲁⲥϥ: ⲕⲁⲑⲉ̀ⲕⲁⲥⲧⲏⲛ ⲡ̀ⲣⲱⲓ̀ ⲕⲉ ⲉⲥⲡⲉ̀ⲣⲁ.\n\nⲦⲉⲛϯⲱ̀ⲟⲩ ⲛⲉ ⲱ̀ ⲑⲏⲉⲧⲥⲙⲁⲙⲁⲧ: ϣⲁ ⲡⲓⲛⲓϥⲓ ⲛ̀ⲧⲉ ⲗⲉⲩⲧⲉⲟⲥ: ϫⲉ ⲁⲣⲉϫⲓⲙⲓ ⲅⲁⲣ ⲛ̀ⲟⲩϩ̀ⲙⲟⲧ: ϧⲁⲧⲉⲛ Ⲡⲉⲛⲟⲩϯ Ⲩⲓⲟⲥ Ⲑⲉⲟⲥ." },
    { language: 'english', text: "Begin with me today, by giving thanks to God, and present hymns and glory, to the Queen of perfection.\n\nSay “The Lord took pleasure, in you O refuge,” We say “What is your name, O you who are exalted above the earthly ones.”\n\nA heaven and throne on the earth, for you contained the Infinite One, and a good unexplainable Fountain, you have brought.\n\nWe call you a cherub, for you have carried the Intangible One, and we praise, with diligence that surpasses nature.\n\nYou were called the Mother of God, the righteous true King, the Inspector of hearts and the Right One, through a miraculous wonder.\n\nTherefore Immanuel whom you gave birth to, has kept you, we praise and exalt Him above all, every day morning and evening.\n\nWe glorify you O blessed one, until the last breath saying, \"You have found favor before, your God the Son of God.\"" },
    { language: 'arabic', text: "ابتدإوا معي اليوم بالشكر لله. وقدموا مديحا ومجدا لملكة الكمال.\n\nقولوا أن الرب قد سر بك أيتها الملجاء نقول ما هو اسمك يا من ارتفعت على الأرضيين.\n\nسماء وكرسي على الأرض لأن غير المحوي حويته وينبوعاً صالحاً غير موصوف أنبعته.\n\nشاروبيم ندعوك لان غير الملموس حملته ثم نسبح باجتهاد يفوق الطبيعة.\n\nدعيت أم الله الملك الحقيقي البار فاحص القلوب والكلي بامر معجز.\n\nعمانوئيل الذي ولدته من أجل هذا حفظك نسبحه ونزيده علوا كل يوم باكرا وعشية .\n\nنمجدك ايتها المباركة إلى النفس الأخير لأنك وجدت نعمة عند إلهك ابن الله." },
    { language: 'englishArabic', text: "Ibtadi'ou ma'i el-yawm bish-shukr lillah, wa qaddimou madeehan wa magdan li-malikat el-kamal.\n\nQoulou inna er-Rabb qad surra biki ayyatuha el-malga'. Naqoul ma huwa ismuki ya man irtafa'ti 'ala el-ardiyyeen?\n\nSama' wa kursi 'ala el-ard, li-anna ghayr el-muhwa hawayteeh, wa yanbou'an salihan ghayr mawsouf anba'teeh.\n\nSharoubeem nad'ouki li-anna ghayr el-malmous hamalteeh, thumma nusabbih bi-igtihad yafouq et-tabee'a.\n\nDu'eeti umm Allah el-malik el-haqeeqi el-barr, fahis el-quloub wal-kula, bi-amr mu'giz.\n\n'Emmanu'eel alladhi waladteehi, min agl hadha hafizaki; nusabbihuhu wa nazeeduhu 'ulouwwan kull yawm bakiran wa 'ashiyya.\n\nNumaggiduki ayyatuha el-mubaraka ila en-nafas el-akheer li-annaki wagadti ni'ma 'ind ilahik Ibn Allah." },
  ] },
  { id: "vp-the-seventh-bohairic-interpretation-a", title: "The Seventh Bohairic Interpretation A", versions: [
    { language: 'coptic', text: "Ⲥⲉⲙⲟⲩϯ ⲉ̀ⲣⲟ ϫⲉ ⲑ̀ⲙⲁⲩ ⲙ̀Ⲫϯ: ⲡⲓⲟⲩⲣⲟ ⲙ̀ⲙⲏⲓ ⲙⲉⲛⲉⲛⲥⲁ ⲑ̀ⲣⲉⲙⲁⲥϥ: ϧⲉⲛ ⲟⲩϣ̀ⲫⲏⲣⲓ ⲛⲉⲙⲟⲩϩⲟϯ: ⲧⲉⲛϩⲱⲥ ⲛⲁϥ ⲧⲉⲛⲉⲣϩⲟⲩⲟ̀ ϭⲁⲥϥ.\n\nⲈⲥⲧⲟⲃ ⲛ̀ϫⲉ ⲧⲉⲡⲁⲣⲑⲉⲛⲓⲁ: ⲱ̀ ⲡⲓⲉⲣⲫⲉⲓ ⲛ̀ⲗⲟⲅⲓⲕⲟⲛ: ϧⲉⲛ ⲟⲩⲛⲓϣϯ ⲛ̀ⲟⲓⲕⲟⲛⲟⲙⲓⲁ: ⲛⲉⲙ ⲟⲩϩⲱⲃ ⲙ̀ⲡⲁⲣⲁⲇⲟⲝⲟⲛ.\n\nⲈⲙⲙⲁⲛⲟⲩⲏⲗ ⲫⲏⲉ̀ⲧⲁⲣⲉⲙⲁⲥϥ: ⲉⲑⲃⲉ ⲫⲁⲓ ⲁϥⲁ̀ⲣⲉϩ ⲉ̀ⲣⲟ: ⲱ̀ⲥⲁⲩⲧⲟⲥ ⲧⲉⲛϩⲱⲥ ⲉ̀ⲣⲟϥ: ϧⲉⲛ ⲟⲩⲱ̀ⲟⲩ ⲛⲉⲙ ⲟⲩⲧⲁⲓⲟ.\n\nⲦⲉⲛϯⲱⲟⲩ ⲛⲉ ⲱ̀ ⲑⲏⲉ̀ⲧⲉⲛϩⲟⲧ: ⲛⲉⲙ ⲡⲓⲁⲅⲅⲉⲗⲟⲥ ⲛ̀ⲧⲉ ⲡⲓⲥ̀ⲙⲟⲩ: ϫⲉ ⲭⲉⲣⲉ ⲕⲉ ⲭⲁⲣⲓⲧⲱⲙⲉⲛⲏ ⲱ̀ ⲑⲏⲉⲑⲙⲉϩ ⲛ̀ϩⲙⲟⲧ: ⲟⲩⲟϩ Ⲡⲟ︦ⲥ︦ ϣⲟⲡ ⲛⲉⲙⲉ." },
    { language: 'english', text: "You are called the Mother of God, the true King and after you bore Him, with wonder and fear, we praise and exceedingly exalt Him.\n\nYour virginity is sealed, O speaking sanctuary, with great arrangement, and a miraculous wonder.\n\nTherefore Immanuel whom you gave birth to, has kept you, therefore we praise Him, with glory and honor.\n\nWe glorify you O trusted one, with the angel of blessing saying, \"Hail to you O full of grace, the Lord is with you.\"" },
    { language: 'arabic', text: "دعيت ام الله الملك الحقيقي وبعد ما ولدته بتعجب وخوف نسبحه ونزيده علوا.\n\nبتوليتك مختومة أيتها الهيكل الناطق بعظم تدبير وامر معجز.\n\nعمانوئيل الذي ولدته فلهذا حفظك. لذلك نسبحه بمجد وكرامة.\n\nنمجدك أيتها الأمينة قائلين مع ملاك البركة أفرحي أيتها الممتلئة نعمة . الرب معك." },
    { language: 'englishArabic', text: "Du'eeti umm Allah el-malik el-haqeeqi, wa ba'dama waladteehi bi-ta'aggub wa khawf nusabbihuhu wa nazeeduhu 'ulouwwan.\n\nBatouliyyatuki makhtouma ayyatuha el-haykal en-natiq, bi-'izam tadbeer wa amr mu'giz.\n\n'Emmanu'eel alladhi waladteehi fa-li-hadha hafizaki; li-dhalika nusabbihuhu bi-magd wa karama.\n\nNumaggiduki ayyatuha el-ameena qa'ileen ma'a malak el-baraka: ifrahi ayyatuha el-mumtali'a ni'ma, er-Rabb ma'aki." },
  ] },
  { id: "vp-the-seventh-bohairic-interpretation-b", title: "The Seventh Bohairic Interpretation B", versions: [
    { language: 'coptic', text: "Ⲏⲥⲁⲏ̀ⲁⲥ ⲁϥⲙⲟⲩϯ ⲉ̀ⲣⲟ: ⲱ̀ Ⲙⲁⲣⲓⲁ ϯⲟⲩⲣⲱ: ϫⲉ ⲑ̀ⲙⲁⲩ ⲙⲪϯ ⲡⲓⲣⲉϥϭ̀ⲣⲟ: ⲉ̀ⲧⲉ ⲫⲁⲓ ⲡⲉ Ⲉⲙⲙⲁⲛⲟⲩⲏⲗ Ⲡⲉⲛⲛⲟⲩϯ.\n\nϪⲉ ϩⲏⲡⲡⲉ ⲓⲥ ϯⲡⲁⲣⲑⲉⲛⲟⲥ: ⲉⲥⲉ̀ⲉⲣⲃⲟⲕⲓ ⲉⲥⲉ̀ⲙⲓⲥⲓ ⲛ̀ⲟⲩϣⲏⲣⲓ: ⲛ̀ⲑⲟϥ ⲡⲉ ⲛ̀ⲟⲩⲣⲟ ⲉⲧϫⲱⲣⲓ: ⲟⲩⲟϩ ⲛ̀ⲉ̀ⲝⲟⲩⲥⲓⲁⲥⲧⲏⲥ.\n\nⲀⲥⲙⲓⲥⲓ ⲙ̀ⲙⲟϥ ⲥⲱⲙⲁⲧⲓⲕⲟⲥ: ⲟⲩⲛⲟⲩϯ ⲙ̀ⲙⲏⲓ ⲛ̀ⲧⲉⲗⲓⲟⲥ: ⲭ̀ⲟⲩⲁⲃ ⲭ̀ⲟⲩⲁⲃ ⲁ̀ⲅⲓⲟⲥ: ϯⲧ̀ⲣⲓⲁⲥ ⲉⲧϫⲏⲕ ⲉ̀ⲃⲟⲗ.\n\nⲘⲁⲣⲉⲛϯⲱ̀ⲟⲩ ⲛ̀ϯⲁ̀ⲅⲓⲁ̀: ϧⲉⲛ ϩⲁⲛⲥ̀ⲙⲏ ⲛ̀ⲇⲟⲝⲟⲗⲟⲅⲓⲁ̀: ϫⲉ ⲭⲉⲣⲉ ⲣⲁϣⲓ ⲱ̀ Ⲙⲁⲣⲓⲁ: ⲟ̀ Ⲕⲩⲣⲓⲟⲥ ⲙⲉⲧⲁ ⲥⲟⲩ." },
    { language: 'english', text: "Isaiah called you, O Mary the Queen, the Mother of God the victorious, He is Immanuel our God.\n\nSaying “Behold the Virgin, will conceive and give birth to a Son, He is the mighty king, the ruler.”\n\nYou gave birth to Him in the flesh, a perfect and true God, holy holy holy, is the perfect Trinity.\n\nLet us glorify the saint, in voice of glorification saying, \"Hail to you rejoice O Mary, the Lord is with you.\"" },
    { language: 'arabic', text: "أشعياء دعاك يا مريم الملكة أم الله الغالب الذي هو عمانوئيل إلهنا.\n\nقائلاً هوذا العذراء تحبل وتلد ابنا وهو الملك القوى المتسلط.\n\nولدته جسدياً إله حقيقي كامل قدوس قدوس قدوس. الثالوث الكامل.\n\nفلنمجد القديسة بأصوات التمجيد قائلين السلام أفرحي يا مريم الرب معك." },
    { language: 'englishArabic', text: "Asha'ya da'aki ya Maryam el-malika umm Allah el-ghalib alladhi huwa 'Emmanu'eel ilahuna,\n\nQa'ilan: ha hiya el-'Adhra' tahbal wa talid ibnan, wa huwa el-malik el-qawiyy el-mutasallit.\n\nWaladteehi gasadiyyan, ilah haqeeqi kamil, quddous quddous quddous, eth-thalouth el-kamil.\n\nFal-numaggid el-qiddeesa bi-aswat et-tamgeed qa'ileen: es-salam, ifrahi ya Maryam er-Rabb ma'aki." },
  ] },
  { id: "vp-the-seventh-coptic-mo-aqap-interpretation", title: "The Seventh Coptic Mo-‘aqap Interpretation", versions: [
    { language: 'coptic', text: "Ⲏⲇⲉⲟⲥ ⲛⲓⲃⲉⲛ ⲛ̀ⲧⲉ ⲛⲓⲛⲟⲃⲓ: ⲛⲉⲙ ϩⲁⲛⲙⲏϣ ⲉⲩϩⲱⲟⲩ ⲛ̀ϩⲃⲏⲟⲩⲓ: ⲁⲩⲑⲱⲟⲩⲧⲥ ⲉ̀ⲣⲟⲓ ⲱ̀ ⲡⲓⲁⲑⲛⲟⲃⲓ: Ⲡⲁⲥⲱⲧⲏⲣ ϣⲉⲛϩⲏⲧ ϧⲁⲣⲟⲓ.\n\nⲠⲁⲥⲱⲧⲏⲣ ϣⲉⲛϩⲏⲧ ϧⲁⲣⲟⲓ: ϧⲉⲛ ⲛⲁⲛⲟⲃⲓ ⲙ̀ⲡⲉⲣⲧⲁⲕⲟⲓ: ⲁⲗⲗⲁ ⲱ̀ⲟⲩⲛ̀ϩⲏⲧ ⲉ̀ϫⲱⲓ: ⲙⲟⲓ ⲛⲏⲓ ⲛ̀ⲟⲩⲙⲉⲧⲁⲛⲟⲓⲁ.\n\nⲘⲟⲓ ⲛⲏⲓ ⲛ̀ⲟⲩⲙⲉⲧⲁⲛⲟⲓⲁ: ⲟⲩⲟϩ ⲥⲱⲗϫ ⲛ̀ⲛⲁⲁ̀ⲛⲟⲙⲓⲁ: ϩⲓⲧⲉⲛ ⲡⲓϣ̀ⲗⲏⲗ ⲛ̀ⲧⲉ Ⲙⲁⲣⲓⲁ: ϯϣⲉⲗⲉⲧ ⲙ̀ⲡⲁⲣⲁⲇⲟⲝⲟⲛ.\n\nϮϣⲉⲗⲉⲧ ⲙ̀ⲡⲁⲣⲁⲇⲟⲍⲟⲛ: ⲡⲓⲁ̀ϩⲟ ⲛ̀ⲧⲉ ⲛⲓⲁ̀ⲅⲁⲑⲟⲛ: ϫⲉ ⲁⲥⲙⲓⲥⲓ ⲙ̀Ⲫϯ ⲛⲁⲛ: ⲉ̀ⲧⲉ Ⲉⲙⲙⲁⲛⲟⲩⲏⲗ Ⲡⲉⲛⲟⲩⲣⲟ.\n\nⲈⲧⲉ Ⲉⲙⲙⲁⲛⲟⲩⲏⲗ Ⲡⲉⲛⲟⲩⲣⲟ: Ⲓⲏ︦ⲥ︦ Ⲡⲭ︦ⲥ︦ ⲡⲓⲣⲉϥⲑⲁⲙⲓⲟ: ⲁⲥⲙⲁⲥϥ ⲛ̀ϫⲉ ϯⲟⲩⲣⲱ: ⲉⲥⲧⲟⲃ ⲛ̀ϫⲉ ⲧⲉⲥⲡⲁⲣⲑⲉⲛⲓⲁ.\n\nⲈⲥⲧⲟⲃ ⲛ̀ϫⲉ ⲧⲉⲥⲡⲁⲣⲑⲉⲛⲓⲁ: ϫⲉ ⲁⲥⲙⲓⲥⲓ ⲁϭⲛⲉ ⲥⲩⲛⲟⲩⲥⲓⲁ: ⲛ̀ⲉⲙⲡ̀ϣⲁ ⲛ̀ϩⲁⲛⲇⲟⲝⲟⲗⲟⲅⲓⲁ: ϫⲉ ⲁⲥϣⲱⲡⲓ ⲛ̀ⲟⲩⲑ̀ⲣⲟⲛⲟⲥ.\n\nϪⲉ ⲁⲥϣⲱⲡⲓ ⲛ̀ⲟⲩⲑ̀ⲣⲟⲛⲟⲥ: ⲙ̀Ⲫϯ ⲡⲓⲇⲏⲙⲓⲟⲩⲣⲅⲟⲥ: ⲫⲱϥ ⲡⲉ ⲡⲓⲱ̀ⲟⲩ ⲛⲉⲙ ⲡⲓϩⲩⲙⲛⲟⲥ: ⲓⲥϫⲉⲛ ϯⲛⲟⲩ ⲛⲉⲙ ϣⲁ ⲉ̀ⲛⲉϩ.\n\nⲦⲉⲛϯⲱ̀ⲟⲩ ⲛⲉ ⲱ̀ ⲑⲏⲉ̀ⲧⲉⲛϩⲟⲧ: ⲉⲧϥⲁⲓ ϧⲁ ⲡⲓⲗⲟⲅⲟⲥ ⲛ̀ⲧⲉ Ⲫ̀ⲓⲱⲧ: ϫⲉ ⲭⲉⲣⲉ ⲑⲏⲉⲑⲙⲉϩ ⲛ̀ϩ̀ⲙⲟⲧ: ⲟⲩⲟϩ Ⲡⲟ︦ⲥ︦ ϣⲟⲡ ⲛⲉⲙⲉ." },
    { language: 'english', text: "Every enjoyment of sin, and many bad works have come upon me, O You who are without sin, my Savior show me compassion.\n\nMy Savior show me compassion, and do not destroy me in my sins, be patient with me, grant me repentance.\n\nGrant me repentance, cleanse me from all my iniquities, through the prayers of Mary, the paradoxical bride.\n\nThe glorified bride, the treasure of goodness, she gave birth to God for us, Immanuel our King.\n\nImmanuel our King, Jesus Christ the Creator, was born of the Queen, and her virginity was sealed.\n\nAnd her virginity was sealed, for she gave birth without seed of man, she is worthy of glorification, for she became the throne.\n\nFor she became the throne, of God the Creator, to whom all glory and praise is due, now and unto the ages.\n\nWe glorify you O faithful one, who carried the Word of the Father, \"Hail to you O full of grace, the Lord is with you.\"" },
    { language: 'arabic', text: "كل لذات الخطية وأعمال كثيرة رديئة أجتمعت علىً يا من بغير خطية يا مخلصي تحنن على.\n\nيا مخلصي تحنن على ولا تهلكني بخطاياي لكن تمهل علي وأعطني توبة.\n\nاعطني توبة وامسح آثامي بصلوات مريم العروسة العروس فائقة الوصف.\n\nالعروسة الممجدة: كنز الخيرات لأنها ولدت لنا الله الذي هو عمانوئيل ملكنا.\n\nالذي هو عمانوئيل ملكنا: يسوع المسيح الخالق ولدته الملكة وبتوليتها مختومة.\n\nوبتوليتها مختومة: لأنها ولدت بغير مباضعة تستحق التمجيد لأنها صارت كرسيا.\n\nلأنها صارت كرسيا: الله الخالق له المجد والتسبيح من الأن وإلى الأبد.\n\nنمجدك ايتها الامينة. الحاملة كلمة الأب قائلين إفرحي يا ممتلئة نعمة. الرب معك" },
    { language: 'englishArabic', text: "Kull ladhdhat el-khatiyya wa a'mal katheera radee'a igtama'at 'alayya; ya man bi-ghayr khatiyya, ya mukhallisi, tahannan 'alayya.\n\nYa mukhallisi tahannan 'alayya, wa la tuhlikni bi-khatayaya, lakin tamahhal 'alayya wa a'tini tawba.\n\nA'tini tawba wamsah athami bi-salawat Maryam el-'arousa, el-'arous fa'iqat el-wasf.\n\nEl-'arousa el-mumaggada: kanz el-khayrat, li-annaha waladat lana Allah alladhi huwa 'Emmanu'eel malikuna.\n\nAlladhi huwa 'Emmanu'eel malikuna: Yasou' el-Maseeh el-khaliq, waladathu el-malika wa batouliyyatuha makhtouma.\n\nWa batouliyyatuha makhtouma: li-annaha waladat bi-ghayr mubada'a; tastahiqq et-tamgeed li-annaha sarat kursiyyan.\n\nLi-annaha sarat kursiyyan: lillah el-khaliq, lahu el-magd wat-tasbeeh min el-an wa ila el-abad.\n\nNumaggiduki ayyatuha el-ameena, el-hamila kalimat el-Ab, qa'ileen: ifrahi ya mumtali'a ni'ma, er-Rabb ma'aki." },
  ] },
  { id: "vp-the-seventh-egyptian-interpretation", title: "The Seventh Egyptian Interpretation", versions: [
    { language: 'coptic', text: "Ⲁⲩⲙⲟⲩϯ ⲉ̀ⲣⲟ ϫⲉ ⲑ̀ⲙⲁⲩ ⲙ̀Ⲫⲛⲟⲩϯ: ⲱ̀ Ⲙⲁⲣⲓⲁ ϯⲡⲁⲣⲑⲉⲛⲟⲥ: ⲙⲉⲛⲉⲛⲥⲁ ⲑ̀ⲣⲉⲙⲓⲥⲓ ⲛⲁⲛ ⲙ̀Ⲫⲛⲟⲩϯ: ⲉⲥⲧⲟⲃ ⲛ̀ϫⲉ ⲧⲉⲡⲁⲣⲑⲉⲛⲓⲁ.\n\nⲀⲩⲙⲟⲩϯ ⲉ̀ⲣⲟ ϫⲉ ⲑ̀ⲙⲁⲩ ⲙ̀Ⲫⲛⲟⲩϯ: ϯϩⲉⲗⲡⲓⲥ ⲛ̀ⲧⲉ ⲡⲉⲛⲟⲩϫⲁⲓ: ⲁϥϣⲟⲡ ⲉ̀ⲣⲟ ⲛ̀ϯⲙⲉⲑⲛⲟⲩϯ: ⲡⲁⲓϩⲱⲃ ⲛ̀ϣ̀ⲫⲏⲣⲓ ⲟⲩⲡⲉ ⲫⲁⲓ.\n\nⲀⲩⲙⲟⲩϯ ⲉ̀ⲣⲟ ϫⲉ ⲑ̀ⲙⲁⲩ ⲙ̀Ⲫⲛⲟⲩϯ: ⲡ̀ϣⲟⲩϣⲟⲩ ⲙ̀ⲡⲉⲛⲅⲉⲛⲟⲥ: ϯϩⲉⲗⲡⲓⲥ ⲛ̀ⲧⲉ ⲛⲉⲛⲓⲟϯ: Ⲙⲁⲣⲓⲁ ϯⲥⲁⲃⲏ ⲙ̀ⲡⲁⲣⲑⲉⲛⲟⲥ.\n\nⲀⲩⲙⲟⲩϯ ⲉ̀ⲣⲟ ϫⲉ ⲑ̀ⲙⲁⲩ ⲙ̀Ⲫⲛⲟⲩϯ: ⲧⲉⲛϯⲱ̀ⲟⲩ ⲛⲉ ⲱ̀ ⲡⲓⲱ̀ⲛⲓ ⲙ̀ⲙⲏⲓ: ⲉⲛϫⲱ ⲙ̀ⲙⲟⲥ ϧⲉⲛ ⲟⲩⲙⲉⲧⲁⲧϩⲟϯ: ϫⲉ ⲭⲉⲣⲉ ⲕⲉ ⲭⲁⲣⲓⲧⲟⲩⲙⲉⲛⲏ.\n\nⲀⲩⲙⲟⲩϯ ⲉ̀ⲣⲟ ϫⲉ ⲑ̀ⲙⲁⲩ ⲙ̀Ⲫⲛⲟⲩϯ: ϩⲏⲧ ⲛⲓⲃⲉⲛ ⲁⲩⲣⲁϣⲓ ⲁⲩϯⲛⲟⲙϯ: ϧⲉⲛ ⲡ̀ϫⲓⲛⲉⲣⲣⲱⲙⲓ: ⲙ̀ⲫ̀ⲣⲁⲛ ⲛ̀Ⲉⲙⲙⲁⲛⲟⲩⲏⲗ Ⲡⲉⲛⲛⲟⲩϯ.\n\nⲀⲩⲙⲟⲩϯ ⲉ̀ⲣⲟ ϫⲉ ⲑ̀ⲙⲁⲩ ⲙ̀Ⲫⲛⲟⲩϯ: ⲱ̀ ϯϣⲉⲗⲉⲧ ⲱ̀ ϯⲟⲩⲣⲱ: ϫⲉ ⲁϥⲛⲁϩⲙⲉⲛ ⲉ̀ⲃⲟⲗ ϩⲓⲧⲟϯ: ϧⲉⲛ ⲡ̀ϫⲓⲛⲓ̀ ⲙ̀ⲡⲉϥϫⲓⲛⲙⲓⲥⲓ ⲛ̀ⲣⲉϥϭ̀ⲣⲟ.\n\nⲀⲩⲙⲟⲩϯ ⲉ̀ⲣⲟ ϫⲉ ⲑ̀ⲙⲁⲩ ⲙ̀Ⲫⲛⲟⲩϯ: ⲟⲩⲙⲁ ⲛ̀ϣⲱⲡⲓ ⲛ̀ϣⲟⲩϣⲟⲩ ⲙ̀ⲡⲓⲕⲟⲥⲙⲟⲥ ⲧⲏⲣϥ: ϫⲉ ⲛ̀ⲑⲟϥ ⲡⲉ Ⲫⲛⲟⲩϯ ⲛ̀ⲧⲉ ⲛⲉⲛⲓⲟϯ: ⲧⲉⲛⲟⲩⲉϩ ⲛ̀ⲥⲱϥ ϧⲉⲛ ⲡⲉⲛϩⲏⲧ ⲧⲏⲣϥ.\n\nⲈⲑⲃⲉ ⲫⲁⲓ ⲧⲉⲛϩⲱⲥ ⲉ̀Ⲫⲛⲟⲩϯ: ⲫⲏⲉ̀ⲧⲁϥϭⲓⲥⲁⲣⲝ ⲉ̀ⲃⲟⲗ ⲛ̀ϧⲏϯ: ⲁϥⲉⲣⲣⲱⲙⲓ ⲙ̀ⲡⲉⲛⲣⲏϯ: ϣⲁⲧⲉⲛ ⲫ̀ⲛⲟⲃⲓ ⲙ̀ⲙⲁⲩⲁⲧϥ." },
    { language: 'english', text: "You are called the Mother of God, O Virgin Mary, and after you gave birth to God for us, your virginity was sealed.\n\nYou are called the Mother of God, the hope of our salvation, you accepted unto yourself the divinity, what is this wondrous matter?\n\nYou are called the Mother of God, the pride of our race, the hope of our fathers, the wise Virgin Mary.\n\nYou are called the Mother of God, we glorify you O true stone, proclaiming without fear, “Hail to you O full of grace.”\n\nYou are called the Mother of God, all the hearts rejoiced and were comforted, through the Incarnation, of the name of Immanuel our Lord.\n\nYou are called the Mother of God, O Bride and Queen, for He delivered us through you, by the coming of His victorious Birth.\n\nYou are called the Mother of God, the dwelling of the pride of the whole world, for He is the God of our fathers, we follow Him with all our hearts.\n\nTherefore we praise God, who was incarnate of you, and became man like us, except for sin alone." },
    { language: 'arabic', text: "دُعيتِ اُم الله، يا مريم العذراء، ومن بعدما ولدتِ لنا الله، بتوليتكِ مختومة.\n\nدُعيتِ اُم الله، يا رجاء خلاصنا، قبلتِ إليكِ اللاهوت، ما هو هذا الأمر العجيب.\n\nدُعيتِ اُم الله، يا فخر جنسنا، يا رجاء آبائنا، مريم العذراء الحكيمة.\n\nدُعيتِ اُم الله، نمجدكِ أيتها الحجر الكريم، قائلين بغير خوف، \"إفرحي يا ممتلئة نعمة.\"\n\nدُعيتِ اُم الله، كل القلوب تفرح، وتتعزَّى بتأنس، إسم عمانوئيل إلهنا.\n\nدُعيتِ اُم الله، أيتها العروس والملكة، لأنه نجانا من قِبَلكِ، بأتيان ميلاده الغالب.\n\nدُعيتِ اُم الله، مسكن فخر كل العالم، لأنه هو إله آبائنا، نتبعه بكل قلبنا.\n\nفلهذا نسبِّح الله، الذي تجسَّد منكِ، وصار إنساناً مثلنا، ما خلا الخطية وحدها." },
    { language: 'englishArabic', text: "Du'eeti umm Allah, ya Maryam el-'Adhra', wa min ba'dama waladti lana Allah, batouliyyatuki makhtouma.\n\nDu'eeti umm Allah, ya raga' khalasina, qabilti ilayki el-lahout, ma huwa hadha el-amr el-'ageeb?\n\nDu'eeti umm Allah, ya fakhr ginsina, ya raga' aba'ina, Maryam el-'Adhra' el-hakeema.\n\nDu'eeti umm Allah, numaggiduki ayyatuha el-hagar el-kareem, qa'ileen bi-ghayr khawf: \"Ifrahi ya mumtali'a ni'ma.\"\n\nDu'eeti umm Allah, kull el-quloub tafrah, wa tata'azza bi-ta'annus, ism 'Emmanu'eel ilahina.\n\nDu'eeti umm Allah, ayyatuha el-'arous wal-malika, li-annahu naggana min qibaliki, bi-ityan meeladihi el-ghalib.\n\nDu'eeti umm Allah, maskan fakhr kull el-'alam, li-annahu huwa ilah aba'ina, nattabi'uhu bi-kull qalbina.\n\nFa-li-hadha nusabbih Allah, alladhi tagassada minki, wa sara insanan mithlana, ma khala el-khatiyya wahdaha." },
  ] },
  { id: "vp-the-seventh-sahidic-interpretation", title: "The Seventh Sahidic Interpretation", versions: [
    { language: 'coptic', text: "Ⲏⲥⲁⲏ̀ⲁⲥ ⲫⲁ ⲡⲓⲛⲓϣϯ ⲛ̀ϧ̀ⲣⲱⲟⲩ: ⲃⲱⲗ ⲛⲁⲛ ⲉ̀ⲃⲟⲗ ⲛ̀ⲛⲉⲕⲡ̀ⲣⲟⲫⲏⲧⲓⲁ: ⲉⲑⲃⲉ ⲑⲏⲉ̀ⲧⲁⲥϫⲱⲗϩ ⲙ̀ⲡⲓⲱ̀ⲟⲩ: ⲑ̀ⲙⲁⲩ ⲙ̀ⲡⲓⲧⲟⲩⲃⲟ Ⲙⲁⲣⲓⲁ.\n\nⲈⲙⲙⲁⲛⲟⲩⲏⲗ ⲁⲥⲙⲁⲥϥ ⲛⲁⲛ: ⲁϭⲛⲉ ⲥ̀ⲡⲉⲣⲙⲁ ⲟⲩⲟϩ ⲛ̀ⲁⲧⲅⲁⲙⲟⲥ: ⲁϥϣⲱⲡⲓ ⲛ̀ϫⲉ Ⲫⲛⲟⲩϯ ⲛⲉⲙⲁⲛ: ⲟⲩⲟϩ ⲁϥⲥⲱϯ ⲙ̀ⲡⲓⲕⲟⲥⲙⲟⲥ.\n\nⲀⲣⲉϫ̀ⲫⲟϥ ϩⲓⲧⲉⲛ ⲡ̀ⲣⲟⲫⲏⲧⲓⲁ: ϧⲉⲛ ⲟⲩϩⲱⲃ ⲙ̀ⲡⲁⲣⲁⲇⲟⲝⲟⲛ: ⲉⲥⲧⲟⲃ ⲛ̀ϫⲉ ⲧⲉⲡⲁⲣⲑⲉⲛⲓⲁ: ⲡⲓⲕⲩⲣⲓⲟⲥ ⲉϥⲟⲓ ⲙ̀ⲡⲁⲣⲁⲇⲟⲝⲟⲛ.\n\nϦⲉⲛ ⲟⲩϫⲟⲙ ⲁϥⲁ̀ⲣⲉϩ ⲉ̀ⲣⲟⲛ: ϧⲉⲛ ⲡⲉϥⲛⲁϩϯ ⲉⲧⲥⲟⲩⲧⲱⲛ: ⲟⲩⲟϩ ⲡ̀ⲥⲟϭⲛⲓ ⲛ̀ⲛⲓⲇⲉⲙⲱⲛ: ⲁϥⲕⲱⲣϥ ⲉ̀ⲃⲟⲗ ϩⲁⲣⲟⲛ.\n\nⲈⲑⲃⲉ ⲫⲁⲓ ⲧⲉⲛϯⲱ̀ⲟⲩ ⲛⲉ: ⲉⲛⲱϣ ⲉ̀ⲃⲟⲗ ⲛⲉⲙ Ⲅⲁⲃⲣⲓⲏⲗ: ϫⲉ ⲭⲉⲣⲉ ⲕⲉ ⲭⲁⲣⲓⲧⲱⲙⲉⲛⲏ: Ⲙⲁⲣⲓⲁ ⲑ̀ⲙⲁⲩ ⲛ̀Ⲉⲙⲙⲁⲛⲟⲩⲏⲗ." },
    { language: 'english', text: "O Isaiah with the great voice, interpreted for us your prophecy, about the one who was filled with glory, Mary the Mother of purity.\n\nShe bore for us Immanuel, without seed or marriage, the Lord dwelt among us, and saved the world.\n\nYou gave birth to Him with prophecy, through a miraculous matter, your virginity is sealed, and the glorified Lord.\n\nWith power has kept us, in His upright faith, He trampled for us, the council of the demons.\n\nTherefore we glorify you, proclaiming with Gabriel, “Hail to you O full of grace, Mary the Mother of Immanuel.”" },
    { language: 'arabic', text: "يا أشعياء صاحب الصوت العظيم، فسَّرْ لنا نبواتك، لأجل التي إشتملت بالمجد، مريم اُم الطهارة.\n\nولدَتْ لنا عمانوئيل، بغير زرع وبغير زواج، وإن الله حل معنا، وخلَّص العالم.\n\nولدتِه بالنبوة، بأمرٍ معجز، وبتوليتكِ مختومة، والرب الممجد.\n\nبقوة قد حفظنا، بأمانته المستقيمة، وأبطل عنا، مشورة الشياطين.\n\nفلهذا نُمجدكِ، ونصرخ مع غبريال قائلين،\"السلام لكِ يا ممتلئة نعمة، مريم اُم عمانوئيل.\"" },
    { language: 'englishArabic', text: "Ya Asha'ya sahib es-sawt el-'azeem, fassir lana nubouwatak, li-agl allati ishtamalat bil-magd, Maryam umm et-tahara.\n\nWaladat lana 'Emmanu'eel, bi-ghayr zar' wa bi-ghayr zawag, wa inna Allah halla ma'ana, wa khallasa el-'alam.\n\nWaladteehi bin-nubouwa, bi-amrin mu'giz, wa batouliyyatuki makhtouma, war-Rabb el-mumaggad.\n\nBi-quwwa qad hafizana, bi-amanatihi el-mustaqeema, wa abtala 'anna, mashourat esh-shayateen.\n\nFa-li-hadha numaggiduki, wa nasrukh ma'a Ghubriyal qa'ileen: \"Es-salam laki ya mumtali'a ni'ma, Maryam umm 'Emmanu'eel.\"" },
  ] },
  { id: "vp-the-seventh-hymn-of-abou-el-saad-of-aboutig", title: "The Seventh Hymn of Abou El-Saad of Aboutig", versions: [
    { language: 'english', text: "You were called the Mother of God / no human tongue can utter trivially / of the living Son of God’s mystery / who is your Son Immanuel.\n\nYou bore Him, while a virgin / that the prophets’ sayings may be fulfilled / For they did not speak anything / except that which is symbolic.\n\nImmanuel whom you bore / without corruption, in purity / He preferred you above all His chosen / for you were selected and chosen.\n\nYou were likened to heaven, His throne / how many are your symbols and signs / like the pot and manna hidden in it / the censer, ark and lampstand.\n\nThe prophets and wise men / realized that the Lord God will come to us / and abolish the evil plots / and save us from destruction.\n\nHail to you O mother of mercy / we are your beloved pray acknowledge us / blessed are you O full of grace / before your Son intercede for us." },
    { language: 'arabic', text: "دعيت أم الله وأي / لسان بشري ينطق بقليل / من أسرار إبن الله الحي / وهو إبنك عمانوئيل.\n\nولدته وأنت بتول لكي / يتم قول الأنبياء وما قيل / لأنهم لم يقولوا شئ / إلا وله معني وتأويل.\n\nعمانوئيل الذي ولدته / من غير فساد بل بطهارة / وفضَّلك عن مختاريه / لأنك مصطفاه ومختاره.\n\nتشبهت بالسماء كرسيه / وكم لك من رمز وإشارة / كالقسط والمن مخفي فيه / شورية وتابوت ومنارة.\n\nأهل النبوة و الحكمة / علموا أن الرب الإله يأتينا / و يهلك مؤامرة الأثمة / و من الهلاك ينجينا.\n\nالسلام لك يا ام الرحمة / نحن عبيدك جيرينا / طوباكِ يا مملوُة نعمة / عند ابنك الحبيب اشفعي فينا." },
    { language: 'englishArabic', text: "Du'eeti umm Allah, wa ayy / lisan bashari yantiq bi-qaleel / min asrar Ibn Allah el-hayy / wa huwa ibnuki 'Emmanu'eel.\n\nWaladteehi wa anti batoul likay / yatimm qawl el-anbiya' wa ma qeel / li-annahum lam yaqoulou shay' / illa wa lahu ma'na wa ta'weel.\n\n'Emmanu'eel alladhi waladteeh / min ghayr fasad bal bi-tahara / wa faddalaki 'an mukhtareeh / li-annaki mustafahu wa mukhtarah.\n\nTashabbahti bis-sama' kursiyyih / wa kam laki min ramz wa ishara / kal-qist wal-mann makhfi feeh / shouriyya wa tabouth wa manara.\n\nAhl en-nubouwa wal-hikma / 'alimou anna er-Rabb el-Ilah ya'teena / wa yuhlik mu'amarat el-athama / wa min el-halak yungeena.\n\nEs-salam laki ya umm er-rahma / nahnu 'abeeduki geereena / toubaki ya mamlou'at ni'ma / 'ind ibniki el-habeeb ishfa'i feena." },
  ] },
  { id: "vp-seventh-hymn-of-cantor-gabriel-of-qay-a", title: "Seventh Hymn of Cantor Gabriel of Qay A", versions: [
    { language: 'english', text: "You were called a mother to your Creator / what tongue can utter of / your explanation and splendor / and your acceptance of the great mystery.\n\nAnd your acceptance of the great mystery / He who sits above the throne / has chosen your goodness, O Mary / according to the word of the psalmist.\n\nAccording to the word of the psalmist / David the king of Israel / prophesied about the birth of Jesus / as Gabriel announced to you.\n\nAs Gabriel announced to you / the great archangel / saying the great King shall come / the Son of God, the Word.\n\nThe Son of God, the Word / Immanuel whom you bore / of your womb O first-born bride / you carried Him in your arms.\n\nYou carried Him in your arms / you were likened to the cherubim / you raised him as a child / He nursed from you.\n\nHe nursed from you / whom heaven and earth cannot contain / patient God, merciful Lord / humbled Himself and took a servant’s form.\n\nHumbled Himself and took a servant’s form / He completed the teachings of the Law / and was called the second Adam / He restored the first Adam to paradise.\n\nHe restored the first Adam to paradise / after he was cast out / your Son Christ restored him / to his rank once again.\n\nTo his rank once again / he was hailing with joy and rejoicing / delight, pleasure and happiness / hail to you O lamp of Light.\n\nHail to you O lamp of Light / whom the Lord desired for / O balm for all wounded / hail to you and hail unto you.\n\nHail to you and hail unto you, we ask you O Mother of the Beloved, grant us to be in your fathers’ dwellings, Abraham Isaac and Jacob." },
    { language: 'arabic', text: "دعيت أُماً لمن أنشاكِ / وأى لسان يقدر يتكلم / بوصفك و شرف معناك / وقبولك للسر الأعظم.\n\nوقبولك للسر الأعظم / الجالس فوق بي اثرونوس / قد اختار حسنك يا مريم / كاتا إبصاجي إمبي هيمنودوس.\n\nكاتا إبصاجي إمبي هيمنودوس / دافيد إب اُؤرو امبيسرائيل / تنبأ عن ميلاد إيسوس / كما بشرك جبرائيل.\n\nكما بشرك جبرائيل / بينيشتي إن أرشي انجيلوس / وقال سوف يأتي الملك المتعال / إبشيري إم افنوتي بي لوغوس.\n\nإبشيري إم افنوتي بي لوغوس / عمانوئيل الذي ولدته / من أحشاك يا بكر وعروس / وفوق ذراعيك حملته.\n\nوفوق ذراعيك حملته / وتشبهت بالكاروبيم / وكمثل غلام قد ربيتيه / رضع ثدييك كالفطيم.\n\nرضع ثدييك كالفطيم / من لا تسعه السماء والارض / إله رؤوف ورب رحيم / تواضع وأخذ شكل العبد.\n\nتواضع و أخذ شكل العبد / وأكمل تعليم الناموس / وسمي آدم الثاني و رد / آدم الاول إلي الفردوس.\n\nآدم الاول إلي الفردوس / من بعد أن كان مطرود مدحور / رده ابنك بي خريستوس / إلي رتبته دفعة أخري.\n\nإلي رتبته دفعة أخرى / وصار يتهني بفرح و سرور / وبهجة و نعيم و مسرة / السلام لك يا مصباح النور.\n\nالسلام لك يا مصباح النور / يا من اشتياق الرب إليك / يا مرهم لدوا المكسور / السلام لكِ ثم السلام عليك.\n\nالسلام لكِ ثم السلام إليك، ونسألك يا أم المحبوب، ان تحظينا في مظال اباءك، ابراهيم واسحق ويعقوب." },
    { language: 'englishArabic', text: "Du'eeti umman li-man ansha'aki / wa ayy lisan yaqdir yatakallam / bi-wasfiki wa sharaf ma'naki / wa qabouliki lis-sirr el-a'zam.\n\nWa qabouliki lis-sirr el-a'zam / el-galis fawq pi-ethronos / qad ikhtara husnaki ya Maryam / kata epsaji empi-humnōdos.\n\nKata epsaji empi-humnōdos / Dauid ep-ouro empi-Israēl / tanabba'a 'an meelad Iēsous / kama bashsharaki Gibra'eel.\n\nKama bashsharaki Gibra'eel / Pinishti en-arkhē-aggelos / wa qala sawfa ya'ti el-malik el-muta'al / Epshēri em-Efnouti pi-Logos.\n\nEpshēri em-Efnouti pi-Logos / 'Emmanu'eel alladhi waladteeh / min ahsha'iki ya bikr wa 'arous / wa fawq dhira'ayki hamalteeh.\n\nWa fawq dhira'ayki hamalteeh / wa tashabbahti bil-Kharoubeem / wa ka-mithl ghulam qad rabbayteeh / radi'a thadyayki kal-fateem.\n\nRadi'a thadyayki kal-fateem / man la tasa'uhu es-sama' wal-ard / ilah ra'ouf wa Rabb raheem / tawada'a wa akhadha shakl el-'abd.\n\nTawada'a wa akhadha shakl el-'abd / wa akmala ta'leem en-namous / wa summiya Adam eth-thani wa radd / Adam el-awwal ila el-firdaws.\n\nAdam el-awwal ila el-firdaws / min ba'd an kana matroud madhour / raddahu ibnuki Pikhristos / ila rutbatihi daf'a ukhra.\n\nIla rutbatihi daf'a ukhra / wa sara yatahanna bi-farah wa sourour / wa bahga wa na'eem wa masarra / es-salam laki ya misbah en-nour.\n\nEs-salam laki ya misbah en-nour / ya man ishtiyaq er-Rabb ilayki / ya marham li-dawa' el-maksour / es-salam laki thumma es-salam 'alayki.\n\nEs-salam laki thumma es-salam ilayki, wa nas'aluki ya umm el-mahboub, an tahzeena fi mazall aba'ik, Ibraheem wa Ishaq wa Ya'qoub." },
  ] },
  { id: "vp-the-seventh-hymn-of-cantor-gabriel-of-qay-b", title: "The Seventh Hymn of Cantor Gabriel of Qay B", versions: [
    { language: 'english', text: "You are called the Mother of the holy God, O Mary the adornment of first-born, your womb carried the Holy One, our Master the mighty King.\n\nAs our father David the righteous, chanted in the psalm, about the dwelling of my Lord Jesus, in your womb O purity of the pure ones.\n\nThe angel brought you the good news, about the chosen Birth, he said “You will carry the holy King, He will save Adam from the hot fire.\n\nThe Son of God the Logos, you will give birth to Him, He will be called Immanuel Jesus, the Lord with us the mighty King.”\n\nAll the ranks and orders, tremble from His light, the four incorporeal creatures, carrying His glorified throne with honor.\n\nMary the wise Virgin, carried in her womb the coal of fire, that He may loosen the chains of the world, and deliver us from the deceiver’s snare.\n\nHail to you O Mother of our Savior, we ask you O pure Virgin, to ask the Lord to bring us, to the harbor in peace." },
    { language: 'arabic', text: "دُعيتِ اُم الله القدوس، يا مريم يا زين الأبكار، حَمَلتْ أحشائكِ بى آجيوس، سيدنا الملك الجبار.\n\nكما رتَّل في إبصالموس، أبونا الأب داود البار، من أجل حلول باشويس إيسوس، في أحشائكِ يا طُهر الأطهار.\n\nبشركِ بي أنجيلوس، من أجل الميلاد المختار، قال \"سوف تلدين الملك القدوس، ويعتق آدم من حر النار.\n\nإبشيري إميفنوني بي لوغوس، سوف تلدينه من أحشائكِ إجهار، يسمى عمانوئيل إيسوس، إبشويس نيميه الملك الجبار.\"\n\nكل الطغمات وكل الطقوس، يرتعدون من نوره إجهار، بي إفتو إن ذوؤن إن آسوماتوس، حاملين كرسي مجده بوقار.\n\nماريا تي ساڤي إمبارثينوس، حملَتْ في أحشاءها جمر النار، ليحل وثاقات بي كوزموس، وينجينا من كيد المكار.\n\nالسلام لكِ يا اُم مخلصنا، ونسألكِ يا بكر نقية، تسألي الرب أن يوصِّلنا، إلى الميناء بطمأنينة." },
    { language: 'englishArabic', text: "Du'eeti umm Allah el-quddous, ya Maryam ya zayn el-abkar, hamalat ahsha'uki Pi-agios, sayyidana el-malik el-gabbar.\n\nKama rattala fi epsalmos, abouna el-ab Dawoud el-barr, min agl houloul pa-Tshois Iēsous, fi ahsha'iki ya tuhr el-at-har.\n\nBashsharaki Pi-aggelos, min agl el-meelad el-mukhtar, qala: \"Sawfa talideena el-malik el-quddous, wa yu'tiq Adam min harr en-nar.\n\nEpshēri em-Efnouti pi-Logos, sawfa talideenahu min ahsha'iki ighar, yusamma 'Emmanu'eel Iēsous, Eptshois nimmeh el-malik el-gabbar.\"\n\nKull et-tughmat wa kull et-touqous, yarta'idoun min nourihi ighar, pi-eftou en-zōon en-asōmatos, hamileen kursi magdihi bi-waqar.\n\nMaria ti-savē emparthenos, hamalat fi ahsha'iha gamr en-nar, li-yahull withaqat pikosmos, wa yungeena min kayd el-makkar.\n\nEs-salam laki ya umm mukhallisina, wa nas'aluki ya bikr naqiyya, tas'ali er-Rabb an yuwassilana, ila el-meena' bi-tuma'neena." },
  ] },
  { id: "vp-the-seventh-hymn-of-cantor-gabriel-of-qay-c", title: "The Seventh Hymn of Cantor Gabriel of Qay C", versions: [
    { language: 'english', text: "You are called O chaste Virgin, the Mother of the holy God of gods, and which tongue can speak of, the Economy of Christ.\n\nAs a Child carried in your womb, and also seated on His throne, and what understanding and mind can, comprehend this tangible Mystery.\n\nComprehend this tangible Mystery, He who sits upon the cherubim, was in the womb of the first-born girl and Bride, upon your hands with great glory.\n\nCome now O people of Jesus, let us bless the daughter of Joachim, proclaiming and saying, “Entreat for us O Mary.”\n\nEntreat for us O Mary, the one God honored and giving, distinguished you with mercy, He chose you for the dwelling of the Word.\n\nWithout your Son we would not see grace, He erased the darkness for us, and we proclaim with a strong voice, “Hail to you O Mother of mercy.”\n\nHail to you O Mother of mercy, blessed are you O full of grace, the Lady of us all Mary, through her prayers and intercessions." },
    { language: 'arabic', text: "دُعيتِ يا بكر وبتول، اُم إله الآلهة القدوس، وأيْ لسان ينطق ويقول، بقليل من تدبير بيخريستوس.\n\nكطفل جنين في أحشائكِ محمول، وجالس فوق بيف إثرونوس، وأيْ أفهام وأيْ عقول، تحوي هذا السر المحسوس.\n\nتحوي هذا السر المحسوس، الجالس فوق الكاروبيم، في أحشاء فتاة بكر وعروس، على ذراعيكِ بمجد عظيم.\n\nتعالوا بنا يا شعب إيسوس، نُطوِّب إبنة يواقيم، إن أوش إيڤول إنجو إمموس، جيرينا يا م ر ي م.\n\nجيرينا يا م ر ي م، يا مَنْ خصكِ بالرحمة، إله واحد مُنعِم وكريم، وإختاركِ لحلول الكلمة.\n\nلولا إبنكِ ما رأينا نعيم، ولا إنكشفت عنا الظلمة، ونحن نصيح بصوت عظيم، \"السلام لكِ يا اُم الرحمة.\"\n\nالسلام لكِ يا اُم الرحمة، طوباكِ يا ممتلئة نعمة، أووتين شويس إننيب ماريا، هيتين نيس طوڤه نيم نيس إبريسڤيِّا." },
    { language: 'englishArabic', text: "Du'eeti ya bikr wa batoul, umm ilah el-aliha el-quddous, wa ayy lisan yantiq wa yaqoul, bi-qaleel min tadbeer Pikhristos.\n\nKa-tifl ganeen fi ahsha'iki mahmoul, wa galis fawq pef-ethronos, wa ayy afham wa ayy 'uqoul, tahwi hadha es-sirr el-mahsous.\n\nTahwi hadha es-sirr el-mahsous, el-galis fawq el-Kharoubeem, fi ahsha' fatat bikr wa 'arous, 'ala dhira'ayki bi-magd 'azeem.\n\nTa'alou bina ya sha'b Iēsous, nutawwib ibnat Yowakeem, en-oush evol en-jō emmos: geereena ya M-R-Y-M.\n\nGeereena ya M-R-Y-M, ya man khassaki bir-rahma, ilah wahid mun'im wa kareem, wakhtaraki li-houloul el-Kalima.\n\nLawla ibnuki ma ra'ayna na'eem, wa la inkashafat 'anna ez-zulma, wa nahnu nasee'h bi-sawt 'azeem: \"Es-salam laki ya umm er-rahma.\"\n\nEs-salam laki ya umm er-rahma, toubaki ya mumtali'a ni'ma, Ouoh ten-tshois ennēb Maria, hiten nes-tovh nem nes-epresvia." },
  ] },
  { id: "vp-the-seventh-hymn-of-pope-abba-markos-viii", title: "The Seventh Hymn of Pope Abba Markos VIII", versions: [
    { language: 'english', text: "You are called the Mother of God our Creator, O Mary the daughter of Zion, He was incarnate of you and He saved us, from the captivity of the Devil.\n\nImmanuel dwelt with us, as a God knowing what will happen, you nursed Him O intercessor, with your milk like all humans.\n\nFor He came and saved us, and acted like all humans, but He has never sinned, the heavenly King.\n\nHe humbled Himself to teach us, to make us a nation and a family, in the Jordan with John He was baptized, and gave us the pledge.\n\nHe willed to be crucified for us, to save him who was captive, and He took our nature, and was crucified on Golgotha.\n\nHe accepted the curse on His own, the Jews the disbelieving people, pierced Him in His side, and they mocked Him.\n\nHe gave up His spirit, He descended to save Adam the prisoner, and now He is with us, He revives us and we are joyful.\n\nHail to you O Lady of virgins, O Mary the Virgin, Jesus Christ dwelt in your womb, and became our Savior." },
    { language: 'arabic', text: "دُعيتِ اُم الله خالِقنا، يا مريم إبنة صهيون، تجسد منكِ وعتقنا، من أسر الشيطان الأركون.\n\nعمانوئيل هو صار معنا، إلهاً عالماً بما سيكون، وأرضعتِيه يا شفيعتنا، من لبنِك مثل البشريون.\n\nلأنه أتى ليخلصنا، وصنع أفعال البشريون، وليس كفعل الخطية، إبؤرو إن إبورانيون.\n\nتواضع كيْ يعلِّمنا، ويجعلنا شعباً وبنون، وفي الأردن من يوحنا، تعمد وأعطانا العربون.\n\nوأراد أن يصلب عنا، ويخلِّص مَنْ كان مسجون، وأخذ شكل طبيعتنا، وصُلب عند الإقرانيون.\n\nومن شعبه قَبَل اللعنة، جنس اليهود الجاحدون، وجعلوا في جنبه الطعنة، وهم به يستهزئون.\n\nوأسلم روحه سيدنا، ونزل خلَّص آدم المسجون، وهو الآن كائن معنا، أحيانا وبه صرنا فرحون.\n\nالسلام لكِ يا ست الأبكار، يا مريم تي بارثينوس، يا مَنْ في أحشائكِ قد حلَّ وصار، مخلصنا إيسوس بيخريستوس." },
    { language: 'englishArabic', text: "Du'eeti umm Allah khaliqina, ya Maryam ibnat Sahyoun, tagassada minki wa 'ataqana, min asr esh-shaytan el-arkhon.\n\n'Emmanu'eel huwa sara ma'ana, ilahan 'aliman bima sayakoun, wa arda'teehi ya shafee'atana, min labaniki mithl el-bashariyyoun.\n\nLi-annahu ata li-yukhallisana, wa sana'a af'al el-bashariyyoun, wa laysa ka-fi'l el-khatiyya, ep-ouro en-epouranion.\n\nTawada'a kay yu'allimana, wa yag'alana sha'ban wa banoun, wa fil-Urdun min Youhanna, ta'ammada wa a'tana el-'arboun.\n\nWa arada an yuslab 'anna, wa yukhallis man kana masgoun, wa akhadha shakl tabee'atina, wa sulib 'ind el-Iqraniyoun.\n\nWa min sha'bihi qabila el-la'na, gins el-Yahoud el-gahidoun, wa ga'alou fi ganbihi et-ta'na, wa hum bihi yastahzi'oun.\n\nWa aslama rouhahu sayyiduna, wa nazala khallasa Adam el-masgoun, wa huwa el-an ka'in ma'ana, ahyana wa bihi sirna farihoun.\n\nEs-salam laki ya sitt el-abkar, ya Maryam Tiparthenos, ya man fi ahsha'iki qad halla wa sar, mukhallisuna Iēsous Pikhristos." },
  ] },
  { id: "vp-the-seventh-hymn-of-el-bardanohee", title: "The Seventh Hymn of El-Bardanohee", versions: [
    { language: 'english', text: "You are called the Mother of the able God, the only King of glory, you gave birth to Him while a virgin, and the seal remained true and shut.\n\nImmanuel gave you victory, and appeared from your womb with flesh, as fire flaming in a tree, with green leaves on branches.\n\nThrough your Son we gained joy and delight, and we returned to Paradise, you defeated the legions of the disobedient, our enemies the Devil’s followers.\n\nAnd He brought him to captivity, in the lowest places of fire, in them are many sufferings, and He saved the human race.\n\nAfter everyone was captive, and humiliated with sorrows, with them Adam was sad, He saved him and returned happy.\n\nFor he disobeyed and ate the fruit, and was naked and not covered, he was cast out of Paradise, to the earth of misery and he became weary.\n\nAnd your Son restored him once again, he was returned and became happy, and gained victory over his enemies, through you O pride of the world.\n\nHail to you O Mother of God, ask your Son on our behalf, to forgive us sinners, through your prayers and honored rank." },
    { language: 'arabic', text: "دُعيتِ اُم إله القدرة، ملك المجد الوحداني، ولدتِه وأنتِ بتول عذراء، وبقى الختم صحيحاً منصانِ.\n\nعمانوئيل أعطاكِ النصرة، وظهر من أحشائكِ جسداني، كنار تتوقد في شجرة، والورق أخضر في الأغصانِ.\n\nبإبنكِ نُلنا فرحاً ومسرة، وعُدنا إلى الفردوس من ثاني، وهزمتِ جيوش الكفرة، أعدائنا جنس الشيطاني.\n\nورماه مسجوناً في حفرة، مطروحاً في قاع النيرانِ، فيه أصناف عذابات مُرَّة، وعتق جنس الإنسانِ.\n\nبعد أن كان الجميع أسرى، مذلولين بالأحزانِ، وآدم في ضيق وحسرة، خلَّصَه وعاد فرحانِ.\n\nلأنه خالف وأكل الثمرة، عدِمَ السترة وصار عريانِ، وخرج مطروداً خارج الجنة، لأرض الشقاء صار تعبانِ.\n\nوإبنكِ أعاده ثاني مرة، ورجع متهللاً فرحان، ونال على أعدائه النصرة، بكِ يا فخر الأكوانِ.\n\nالسلام لكِ يا اُم الإله، جيرينا قدام إبنِك، ليسامحنا نحن الخطاة، بصلاتِك وشرف جنسِك." },
    { language: 'englishArabic', text: "Du'eeti umm ilah el-qudra, malik el-magd el-wahdani, waladteehi wa anti batoul 'adhra', wa baqa el-khatm saheehan munsani.\n\n'Emmanu'eel a'taki en-nusra, wa zahara min ahsha'iki gasadani, ka-nar tatawaqqad fi shagara, wal-waraq akhdar fil-aghsani.\n\nBi-ibniki nilna farahan wa masarra, wa 'udna ila el-firdaws min thani, wa hazamti guyoush el-kafara, a'da'ina gins esh-shaytani.\n\nWa ramahu masgounan fi hufra, matrouhan fi qa' en-neerani, feehi asnaf 'adhabat murra, wa 'ataqa gins el-insani.\n\nBa'd an kana el-gamee' asra, madhlouleen bil-ahzani, wa Adam fi deeq wa hasra, khallasahu wa 'ada farhani.\n\nLi-annahu khalafa wa akala eth-thamara, 'adima es-sutra wa sara 'uryani, wa kharaga matroudan kharig el-ganna, li-ard esh-shaqa' sara ta'bani.\n\nWa ibnuki a'adahu thani marra, wa raga'a mutahallilan farhan, wa nala 'ala a'da'ihi en-nusra, biki ya fakhr el-akwani.\n\nEs-salam laki ya umm el-Ilah, geereena quddam ibnik, li-yusamihana nahnu el-khutah, bi-salatik wa sharaf ginsik." },
  ] },
  { id: "vp-the-eighth-greek-interpretation", title: "The Eighth Greek Interpretation", versions: [
    { language: 'coptic', text: "Ⲕⲁⲗⲱⲥ Ⲓⲇⲉⲛ ⲥⲉ Ⲓⲁⲕⲱⲃ: ⲡⲉⲛⲓⲱⲧ ⲕ̀ⲗⲓⲙⲁⲕⲁ ⲙ̀ⲯⲩⲭⲱⲛ: ⲉⲥϭⲟⲥⲓ ⲉ̀ⲧ̀ⲫⲉ ⲉ̀ⲣⲉ Ⲡⲟ︦ⲥ︦ ⲫⲏⲉ︦ⲑ︦ⲩ︦: ϩⲉⲙⲥⲓ ϩⲓϫⲱⲥ ⲱ̀ ϯⲧ̀ⲣⲩⲅⲱⲛ.\n\nⲠⲁⲛⲩⲙⲛⲓⲇⲟⲥ ⲛ̀ⲕⲟⲥⲙⲓⲕⲏ̀: ⲉⲧⲁⲥϣⲉⲡ ⲡⲓⲁ̀ⲭⲱⲣⲓⲧⲟⲥ: ϧⲉⲛ ⲧⲉⲥⲙⲏⲧⲣⲁ ⲙ̀ⲡⲁⲣⲑⲉⲛⲓⲕⲓⲏ̀: ⲛⲉⲙ ⲡⲉⲥⲁ̀ⲙⲏⲣ ⲡⲁⲛⲁ̀ⲣⲉⲧⲟⲥ.\n\nϪⲉ ⲁϥⲓ̀ⲣⲓ ⲛ̀ⲛⲉⲥ̀ⲡⲗⲁⲅⲭⲛⲟⲛ ⲑ̀ⲣⲟⲛⲟⲛ: ⲕⲉ ⲡⲁⲗⲓⲛ ⲧⲏⲛ ⲥⲩⲛ ⲅⲁⲥⲧⲏⲣⲁ: ⲉ̀ⲫⲩⲗⲁⲧⲧⲟⲙⲉⲛⲏ ⲉⲝⲟⲩⲣⲁⲛⲟⲛ: ⲉ̀ⲡⲉⲣⲅⲁⲥⲧⲟ ⲡ̀ⲗⲁⲧⲓ̀ⲧⲉⲣⲁ.\n\nⲘⲁⲣⲉⲛϫⲟⲥ ⲧⲏⲣⲉⲛ ⲱ̀ ⲡⲓⲙⲟⲕⲓ: ⲁⲙⲟⲗⲩⲥⲙⲁⲧⲟⲥ ⲙⲁⲕⲁⲣⲓⲟⲥ: ⲁ̀ⲣⲉⲧⲉⲛⲑⲱⲛϯ ⲉ̀ϯⲙⲟⲩⲕⲓ: ⲑⲏⲉ̀ⲧⲁ Ⲓⲁⲕⲱⲃ ⲛⲁⲩ ⲉ̀ⲣⲟⲥ.\n\nⲬⲉⲣⲉ ⲛⲉ ⲉ̀ⲃⲟⲗϩⲓⲧⲟⲧⲉⲛ: ⲉⲕ ⲧⲟⲛ ⲑⲩⲥⲁⲩⲣⲟⲛ ⲥⲉ ⲅⲁⲣ ⲉⲧⲧⲟⲃ: ⲁ̀ⲣⲉⲙⲓⲥⲓ ⲙ̀ⲫⲏⲉⲑⲙⲟⲧⲉⲛ: ⲙ̀ⲙⲟϥ ϧⲉⲛ ⲛⲏⲉ︦ⲑ︦ⲩ︦.\n\nϢⲱⲡⲓ ⲛⲁⲛ ⲛ̀ⲟⲩⲡ̀ⲣⲟⲥⲧⲁⲥⲓⲁ: ϧⲁⲧⲟⲧϥ ⲉⲑⲣⲉⲛϣⲱⲡⲓ ⲛ̀ⲁⲧϩⲏⲃⲓ: ⲛ̀ⲧⲉϥⲑⲟⲩⲱ̀ⲧⲉⲛ ⲇⲏⲙⲟⲥⲓⲁ: ϧⲉⲛ ⲧⲉϥⲙⲉⲧⲟⲩⲣⲟ ⲉⲧ ϧⲉⲛ ⲛⲓⲫⲏⲟⲩⲓ.\n\nⲦⲉⲛϯⲱ̀ⲟⲩ ⲛⲉ ⲱ̀ ⲑⲏⲉⲧⲥⲙⲁⲙⲁⲧ: ϣⲁ ⲡⲓⲛⲓϥⲓ ⲛ̀ⲧⲉ ⲗⲉⲩⲧⲉⲟⲥ: ϫⲉ ⲁⲣⲉϫⲓⲙⲓ ⲅⲁⲣ ⲛ̀ⲟⲩϩ̀ⲙⲟⲧ: ϧⲁⲧⲉⲛ Ⲡⲉⲛⲟⲩϯ Ⲩⲓⲟⲥ Ⲑⲉⲟⲥ." },
    { language: 'english', text: "Jacob your father saw you with goodness, like a spiritual ladder, ascending to heaven and the Lord the Holy One, seated upon it O turtle-dove.\n\nWho is praised at all times throughout the world, who accepted the Infinite One, in her virginal womb, and on her pure lap.\n\nFor He made your womb a throne, and your sealed abdomen, He extended it to be, larger than the heavens.\n\nLet us all say O vessel, pure and blessed, you were likened to the ladder, which Jacob saw.\n\nHail to you from us, for out of your sealed treasure, you bore Him who rests, with the saints.\n\nBe for us an intercessor, to Him that we may be without sorrow, and He may gather all of us, in His heavenly kingdom.\n\nWe glorify you O blessed one, until the last breath saying, \"You have found favor before, your God the Son of God.\"" },
    { language: 'arabic', text: "حسنا رآك يعقوب أبونا مثل سلم ذي نفس مرتفعة إلى السماء والرب القدوس جالس عليها أيتها اليمامة.\n\nالكلية السبح العالمي التي قبلت غير المحوي في احشاءها البتولي وحجرها الفاخر.\n\nلأنه صنع أحشاك عرشا وأيضا بطنك المختوم جعله أوسع من السموات\n\nفلنقل كلنا يا إناء طاهراً مغبوطا تشبهت بالسلم الذي رآه يعقوب.\n\nالسلام لك من قبلنا لأن من كنزك المختوم ولدت المستريح في القديسين.\n\nكوني لنا شفيعة عنده لنكون بغير حزن ويجمعنا جميعا في ملكوته السمائي.\n\nنمجدك ايتها المباركة إلى النفس الأخير لأنك وجدت نعمة عند إلهك ابن الله." },
    { language: 'englishArabic', text: "Hasanan ra'aki Ya'qoub abouna mithl sullam dhi nafs murtafi'a ila es-sama', war-Rabb el-quddous galis 'alayha ayyatuha el-yamama.\n\nEl-kulliyyat es-sabh el-'alami, allati qabilat ghayr el-muhwa fi ahsha'iha el-batouli wa hugriha el-fakhir.\n\nLi-annahu sana'a ahsha'aki 'arshan, wa aydan batnuki el-makhtoum ga'alahu awsa' min es-samawat.\n\nFal-naqoul kulluna: ya ina'an tahiran maghboutan, tashabbahti bis-sullam alladhi ra'ahu Ya'qoub.\n\nEs-salam laki min qibalina, li-anna min kanziki el-makhtoum waladti el-mustareeh fil-qiddeeseen.\n\nKouni lana shafee'a 'indahu li-nakoun bi-ghayr huzn, wa yagma'ana gamee'an fi malakoutihi es-samawi.\n\nNumaggiduki ayyatuha el-mubaraka ila en-nafas el-akheer li-annaki wagadti ni'ma 'ind ilahik Ibn Allah." },
  ] },
  { id: "vp-the-eighth-bohairic-interpretation-a", title: "The Eighth Bohairic Interpretation A", versions: [
    { language: 'coptic', text: "Ⲙⲁⲣⲓⲁ ϯⲙⲟⲩⲕⲓ ⲙ̀ⲙⲏⲓ: ⲑⲏⲉ̀ⲧⲁ Ⲓⲁⲕⲱⲃ ⲛⲁⲩ ⲉ̀ⲣⲟⲥ: ⲉⲥϭⲟⲥⲓ ⲉ̀ⲧ̀ⲫⲉ ϧⲉⲛ ⲟⲩⲙⲉⲑⲙⲏⲓ: ⲁ̀ⲣⲉ Ⲡⲟ︦ⲥ︦ ϩⲉⲙⲥⲓ ϩⲓϫⲱⲥ.\n\nⲬⲉⲣⲉ ⲛⲉ ⲉ̀ⲃⲟⲗϩⲓⲧⲟⲧⲉⲛ: ⲉ̀ ⲑ̀ⲙⲁⲩ ⲙ̀ⲡⲓⲁ̀ⲭⲱⲣⲓⲧⲟⲥ: ⲫⲏⲉ̀ⲧⲁϥϭⲓⲥⲁⲣⲝ ⲉⲑⲃⲏⲧⲉⲛ: ⲁϥⲁⲓⲧⲉⲛ ⲛⲁϥ ⲛ̀ⲟⲩⲗⲁⲟⲥ.\n\nⲀⲣⲉϣⲱⲡⲓ ⲛⲁⲛ ⲛ̀ⲟⲩⲡ̀ⲣⲟⲥⲧⲁⲧⲏⲥ: ⲛⲁϩⲣⲉⲛ Ⲫϯ ⲡⲉⲛⲣⲉϥⲥⲱϯ: Ⲓⲏ︦ⲥ︦ Ⲡⲭ︦ⲥ︦ ⲡⲓⲙⲟⲛⲟⲅⲉⲛⲏⲥ: ⲫⲏⲉ̀ⲧⲁϥⲓ̀ ⲉⲑⲃⲉ ⲡⲉⲛⲥⲱϯ.\n\nⲦⲉⲛϯⲱⲟⲩ ⲛⲉ ⲱ̀ ⲑⲏⲉ̀ⲧⲉⲛϩⲟⲧ: ⲛⲉⲙ ⲡⲓⲁⲅⲅⲉⲗⲟⲥ ⲛ̀ⲧⲉ ⲡⲓⲥ̀ⲙⲟⲩ: ϫⲉ ⲭⲉⲣⲉ ⲕⲉ ⲭⲁⲣⲓⲧⲱⲙⲉⲛⲏ ⲱ̀ ⲑⲏⲉⲑⲙⲉϩ ⲛ̀ϩⲙⲟⲧ: ⲟⲩⲟϩ Ⲡⲟ︦ⲥ︦ ϣⲟⲡ ⲛⲉⲙⲉ." },
    { language: 'english', text: "Mary the true ladder, which Jacob saw, truly rising up to heaven, and the Lord sitting upon it.\n\nHail to you from us, O Mother of the Infinite One, who was incarnated for our sake, and made us a congregation for Himself.\n\nYou became an intercessor for us, before God our Savior, Jesus Christ the only-begotten, who came for our salvation.\n\nWe glorify you O trusted one, with the angel of blessing saying, \"Hail to you O full of grace, the Lord is with you.\"" },
    { language: 'arabic', text: "مريم السلم الحقيقي الذي رآه يعقوب مرتفعا للسماء بالحقيقة والرب جالس عليه.\n\nالسلام لك من قبلنا يا أمر غير المحوي الذي تجسد من أجلنا وصيرنا له شعبا.\n\nصرت لنا شفيعة عند الله مخلصنا يسوع المسيح الوحيد الذي أتي لأجل خلاصنا.\n\nنمجدك أيتها الأمينة قائلين مع ملاك البركة أفرحي أيتها الممتلئة نعمة . الرب معك." },
    { language: 'englishArabic', text: "Maryam es-sullam el-haqeeqi alladhi ra'ahu Ya'qoub murtafi'an lis-sama' bil-haqeeqa, war-Rabb galis 'alayh.\n\nEs-salam laki min qibalina ya umm ghayr el-muhwa alladhi tagassada min aglina wa sayyarana lahu sha'ban.\n\nSirti lana shafee'a 'ind Allah mukhallisina Yasou' el-Maseeh el-waheed alladhi ata li-agl khalasina.\n\nNumaggiduki ayyatuha el-ameena qa'ileen ma'a malak el-baraka: ifrahi ayyatuha el-mumtali'a ni'ma, er-Rabb ma'aki." },
  ] },
  { id: "vp-the-eighth-bohairic-interpretation-b", title: "The Eighth Bohairic Interpretation B", versions: [
    { language: 'coptic', text: "Ⲑⲙⲉⲗⲉⲧⲏ ⲛ̀ⲧⲉ ⲡⲉⲛⲛⲟⲩⲥ: ⲱ̀ Ⲙⲁⲣⲓⲁ ϯⲡⲁⲣⲑⲉⲛⲟⲥ: ⲁϥⲉ̀ⲣⲟⲩⲱⲓⲛⲓ ⲙ̀ⲡⲉⲛⲛⲟⲩⲥ: ⲕⲁⲧⲁ ⲡ̀ⲥⲁϫⲓ ⲛ̀ⲛⲓⲅ̀ⲣⲁⲫⲏ.\n\nϮⲙⲟⲩⲕⲓ ⲉ̀ⲧⲁϥⲛⲁⲩ ⲉ̀ⲣⲟⲥ: ⲛ̀ϫⲉ Ⲓⲁⲕⲱⲃ ⲡⲓⲇⲓⲕⲉⲟⲥ: ⲱ̀ ϯⲡⲟⲗⲓⲥ ⲛ̀ⲕⲁⲑⲁⲣⲟⲥ: ⲁ̀ⲣⲉϭⲓⲥⲓ ⲛ̀ⲑⲟ ⲉ̀ϩⲟⲧⲉⲣⲱⲟⲩ ⲧⲏⲣⲟⲩ.\n\nⲬⲉⲣⲉ ⲛⲉ ⲱ̀ ϯⲡⲁⲣⲑⲉⲛⲟⲥ: ϧⲁϫⲉⲛ ⲛⲓⲥⲏⲟⲩ ⲛⲉⲙ ⲛⲓⲭ̀ⲣⲟⲛⲟⲥ: ϩⲓⲧⲉⲛ Ⲫϯ ⲡⲓϩⲩⲅⲟⲩⲙⲉⲛⲟⲥ: ⲫⲏⲉⲧϣⲟⲡ ϣⲁ ⲉ̀ⲛⲉϩ.\n\nⲘⲁⲣⲉⲛϯⲱ̀ⲟⲩ ⲛ̀ϯⲁ̀ⲅⲓⲁ̀: ϧⲉⲛ ϩⲁⲛⲥ̀ⲙⲏ ⲛ̀ⲇⲟⲝⲟⲗⲟⲅⲓⲁ̀: ϫⲉ ⲭⲉⲣⲉ ⲣⲁϣⲓ ⲱ̀ Ⲙⲁⲣⲓⲁ: ⲟ̀ Ⲕⲩⲣⲓⲟⲥ ⲙⲉⲧⲁ ⲥⲟⲩ." },
    { language: 'english', text: "The delight of our minds, O Mary the Virgin, enlightened our minds, according to the Scriptures.\n\nThe ladder that was seen, by Jacob the righteous, O pure city, you were exalted more then all of them.\n\nHail to you O Virgin, before all the ages and time, from God the Leader, THE BEING forever.\n\nLet us glorify the saint, in voice of glorification saying, \"Hail to you rejoice O Mary, the Lord is with you.\"" },
    { language: 'arabic', text: "تلاوة عقولنا يا مريم العذراء تنير عقولنا كقول الكتب\n\nالسلم الذي رأه يعقوب الصديق والمدينة النقية ارتفعت أنت اكثر من جميعهم\n\nالسلام لك أيتها العذراء من قبل الدهور والأزمان من قبل الله المدبر الكائن إلى الأبد.\n\nفلنمجد القديسة بأصوات التمجيد قائلين السلام أفرحي يا مريم الرب معك." },
    { language: 'englishArabic', text: "Tilawat 'uqoulina ya Maryam el-'Adhra' tuneer 'uqoulana ka-qawl el-kutub.\n\nEs-sullam alladhi ra'ahu Ya'qoub es-siddeeq wal-madeena en-naqiyya, irtafa'ti anti akthar min gamee'ihim.\n\nEs-salam laki ayyatuha el-'Adhra' min qabl ed-dohour wal-azman, min qibal Allah el-mudabbir el-ka'in ila el-abad.\n\nFal-numaggid el-qiddeesa bi-aswat et-tamgeed qa'ileen: es-salam, ifrahi ya Maryam er-Rabb ma'aki." },
  ] },
  { id: "vp-the-eighth-coptic-mo-aqap-interpretation", title: "The Eighth Coptic Mo-‘aqap Interpretation", versions: [
    { language: 'coptic', text: "Ⲑⲉⲟⲥ ⲙ̀ⲡⲉⲣⲭⲁⲧ ⲛ̀ⲥⲱⲕ: ⲙ̀ⲡⲉⲣϩⲓⲧ ⲥⲁⲃⲟⲗ ⲙ̀ⲙⲟⲕ: ϫⲉ ⲁⲓⲱϣ ⲉ̀ⲡ̀ϣⲱⲓ ϩⲁⲣⲟⲕ: ⲥⲱⲧⲉⲙ ⲉ̀ⲧⲁⲥ̀ⲙⲏ ⲛ̀ⲭⲱⲗⲉⲙ.\n\nⲤⲱⲧⲉⲙ ⲉ̀ⲧⲁⲥ̀ⲙⲏ ⲛ̀ⲭ̀ⲱⲗⲉⲙ: ⲱ̀ ⲫⲏⲉⲑⲟⲩⲱϣ ⲉ̀ⲛⲟϩⲉⲙ: ⲛ̀ⲛⲏⲧⲏⲣⲟⲩ ⲉ̀ⲧⲁⲩⲥⲱⲣⲉⲙ: ⲉⲑⲃⲉ ⲡ̀ⲁ̀ϣⲁⲓ ⲛ̀ⲧⲉ ⲡⲉⲕⲛⲁⲓ.\n\nⲈⲑⲃⲉ ⲡ̀ⲁ̀ϣⲁⲓ ⲛ̀ⲧⲉ ⲡⲉⲕⲛⲁⲓ: ⲁⲕⲟⲩⲱⲣⲡ ⲙ̀ⲡⲉⲕⲟⲩϫⲁⲓ: ⲉ̀ⲧⲉ Ⲓⲏ︦ⲥ︦ Ⲡⲭ︦ⲥ︦ ⲁϥϣⲁⲓ: ⲁϥϭⲓⲥⲁⲣⲝ ϧⲉⲛ ϯⲡⲁⲣⲑⲉⲛⲟⲥ.\n\nⲀϥϭⲓⲥⲁⲣⲝ ϧⲉⲛ ϯⲡⲁⲣⲑⲉⲛⲟⲥ: ⲉ̀ⲧⲁ Ⲓⲁⲕⲱⲃ ⲡⲓⲇⲓⲕⲉⲟⲥ: ⲁϥϯ ⲛⲁⲛ ⲙ̀ⲡⲉϥⲛⲓϣϯ ⲛ̀ⲧⲩⲡⲟⲥ: ⲕⲁⲧⲁ ⲫ̀ⲣⲏϯ ⲉ̀ⲧⲁϥϫⲟⲥ.\n\nⲔⲁⲧⲁ ⲫ̀ⲣⲏϯ ⲉ̀ⲧⲁϥϫⲟⲥ: ϫⲉ ⲁⲓⲛⲁⲩ ⲉ̀ⲟⲩⲙⲟⲩⲕⲓ ⲁ̀ⲗⲏⲑⲟⲥ: ⲉ̀ⲣⲉ Ⲫϯ ϩⲉⲙⲥⲓ ϩⲓϫⲱⲥ: ⲉ̀ⲧⲉ ϯⲥⲉⲙⲛⲉ ⲛ̀ⲕⲁⲑⲁⲣⲟⲥ.\n\nⲈⲧⲉ ϯⲥⲉⲙⲛⲉ ⲛ̀ⲕⲁⲑⲁⲣⲟⲥ: ⲡⲉ ϯⲙⲟⲩⲕⲓ ⲁ̀ⲗⲏⲑⲟⲥ: ⲉ̀ⲧⲁ Ⲓⲁⲕⲱⲃ ⲉⲣⲙⲉⲑⲣⲉ ϧⲁⲣⲟⲥ: ϫⲉ ⲁⲥϥⲁⲓ ϧⲁ Ⲡⲟ︦ⲥ︦ ⲛ̀ⲧⲉ ⲡ̀ⲱ̀ⲟⲩ.\n\nϪⲉ ⲁⲥϥⲁⲓ ϧⲁ Ⲡⲟ︦ⲥ︦ ⲛ̀ⲧⲉ ⲡ̀ⲱ̀ⲟⲩ: ⲟⲩⲟϩ ⲡ̀ⲟⲩⲣⲟ ⲛ̀ⲧⲉ ⲛⲓⲟⲩⲣⲱⲟⲩ: ⲡⲓⲛⲓϣϯ ⲙ̀ⲙⲁⲛⲉ̀ⲥⲱⲟⲩ: ⲉ̀ⲧⲁϥⲑⲱⲟⲩϯ ⲛ̀ⲛⲓⲡⲓⲥⲧⲟⲥ.\n\nⲈⲧⲁϥⲑⲱⲟⲩϯ ⲛ̀ⲛⲓⲡⲓⲥⲧⲟⲥ: ⲁϥϩⲟⲧⲡⲟⲩ ⲛⲉⲙ ⲛⲓⲁⲅⲅⲉⲗⲟⲥ: ⲁϥⲁⲓⲧⲟⲩ ⲛ̀ⲕ̀ⲗⲏⲣⲟⲛⲟⲙⲟⲥ: ⲛ̀ⲧⲉϥⲙⲉⲧⲟⲩⲣⲟ ⲛ̀ⲉ̀ⲛⲉϩ.\n\nⲦⲉⲛϯⲱ̀ⲟⲩ ⲛⲉ ⲱ̀ ⲑⲏⲉ̀ⲧⲉⲛϩⲟⲧ: ⲉⲧϥⲁⲓ ϧⲁ ⲡⲓⲗⲟⲅⲟⲥ ⲛ̀ⲧⲉ Ⲫ̀ⲓⲱⲧ: ϫⲉ ⲭⲉⲣⲉ ⲑⲏⲉⲑⲙⲉϩ ⲛ̀ϩ̀ⲙⲟⲧ: ⲟⲩⲟϩ Ⲡⲟ︦ⲥ︦ ϣⲟⲡ ⲛⲉⲙⲉ." },
    { language: 'english', text: "O God do not turn away from me, and do not reject me, for I called unto You, hear my voice speedily.\n\nHear my voice speedily, O You who wish salvation, for all who have gone astray, because of the abundance of Your mercy.\n\nBecause of the abundance of Your mercy, You have sent Your salvation, through the appearance of Jesus Christ, He took flesh from the Virgin.\n\nHe took flesh from the Virgin, concerning which Jacob the righteous gave, a great symbol, as he spoke.\n\nAs he spoke, I truly saw a ladder, on which God was seated, the chaste and the pure.\n\nThe chaste and the pure, truly is the ladder, to which Jacob testified, for she carried the Lord of glory.\n\nFor she carried the Lord of glory, and the King of kings, the Great Shepherd, who has gathered the faithful.\n\nWho has gathered the faithful, and united them with the angels, He made them heirs, of His eternal kingdom.\n\nWe glorify you O faithful one, who carried the Word of the Father, \"Hail to you O full of grace, the Lord is with you.\"" },
    { language: 'arabic', text: "يا الله لا ترفضني ولا تطرحني عنك. لأني صرخت إليك أسمع صوتي عاجلاً.\n\nاسمع صوتي عاجلاً يا من يشاء خلاص جميع الضالين من أجل كثرة رحمتك.\n\nمن اجل كثرة رحمتك: أرسلت خلاصك الذي هو يسوع المسيح أشرق متجسداً من العذراء.\n\nمتجسداً من العذراء: الذي يعقوب الصديق أعطانا مثاله العظيم كما قال.\n\nكما قال: أني رأيت سلما بالحقيقة والله جالس عليه التي هي العفيفة النقية.\n\nالتي هي العفيفة النقية: السلم الحقيقي الذي يعقوب شهد عنه لأنها حملت رب المجد.\n\nلأنها حملت رب المجد: وملك الملوك الراعي العظيم الذي جمع المؤمنين.\n\nالذي جمع المؤمنين: وألفهم مع الملائكة وصيرهم وارثين لملكوته الأبدية.\n\nنمجدك ايتها الامينة. الحاملة كلمة الأب قائلين إفرحي يا ممتلئة نعمة. الرب معك" },
    { language: 'englishArabic', text: "Ya Allah la tarfudni wa la tatrahni 'ank, li-anni sarakhtu ilayk; isma' sawti 'agilan.\n\nIsma' sawti 'agilan ya man yasha' khalas gamee' ed-dalleen min agl kathrat rahmatik.\n\nMin agl kathrat rahmatik: arsalta khalasak alladhi huwa Yasou' el-Maseeh, ashraqa mutagassidan min el-'Adhra'.\n\nMutagassidan min el-'Adhra': alladhi Ya'qoub es-siddeeq a'tana mithalahu el-'azeem kama qal.\n\nKama qal: inni ra'aytu sullaman bil-haqeeqa wa Allah galis 'alayh, allati hiya el-'afeefa en-naqiyya.\n\nAllati hiya el-'afeefa en-naqiyya: es-sullam el-haqeeqi alladhi Ya'qoub shahida 'anhu, li-annaha hamalat Rabb el-magd.\n\nLi-annaha hamalat Rabb el-magd: wa malik el-moulouk er-ra'i el-'azeem alladhi gama'a el-mu'mineen.\n\nAlladhi gama'a el-mu'mineen: wa allafahum ma'a el-mala'ika wa sayyarahum waritheen li-malakoutihi el-abadi.\n\nNumaggiduki ayyatuha el-ameena, el-hamila kalimat el-Ab, qa'ileen: ifrahi ya mumtali'a ni'ma, er-Rabb ma'aki." },
  ] },
  { id: "vp-the-eighth-egyptian-interpretation", title: "The Eighth Egyptian Interpretation", versions: [
    { language: 'coptic', text: "Ⲁⲣⲉⲧⲉⲛⲑⲱⲛϯ ⲉ̀ϯⲙⲟⲩⲕⲓ: ⲑⲏⲉ̀ⲧⲁ Ⲓⲁⲕⲱⲃ ⲡⲓⲡⲁⲧⲣⲓⲁⲣⲭⲏⲥ: ⲛⲁⲩ ⲉ̀ⲣⲟⲥ ϩⲓϫⲉⲛ ⲡⲓⲕⲁϩⲓ: ⲁ̀ⲣⲉ Ⲫⲛⲟⲩϯ ϩⲉⲙⲥⲓ ϩⲓϫⲱⲥ.\n\nⲀⲣⲉⲧⲉⲛⲑⲱⲛϯ ⲉ̀ϯⲙⲟⲩⲕⲓ: ⲉϥⲟ̀ϩⲓ ϧⲉⲛ ⲡⲓⲥ̀ⲧⲉⲣⲉⲱ̀ⲙⲁ: ⲛⲓⲁⲅⲅⲉⲗⲟⲥ ⲛ̀ⲧⲉ ⲡ̀ϭⲓⲥⲓ: ϩⲱⲥ ⲉ̀ⲣⲟϥ ⲛⲉⲙ ⲛⲓⲧⲁⲅⲙⲁ.\n\nⲀⲣⲉⲧⲉⲛⲑⲱⲛϯ ⲉ̀ϯⲙⲟⲩⲕⲓ: ⲉ̀ⲧⲁⲥϥⲁⲓ ϧⲁ Ⲡϭⲟⲓⲥ ⲛ̀ⲧⲉ ⲡ̀ⲱ̀ⲟⲩ: ⲁ̀ⲗⲏⲑⲱⲥ ⲛ̀ⲑⲟϥ ⲡⲉ Ⲡⲟⲩⲣⲟ ⲉⲧϭⲟⲥⲓ: Ⲡϣⲏⲣⲓ ⲫⲁ ⲡⲓⲛⲓϣϯ ⲛ̀ⲱ̀ⲟⲩ.\n\nⲀⲣⲉⲧⲉⲛⲑⲱⲛϯ ⲉ̀ϯⲙⲟⲩⲕⲓ: ⲉ̀ⲣⲉ Ⲡϭⲟⲓⲥ ϩⲓϫⲱⲥ ϧⲉⲛ ⲟⲩϩⲟϯ: ⲁϥⲧⲟⲩⲃⲟ ⲙ̀ⲙⲟⲛ ϧⲉⲛ ⲟⲩϭⲣⲟⲙⲡⲓ: ϧⲉⲛ ⲡ̀ϫⲓⲛⲑ̀ⲣⲉϥⲓ̀ ϧⲉⲛ ⲧⲉⲛⲉϫⲓ.\n\nⲀⲣⲉⲧⲉⲛⲑⲱⲛϯ ⲉ̀ϯⲙⲟⲩⲕⲓ: ⲉⲧⲥⲁⲡⲉⲥⲏⲧ ⲉ̀ϩ̀ⲣⲏⲓ ⲉ̀ⲃⲟⲗ ϧⲉⲛ ⲧ̀ⲫⲉ: ⲁ̀ⲣⲉ Ⲡϭⲟⲓⲥ ⲛ̀ⲧⲉ ⲧ̀ⲫⲉ ⲛⲉⲙ ⲡ̀ⲕⲁϩⲓ: ϩⲉⲙⲥⲓ ϩⲓϫⲉⲛ ⲧⲉϥⲫⲉ.\n\nⲈⲑⲃⲉ ⲫⲁⲓ ⲧⲉⲛϩⲱⲥ ⲉ̀Ⲫⲛⲟⲩϯ: ⲫⲏⲉ̀ⲧⲁϥϭⲓⲥⲁⲣⲝ ⲉ̀ⲃⲟⲗ ⲛ̀ϧⲏϯ: ⲁϥⲉⲣⲣⲱⲙⲓ ⲙ̀ⲡⲉⲛⲣⲏϯ: ϣⲁⲧⲉⲛ ⲫ̀ⲛⲟⲃⲓ ⲙ̀ⲙⲁⲩⲁⲧϥ." },
    { language: 'english', text: "You were likened to the ladder, which Jacob the patriarch, saw on the earth, and God sitting upon it.\n\nYou were likened to the ladder, that is firm on the firmament, and the angels of the high standings, praise Him with the ranks.\n\nYou were likened to the ladder, which carries the Lord of glory, truly He is the Most High King, the Son of the great glory.\n\nYou were likened to the ladder, and the awesome Lord on it, He purified us through a dove, through His Coming in your womb.\n\nYou were likened to the ladder, that is descending from heaven, and the Lord of heaven and earth became, sitting on His heaven.\n\nTherefore we praise God, who was incarnate of you, and became man like us, except for sin alone." },
    { language: 'arabic', text: "تشبهتِ بالسُلَّم، الذي رآه يعقوب، رئيس الآباء على الأرض، والرب جالس عليه.\n\nتشبهتِ بالسُلَّم، الثابت في الفَلَك، وملائكة العُلوْ، تسبحه مع الطغمات.\n\nتشبهتِ بالسُلَّم، الحامل رب المجد الحقيقي، هو الملك المتعالي، الإبن صاحب المجد العظيم.\n\nتشبهتِ بالسُلَّم، والرب عليه مخوف، وطهرنا بالحمامة، عندما أتى وصار في بطنكِ.\n\nتشبهتِ بالسُلَّم، النازل من السماء، وصار رب السماء والأرض، جالساً على سمائه.\n\nفلهذا نسبِّح الله، الذي تجسَّد منكِ، وصار إنساناً مثلنا، ما خلا الخطية وحدها." },
    { language: 'englishArabic', text: "Tashabbahti bis-sullam, alladhi ra'ahu Ya'qoub, ra'ees el-aba' 'ala el-ard, war-Rabb galis 'alayh.\n\nTashabbahti bis-sullam, eth-thabit fil-falak, wa mala'ikat el-'ulou, tusabbihuhu ma'a et-tughmat.\n\nTashabbahti bis-sullam, el-hamil Rabb el-magd el-haqeeqi, huwa el-malik el-muta'ali, el-Ibn sahib el-magd el-'azeem.\n\nTashabbahti bis-sullam, war-Rabb 'alayhi makhouf, wa tahharana bil-hamama, 'indama ata wa sara fi batniki.\n\nTashabbahti bis-sullam, en-nazil min es-sama', wa sara Rabb es-sama' wal-ard, galisan 'ala sama'ih.\n\nFa-li-hadha nusabbih Allah, alladhi tagassada minki, wa sara insanan mithlana, ma khala el-khatiyya wahdaha." },
  ] },
  { id: "vp-the-eighth-sahidic-interpretation", title: "The Eighth Sahidic Interpretation", versions: [
    { language: 'coptic', text: "Ⲑⲩⲥⲁⲩⲣⲟⲥ ⲛ̀ⲧⲉ ⲛⲓⲁ̀ⲅⲁⲑⲟⲛ: ⲛⲉⲙ ⲛⲓⲉϣⲗⲏⲗⲟⲩⲓ ⲛⲉⲙ ⲛⲓⲟⲩⲥⲓⲁ: ⲁⲩⲑⲱⲟⲩϯ ϧⲉⲛ ⲛⲓⲁ̀ⲣⲉⲧⲏ: ⲛ̀ϯⲑⲉⲟ̀ⲧⲟⲕⲟⲥ Ⲙⲁⲣⲓⲁ.\n\nϮⲙⲟⲩⲕⲓ ⲑⲏⲉ̀ⲧⲁϥⲛⲁⲩ ⲉ̀ⲣⲟⲥ: ⲛ̀ϫⲉ Ⲓⲁⲕⲱⲃ ⲡⲓⲇⲓⲕⲉⲟⲥ: ⲑⲏⲉ̀ⲧⲁϥϩⲉⲙⲥⲓ ϩⲓϫⲱⲥ: ⲛ̀ϫⲉ Ⲫⲛⲟⲩϯ ⲡⲓⲁ̀ⲭⲱⲣⲓⲧⲟⲥ.\n\nⲚⲑⲟ ϩⲱⲓ ⲱ̀ ϯⲡⲁⲣⲑⲉⲛⲟⲥ: ϯⲙⲟⲩⲕⲓ ⲉⲑⲟⲩⲁⲃ ⲟⲩⲟϩ ⲡⲓⲑ̀ⲣⲟⲛⲟⲥ: ϫⲉ ⲁ̀ⲣⲉϥⲁⲓ ϧⲁ Ⲫⲛⲟⲩϯ ⲛ̀ⲛⲓⲭ̀ⲣⲟⲛⲟⲥ: ϧⲉⲛ ⲧⲉⲙⲏⲧⲣⲁ ⲛ̀ⲕⲁⲑⲁⲣⲟⲥ.\n\nⲀⲣⲉⲙⲓⲥⲓ ⲙ̀Ⲡϭⲟⲓⲥ ⲁ̀ⲗⲏⲑⲱⲥ: ⲛ̀ⲑⲟ ⲉⲧϣⲟⲧⲉⲙ ⲛ̀ⲥⲁⲥⲁ ⲛⲓⲃⲉⲛ: ⲧⲉⲛϩⲱⲥ ⲛⲁϥ ⲛⲉⲙ ⲛⲓⲁⲅⲅⲉⲗⲟⲥ: ⲛ̀ⲑⲟϥ ⲡⲉ Ⲡϭⲟⲓⲥ ⲛ̀ⲟⲩⲟⲛ ⲛⲓⲃⲉⲛ.\n\nⲀϥⲛⲁϩⲙⲉⲛ ⲉ̀ⲃⲟⲗ ϧⲉⲛ ⲛⲉⲛϫⲁϫⲓ: ⲛⲉⲙ ⲛⲏⲉⲑⲙⲟⲥϯ ⲙ̀ⲙⲟⲛ: ⲕⲁⲧⲁ ⲫ̀ⲣⲏϯ ⲉ̀ⲧⲁϥⲥⲁϫⲓ: ϧⲉⲛ ⲡⲉϥϩⲱⲃ ⲛ̀ⲇⲓⲕⲉⲟⲛ.\n\nⲈⲑⲃⲉ ⲫⲁⲓ ⲧⲉⲛϯⲱ̀ⲟⲩ ⲛⲉ: ⲉⲛⲱϣ ⲉ̀ⲃⲟⲗ ⲛⲉⲙ Ⲅⲁⲃⲣⲓⲏⲗ: ϫⲉ ⲭⲉⲣⲉ ⲕⲉ ⲭⲁⲣⲓⲧⲱⲙⲉⲛⲏ: Ⲙⲁⲣⲓⲁ ⲑ̀ⲙⲁⲩ ⲛ̀Ⲉⲙⲙⲁⲛⲟⲩⲏⲗ." },
    { language: 'english', text: "The treasure of good things, joy and jewels, were gathered in the virtues, of Mary the Theotokos.\n\nThe ladder which was seen, by Jacob the righteous, and He who sits upon it, is God the Infinite One.\n\nYou are O Virgin, the holy ladder and the throne, for you have carried the God of the ages, in your pure womb.\n\nYou truly gave birth to the Lord, and you are sealed from all sides, we praise Him with the angels, for He is the Lord of everyone.\n\nHe delivered us from our enemies, and those who hate us, according to His saying, with His righteous command.\n\nTherefore we glorify you, proclaiming with Gabriel, “Hail to you O full of grace, Mary the Mother of Immanuel.”" },
    { language: 'arabic', text: "كنز الخيرات، والتهليل والجواهر، قد إجتمعت في فضائل، مريم والدة الإله.\n\nالسُلَّم الذي رآه، يعقوب الصديق، والله غير المحوى، جالس عليه.\n\nأنتِ أيتها العذراء، السُلَّم الطاهر والكرسي، لأنكِ حملتِ إله الدهور، في أحشائكِ النقية.\n\nولدتِ الرب الحقيقي، وأنتِ مختومة من كل ناحية، نسبحه مع الملائكة، لأنه هو رب الكل.\n\nنجانا من أعدائنا، ومبغضينا، كما تكلم، بأمره العادل.\n\nفلهذا نُمجدكِ، ونصرخ مع غبريال قائلين،\"السلام لكِ يا ممتلئة نعمة، مريم اُم عمانوئيل.\"" },
    { language: 'englishArabic', text: "Kanz el-khayrat, wat-tahleel wal-gawahir, qad igtama'at fi fada'il, Maryam walidat el-Ilah.\n\nEs-sullam alladhi ra'ahu, Ya'qoub es-siddeeq, wa Allah ghayr el-muhwa, galis 'alayh.\n\nAnti ayyatuha el-'Adhra', es-sullam et-tahir wal-kursi, li-annaki hamalti ilah ed-dohour, fi ahsha'iki en-naqiyya.\n\nWaladti er-Rabb el-haqeeqi, wa anti makhtouma min kull nahiya, nusabbihuhu ma'a el-mala'ika, li-annahu huwa Rabb el-kull.\n\nNaggana min a'da'ina, wa mubghideena, kama takallama, bi-amrihi el-'adil.\n\nFa-li-hadha numaggiduki, wa nasrukh ma'a Ghubriyal qa'ileen: \"Es-salam laki ya mumtali'a ni'ma, Maryam umm 'Emmanu'eel.\"" },
  ] },
  { id: "vp-the-eighth-hymn-of-abou-el-saad-of-aboutig", title: "The Eighth Hymn of Abou El-Saad of Aboutig", versions: [
    { language: 'english', text: "A ladder which Jacob saw / above it the Lord of hosts / erected upon the earth / and reaching unto heaven.\n\nHe was afraid and confused / of the awe of this splendor / saying, the awesome Lord will come / incarnate in the fullness of time.\n\nWhat wise man can realize / the honor of this mystery / my mind is truly mystified / all my life, I am confused.\n\nMary, you are the ladder / you carried the Lord of lords / according to the orator father / Jacob, His father, in the vision.\n\nWe were in the sea of darkness / Satan having authority over us / by the coming of the Logos, the Son of God / in your womb, we were freed.\n\nHail to you O mother of mercy / we are your beloved pray acknowledge us / blessed are you O full of grace / before your Son intercede for us." },
    { language: 'arabic', text: "سلم رآه الآب يعقوب / ومن فوقه رب القوات / علي الأرض إذ هو منصوب / ومرتفعاً إلي السموات.\n\nفتحير وهو مرعوب / من هيبة ذي الهيبات / وقال سيجئ الرب المرهوب / ويتجسد في عقب الأوقات.\n\nأي حكيم العقل علم / شرف هذا السر وما يحويه / حقاً إن عقلي مظلم / و طول دهري متحير فيه.\n\nمريم أنت هي السلم / وإله الآلهه أنت حملتيه / كقول الاب المتكلم / في الرؤيا يعقوب أبيه.\n\nكُنّا في بحر الظلمة / والشيطان متحكم فينا / بحلول إبن الله الكلمة / في أحشائك انعتقنا.\n\nالسلام لك يا ام الرحمة / نحن عبيدك جيرينا / طوباكِ يا مملوُة نعمة / عند ابنك الحبيب اشفعي فينا." },
    { language: 'englishArabic', text: "Sullam ra'ahu el-ab Ya'qoub / wa min fawqihi Rabb el-quwwat / 'ala el-ard idh huwa mansoub / wa murtafi'an ila es-samawat.\n\nFa-tahayyara wa huwa mar'oub / min haybat dhi el-haybat / wa qala sa-yagi' er-Rabb el-marhoub / wa yatagassad fi 'aqib el-awqat.\n\nAyy hakeem el-'aql 'alim / sharaf hadha es-sirr wa ma yahweeh / haqqan inna 'aqli muzlim / wa toul dahri mutahayyir feeh.\n\nMaryam anti hiya es-sullam / wa ilah el-aliha anti hamalteeh / ka-qawl el-ab el-mutakallim / fir-ru'ya Ya'qoub abeeh.\n\nKunna fi bahr ez-zulma / wash-shaytan mutahakkim feena / bi-houloul Ibn Allah el-Kalima / fi ahsha'iki in'ataqna.\n\nEs-salam laki ya umm er-rahma / nahnu 'abeeduki geereena / toubaki ya mamlou'at ni'ma / 'ind ibniki el-habeeb ishfa'i feena." },
  ] },
  { id: "vp-eighth-hymn-of-cantor-gabriel-of-qay-a", title: "Eighth Hymn of Cantor Gabriel of Qay A", versions: [
    { language: 'english', text: "With whom shall I liken and call you / I utter and speak words / O you whom all the fathers / blessed throughout the ages.\n\nBlessed throughout the ages / and all times and periods / how they said parables / and the visions of the fathers.\n\nAnd the visions of the fathers / a ladder of light seen by Jacob / reaching the heights of heaven / erected upon the earth.\n\nErected upon the earth / The heavenly ranks descending on it / and ascending to the hidden throne / angels worshipping around it.\n\nAngels worshipping around it / thousands of thousands and myriads / perplexed in explaining it / saying the awesome One will come.\n\nSaying the awesome One will come / appearing in human flesh / incarnate in the fullness of time / born a human birth.\n\nBorn a human birth / dwelt in your womb and you bore Him / as the blessed father’s saying / in his vision, Jacob the father.\n\nIn his vision, Jacob the father / for you are the ladder / you bore the God of gods / who renewed us after death.\n\nWho renewed us after death / He made us a justified people to Him / He chose you, O beauty of nations / you bore the invisible living One.\n\nYou bore the invisible living One / and we all bless you / saying, blessed are you O Mother of Light / hail to you and hail unto you.\n\nHail to you and hail unto you, we ask you O Mother of the Beloved, grant us to be in your fathers’ dwellings, Abraham Isaac and Jacob." },
    { language: 'arabic', text: "بمن اُشبهكِ و بمن أدعوكِ / وأنطق و أتكلم بأقوال / يا من كل الآباء أعطوكِ / الطوبى في كل الاجيال.\n\nالطوبى في كل الاجيال / و كل الأزمان و الأوقات / وكم ضربوا عنكِ أمثال / وكم نظر الآباء رؤيات.\n\nو كم نظر الآباء رؤيات / سلم نوراني رآه يعقوب / متصلاً بأعلي السموات / وعلي الأرض إذ هو منصوب.\n\nوعلي الأرض إذ هو منصوب / وطقوس السماء نازلين عليه / وصاعدين للعرش المحجوب / وملائكته ساجدين حواليه.\n\nو ملائكته ساجدين حواليه / اُلوف اُلوف مع ربوات / تتحير في وصف معانيه / وقال سيجئ ذي الهيبات.\n\nوقال سيجئ ذي الهيبات / ويظهر بجسد إنساني / ويتجسد في عقب الأوقات / ويولد الميلاد الجسداني.\n\nويولد الميلاد الجسداني / سكن في أحشاكِِ و ولدتيه / كقول الآب الطوباني / في الرؤيا يعقوب أبيه.\n\nفي الرؤيا يعقوب أبيه / لأنك أنت هي السلم / وإله الآلهه قد حملته / وجددنا من بعد عدم.\n\nجددنا من بعد عدم / و صيرانا له شعباً مبرور / و اختارك يا زين كل الأمم / وحملت الحي غير المنظور.\n\nوحملت الحي غير المنظور / ونحن الكل نطوِّبك / ونقول طوباك يا أم النور / السلام لكِ ثم السلام عليك.\n\nالسلام لكِ ثم السلام إليك، ونسألك يا أم المحبوب، ان تحظينا في مظال اباءك، ابراهيم واسحق ويعقوب." },
    { language: 'englishArabic', text: "Bi-man ushabbihuki wa bi-man ad'ouki / wa antiq wa atakallam bi-aqwal / ya man kull el-aba' a'tawki / et-touba fi kull el-agyal.\n\nEt-touba fi kull el-agyal / wa kull el-azman wal-awqat / wa kam darabou 'anki amthal / wa kam nazara el-aba' ru'yat.\n\nWa kam nazara el-aba' ru'yat / sullam nourani ra'ahu Ya'qoub / muttasilan bi-a'la es-samawat / wa 'ala el-ard idh huwa mansoub.\n\nWa 'ala el-ard idh huwa mansoub / wa touqous es-sama' nazileen 'alayh / wa sa'ideen lil-'arsh el-mahgoub / wa mala'ikatuhu sagideen hawalayh.\n\nWa mala'ikatuhu sagideen hawalayh / ulouf ulouf ma'a rabawat / tatahayyar fi wasf ma'aneeh / wa qala sa-yagi' dhul-haybat.\n\nWa qala sa-yagi' dhul-haybat / wa yazhar bi-gasad insani / wa yatagassad fi 'aqib el-awqat / wa youlad el-meelad el-gasadani.\n\nWa youlad el-meelad el-gasadani / sakana fi ahsha'iki wa waladteeh / ka-qawl el-ab et-toubani / fir-ru'ya Ya'qoub abeeh.\n\nFir-ru'ya Ya'qoub abeeh / li-annaki anti hiya es-sullam / wa ilah el-aliha qad hamalteeh / wa gaddadana min ba'd 'adam.\n\nGaddadana min ba'd 'adam / wa sayyarana lahu sha'ban mabrour / wakhtaraki ya zayn kull el-umam / wa hamalti el-hayy ghayr el-manzour.\n\nWa hamalti el-hayy ghayr el-manzour / wa nahnu el-kull nutawwibuki / wa naqoul toubaki ya umm en-nour / es-salam laki thumma es-salam 'alayki.\n\nEs-salam laki thumma es-salam ilayki, wa nas'aluki ya umm el-mahboub, an tahzeena fi mazall aba'ik, Ibraheem wa Ishaq wa Ya'qoub." },
  ] },
  { id: "vp-the-eighth-hymn-of-cantor-gabriel-of-qay-b", title: "The Eighth Hymn of Cantor Gabriel of Qay B", versions: [
    { language: 'english', text: "As Jacob saw revelations, a high ladder explained, and on it the Lord is seated, surrounding Him many orders.\n\nThey chant with the loudest voice, and tremble in His presence, all the ranks and powers, thousands and myriads praise Him.\n\nSo he was puzzled with this vision, and his heart became pale, and he learned the fulfillment of it, through the pregnancy.\n\nHe said “The Awesome One will come, to restore the sheep, truly from a virgin first-born, the Compassionate will be born.\n\nHe will be incarnate in the end of time, His Coming as rain on wool, He who fills heaven and earth, will walk in the world.”\n\nWith His divinity He did miracles, He raised the dead and healed the blind, and filled thousands of people, from two fish and five loaves.\n\nHail to you O Mother of our Savior, we ask you O pure Virgin, to ask the Lord to bring us, to the harbor in peace." },
    { language: 'arabic', text: "كما عاين يعقوب رؤيات، سُلَّماً مرتفعاً موصوف، وعليه جالس رب القوات، ومن حوليه صفوف صفوف.\n\nتُرتِّل بأعلى الأصوات، ومنه ترتعد في خوف، كل المراتب والقوات، تسبح له ربوات وألوف.\n\nفتحيَّر في تلك الرؤيات، وصار باهت قلبه مرجوف، وعَلِمَ تحقيق الرؤيات، من قِبَل الحَبَل الموصوف.\n\nوقال \"سيجئ ذو الهيبات، يأتي ليرد الخروف، من عذراء بكر بثبات، يولد المتحنن الرؤوف.\n\nيتجسد في عَقِب الأوقات، نزوله كالقطر على الصوف، المالئ الأرض مع السموات، يمشي بين العالم مكشوف.\"\n\nبلاهوته صنع الآيات، أقام الميت وأبرأ المكفوف، وأشبع من سمكتين وخمس خبزات، ربوات ربوات مع ألوف.\n\nالسلام لكِ يا اُم مخلصنا، ونسألكِ يا بكر نقية، تسألي الرب أن يوصِّلنا، إلى الميناء بطمأنينة." },
    { language: 'englishArabic', text: "Kama 'ayana Ya'qoub ru'yat, sullaman murtafi'an mawsouf, wa 'alayhi galis Rabb el-quwwat, wa min hawalayhi sufouf sufouf.\n\nTurattil bi-a'la el-aswat, wa minhu tarta'id fi khawf, kull el-maratib wal-quwwat, tusabbih lahu rabawat wa ulouf.\n\nFa-tahayyara fi tilka er-ru'yat, wa sara bahit qalbuhu margouf, wa 'alima tahqeeq er-ru'yat, min qibal el-habal el-mawsouf.\n\nWa qala: \"Sa-yagi' dhul-haybat, ya'ti li-yarudd el-kharouf, min 'adhra' bikr bi-thabat, youlad el-mutahannin er-ra'ouf.\n\nYatagassad fi 'aqib el-awqat, nuzouluhu kal-qatr 'ala es-souf, el-mali' el-ard ma'a es-samawat, yamshi bayna el-'alam makshouf.\"\n\nBi-lahoutihi sana'a el-ayat, aqama el-mayyit wa abra'a el-makfouf, wa ashba'a min samakatayn wa khams khubzat, rabawat rabawat ma'a ulouf.\n\nEs-salam laki ya umm mukhallisina, wa nas'aluki ya bikr naqiyya, tas'ali er-Rabb an yuwassilana, ila el-meena' bi-tuma'neena." },
  ] },
  { id: "vp-the-eighth-hymn-of-cantor-gabriel-of-qay-c", title: "The Eighth Hymn of Cantor Gabriel of Qay C", versions: [
    { language: 'english', text: "A ladder of light Jacob saw, he wondered about this vision, it was standing high, and the Lord of glory on its top.\n\nSo he became pale and trembled, and was lost and confused with this matter, and said “The awesome Lord will come, and incarnate of a first-born girl.\n\nAnd incarnate of a first-born girl, He comes with a human body, and leads him who was lost, and returns him to the Paradise.”\n\nHe fulfilled what His prophets prophesied, about the bodily Birth, from David who was called His father, the righteous and blessed father.\n\nThe righteous and blessed father, who spoke of the dwelling of the Word, who is perfect in all the signs, who is of the beautiful voice.\n\nCome let us chant with hymns, “Blessed are you O full of grace, blessed are you O standing sanctuary, hail to you O Mother of mercy.”\n\nHail to you O Mother of mercy, blessed are you O full of grace, the Lady of us all Mary, through her prayers and intercessions." },
    { language: 'arabic', text: "سُلَّم نوراني رآه يعقوب، صار متعجباً في رؤياه، مرتفعاً عالياً منصوب، ورب المجد صعد أعلاه.\n\nفصار باهتاً وبقى مرعوب، وتحيَّر في الأمور وتاه، وقال \"سيجئ الرب المرهوب، ويتجسد من بكر فتاة.\n\nويتجسد من بكر فتاة، يأتي بجسد إنساني، ويهدي مَنْ قد ضلَّ وتاه، ويرده للفردوس ثاني.\"\n\nوكمل ما تنبأ به أنبياه، عن الميلاد الجسداني، من داود وسُمِّيَ أباه، الأب البار الطوباني.\n\nالأب البار الطوباني، الناطق بحلول الكلمة، الكامل في كل المعاني، ذو الصوت الحسن النغمة.\n\nتعالوا نرتل بالألحان، ونقول \"طوباكِ يا مملوءة نعمة، طوباكِ يا هيكل منصان، السلام لكِ يا اُم الرحمة.\"\n\nالسلام لكِ يا اُم الرحمة، طوباكِ يا ممتلئة نعمة، أووتين شويس إننيب ماريا، هيتين نيس طوڤه نيم نيس إبريسڤيِّا." },
    { language: 'englishArabic', text: "Sullam nourani ra'ahu Ya'qoub, sara muta'aggiban fi ru'yah, murtafi'an 'aliyan mansoub, wa Rabb el-magd sa'ida a'lah.\n\nFa-sara bahitan wa baqa mar'oub, wa tahayyara fil-oumour wa tah, wa qala: \"Sa-yagi' er-Rabb el-marhoub, wa yatagassad min bikr fatah.\n\nWa yatagassad min bikr fatah, ya'ti bi-gasad insani, wa yahdi man qad dalla wa tah, wa yaruddahu lil-firdaws thani.\"\n\nWa kamula ma tanabba'a bihi anbiyah, 'an el-meelad el-gasadani, min Dawoud wa summiya abah, el-ab el-barr et-toubani.\n\nEl-ab el-barr et-toubani, en-natiq bi-houloul el-Kalima, el-kamil fi kull el-ma'ani, dhu es-sawt el-hasan en-nagham.\n\nTa'alou nurattil bil-alhan, wa naqoul: \"Toubaki ya mamlou'at ni'ma, toubaki ya haykal munsan, es-salam laki ya umm er-rahma.\"\n\nEs-salam laki ya umm er-rahma, toubaki ya mumtali'a ni'ma, Ouoh ten-tshois ennēb Maria, hiten nes-tovh nem nes-epresvia." },
  ] },
  { id: "vp-the-eighth-hymn-of-pope-abba-markos-viii", title: "The Eighth Hymn of Pope Abba Markos VIII", versions: [
    { language: 'english', text: "A ladder father Jacob saw, truly in the vision, it was standing high, from the earth to the heavens.\n\nAnd the angels of the awesome Lord, thousands descending on it, and ascending to the hidden throne, and upon it is the Lord of hosts.\n\nHe trembled by this vision, it is a sign and a testimony, the writings about Mary were fulfilled, with all the sayings and prophecies.\n\nShe carried the Forgiver of all sins, and to Him all the ranks worship, He was crucified by His Economy, and was buried among the dead.\n\nAnd on the chosen third day, our awesome Master arose, and saved those in tribulations, in the fire of Hades in distress.\n\nAdam and his sons have attained what was needed, and were saved from those flashes, and the Devil was bound, and placed in that darkness.\n\nHail to you O Lady of virgins, O Mary the Virgin, Jesus Christ dwelt in your womb, and became our Savior." },
    { language: 'arabic', text: "سُلَّم رآه الأب يعقوب، في الرؤيا حقاً بثبات، مرتفعاً عالياً منصوب، من الأرض إلى السموات.\n\nوملائكة الرب المرهوب، نازلين عليه ألوف مع ربوات، وصاعدين للعرش المحجوب، وعليه جالس رب القوات.\n\nوقد صار من رؤياه مرعوب، وهذا رمز وإشارات، عن مريم قد تم المكتوب، بكل أقوالٍ ونبوات.\n\nهي حَمَلَت غافر كل ذنوب، وله تسجد كل الطغمات، بتدبيره قد صار مصلوب، ودُفن في قبر مع الأموات.\n\nوفي ثالث يومٍ محسوب، قام سيدنا صاحب الهيبات، وخلَّص مَنْ كان قد متعوب، في نار جحيم ببكاء وحسرات.\n\nآدم وبنوه بلغوا المطلوب، وخلصوا من تلك الرجفات، والشيطان صار مسجوناً مغلوب، موضوعاً في تلك الظلمات.\n\nالسلام لكِ يا ست الأبكار، يا مريم تي بارثينوس، يا مَنْ في أحشائكِ قد حلَّ وصار، مخلصنا إيسوس بيخريستوس." },
    { language: 'englishArabic', text: "Sullam ra'ahu el-ab Ya'qoub, fir-ru'ya haqqan bi-thabat, murtafi'an 'aliyan mansoub, min el-ard ila es-samawat.\n\nWa mala'ikat er-Rabb el-marhoub, nazileen 'alayhi ulouf ma'a rabawat, wa sa'ideen lil-'arsh el-mahgoub, wa 'alayhi galis Rabb el-quwwat.\n\nWa qad sara min ru'yahu mar'oub, wa hadha ramz wa isharat, 'an Maryam qad tamma el-maktoub, bi-kull aqwalin wa nubouwat.\n\nHiya hamalat ghafir kull dhunoub, wa lahu tasgud kull et-tughmat, bi-tadbeerihi qad sara masloub, wa dufina fi qabr ma'a el-amwat.\n\nWa fi thalith yawmin mahsoub, qama sayyiduna sahib el-haybat, wa khallasa man kana qad mat'oub, fi nar gaheem bi-buka' wa hasarat.\n\nAdam wa banouhu balaghou el-matloub, wa khalasou min tilka er-ragafat, wash-shaytan sara masgounan maghloub, mawdou'an fi tilka ez-zulumat.\n\nEs-salam laki ya sitt el-abkar, ya Maryam Tiparthenos, ya man fi ahsha'iki qad halla wa sar, mukhallisuna Iēsous Pikhristos." },
  ] },
  { id: "vp-the-eighth-hymn-of-el-bardanohee", title: "The Eighth Hymn of El-Bardanohee", versions: [
    { language: 'english', text: "A ladder father Jacob saw, made perfect with many things, standing from earth to heaven, and upon it hosts of the orders.\n\nAnd on its top seated the feared, God the Lord of powers, and the ladder standing with might, carrying the One who came and will come again.\n\nThe hidden Mystery dwelt in you, He knows all the hidden matters, He appeared in flesh without blemish, and performed wonders and signs.\n\nHe was crucified through His Economy, and was buried among the dead, and His Blood was shed for Adam, It washed the trespasses for him.\n\nAnd on the third day the Beloved rose, and erased for us all harms, and He will come on the feared Day, to judge the living from the dead.\n\nHe will sit on an awesome throne, on a hill named Jehoshaphat, and it is a perfect and planned Day, the whole creation will stand in it.\n\nThe sinner will come trembled and scared, and the pure with joy and happiness, through your Son O Mary we receive what is desired, and we will be healed of every illness.\n\nAnd saved from every sin, through your intercession at all times, through your Son we receive what is desired, and the troubled ones will be saved.\n\nHail to you O Mother of God, ask your Son on our behalf, to forgive us sinners, through your prayers and honored rank." },
    { language: 'arabic', text: "سُلَّم رآه الأب يعقوب، مُكوَّن كامل بكل الصفات، من الأرض إلى السماء منصوب، وعليه جنود من الطغمات.\n\nوجالس من فوقه المخوف المرهوب، الإله رب القوات، والسُلَّم بالقدرة منصوب، يتحمَّل مَنْ أتى ويأت.\n\nسكن فيكِ سر محجوب، وهو عالم كل خفيات، ظهر بشري من غير عيوب، وعمل عجائب مع آيات.\n\nوبتدبيره قد صار مصلوب، ودُفِن في قبر مع الأموات، ونزل دمه لآدم مسكوب، غسل عنه كل السيئات.\n\nوفي ثالث يوم قام المحبوب، وأبطل عنا كل الجراحات، ويأتي في اليوم المرهوب، ليدين الأحياء من الأموات.\n\nيجلس على كرسي مرهوب، في وادي يسمى يهوشافاط، وهو يوم كامل محسوب، تقوم فيه كل المخلوقات.\n\nيجئ الخاطئ خائفاً مرعوب، والطاهر في فرح وبهجات، وبإبنكِ يا مريم ننال المطلوب، ونبرأ من كل العاهات.\n\nونتخلص من كل ذنوب، بشفاعتكِ في كل الأوقات، وبإبنكِ ننال المطلوب، ويخلص مَنْ كان في ضيقات.\n\nالسلام لكِ يا اُم الإله، جيرينا قدام إبنِك، ليسامحنا نحن الخطاة، بصلاتِك وشرف جنسِك." },
    { language: 'englishArabic', text: "Sullam ra'ahu el-ab Ya'qoub, mukawwan kamil bi-kull es-sifat, min el-ard ila es-sama' mansoub, wa 'alayhi gunoud min et-tughmat.\n\nWa galis min fawqihi el-makhouf el-marhoub, el-Ilah Rabb el-quwwat, was-sullam bil-qudra mansoub, yatahammal man ata wa ya't.\n\nSakana feeki sirr mahgoub, wa huwa 'alim kull khafiyyat, zahara bashari min ghayr 'uyoub, wa 'amila 'aga'ib ma'a ayat.\n\nWa bi-tadbeerihi qad sara masloub, wa dufina fi qabr ma'a el-amwat, wa nazala damuhu li-Adam maskoub, ghasala 'anhu kull es-sayyi'at.\n\nWa fi thalith yawm qama el-mahboub, wa abtala 'anna kull el-garahat, wa ya'ti fil-yawm el-marhoub, li-yadeen el-ahya' min el-amwat.\n\nYaglis 'ala kursi marhoub, fi wadi yusamma Yahoushafat, wa huwa yawm kamil mahsoub, taqoum feehi kull el-makhlouqat.\n\nYagi' el-khati' kha'ifan mar'oub, wat-tahir fi farah wa bahgat, wa bi-ibniki ya Maryam nanal el-matloub, wa nabra' min kull el-'ahat.\n\nWa natakhallas min kull dhunoub, bi-shafa'atiki fi kull el-awqat, wa bi-ibniki nanal el-matloub, wa yakhlus man kana fi deeqat.\n\nEs-salam laki ya umm el-Ilah, geereena quddam ibnik, li-yusamihana nahnu el-khutah, bi-salatik wa sharaf ginsik." },
  ] },
  { id: "vp-the-ninth-greek-interpretation", title: "The Ninth Greek Interpretation", versions: [
    { language: 'coptic', text: "Ⲓⲥ ⲁ̀ⲛⲁⲧⲟⲗⲏ ⲕⲉ ⲇⲩⲥⲓⲥ: ⲏ̀ⲗⲓⲟⲩ ⲛⲉⲙ ⲡⲉⲙϩⲓⲧ ϣⲁ ⲫ̀ⲣⲏⲥ: ⲥⲓ ⲡ̀ⲣⲟⲥⲫⲉⲣⲟⲩⲥⲓⲛ ⲉ̀ⲛⲉⲥⲓⲥ: ⲉⲩϫⲱ ⲙ̀ⲙⲟⲥ ϧⲉⲛ ⲟⲩⲛⲟⲩⲥ ⲉϥⲣⲏⲥ.\n\nⲰ ⲑⲏⲉ̀ⲧⲁⲥϣⲱⲡ ⲉ̀ⲣⲟⲥ ⲡⲗⲏⲣⲱⲙⲁ: ⲧⲏⲥ ⲁ̀ⲅⲓⲁⲥ ⲧ̀ⲣⲓⲁ̀ⲇⲟⲥ: ⲟⲩⲟϩ ⲁⲥϣⲱⲡ ⲛ̀ⲟⲩⲥ̀ⲕⲏⲛⲟⲙⲁ: ⲧⲟⲩ ⲩ̀ⲓⲟⲩ Ⲇⲁⲩⲓⲇ ⲡⲓϩⲩⲙⲛⲟⲇⲟⲥ.\n\nⲞ Ⲡⲁⲧⲏⲣ ⲉ̀ⲝⲁⲗⲉ̀ⲝⲁⲧⲟ ⲥⲟⲩ: ⲕⲉ ⲡ︦ⲛ︦ⲁ︦ ⲉ̀ⲡⲓⲥⲕⲓ̀ⲁⲥⲉⲛ: Ⲩⲓⲟⲥ ⲙⲉⲛ ⲉ̀ⲡⲓⲥⲕⲉ̀ⲯⲁⲧⲟ ⲥⲟⲩ: ⲥⲁⲣⲕⲱⲑⲏ̀ⲥⲁⲉ ⲏ ⲁ̀ⲅⲁⲡⲏⲥⲉⲛ.\n\nϨⲏⲡⲡⲉ ⲓⲥ Ⲡⲟ︦ⲥ︦ ⲁϥⲓ̀ ⲉ̀ⲃⲟⲗ ⲛ̀ϧⲏϯ: ⲱ̀ ⲑⲏⲉⲧⲥ̀ⲙⲁⲙⲁⲧ: ⲛ̀ⲧⲉⲗⲓⲁ ⲟⲩⲟϩ ⲉⲧⲥⲉⲗⲥⲱⲗ: ϧⲉⲛ ⲡ̀ⲱ̀ⲟⲩ ⲛⲉⲙ ⲡ̀ⲧⲁⲓⲟ ⲛⲉⲙ ⲡⲓϩ̀ⲙⲟⲧ.\n\nⲚⲧⲉϥϯ ⲙ̀ⲫ̀ⲛⲟϩⲉⲙ ⲙ̀ⲡⲓⲕⲟⲥⲙⲟⲥ: ⲉ̀ⲧⲁϥⲑⲁⲙⲓⲟϥ ϧⲉⲛ ⲡⲉϥⲟⲩⲱϣ: ⲛ̀ⲧⲟⲩⲟⲩϫⲁⲓ ⲁⲡⲟ̀ ⲡⲓⲣⲁⲥⲙⲟⲥ: ⲉⲑⲃⲉ ⲛⲉϥⲙⲉⲧϣⲉⲛϩⲏⲧ ⲉⲧⲟϣ.\n\nⲦⲉⲛϩⲱⲥ ⲉ̀ⲣⲟϥ ⲁⲥⲙⲁ ⲕⲉⲛⲟⲛ: ⲟⲩⲟϩ ⲟⲛ ⲧⲉⲛⲉⲣϩⲟⲩⲟ̀ ϭⲁⲥϥ: ⲕⲉ ⲉ̀ⲛⲟⲩⲙⲉⲛ ⲇⲓⲁ̀ⲙⲉⲛⲟⲛ: ⲛⲁϩⲣⲉⲛ ⲇⲉⲥⲡⲓⲛⲁ ⲑⲏⲉ̀ⲧⲁⲥⲙⲁⲥϥ.\n\nⲦⲉⲛϯⲱ̀ⲟⲩ ⲛⲉ ⲱ̀ ⲑⲏⲉⲧⲥⲙⲁⲙⲁⲧ: ϣⲁ ⲡⲓⲛⲓϥⲓ ⲛ̀ⲧⲉ ⲗⲉⲩⲧⲉⲟⲥ: ϫⲉ ⲁⲣⲉϫⲓⲙⲓ ⲅⲁⲣ ⲛ̀ⲟⲩϩ̀ⲙⲟⲧ: ϧⲁⲧⲉⲛ Ⲡⲉⲛⲟⲩϯ Ⲩⲓⲟⲥ Ⲑⲉⲟⲥ." },
    { language: 'english', text: "From east to west, from north to south, they present to you praise, saying with a vigilant mind.\n\nO you who accepted the perfection, of the Holy Trinity, and became a dwelling, to the Son of David the hymnist.\n\nThe Father chose you, and the Spirit overshadowed you, and the Son pledged you, incarnated from you as He loved.\n\nBehold the Lord came out of you, O blessed one, the perfect one and who is adorned, with glory and honor and grace.\n\nThat He may grant the world salvation, which He created with His will, that it may be saved from temptation, according to His many compassions.\n\nWe praise Him with a new song, and also exalt Him, and we present praise at all times, before our Lady who bore Him.\n\nWe glorify you O blessed one, until the last breath saying, \"You have found favor before, your God the Son of God.\"" },
    { language: 'arabic', text: "من مشارق الشمس إلي مغاربها ومن الشمال إلى الجنوب يقدمون لك التسبيح.\n\nقائلين بعقل مستيقظ يا التي قبلت كمال الثالوث القدوس وصارت مسكنا لابن داود المرتل.\n\nالآب اختارك والروح ظللك والابن تعهدك متجسدا منك كما أحب.\n\nهوذا الرب خرج منك أيتها المباركة الكاملة والمزينة بالمجد والإكرام والنعمة.\n\nليعطي الخلاص للعالم الذي خلقه بإرادته لينجوا من التجربة من أجل رأفاته الكثيرة.\n\nنسبحه تسبيحا جديداً وأيضاً نزيده علوا ثم نسبح دائما أمام سيدتنا التي ولدته.\n\nنمجدك ايتها المباركة إلى النفس الأخير لأنك وجدت نعمة عند إلهك ابن الله." },
    { language: 'englishArabic', text: "Min mashariq esh-shams ila magharibiha wa min esh-shamal ila el-ganoub yuqaddimoun laki et-tasbeeh,\n\nQa'ileen bi-'aql mustayqiz: ya allati qabilat kamal eth-thalouth el-quddous wa sarat maskanan li-Ibn Dawoud el-murattil.\n\nEl-Ab ikhtaraki war-Rouh zallalaki wal-Ibn ta'ahhadaki mutagassidan minki kama ahabb.\n\nHa huwa dha er-Rabb kharaga minki ayyatuha el-mubaraka el-kamila wal-muzayyana bil-magd wal-ikram wan-ni'ma,\n\nLi-yu'ti el-khalas lil-'alam alladhi khalaqahu bi-iradatih, li-yangou min et-tagriba min agl ra'afatihi el-katheera.\n\nNusabbihuhu tasbeehan gadeedan wa aydan nazeeduhu 'ulouwwan, thumma nusabbih da'iman amam sayyidatina allati waladathu.\n\nNumaggiduki ayyatuha el-mubaraka ila en-nafas el-akheer li-annaki wagadti ni'ma 'ind ilahik Ibn Allah." },
  ] },
  { id: "vp-the-ninth-bohairic-interpretation-a", title: "The Ninth Bohairic Interpretation A", versions: [
    { language: 'coptic', text: "Ϩⲏⲡⲡⲉ ⲓⲥ Ⲡⲟ︦ⲥ︦ Ⲫϯ: ϧⲉⲛ ⲧⲉⲛⲉϫⲓ ⲁϥⲓ̀ ⲉ̀ⲃⲟⲗ: ⲟⲩⲟϩ ⲁϥϯ ⲛⲁⲛ ⲛ̀ⲟⲩⲥⲱϯ: ⲱ̀ ⲑⲏⲉ̀ⲧⲥⲙⲁⲙⲁⲧ ⲉⲧϫⲏⲕ ⲉ̀ⲃⲟⲗ.\n\nⲈⲛⲟϩⲉⲙ ⲙ̀ⲡⲓⲕⲟⲥⲙⲟⲥ: ϧⲉⲛ ⲛⲉϥⲛⲁⲓ ⲛⲉⲙ ⲛⲉϥⲙⲉⲧϣⲉⲛϩⲏⲧ: ⲛⲉⲙ ⲧⲉϥⲛⲓϣϯ ⲙ̀ⲙⲉⲧⲁ̀ⲅⲁⲑⲟⲥ: ⲛⲉⲙ ⲧⲉϥⲙⲉⲧⲣⲉϥⲱ̀ⲟⲩ ⲛ̀ϩⲏⲧ.\n\nⲦⲉⲛϩⲱⲥ ⲉ̀ⲣⲟϥ ⲧⲉⲛϯⲱ̀ⲟⲩ ⲛⲁϥ: ⲧⲉⲛⲉⲣϩⲟⲩⲟ̀ ϭⲓⲥⲓ ⲙ̀ⲙⲟϥ: ⲧⲉⲛⲉⲣⲡ̀ⲣⲟⲥⲕⲩⲛⲏⲥⲓⲥ ⲛⲁϩⲣⲁϥ: ⲟⲩⲟϩ ⲟⲛ ⲧⲉⲛⲟⲩⲱϣⲧ ⲙ̀ⲙⲟϥ.\n\nⲦⲉⲛϯⲱ̀ⲟⲩ ⲛⲉ ⲱ̀ ⲑⲏⲉ̀ⲧⲉⲛϩⲟⲧ: ⲛⲉⲙ ⲡⲓⲁⲅⲅⲉⲗⲟⲥ ⲛ̀ⲧⲉ ⲡⲓⲥ̀ⲙⲟⲩ: ϫⲉ ⲭⲉⲣⲉ ⲕⲉ ⲭⲁⲣⲓⲧⲱⲙⲉⲛⲏ ⲱ̀ ⲑⲏⲉⲑⲙⲉϩ ⲛ̀ϩⲙⲟⲧ: ⲟⲩⲟϩ Ⲡⲟ︦ⲥ︦ ϣⲟⲡ ⲛⲉⲙⲉ." },
    { language: 'english', text: "Behold the Lord God, came out of your womb, and granted us salvation, O blessed perfect one.\n\nThat He may deliver the world, with His mercies and compassions, and the greatness of His goodness, and His longsuffering.\n\nWe praise and glorify Him, and exalt Him above all, we bow down before Him, and worship Him.\n\nWe glorify you O trusted one, with the angel of blessing saying, \"Hail to you O full of grace, the Lord is with you.\"" },
    { language: 'arabic', text: "هوذا الرب الإله خرج من بطنك وأعطانا الخلاص أيتها المباركة الكاملة.\n\nليخلص العالم بمراحمه ورأفاته وعظم صلاحه وطول روحه (أناته).\n\nنسبحه ونمجده ونزيده علوا ونخر امامه وأيضا نسجد له.\n\nنمجدك أيتها الأمينة قائلين مع ملاك البركة أفرحي أيتها الممتلئة نعمة . الرب معك." },
    { language: 'englishArabic', text: "Ha huwa dha er-Rabb el-Ilah kharaga min batniki wa a'tana el-khalas ayyatuha el-mubaraka el-kamila,\n\nLi-yukhallis el-'alam bi-marahimihi wa ra'afatihi wa 'izam salahihi wa toul rouhihi (anatih).\n\nNusabbihuhu wa numaggiduhu wa nazeeduhu 'ulouwwan, wa nakhirru amamahu wa aydan nasgudu lah.\n\nNumaggiduki ayyatuha el-ameena qa'ileen ma'a malak el-baraka: ifrahi ayyatuha el-mumtali'a ni'ma, er-Rabb ma'aki." },
  ] },
  { id: "vp-the-ninth-bohairic-interpretation-b", title: "The Ninth Bohairic Interpretation B", versions: [
    { language: 'coptic', text: "Ⲓⲉⲍⲉⲕⲓⲏⲗ ⲡⲓⲡ̀ⲣⲟⲫⲏⲧⲏⲥ: ⲱϣ ⲉ̀ⲃⲟⲗ ⲉϥⲟⲓ ⲙ̀ⲙⲉⲑⲣⲉ: ϫⲉ ⲁⲓⲛⲁⲩ ⲉ̀ⲟⲩⲡⲩⲗⲏ ⲛ̀ⲥⲁ ⲛⲓⲙⲁ ⲛ̀ϣⲁⲓ: ⲉⲥⲧⲟⲃ ϧⲉⲛ ⲟⲩⲧⲉⲃⲥ ⲛ̀ϣ̀ⲫⲏⲣⲓ.\n\nⲘⲡⲉϩ̀ⲗⲓ ϣⲉ ⲉ̀ϧⲟⲩⲛ ⲉ̀ⲣⲟⲥ: ⲉ̀ⲃⲏⲗ ⲉ̀Ⲡϭⲟⲓⲥ ⲛ̀ⲧⲉ ⲛⲓϫⲟⲙ: ⲁϥϣⲉ ⲉ̀ϧⲟⲩⲛ ⲁϥⲓ̀ ⲉ̀ⲃⲟⲗ: ⲉⲥⲟ̀ϩⲓ ⲉⲥϣⲟⲧⲉⲙ ⲙ̀ⲡⲉⲥⲣⲏϯ.\n\nϮⲡⲩⲗⲏ ⲅⲁⲣ ⲡⲉ ϯⲡⲁⲣⲑⲉⲛⲟⲥ: ⲑⲏⲉ̀ⲧⲁⲥⲙⲓⲥⲓ ⲙ̀Ⲡⲉⲛⲥⲱⲧⲏⲣ: ⲟⲩⲟϩ ⲟⲛ ⲙⲉⲛⲉⲛⲥⲁ ⲑ̀ⲣⲉⲥⲙⲁⲥϥ: ⲁⲥⲟ̀ϩⲓ ⲟⲛ ⲉⲥⲟⲓ ⲙ̀ⲡⲁⲣⲑⲉⲛⲟⲥ.\n\nϤⲥ̀ⲙⲁⲣⲱⲟⲩⲧ ⲛ̀ϫⲉ ⲡⲉⲕⲁⲣⲡⲟⲥ: ⲱ̀ ⲑⲏⲉ̀ⲧⲁⲥϫ̀ⲫⲉ Ⲫⲛⲟⲩϯ ⲛⲁⲛ ϧⲉⲛ ⲡⲓⲕⲟⲥⲙⲟⲥ: ϣⲁ ⲛ̀ⲧⲉϥⲥⲟⲧⲧⲉⲛ ϧⲉⲛ ⲛⲉⲛϫⲓϫ: ⲙ̀ⲡⲓⲇⲩⲣⲁⲛⲛⲟⲥ ⲛ̀ⲁⲑⲛⲁⲓ.\n\nⲘⲁⲣⲉⲛϯⲱ̀ⲟⲩ ⲛ̀ϯⲁ̀ⲅⲓⲁ̀: ϧⲉⲛ ϩⲁⲛⲥ̀ⲙⲏ ⲛ̀ⲇⲟⲝⲟⲗⲟⲅⲓⲁ̀: ϫⲉ ⲭⲉⲣⲉ ⲣⲁϣⲓ ⲱ̀ Ⲙⲁⲣⲓⲁ: ⲟ̀ Ⲕⲩⲣⲓⲟⲥ ⲙⲉⲧⲁ ⲥⲟⲩ." },
    { language: 'english', text: "Ezekiel the prophet, has witnessed saying, “I saw a gate to the east, sealed with a mysterious seal.\n\nAnd no one went through it, but the Lord of powers, He entered and went out, and the gate remained sealed.”\n\nFor the gate is the Virgin, who gave birth to our Savior, and after His birth, she remained a virgin.\n\nBlessed is your Fruit, O you who gave birth to God for the world, so as to redeem us from the hands, of the unmerciful tyrant.\n\nLet us glorify the saint, in voice of glorification saying, \"Hail to you rejoice O Mary, the Lord is with you.\"" },
    { language: 'arabic', text: "حزقيال النبي، يصرخ شاهداً قائلاً، \"إني رأيت باباً ناحية المشرق، مختوماً بختم عجيب.\n\nولم يدخل أحد إليه، إلا رب القوات، دخل وخرج، وبقى مختوماً بحاله.\"\n\nالباب هو العذراء، التي ولدت مخلصنا، وأيضاً من بعد ما ولدته، بَقِيَت عذراء.\n\nمباركة هي ثمرتكِ، يا مَنْ ولدت لنا الله في العالم، حتى خلصنا من أيدي، المضاد غير الرحوم.\n\nفلنمجد القديسة بأصوات التمجيد قائلين السلام أفرحي يا مريم الرب معك." },
    { language: 'englishArabic', text: "Hizqiyal en-nabi, yasrukh shahidan qa'ilan: \"Inni ra'aytu baban nahiyat el-mashriq, makhtouman bi-khatm 'ageeb.\n\nWa lam yadkhul ahad ilayh, illa Rabb el-quwwat, dakhala wa kharag, wa baqa makhtouman bi-halih.\"\n\nEl-bab huwa el-'Adhra', allati waladat mukhallisana, wa aydan min ba'd ma waladathu, baqiyat 'adhra'.\n\nMubaraka hiya thamaratuki, ya man waladti lana Allah fil-'alam, hatta khallasana min aydi, el-mudadd ghayr er-rahoum.\n\nFal-numaggid el-qiddeesa bi-aswat et-tamgeed qa'ileen: es-salam, ifrahi ya Maryam er-Rabb ma'aki." },
  ] },
  { id: "vp-the-ninth-coptic-mo-aqap-interpretation", title: "The Ninth Coptic Mo-‘aqap Interpretation", versions: [
    { language: 'coptic', text: "Ⲓⲏ︦ⲥ︦ Ⲡⲭ︦ⲥ︦ ⲡⲁⲃⲟⲓ̀ⲑⲟⲥ: ⲛⲁⲓ ϧⲁ ⲧⲁⲙⲉⲧⲉ̀ⲗⲁⲭⲓⲥⲧⲟⲥ: ⲉⲑⲃⲉ ⲧⲉⲕⲙⲉⲧⲁ̀ⲅⲁⲑⲟⲥ: ⲙ̀ⲡⲉⲣⲱⲡ ⲉ̀ⲣⲟⲓ ⲛ̀ⲛⲁⲁ̀ⲛⲟⲙⲓⲁ.\n\nⲘⲡⲉⲣⲱⲡ ⲉ̀ⲣⲟⲓ ⲛ̀ⲛⲁⲁ̀ⲛⲟⲙⲓⲁ: ⲛⲉⲙ ⲫ̀ⲛⲟⲃⲓ ⲛ̀ⲧⲁϩⲩⲗⲓⲕⲓⲁ: ⲁⲗⲗⲁ ⲥⲟⲗϫⲟⲩ ⲉⲑⲃⲉ Ⲙⲁⲣⲓⲁ: ⲉ̀ⲧⲁⲕⲓ̀ ⲁⲕϣⲱⲡⲓ ⲛ̀ϧⲏⲧⲥ.\n\nⲈⲧⲁⲕⲓ̀ ⲁⲕϣⲱⲡⲓ ⲛ̀ϧⲏⲧⲥ: ϫⲉ ⲛ̀ⲑⲟⲕ ⲡⲉ ⲉ̀ⲧⲁⲕⲉⲣϩⲏⲧⲥ: ⲁⲕⲥⲟⲃϯ ⲙ̀ⲙⲟⲥ ⲟⲩⲟϩ ⲁⲕⲥⲉⲙⲛⲏⲧⲥ: ⲉⲑⲃⲉ ⲫ̀ⲛⲟϩⲉⲙ ⲙ̀ⲡⲓⲕⲟⲥⲙⲟⲥ.\n\nⲈⲑⲃⲉ ⲫ̀ⲛⲟϩⲉⲙ ⲙ̀ⲡⲓⲕⲟⲥⲙⲟⲥ: ⲛⲉⲙ ⲡⲓⲣⲱⲙⲓ ⲛ̀ⲁⲣⲭⲉⲟⲥ: ⲁⲕⲓ̀ ⲁⲕⲉⲣⲥⲱⲙⲁⲧⲓⲕⲟⲥ: ⲉ̀ⲃⲟⲗϧⲉⲛ ϯϣⲉⲗⲉⲧ Ⲙⲁⲣⲓⲁ.\n\nⲈⲃⲟⲗϧⲉⲛ ϯϣⲉⲗⲉⲧ Ⲙⲁⲣⲓⲁ: ⲕⲁⲧⲁ ⲧⲉⲕⲉ̀ⲡⲁⲅⲅⲉⲗⲓⲁ: ⲁⲕⲥⲱϯ ⲛ̀ⲧⲉⲕⲕ̀ⲗⲏⲣⲟⲛⲟⲙⲓⲁ: ⲉ̀ⲧⲉ ⲁ̀ⲛⲟⲛ ϧⲁ ⲛⲓⲡⲓⲥⲧⲟⲥ.\n\nⲈⲧⲉ ⲁ̀ⲛⲟⲛ ϧⲁ ⲛⲓⲡⲓⲥⲧⲟⲥ: ⲧⲉⲛϩⲱⲥ ⲉ̀ⲣⲟⲕ ⲉⲛϫⲱ ⲙ̀ⲙⲟⲥ: ϫⲉ ⲫⲱⲕ ⲡⲉ ⲡⲓⲱ̀ⲟⲩ ⲛⲉⲙ ⲡⲓϩⲩⲙⲛⲟⲥ: ⲓⲥϫⲉⲛ ϯⲛⲟⲩ ⲛⲉⲙ ϣⲁ ⲉ̀ⲛⲉϩ.\n\nⲦⲉⲛϯⲱ̀ⲟⲩ ⲛⲉ ⲱ̀ ⲑⲏⲉ̀ⲧⲉⲛϩⲟⲧ: ⲉⲧϥⲁⲓ ϧⲁ ⲡⲓⲗⲟⲅⲟⲥ ⲛ̀ⲧⲉ Ⲫ̀ⲓⲱⲧ: ϫⲉ ⲭⲉⲣⲉ ⲑⲏⲉⲑⲙⲉϩ ⲛ̀ϩ̀ⲙⲟⲧ: ⲟⲩⲟϩ Ⲡⲟ︦ⲥ︦ ϣⲟⲡ ⲛⲉⲙⲉ." },
    { language: 'english', text: "Jesus Christ my helper, have mercy upon Your poor one, for the sake of Your goodness, do not count my iniquities.\n\nDo not count my iniquities, and the sins of my youth, wipe them out for the sake of Mary, to whom You came and dwelt in.\n\nTo whom You came and dwelt in, for You are the One who began, You prepared and established her, for the salvation of the world.\n\nFor the salvation of the world, and the first man, You came and took flesh, from the bride Mary.\n\nFrom the bride Mary, according to Your promises, You saved Your heritage, we the faithful.\n\nWe the faithful, praise You saying, \"Unto You is due glory and praise, from now and forever.\"\n\nWe glorify you O faithful one, who carried the Word of the Father, \"Hail to you O full of grace, the Lord is with you.\"" },
    { language: 'arabic', text: "يا يسوع المسيح معينني أرحم حقارتي من أجل صلاحك لا تحسب على آثامي.\n\nلا تحسب على آثامي وخطايا شبابي لكن أمحها من أجل مريم التي اتيت وحللت فيها.\n\nالتي أتيت وحللت فيها: لأنك أنت الذي ابتدأت وأعددتها وثبتها من أجل خلاص العالم.\n\nمن أجل خلاص العالم: والإنسان الأول أتيت وتجسدت من العروسة مريم.\n\nمن العروسة مريم: كموعدك وخلصت ميراثك أى نحن المؤمنون.\n\nأى نحن المؤمنون: نسبحك قائلين: لك المجد والتسبيح من الآن وإلى الأبد\n\nنمجدك ايتها الامينة. الحاملة كلمة الأب قائلين إفرحي يا ممتلئة نعمة. الرب معك" },
    { language: 'englishArabic', text: "Ya Yasou' el-Maseeh mu'eeni, irham haqarati min agl salahik, la tahsib 'alayya athami.\n\nLa tahsib 'alayya athami wa khataya shababi, lakin imhaha min agl Maryam allati atayta wa halalta feeha.\n\nAllati atayta wa halalta feeha: li-annaka anta alladhi ibtada'ta wa a'dadtaha wa thabbattaha min agl khalas el-'alam.\n\nMin agl khalas el-'alam: wal-insan el-awwal atayta wa tagassadta min el-'arousa Maryam.\n\nMin el-'arousa Maryam: ka-maw'idik, wa khallasta meerathak ayy nahnu el-mu'minoun.\n\nAyy nahnu el-mu'minoun: nusabbihuka qa'ileen: laka el-magd wat-tasbeeh min el-an wa ila el-abad.\n\nNumaggiduki ayyatuha el-ameena, el-hamila kalimat el-Ab, qa'ileen: ifrahi ya mumtali'a ni'ma, er-Rabb ma'aki." },
  ] },
  { id: "vp-the-ninth-egyptian-interpretation", title: "The Ninth Egyptian Interpretation", versions: [
    { language: 'coptic', text: "Ϩⲏⲡⲡⲉ Ⲡϭⲟⲓⲥ Ⲫⲛⲟⲩϯ: ⲱ̀ ϯⲡⲁⲣⲑⲉⲛⲟⲥ ⲉⲧϫⲏⲕ ⲉ̀ⲃⲟⲗ: ⲁϥⲓ̀ ⲛ̀ϧⲏϯ ⲉⲑⲃⲉ ⲡⲉⲛⲥⲱϯ: ϩⲓⲛⲁ ⲛ̀ⲧⲉϥⲭⲱ ⲛⲁⲛ ⲉ̀ⲃⲟⲗ.\n\nϨⲏⲡⲡⲉ Ⲡϭⲟⲓⲥ Ⲫⲛⲟⲩϯ: ⲧⲉⲛϩⲱⲥ ⲉ̀ⲣⲟϥ ⲧⲉⲛϯⲱ̀ⲟⲩ ⲛⲁϥ: ϫⲉ ⲛ̀ⲑⲟϥ ⲡⲉ Ⲫⲛⲟⲩϯ ⲛ̀ⲧⲉ ⲛⲉⲛⲓⲟϯ: ⲧⲉⲛⲉⲣϩⲟⲩⲟ̀ ϭⲓⲥⲓ ⲙ̀ⲙⲟϥ.\n\nϨⲏⲡⲡⲉ Ⲡϭⲟⲓⲥ Ⲫⲛⲟⲩϯ: ⲁϥⲓ̀ ⲉ̀ⲛⲟϩⲉⲙ ⲙ̀ⲡⲓⲕⲟⲥⲙⲟⲥ ⲧⲏⲣϥ: ⲁϥⲉⲣⲣⲱⲙⲓ ⲙ̀ⲡⲉⲛⲣⲏϯ: ϣⲁⲧⲉⲛ ⲫ̀ⲛⲟⲃⲓ ⲙ̀ⲙⲁⲩⲁⲧϥ.\n\nϨⲏⲡⲡⲉ Ⲡϭⲟⲓⲥ Ⲫⲛⲟⲩϯ: ⲱ̀ ϯⲫⲉ ⲙ̀ⲃⲉⲣⲓ ⲙ̀ⲙⲁϩⲥ̀ⲛⲟⲩϯ: ⲁϥϣⲁⲓ ⲛⲁⲛ ⲉ̀ⲃⲟⲗ ⲛ̀ϧⲏϯ: ⲛ̀ϫⲉ ⲡⲓⲣⲏ ⲛ̀ⲧⲉ ϯⲇⲓⲕⲉⲟ̀ⲥⲩⲛⲏ.\n\nϨⲏⲡⲡⲉ Ⲡϭⲟⲓⲥ Ⲫⲛⲟⲩϯ: ⲁϥⲓ̀ ⲉⲑⲣⲉϥⲁⲓⲧⲉⲛ ⲛⲁϥ ⲛ̀ⲟⲩⲗⲁⲟⲥ: ϯⲧⲱⲃϩ ⲙ̀ⲙⲟⲕ Ⲡϭⲟⲓⲥ Ⲡⲁⲛⲟⲩϯ: ⲛⲁⲓ ϧⲁ ⲧⲉⲛⲙⲉⲧⲉ̀ⲗⲁⲭⲓⲥⲧⲟⲥ.\n\nⲈⲑⲃⲉ ⲫⲁⲓ ⲧⲉⲛϩⲱⲥ ⲉ̀Ⲫⲛⲟⲩϯ: ⲫⲏⲉ̀ⲧⲁϥϭⲓⲥⲁⲣⲝ ⲉ̀ⲃⲟⲗ ⲛ̀ϧⲏϯ: ⲁϥⲉⲣⲣⲱⲙⲓ ⲙ̀ⲡⲉⲛⲣⲏϯ: ϣⲁⲧⲉⲛ ⲫ̀ⲛⲟⲃⲓ ⲙ̀ⲙⲁⲩⲁⲧϥ." },
    { language: 'english', text: "Behold the Lord God, O perfect Virgin, came through you for our salvation, that He may forgive us.\n\nBehold the Lord God, we praise and glorify Him, for He is the God of our fathers, and exalt Him above all.\n\nBehold the Lord God, came to save the whole world, He became a man like us, except for sin alone.\n\nBehold the Lord God, O new and second heaven, out of you the Sun of Righteousness, shone upon us.\n\nBehold the Lord God, came to make us a congregation for Himself, I pray to You O Lord my God, have mercy on our poor selves.\n\nTherefore we praise God, who was incarnate of you, and became man like us, except for sin alone." },
    { language: 'arabic', text: "ها هوذا الرب الإله، أيتها العذراء الكاملة، أتى فيكِ من أجل خلصنا، لكيْ يغفر لنا.\n\nها هوذا الرب الإله، نسبحه ونمجده، لأنه هو إله آبائنا، ونزيده علواً.\n\nها هوذا الرب الإله، جاء ليخلص العالم كله، وقد صار إنساناً، ما خلا الخطية فقط.\n\nها هوذا الرب الإله، أيتها السماء الجديدة الثانية، قد أشرق لنا منكِ، شمس البر.\n\nها هوذا الرب الإله، جاء لكيْ يجعلنا له شعباً، أطلب إليك يا رب إلهي، أن ترحم حقارتنا.\n\nفلهذا نسبِّح الله، الذي تجسَّد منكِ، وصار إنساناً مثلنا، ما خلا الخطية وحدها." },
    { language: 'englishArabic', text: "Ha huwa dha er-Rabb el-Ilah, ayyatuha el-'Adhra' el-kamila, ata feeki min agl khalasina, likay yaghfir lana.\n\nHa huwa dha er-Rabb el-Ilah, nusabbihuhu wa numaggiduh, li-annahu huwa ilah aba'ina, wa nazeeduhu 'ulouwwan.\n\nHa huwa dha er-Rabb el-Ilah, ga'a li-yukhallis el-'alam kullah, wa qad sara insanan, ma khala el-khatiyya faqat.\n\nHa huwa dha er-Rabb el-Ilah, ayyatuha es-sama' el-gadeeda eth-thaniya, qad ashraqa lana minki, shams el-birr.\n\nHa huwa dha er-Rabb el-Ilah, ga'a likay yag'alana lahu sha'ban, atlub ilayka ya Rabbi ilahi, an tarham haqaratana.\n\nFa-li-hadha nusabbih Allah, alladhi tagassada minki, wa sara insanan mithlana, ma khala el-khatiyya wahdaha." },
  ] },
  { id: "vp-the-ninth-sahidic-interpretation", title: "The Ninth Sahidic Interpretation", versions: [
    { language: 'coptic', text: "Ⲓⲱⲥ ⲙ̀ⲙⲱⲧⲉⲛ ⲱ̀ ⲛⲓⲡⲓⲥⲧⲟⲥ: ⲧⲉⲛⲉⲣϩⲩⲙⲛⲟⲥ Ⲉⲙⲙⲁⲛⲟⲩⲏⲗ: Ⲡⲉⲛⲥⲱⲧⲏⲣ Ⲓⲏⲥⲟⲩⲥ Ⲡⲓⲭ̀ⲣⲓⲥⲧⲟⲥ: ⲛ̀ⲑⲟϥ ⲡⲉ Ⲫⲛⲟⲩϯ ⲙ̀Ⲡⲓⲥ̀ⲣⲁⲏⲗ.\n\nϪⲉ ⲁϥⲣⲉⲕ ⲛⲓⲫⲏⲟⲩⲓ: ⲁϥⲓ̀ ⲉ̀ⲡⲉⲥⲏⲧ ϣⲁⲣⲟⲛ: ⲟⲩⲟϩ ⲁϥⲛⲁϣⲧⲉⲛ ϧⲉⲛ ⲛⲉⲛϩ̀ⲃⲏⲟⲩⲓ: ⲛ̀ⲁⲧϣⲁⲩ ⲙ̀ⲡⲟⲛⲏⲣⲟⲛ.\n\nⲀϥϣⲁⲓ ⲛⲁⲛ ⲉ̀ⲃⲟⲗ ϧⲉⲛ Ⲙⲁⲣⲓⲁ: ⲕⲁⲧⲁ ⲛⲓⲥ̀ⲙⲏ ⲛ̀ⲧⲉ ⲛⲓⲡ̀ⲣⲟⲫⲏⲧⲏⲥ: ⲁⲛϫⲓⲙⲓ ⲙ̀ⲡⲉⲕⲥⲱⲧⲏⲣⲓⲁ: ⲉ̀ⲃⲟⲗ ϩⲓⲧⲉⲛ ϯⲡ̀ⲣⲟⲥⲧⲁⲧⲏⲥ.\n\nϨⲏⲡⲡⲉ ⲓⲥ Ⲡϭⲟⲓⲥ Ⲫⲛⲟⲩϯ: ⲫⲁ ⲡⲓⲑ̀ⲣⲟⲛⲟⲥ ⲛ̀ϣⲁϩ ⲛ̀ⲭ̀ⲣⲱⲙ: ⲁϥⲟⲩⲱⲛϩ ⲛⲁⲛ ⲉ̀ⲃⲟⲗ ⲛ̀ϧⲏϯ: ⲑ̀ⲙⲁⲩ ⲙ̀ⲡ̀ⲱ̀ⲟⲩ ⲛ̀ⲁⲧⲗⲱⲙ.\n\nⲠⲓⲁⲓⲇⲓⲟⲥ ⲛⲉⲙ Ⲡⲉϥⲓⲱⲧ: ⲉ̀ⲃⲟⲗ ϧⲉⲛ ⲟⲩⲥⲓⲁ ⲛ̀ⲛⲟⲩϯ: ⲧⲁⲓⲡⲁⲣⲑⲉⲛⲟⲥ ⲉⲧⲥⲉⲃⲧⲱⲧ: ⲁⲥⲉⲣⲙ̀ⲡ̀ϣⲁ ⲛ̀ⲧⲉⲥϥⲁⲓ ⲛ̀ⲧⲉϥⲙⲉⲑⲛⲟⲩϯ.\n\nⲦⲉⲛϩⲱⲥ ⲉ̀ⲣⲟϥ ⲟⲩⲟϩ ⲧⲉⲛⲟⲩⲱϣⲧ ⲙ̀ⲙⲟϥ: ϧⲉⲛ ⲛⲏⲉⲧϩⲏⲡ ⲛⲉⲙ ⲟⲩⲣⲏⲧⲟⲥ: ϧⲉⲛ ⲟⲩⲥ̀ⲙⲏ ⲛ̀ⲁⲧⲭⲁⲣⲱϥ: ⲉⲑⲃⲉ ϫⲉ ⲁϥⲓ̀ ⲟⲩⲟϩ ⲁϥⲛⲁⲓ ⲛⲁⲛ ⲁ̀ⲛⲟⲛ ϧⲁ ⲡⲉϥⲗⲁⲟⲥ.\n\nⲈⲑⲃⲉ ⲫⲁⲓ ⲧⲉⲛϯⲱ̀ⲟⲩ ⲛⲉ: ⲉⲛⲱϣ ⲉ̀ⲃⲟⲗ ⲛⲉⲙ Ⲅⲁⲃⲣⲓⲏⲗ: ϫⲉ ⲭⲉⲣⲉ ⲕⲉ ⲭⲁⲣⲓⲧⲱⲙⲉⲛⲏ: Ⲙⲁⲣⲓⲁ ⲑ̀ⲙⲁⲩ ⲛ̀Ⲉⲙⲙⲁⲛⲟⲩⲏⲗ." },
    { language: 'english', text: "Hurry O believers, let us chant to Immanuel, our Savior Jesus Christ, He is the God of Israel.\n\nFor He bowed the heavens, and came down to us, and made us hard hearted in our works, that are unbeneficial and hidden.\n\nHe shone to us from Mary, according to the prophetic voices, so we found Your salvation, through the intercessor.\n\nBehold the Lord God, who has the burning throne, appeared to us from you, the Mother of the unfading glory.\n\nThe Eternal One with His Father, has the divine nature, this prepared Virgin, was worthy to carry His divinity.\n\nWe praise and worship Him, in secret and publicly, with an unceasing voice, for He came and had mercy on us His people.\n\nTherefore we glorify you, proclaiming with Gabriel, “Hail to you O full of grace, Mary the Mother of Immanuel.”" },
    { language: 'arabic', text: "أسرعوا أيها المؤمنون، لنسبح عمانوئيل، مخلصنا يسوع المسيح، لأنه هو إله إسرائيل.\n\nلأنه قد طأطأ السموات، ونزل إلينا، ونشلنا من أعمالنا، غير الفالحة الخبيئة.\n\nأشرق لنا من مريم، كأصوات الأنبياء، فوجدنا خلاصك، من قِبَل الشفيعة.\n\nهوذا الرب الإله، ذو الكرسي الملتهب ناراً، ظهر لنا منكِ، يا اُم المجد غير المضمحل.\n\nالأزلي مع أبيه، من جوهر الإله، هذه العذراء المستعدة، إستحقت أن تحمل لاهوته.\n\nنسبحه ونسجد له، في السر والإجهار، بصوت لا يسكت، من أجل أنه قد أتى ورحمنا نحن شعبه.\n\nفلهذا نُمجدكِ، ونصرخ مع غبريال قائلين،\"السلام لكِ يا ممتلئة نعمة، مريم اُم عمانوئيل.\"" },
    { language: 'englishArabic', text: "Asri'ou ayyuha el-mu'minoun, li-nusabbih 'Emmanu'eel, mukhallisana Yasou' el-Maseeh, li-annahu huwa ilah Isra'eel.\n\nLi-annahu qad ta'ta'a es-samawat, wa nazala ilayna, wa nashalana min a'malina, ghayr el-faliha el-khabee'a.\n\nAshraqa lana min Maryam, ka-aswat el-anbiya', fa-wagadna khalasak, min qibal esh-shafee'a.\n\nHa huwa dha er-Rabb el-Ilah, dhu el-kursi el-multahib naran, zahara lana minki, ya umm el-magd ghayr el-mudmahill.\n\nEl-azali ma'a abeeh, min gawhar el-Ilah, hadhihi el-'Adhra' el-musta'idda, istahaqqat an tahmil lahoutah.\n\nNusabbihuhu wa nasgudu lah, fis-sirr wal-ighar, bi-sawt la yaskut, min agl annahu qad ata wa rahimana nahnu sha'bah.\n\nFa-li-hadha numaggiduki, wa nasrukh ma'a Ghubriyal qa'ileen: \"Es-salam laki ya mumtali'a ni'ma, Maryam umm 'Emmanu'eel.\"" },
  ] },
  { id: "vp-the-ninth-hymn-of-abou-el-saad-of-aboutig", title: "The Ninth Hymn of Abou El-Saad of Aboutig", versions: [
    { language: 'english', text: "Behold, the Lord came from you / and saved the world He created / from the bondage of the cursed Satan / in the belly of Hades He crushed him.\n\nAnd we became His justified people / He tore the handwriting of slavery / our father Adam who was bound / since ancient times in Hades, He released.\n\nWe praise and glorify Him / and exalt Him forever / as the Good One and Lover of Mankind with His Father / and the Holy Spirit, One with Him.\n\nI am with you, O lovers of God / come let us ask the patient One / through the intercessions of the Theotokos / to grant us deliverance.\n\nHe gave us a sign of signs / by baptism, He gave us life / on judgment day of Resurrection / He will put us at His right hand.\n\nHail to you O mother of mercy / we are your beloved pray acknowledge us / blessed are you O full of grace / before your Son intercede for us." },
    { language: 'arabic', text: "هوذا الرب أتي منك / وخلّص العالم الذي خلقة / من أسر الشيطان اللعين / وفي جوف الجحيم سحقه.\n\nوصيرنا له شعباً مبرور / وكتاب العبودية مزّقة / وآدم أبونا الذي كان مأسور / من قديم في جوف الجحيم عتقة.\n\nنسبح له ونمجد إياه / ونزيده علواً إلي الآباد / كصالح محب البشر مع أبيه / والروح القدس الذي به اتحد.\n\nأنا معكم يا محبي الإله / العبد سقيم الروح والجسد / تعالوا نسأل طويل الأناه / أن يهب الخلاص لكل أحد.\n\nلأنه أعطانا رسماً رسمه / بالمعمودية يحيينا / ويوم القيامة في الزحمة / من عن يمينه يوقفنا.\n\nالسلام لك يا ام الرحمة / نحن عبيدك جيرينا / طوباكِ يا مملوُة نعمة / عند ابنك الحبيب اشفعي فينا." },
    { language: 'englishArabic', text: "Ha huwa dha er-Rabb ata minki / wa khallasa el-'alam alladhi khalaqah / min asr esh-shaytan el-la'een / wa fi gawf el-gaheem sahaqah.\n\nWa sayyarana lahu sha'ban mabrour / wa kitab el-'oubudiyya mazzaqah / wa Adam abouna alladhi kana ma'sour / min qadeem fi gawf el-gaheem 'ataqah.\n\nNusabbih lahu wa numaggid iyyah / wa nazeeduhu 'ulouwwan ila el-abad / ka-salih muhibb el-bashar ma'a abeeh / war-Rouh el-Qudus alladhi bihi ittahad.\n\nAna ma'akum ya muhibbi el-Ilah / el-'abd saqeem er-rouh wal-gasad / ta'alou nas'al taweel el-anah / an yahab el-khalas li-kull ahad.\n\nLi-annahu a'tana rasman rasamah / bil-ma'moudiyya yuhyeena / wa yawm el-qiyama fiz-zahma / min 'an yameenihi yuwaqqifna.\n\nEs-salam laki ya umm er-rahma / nahnu 'abeeduki geereena / toubaki ya mamlou'at ni'ma / 'ind ibniki el-habeeb ishfa'i feena." },
  ] },
  { id: "vp-ninth-hymn-of-cantor-gabriel-of-qay-a", title: "Ninth Hymn of Cantor Gabriel of Qay A", versions: [
    { language: 'english', text: "Behold the Lord desired and loved / wishing to fulfill the promise / the Lord granted what He promised / He erased all His people’s recklessness.\n\nHe erased all His people’s recklessness / and taught us His divine mystery / You bore Him and He fulfilled the word / He baptized us in the Trinity’s name.\n\nHe baptized us in the Trinity’s name / He shone His light after darkness / He granted us His kingdom / and erased all our sins.\n\nAnd erased all our sins / we praise and glorify Him / He is due eternal glory and honor / as a Good One and Lover of Mankind, with His Father.\n\nAs the Good One and Lover of Mankind, with His Father / and the eternal Holy Spirit / only God, no Lord but Him / eternal, everlasting, omnipresent.\n\nEternal, everlasting, omnipresent / Creator, giver, bestower / He chose you O daughter of David / Lord of lords dwelt in your womb.\n\nLord of lords dwelt in your womb / you gave birth to Him and you suckled Him / while being in His Father’s glory / for the sake of your parents.\n\nFor the sake of your parents / after they were in affliction and sadness / O you, whom the Lord desired / save us from Satan’s evil.\n\nSave us from Satan’s evil / for we are regarded by you / the servant the composer of the hymn / a sinner who approaches you.\n\nA sinner who approaches you / confessing my sins / hoping by praising you / O Mary, my shelter.\n\nO Mary, my shelter / I plead you on the dreadful day / I, your sinful servant / ask you, I who is regarded by you.\n\nAsk you, I who is regarded by you / do not neglect who are regarded by you / your servant who is full of sins / with effort says, hail to you.\n\nHail to you and hail unto you, we ask you O Mother of the Beloved, grant us to be in your fathers’ dwellings, Abraham Isaac and Jacob." },
    { language: 'arabic', text: "هوذا الرب شاء و أحب / وأراد وفاء وعد بكمال / وما وعد به الرب وهب / ومحا عن شعبه كل ضلال.\n\nومحا عن شعبه كل ضلال / وعرفنا سر اللاهوت / وحملتيه وأكمل الأقوال / وعمدنا باسم الثالوث.\n\nوعمدنا باسم الثالوث / وأشرق نوره من بعد ظلام / وجاد علينا بالملكوت / ومحا عنا كل الآثام.\n\nومحا عنا كل الآثام / نسبح له ونمجد إياه / له المجد الدائم والإكرام / كصالح محب البشر مع آباه.\n\nكصالح محب البشر مع آباه / والروح القدس أزلي موجود / إله واحد لا رب سواه / دائم باقي حاضر موجود.\n\nدائم باقي حاضر موجود / خالق رازق عاطي وهاب / إختاركِ يا إبنة داود / وسكن في أحشاك رب الأرباب.\n\nسكن في أحشاك رب الأرباب / وولدتيه ورضع من ثدييك / وهو كائن في مجد الآب / من أجل أمك و أبيك.\n\nمن أجل أمك وأبيك / بعد أن كانوا في ضيق وأحزان / يا من تاق الرب إليك / نجينا من شر الشيطان.\n\nنجينا من شر الشيطان لأننا محسوبين عليك والعبد الناظم ذي الأوزان خاطئ وتقدمت إليك\n\nخاطئ وتقدمت إليك معترفا لك بخطاياي ومتعشم بمديحي فيك يا مريم أنت ملجأي\n\nيا مريم أنت ملجأي اترجاك في اليوم المرهوب أنا عبدك الخاطي متوسل بك وعليك محسوب\n\nمتوسل بك وعليك محسوب فلا تفوتي من حسب عليك عبدك في الرق المكتوب بالجهد يقول السلام إليك\n\nالسلام لكِ ثم السلام إليك، ونسألك يا أم المحبوب، ان تحظينا في مظال اباءك، ابراهيم واسحق ويعقوب." },
    { language: 'englishArabic', text: "Ha huwa dha er-Rabb sha'a wa ahabb / wa arada wafa' wa'd bi-kamal / wa ma wa'ada bihi er-Rabb wahab / wa maha 'an sha'bihi kull dalal.\n\nWa maha 'an sha'bihi kull dalal / wa 'arrafana sirr el-lahout / wa hamalteehi wa akmala el-aqwal / wa 'ammadana bism eth-thalouth.\n\nWa 'ammadana bism eth-thalouth / wa ashraqa nouruhu min ba'd zalam / wa gada 'alayna bil-malakout / wa maha 'anna kull el-atham.\n\nWa maha 'anna kull el-atham / nusabbih lahu wa numaggid iyyah / lahu el-magd ed-da'im wal-ikram / ka-salih muhibb el-bashar ma'a abah.\n\nKa-salih muhibb el-bashar ma'a abah / war-Rouh el-Qudus azali mawgoud / ilah wahid la Rabb siwah / da'im baqi hadir mawgoud.\n\nDa'im baqi hadir mawgoud / khaliq raziq 'ati wahhab / ikhtaraki ya ibnat Dawoud / wa sakana fi ahsha'iki Rabb el-arbab.\n\nSakana fi ahsha'iki Rabb el-arbab / wa waladteehi wa radi'a min thadyayki / wa huwa ka'in fi magd el-Ab / min agl ummiki wa abeeki.\n\nMin agl ummiki wa abeeki / ba'd an kanou fi deeq wa ahzan / ya man taqa er-Rabb ilayki / nageena min sharr esh-shaytan.\n\nNageena min sharr esh-shaytan, li-annana mahsoubeen 'alayki, wal-'abd en-nazim dhul-awzan, khati' wa taqaddamtu ilayki.\n\nKhati' wa taqaddamtu ilayki, mu'tarifan laki bi-khatayaya, wa muta'ashshim bi-madeehi feeki, ya Maryam anti malga'i.\n\nYa Maryam anti malga'i, atarqaki fil-yawm el-marhoub, ana 'abduki el-khati' mutawassil biki wa 'alayki mahsoub.\n\nMutawassil biki wa 'alayki mahsoub, fa-la tufawwiti man hasaba 'alayki, 'abduki fir-riqq el-maktoub, bil-guhd yaqoul es-salam ilayki.\n\nEs-salam laki thumma es-salam ilayki, wa nas'aluki ya umm el-mahboub, an tahzeena fi mazall aba'ik, Ibraheem wa Ishaq wa Ya'qoub." },
  ] },
  { id: "vp-the-ninth-hymn-of-cantor-gabriel-of-qay-b", title: "The Ninth Hymn of Cantor Gabriel of Qay B", versions: [
    { language: 'english', text: "Behold the Lord came and appeared, from your womb O pride of generations, and walked among people in the day, and perfected humanity.\n\nYou carried Him without man’s seed, and bore Him without impossibility, to remove for us all harms, and erase all deception.\n\nBlessed are you O vessel of coal, your servant entreats and asks, to Him who came and appeared, through you in the end of time.\n\nAs He said in His Book, about the lost sheep, and I the sinner cry openly, “Have mercy O honored One.\n\nAnd keep the people who are present, O magnificent and honored One, and behold with Your kindness and look, to Your servant who wrote these sayings.\n\nMy tongue is weak and falling short, from many iniquities and acts, and cannot speak and mention, my name Gabriel among the people.”\n\nHail to you O Mother of our Savior, we ask you O pure Virgin, to ask the Lord to bring us, to the harbor in peace." },
    { language: 'arabic', text: "هوذا الرب أتى وظهر، من أحشاكِ يا فخر الأجيال، ومشى بين العالم بالنهار، وأكمل طبع الناسوت بكمال.\n\nحملتِه من غير زرع بشر، وولدتِه حقاً بغير مُحال، ليزيل عنا كل ضرر، ويمحي عنا كل ضلال.\n\nطوباكِ يا إناء العنبر، عبدكِ يتضرع ويسأل، إلى مَنْ قد أتى وظهر، منكِ في عَقِب الأجيال.\n\nكما في كتبه قد خبَّر، من أجل الخروف الضال، وأنا الخاطئ أصرخ إجهار، قائلاً \"إرحمني يا ذا الجلال.\n\nوإحفظ هذا الشعب الحاضر، يا ذا الهيبة مع كل جلال، وتطلَّع بألطافك وأنظر، إلى عبدك ناظم الأقوال.\n\nلساني عاجز ومقصِّر، من كثرة إثمي والأفعال، ولم أقدر أنطق وأذكر، إسمي بين الناس غبريال.\"\n\nالسلام لكِ يا اُم مخلصنا، ونسألكِ يا بكر نقية، تسألي الرب أن يوصِّلنا، إلى الميناء بطمأنينة." },
    { language: 'englishArabic', text: "Ha huwa dha er-Rabb ata wa zahar, min ahsha'iki ya fakhr el-agyal, wa masha bayna el-'alam bin-nahar, wa akmala tab' en-nasout bi-kamal.\n\nHamalteehi min ghayr zar' bashar, wa waladteehi haqqan bi-ghayr muhal, li-yuzeel 'anna kull darar, wa yamhi 'anna kull dalal.\n\nToubaki ya ina' el-'anbar, 'abduki yatadarra' wa yas'al, ila man qad ata wa zahar, minki fi 'aqib el-agyal.\n\nKama fi kutubihi qad khabbar, min agl el-kharouf ed-dall, wa ana el-khati' asrukh ighar, qa'ilan: \"Irhamni ya dhal-galal.\n\nWahfaz hadha esh-sha'b el-hadir, ya dhal-hayba ma'a kull galal, wa tatalla' bi-altafika wanzur, ila 'abdika nazim el-aqwal.\n\nLisani 'agiz wa muqassir, min kathrat ithmi wal-af'al, wa lam aqdir antiq wa adhkur, ismi bayna en-nas Ghubriyal.\"\n\nEs-salam laki ya umm mukhallisina, wa nas'aluki ya bikr naqiyya, tas'ali er-Rabb an yuwassilana, ila el-meena' bi-tuma'neena." },
  ] },
  { id: "vp-the-ninth-hymn-of-cantor-gabriel-of-qay-c", title: "The Ninth Hymn of Cantor Gabriel of Qay C", versions: [
    { language: 'english', text: "Behold the Lord desired and wanted, to fulfill the old promise, to rescue us from all corruption, and renew us after we were nothing.\n\nSo the Father looked down from His heaven, and found no one pure like you O Mary, He sent His Son to be incarnate of you, and to us His promise was fulfilled.\n\nAnd to us His promise was fulfilled, we praise and glorify Him, as the Good One Giver of Life and Lover of Mankind, who lives through His Holy Spirit and His Father.\n\nCome let glorify and exalt, and praise the unseen One, to Him is the eternal glory and honor, forever and ever.\n\nForever and ever, eternal immortal and great, we ask of His goodness and gifts, to give His people eternal grace.\n\nAnd the servant who confesses his sins, chants to Mary the pride of the nation, Gabriel who is saying, “Hail to you O Mother of mercy.”\n\nHail to you O Mother of mercy, blessed are you O full of grace, the Lady of us all Mary, through her prayers and intercessions." },
    { language: 'arabic', text: "هوذا الرب شاء وأراد، أن يوفي الوعد المتقدم، وينقذنا من كل فساد، ويجدِّدنا من بعد عدم.\n\nفتطلَّع الآب من سمائه فلم يجد، مَنْ يُشبه طُهركِ يا مريم، فأرسل إبنه منكِ تجسد، ولنا وعده الصادق قد تم.\n\nولنا وعده الصادق قد تم، نسبح له ونمجد أيَّاه، كصالح محب البشر منعم، الحيْ بروح قدسه وأبيه.\n\nتعالوا نمجد ونعظِّم، ونسبح من لا عين تراه، له المجد الدائم والإكرام، شا إينيه إنتيه بي إينيه.\n\nشا إينيه إنتيه بي إينيه، دائم باقي ذو العظمة، نطلب من جوده وعطاياه، أن يديم على شعبه النعمة.\n\nوالعبد المعترف بخطاياه، مادح مريم زين الأمة، غبريال القائل من فاه، \"السلام لكِ يا اُم الرحمة.\"\n\nالسلام لكِ يا اُم الرحمة، طوباكِ يا ممتلئة نعمة، أووتين شويس إننيب ماريا، هيتين نيس طوڤه نيم نيس إبريسڤيِّا." },
    { language: 'englishArabic', text: "Ha huwa dha er-Rabb sha'a wa arad, an youfi el-wa'd el-mutaqaddim, wa yunqidhana min kull fasad, wa yugaddidana min ba'd 'adam.\n\nFa-tatalla'a el-Ab min sama'ihi fa-lam yagid, man yushbih tuhraki ya Maryam, fa-arsala ibnahu minki tagassad, wa lana wa'duhu es-sadiq qad tamm.\n\nWa lana wa'duhu es-sadiq qad tamm, nusabbih lahu wa numaggid iyyah, ka-salih muhibb el-bashar mun'im, el-hayy bi-Rouh qudsihi wa abeeh.\n\nTa'alou numaggid wa nu'azzim, wa nusabbih man la 'ayn tarah, lahu el-magd ed-da'im wal-ikram, sha eneh ente pi-eneh.\n\nSha eneh ente pi-eneh, da'im baqi dhul-'azama, natlub min goudihi wa 'atayah, an yudeem 'ala sha'bihi en-ni'ma.\n\nWal-'abd el-mu'tarif bi-khatayah, madih Maryam zayn el-umma, Ghubriyal el-qa'il min fah: \"Es-salam laki ya umm er-rahma.\"\n\nEs-salam laki ya umm er-rahma, toubaki ya mumtali'a ni'ma, Ouoh ten-tshois ennēb Maria, hiten nes-tovh nem nes-epresvia." },
  ] },
  { id: "vp-the-ninth-hymn-of-pope-abba-markos-viii", title: "The Ninth Hymn of Pope Abba Markos VIII", versions: [
    { language: 'english', text: "Behold the Lord appeared from you, O Mary the Virgin, and our good Savior, chose your beautiful purity.\n\nBlessed are you who became, a Mother to the holy God, the salvation of Adam appeared from you, through your conception of my Lord Jesus.\n\nHe took a perfect flesh from you, with it He saved Adam the prisoner, in the bottom of Hades he wept, as a captive of the Devil.\n\nHe shed precious Blood for us, for the salvation of all the souls, you carried in your womb O Mary, the salvation of the Christians.\n\nHail to you who ate bread, from the hands of the angels, they brought it to you in the temple, O Mary the first-born Bride.\n\nI ask and entreat your intercessions, I am the sinner your servant Markos, and for all the people participating, in the faith of the holy Son.\n\nMay the spirits bodies and souls, be preserved through you, and the Church be at rest, with her servants deacons and priests.\n\nHail to you O Lady of virgins, O Mary the Virgin, Jesus Christ dwelt in your womb, and became our Savior." },
    { language: 'arabic', text: "هوذا الرب ظهر منكِ، يا مريم تي بارثينوس، وإختار حسن طهارتكِ، بين سوتير إن آغاثوس.\n\nطوباكِ يا مَنْ قد صرتِ، أماً للإله القدوس، خلاص آدم قد ظهر بكِ، بحملكِ في باشويس إيسوس.\n\nأخذ جسداً كاملاً منكِ، خلِّص به آدم الذي كان محبوس، في قاع الجحيم كان فيه يبكي، مسبياً مع بي ذيَّاڤولوس.\n\nسفكه عنا دماً زكي، لأجل خلاص كل النفوس، في أحشائكِ يا مريم حَملْتِ، خلاص إنني إخريستيانوس.\n\nالسلام لكِ يا مَنْ أكلتِ، خبزاً من يد ني أنجيلوس، وفي بي إرفيه أحضروه لكِ، يا مريم بكر وعروس.\n\nأسال وأطلب شفاعتِك، أنا الخاطئ عبدِك مرقس، وعن كل الشعب المشترِك، في الإيمان بالإبن القدوس.\n\nيكونون محفوظين بكِ، أرواحاً وأجساداً ونفوس، والبيعة تكون في طمأنينة، وخدامها شمامسة وقسوس.\n\nالسلام لكِ يا ست الأبكار، يا مريم تي بارثينوس، يا مَنْ في أحشائكِ قد حلَّ وصار، مخلصنا إيسوس بيخريستوس." },
    { language: 'englishArabic', text: "Ha huwa dha er-Rabb zahara minki, ya Maryam Tiparthenos, wakhtara husn taharatiki, pen-Sōtēr en-agathos.\n\nToubaki ya man qad sirti, umman lil-Ilah el-quddous, khalas Adam qad zahara biki, bi-hamliki fi pa-Tshois Iēsous.\n\nAkhadha gasadan kamilan minki, khallasa bihi Adam alladhi kana mahbous, fi qa' el-gaheem kana feehi yabki, masbiyyan ma'a Pidiavolos.\n\nSafakahu 'anna daman zakiyy, li-agl khalas kull en-nufous, fi ahsha'iki ya Maryam hamalti, khalas en-ni-ekhristianos.\n\nEs-salam laki ya man akalti, khubzan min yad ni-aggelos, wa fi pi-erfei ahdarouhu laki, ya Maryam bikr wa 'arous.\n\nAs'al wa atlub shafa'atak, ana el-khati' 'abduki Murqus, wa 'an kull esh-sha'b el-mushtarik, fil-eeman bil-Ibn el-quddous.\n\nYakounoun mahfouzeen biki, arwahan wa agsadan wa nufous, wal-bee'a takoun fi tuma'neena, wa khuddamuha shamamisa wa qusous.\n\nEs-salam laki ya sitt el-abkar, ya Maryam Tiparthenos, ya man fi ahsha'iki qad halla wa sar, mukhallisuna Iēsous Pikhristos." },
  ] },
  { id: "vp-the-ninth-hymn-of-el-bardanohee", title: "The Ninth Hymn of El-Bardanohee", versions: [
    { language: 'english', text: "Behold the Lord came out of you, O Mary the pride of the world, from His highest heaven He chose your beauty, at the end of time He was sent to you.\n\nHis only Son came dwelling in your womb, a hidden Mystery was declared, and the sons of your race were saved, from slavery and dishonor.\n\nBy the dwelling of the Word in your womb, our Savior Jesus the Judge, became a child drinking your milk, resting on your lap and bosom.\n\nSalome came to you at your request, you put Him in the manger, and the ranks came down to that place, worshiping the Son of Man.\n\nTheir Creator became your Son, praise to Him from every tongue, you kissed Him and, He was nursed like the humans.\n\nBlessed are you and your honored race, you carried the Creator of the world, and salvation came to us through your purity, and we won [freedom] from the fire.\n\nThe Lord found no one like you, you became a sanctuary for God, we were freed through your honor, and were saved from the Devil’s slavery.\n\nHail to you O Mother of God, ask your Son on our behalf, to forgive us sinners, through your prayers and honored rank." },
    { language: 'arabic', text: "هوذا الرب خرج منكِ، يا مريم فخر الأكوان، من عُلو سمائه إختار حسنكِ، أُرسِلَ لكِ في عَقِب الأزمان.\n\nنزل وحيده سكن فى بطنِك، سراً مخفى قد صار إعلان، وخلصت أبناء جنسِك، من أسر عبودية وهوان.\n\nبحلول الكلمة في بطنِك، يسوع مخلصنا الديان، وصار طفلاً يرضع لبنِك، في حجركِ بين الأحضان.\n\nوأتت لكِ سلومى بقصدِك، ووضعتِه في مذود عريان، والطغمات نزلوا إلى عندِك، بسجود إلى إبن الإنسان.\n\nخالقهم قد صار إبنِك، له التسبيح من كل لسان، وقبَّلتيه بفمِك، ورضع كسائر البشريين.\n\nطوباكِ وطوبى لشرف جنسِك، حملتِ خالق كل الأكوان، وصار الخلاص لنا بطهرِك، وفزنا من حر النيران.\n\nلم يجد الآب مَنْ هو شبهِك، صرتِ لله هيكلاً منصان، وصرنا أحراراً بشرف قدرِك، وعُتقنا من أسر الشيطان.\n\nالسلام لكِ يا اُم الإله، جيرينا قدام إبنِك، ليسامحنا نحن الخطاة، بصلاتِك وشرف جنسِك." },
    { language: 'englishArabic', text: "Ha huwa dha er-Rabb kharaga minki, ya Maryam fakhr el-akwan, min 'ulou sama'ihi ikhtara husnaki, ursila laki fi 'aqib el-azman.\n\nNazala waheeduhu sakana fi batniki, sirran makhfiyyan qad sara i'lan, wa khallasti abna' ginsiki, min asr 'oubudiyya wa hawan.\n\nBi-houloul el-Kalima fi batniki, Yasou' mukhallisuna ed-dayyan, wa sara tiflan yarda' labanaki, fi hugriki bayna el-ahdan.\n\nWa atat laki Salomi bi-qasdiki, wa wada'teehi fi mizwad 'uryan, wat-tughmat nazalou ila 'indiki, bi-sougoud ila Ibn el-insan.\n\nKhaliquhum qad sara ibnaki, lahu et-tasbeeh min kull lisan, wa qabbalteehi bi-fammiki, wa radi'a ka-sa'ir el-bashariyyeen.\n\nToubaki wa touba li-sharaf ginsiki, hamalti khaliq kull el-akwan, wa sara el-khalas lana bi-tuhriki, wa fuzna min harr en-neeran.\n\nLam yagid el-Ab man huwa shibhuki, sirti lillah haykalan munsan, wa sirna ahraran bi-sharaf qadriki, wa 'utiqna min asr esh-shaytan.\n\nEs-salam laki ya umm el-Ilah, geereena quddam ibnik, li-yusamihana nahnu el-khutah, bi-salatik wa sharaf ginsik." },
  ] },
  { id: "vp-melody-for-the-saturday-theotokia-by-bishop-youannis-from-the-13th-century-first-passage", title: "Melody for the Saturday Theotokia by Bishop Youannis from the 13th Century (First Passage)", versions: [
    { language: 'english', text: "(1/7) Fasting and prayer shame Satan / Asceticism defeats his evil plots / Love is the foundation of all growth / Humility quenches his fires\n\n(2/7) He said, “Do not worry about tomorrow / Tomorrow will worry about itself / Seek first the kingdom of God / And all these will be added to you”\n\n(3/7) Give alms to the orphans / Partake with them in the inheritance+ / Be confirmed in the faith / Labor with the ten talents\n\n(4/7) Crowns are prepared for the victorious / In the place of grace, they shall wear them / Eternal punishment is for the apostate / Unceasing worms comparable to serpents\n\n(5/7) Do not be double-tongued / Do not break the laws / Do not be hypocritical / For the works of the sinners will shame them\n\n(6/7) Blessed are those who have mercy / Who give to the poor and fast and pray / The Holy Spirit will fill their hearts / The Son will show them mercy on Judgment Day\n\n(7/7) Blessed are those who have mercy / From God they shall obtain mercy / On Judgment Day Christ will set them apart / May His Holy Spirit fill all their heart" },
    { language: 'arabic', text: "(٧/١) الصوم والصلاة يخزيان الشيطان / والزهد يهزم طغيانه / والمحبة أساس كل البنيان / والتواضع يخمد نيرانه\n\n(٧/٢) قال لا تهتموا للغد بشأن / فإن الغد يهتم بشأنه / أطلبوا أولاً ملكوت الله / وهذا كله تزدادونه\n\n(٧/٣) أعطوا صدقة للمنقطعين / لتشاركوهم فى الميراث / وكونوا فى الإيمان ثابتين / وتاجروا فى العشرة وزنات\n\n(٧/٤) أكاليل معدة للفائزين / فى دار النعيم لابسين تاجات / وعذاباً مخلد للحائدين / ودوداً لا ينام شبه الحيات\n\n(٧/٥) لا تكونوا ذوى لسانين / والشرائع لا تحابوا فيها / ولا تمشوا أيضاً بوجهين / فإن الأثمة أعمالهم تخزيهم\n\n(٧/٦) طوبى للرحما على المساكين / فإن الرحمة تحل عليهم / والمسيح يرحمهم في يوم الدين / ويحل بروح قدسه فيهم" },
  ] },
  { id: "vp-melody-for-the-saturday-theotokia-by-bishop-youannis-second-passage", title: "Melody for the Saturday Theotokia by Bishop Youannis (Second Passage)", versions: [
    { language: 'english', text: "(1/7) A medicine for all wounds / Is fasting with mercy for the needy / Our Master fasted after His baptism / Forty complete days on the mountain\n\n(2/7) Finally, He felt hunger / The tempter dared to call to Him / Saying, “Say to the stones / To become bread to feed the hungry”\n\n(3/7) Our Master defeated him with His words / “Man shall not live by bread alone / But by all the words of God / Away with you, O Satan!”\n\n(4/7) When he heard these sayings / He fled and vanished like smoke / His desires and hopes were crushed / He was shamed, expelled and humiliated\n\n(5/7) He is a wretched thief / Who cannot attack the vigilant / He comes to those who are asleep / And throws them in the midst of his traps\n\n(6/7) Blessed are those who have mercy / Who give to the poor and fast and pray / The Holy Spirit will fill their hearts / The Son will show them mercy on Judgment Day\n\n(7/7) Blessed are those who have mercy / From God they shall obtain mercy / On Judgment Day Christ will set them apart / May His Holy Spirit fill all their heart" },
    { language: 'arabic', text: "(٧/١) دواء يبرئ كل الجراحات / الصوم والرأفة بالمساكين / من بعد العماد سيدنا صام / أربعين يوماً فى الجبل كاملين\n\n(٧/٢) فجاع فى الآخر جوعاً بآلام / فجسر المجرب وناداه بيقين / قال له قل للحجارة أنت بكلام / تصير خبزاً يحيى الجائعين\n\n(٧/٣) فرشقه سيدنا من فاه / قال ليس بالخبز يحيا الإنسان / بل بكل كلام الله / إهرب من خلفى يا شيطان\n\n(٧/٤) فلما سمع ذا القول دهاه / وصار ذاهب مثل الدخان / فخاب أمله وانقطع رجاه / وصار مخزى مطرود مهان\n\n(٧/٥) لأنه لصاً سارق مسكين / والسهارى لا يسطى عليهم / بل يجئ للمتغافلين / فى وسط إشراكه يرميهم\n\n(٧/٦) طوبى للرحما على المساكين / فإن الرحمة تحل عليهم / والمسيح يرحمهم في يوم الدين / ويحل بروح قدسه فيهم" },
  ] },
  { id: "vp-melody-for-the-saturday-theotokia-by-bishop-youannis-third-passage", title: "Melody for the Saturday Theotokia by Bishop Youannis (Third Passage)", versions: [
    { language: 'english', text: "(1/7) Words of the Scriptures revive the spirits / [Spiritual] instructions [help] forgive sins / Repentance is an ointment for all wounds / Love covers all blemishes\n\n(2/7) Through joy and virtues / The Scriptures are fulfilled / Our Master accepted willingly / To be crucified for us in love\n\n(3/7) Avoid the unrighteous profit / Pray vespers and matins / Be content with righteous profit / Like the wise lost son\n\n(4/7) Offer oblations at all times / With careful and alert minds / And remain always vigilant / Do not be careless with the religious canons\n\n(5/7) Do not complain about your leaders / For they are vigilant for you / Praying day and night asking / For salvation and deliverance from their Creator\n\n(6/7) Blessed are those who have mercy / Who give to the poor and fast and pray / The Holy Spirit will fill their hearts / The Son will show them mercy on Judgment Day\n\n(7/7) Blessed are those who have mercy / From God they shall obtain mercy / On Judgment Day Christ will set them apart / May His Holy Spirit fill all their heart" },
    { language: 'arabic', text: "(٧/١) كلام الكتب يحيى الأرواح / والوعظ يمحى كل الذنوب / والتوبة مرهم لكل جراح / والمحبة تستر كل عيوب\n\n(٧/٢) أما الفضائل والأفراح / بها يكمل كل المكتوب / سيدنا هو رضى بسماح / بالمحبة صار عنا مصلوب\n\n(٧/٣) تجنبوا المكسب المذموم / وصلوا عشية مع باكر / وإستكفوا بالرزق المقسوم / كما فعل الإبن الشاطر\n\n(٧/٤) إرفعوا القرابين فى كل حين / بعقل حريص متيقظين / وكونوا دائماً سهرانين / ولا تتهاونوا فى شروط الدين\n\n(٧/٥) والرؤساء لا تَشُكُّوا فيهم / لأنهم عنكم سهرانين / يصلوا الليل والنهار طالبين / النجاة والخلاص من باريهم\n\n(٧/٦) طوبى للرحما على المساكين / فإن الرحمة تحل عليهم / والمسيح يرحمهم في يوم الدين / ويحل بروح قدسه فيهم" },
  ] },
  { id: "vp-melody-for-the-saturday-theotokia-by-bishop-youannis-fourth-passage", title: "Melody for the Saturday Theotokia by Bishop Youannis (Fourth Passage)", versions: [
    { language: 'english', text: "(1/7) The Lord of the highest armies / Was humble and took the image of man / He spoke with the Samaritan woman / Saying, “I am thirsty, give Me a drink”\n\n(2/7) She replied: “The well is deep / And You have no water pot, O Man.” / Come and behold the Creator / How He thirsts while He is the Judge\n\n(3/7) A great profit, comfort, and grace / For him who performs charity / Truly becomes a son of Abraham / According to his faith and intentions\n\n(4/7) He will inherit the Paradise of Joy / And be filled with all good things / This is the reward to him who helps the sick / And covers the naked in secret\n\n(5/7) Love is a strong tower / It completes all virtues / All those who seek it / Its light shines in them\n\n(6/7) Blessed are those who have mercy / Who give to the poor and fast and pray / The Holy Spirit will fill their hearts / The Son will show them mercy on Judgment Day\n\n(7/7) Blessed are those who have mercy / From God they shall obtain mercy / On Judgment Day Christ will set them apart / May His Holy Spirit fill all their heart" },
    { language: 'arabic', text: "(٧/١) رب الجيوش العلوية / إتضع ولبس صورة إنسان / وتكلم مع إمرأة سامرية / قال لها إسقينى فإنى عطشان\n\n(٧/٢) قالت له فارغة الهدرية / وليس لك دلوا يا إنسان / تعالوا أنظروا خالق كل برية / كيف يعطش وهو الديان\n\n(٧/٣) ربح جزيل وعزاء ونعيم / مهيأ لمن يعمل صدقات / حقاً يصير إبن إبراهيم / بحسب الإيمان والنيات\n\n(٧/٤) ويصير وارث فردوس النعيم / ويشبع من كل الخيرات / هذا جزاء من يأوى سقيم / ويكسى العرايا فى خفيات\n\n(٧/٥) المحبة هى برج حصين / وكل الفضائل تُنَميهم / وسراج مضئ لكل الطالبين / وهو نور يشرق فيهم\n\n(٧/٦) طوبى للرحما على المساكين / فإن الرحمة تحل عليهم / والمسيح يرحمهم في يوم الدين / ويحل بروح قدسه فيهم" },
  ] },
  { id: "vp-melody-for-the-saturday-theotokia-by-bishop-youannis-fifth-passage", title: "Melody for the Saturday Theotokia by Bishop Youannis (Fifth Passage)", versions: [
    { language: 'english', text: "(1/7) Jesus was walking on the road and met / Timaeus son of Timaeus in the crowd / Who said, “Have mercy on me, O Son of God / O God of mercy and compassion!”\n\n(2/7) He spat on the ground with His mouth / And anointed the eyes of that blind man / Immediately his eyes were opened / He saw light after the darkness\n\n(3/7) Many miracles by our Master were done / As the bleeding woman whose flow He stopped / She was purified by touching His garment / He accepted the sinful woman in Simon’s house\n\n(4/7) Through His power He turned water / Into good wine at the wedding / His true faith was confirmed / And spread throughout all the land\n\n(5/7) By His death, He loosened the bound / And shone His light on them in the darkness / He saved all the captives / From the shame of their father Adam\n\n(6/7) Blessed are those who have mercy / Who give to the poor and fast and pray / The Holy Spirit will fill their hearts / The Son will show them mercy on Judgment Day\n\n(7/7) Blessed are those who have mercy / From God they shall obtain mercy / On Judgment Day Christ will set them apart / May His Holy Spirit fill all their heart" },
    { language: 'arabic', text: "(٧/١) يسوع ماشياً فى الطريق فوافاه / طيما إبن طيما فى الزحمة / فصاح إرحمنى يا إبن الله / يا إله الرأفة والرحمة\n\n(٧/٢) فتفل على الأرض من فاه / وطلى به عينى ذلك الأعمى / وللوقت إنفتحت عيناه / وأبصر النور بعد الظلمة\n\n(٧/٣) كم عجائب لسيدنا ظهرت / والنازفة منع عنها الجرايان / وبلمس ثيابه قد طهرت / والخاطية قبلها فى بيت سمعان\n\n(٧/٤) والمياه من هيبته إنقلبت / خمراً طيب وسط الأدنان / والأمانة الصحيحة به ثبتت / وإنتشرت فى كل البلدان\n\n(٧/٥) بموته حل الموثوقين / وأشرق فى الظلمة عليهم / وخلص كل المسبيين / من زلة آدم أبيهم\n\n(٧/٦) طوبى للرحما على المساكين / فإن الرحمة تحل عليهم / والمسيح يرحمهم في يوم الدين / ويحل بروح قدسه فيهم" },
  ] },
  { id: "vp-melody-for-the-saturday-theotokia-by-bishop-youannis-sixth-passage", title: "Melody for the Saturday Theotokia by Bishop Youannis (Sixth Passage)", versions: [
    { language: 'english', text: "(1/7) Attend church and recite the readings / Beat your chest during the prayers / He who does not love his brother / Lives in the midst of the darkness\n\n(2/7) How beautiful are the epistles / Sweeter than the honeycomb / Saint Paul’s words restored the disobedient / Both, free and slaves, men and women\n\n(3/7) The house of worship and guidance / Is the Orthodox Church / The house of angels and soldiers+ / The house of the Christian nation\n\n(4/7) [Living] water is available in Her / For the salvation of humanity / As mentioned in the Song of Songs / The homilies and the Didascalia+\n\n(5/7) The mother is joyful in her children / When they are thirsty, she quenches them / Their vessels are always full / The dwellers in her are given drink\n\n(6/7) Blessed are those who have mercy / Who give to the poor and fast and pray / The Holy Spirit will fill their hearts / The Son will show them mercy on Judgment Day\n\n(7/7) Blessed are those who have mercy / From God they shall obtain mercy / On Judgment Day Christ will set them apart / May His Holy Spirit fill all their heart" },
    { language: 'arabic', text: "(٧/١) واظبوا على الكنائس وأتلوا القراءة / ودقوا صدوركم فى الصلوات / وأى إنسان لا يحب أخاه / فهو كائن فى وسط الظلمات\n\n(٧/٢) قول الرسائل ياما أحلاه / ألذ من شهد الخلايات / بولس رد به كل عصاه / أحرار وعبيد ذكور وأناث\n\n(٧/٣) بيت العبادة والإرشاد / البيعة الأرثوذكسية / بيت الملائكة والأجناد / بيت الأمة النصرانية\n\n(٧/٤) موضوع لنا فيها ماء وزاد / لأجل خلاص البشرية / يذكر عنه نشيد الأنشاد / فى المواعظ والدسقولية\n\n(٧/٥) أم الأولاد تفرح بالبنين / يكونوا عطاشى ترويهم / وأوعيتها دائماً ملآنين / والقائمين فيها تسقيهم\n\n(٧/٦) طوبى للرحما على المساكين / فإن الرحمة تحل عليهم / والمسيح يرحمهم في يوم الدين / ويحل بروح قدسه فيهم" },
  ] },
  { id: "vp-melody-for-the-saturday-theotokia-by-bishop-youannis-seventh-passage", title: "Melody for the Saturday Theotokia by Bishop Youannis (Seventh Passage)", versions: [
    { language: 'english', text: "(1/7) Love your enemies, forgive your brethren / To become children of the most high God / Bless those who curse you / As He said in the Gospel\n\n(2/7) Do not resist those who cast you out / Because the end of evil is murder / Do not let anything distract you / From the kingdom of the most high glory\n\n(3/7) Whoever does good works will find it / On Resurrection Day in heaven / Woe to him who does evil works / He will always suffer from punishment\n\n(4/7) Fear your God and keep His commandments / He will save you from evil / He who puts death before his eyes / All things will be dispensable for him\n\n(5/7) Visit your imprisoned brethren / Treat them with gentleness / Be a supporter in their calamities / As members of the body help each other\n\n(6/7) Blessed are those who have mercy / Who give to the poor and fast and pray / The Holy Spirit will fill their hearts / The Son will show them mercy on Judgment Day\n\n(7/7) Blessed are those who have mercy / From God they shall obtain mercy / On Judgment Day Christ will set them apart / May His Holy Spirit fill all their heart" },
    { language: 'arabic', text: "(٧/١) حبوا الأعداء وسامحوا إخوتكم / لتصيروا بنين لله المتعال / وباركوا على من يشتمكم / كما قال فى الإنجيل بكمال\n\n(٧/٢) لا تقاوموا من يطردكم / لأن الشر آخره قتال / ولا تدعوا شيئاً يشغلكم / عن مُلك نعيم المجد المتعال\n\n(٧/٣) من يعمل خيراً يلقاه / يوم القيامة فى السموات / ومن يعمل شراً يا شقاه / دائماً يقاسى فى عقوبات\n\n(٧/٤) خف إلهك وإعمل وصاياه / وهو ينجيك من الآفات / ومن نصب الموت بين عيناه / هانت عليه كل الأشياء\n\n(٧/٥) إفتقدوا إخوتكم المحبوسين / وحنوا بالشفقة عليهم / فى المصائب كونوا لهم مشاركين / فإن الأعضاء تساعد بعضهم\n\n(٧/٦) طوبى للرحما على المساكين / فإن الرحمة تحل عليهم / والمسيح يرحمهم في يوم الدين / ويحل بروح قدسه فيهم" },
  ] },
  { id: "vp-melody-for-the-saturday-theotokia-by-bishop-youannis-eighth-passage", title: "Melody for the Saturday Theotokia by Bishop Youannis (Eighth Passage)", versions: [
    { language: 'english', text: "(1/7) O how beloved is the taste of prayers / Better than the sweetest honey / Sweeter in my mouth than sugar / More beautiful than wedding garments\n\n(2/7) The spring of blessing flows from them / As the word of David the prophet / They are the perfection of liturgies / The souls will live by them\n\n(3/7) When Judas the cursed became / A vessel for Satan and was lost / He went to the evil people / And plotted with them against the worshipped One\n\n(4/7) In the Praetorium his mind was perverted / He took thirty pieces of silver / His name was stricken from among the righteous / And he was deposed from his office\n\n(5/7) The love of silver makes the prudent lost / Those who desired it became blind / Like Ananias and Sapphira the greedy / Saint Peter’s judgment befell them\n\n(6/7) Blessed are those who have mercy / Who give to the poor and fast and pray / The Holy Spirit will fill their hearts / The Son will show them mercy on Judgment Day\n\n(7/7) Blessed are those who have mercy / From God they shall obtain mercy / On Judgment Day Christ will set them apart / May His Holy Spirit fill all their heart" },
    { language: 'arabic', text: "(٧/١) نعم ما أحلى طعم الصلوات / أحلى من عسل الأقراص / داخل فمى كسكر نبات / وهى أجمل من حلل الأعراس\n\n(٧/٢) منها يفيض ينبوع البركات / كقول دافيد بى إبروفىتيس / وهى تكمل القداسات / وبها تحيا كل نفوس\n\n(٧/٣) يهوذا اللعين بعد ما صار / أتاه الشيطان وصبح مفقود / ومضى إلى القوم الأشرار / وتآمر معهم على المعبود\n\n(٧/٤) فى دار الولاية عقله إندار / وأخذ ثلاثين فضة بعدود / وإنشطب إسمه دون الأبرار / وصار من مرتبته مطرود\n\n(٧/٥) بحب الفضة عدم الدارين / والراغبين فيها تعميهم / حنانيا وسفيرة الطماعين / دعا بطرس قد حاق فيهم\n\n(٧/٦) طوبى للرحما على المساكين / فإن الرحمة تحل عليهم / والمسيح يرحمهم في يوم الدين / ويحل بروح قدسه فيهم" },
  ] },
  { id: "vp-melody-for-the-saturday-theotokia-by-bishop-youannis-ninth-passage", title: "Melody for the Saturday Theotokia by Bishop Youannis (Ninth Passage)", versions: [
    { language: 'english', text: "(1/8) Remember me, O Lord, in Your kingdom / As You remembered Joseph and Nicodemus / As the right-hand thief heard Your voice / Saying, “Today you will be with Me in Paradise”\n\n(2/8) O You who gave us life through Your Crucifixion / Put to shame the devil / Keep us by the power of Your divinity / Through the prayers of Mary the Virgin\n\n(3/8) May Christ’s congregation be in peace / Filled with divine grace / O Physician of the sick and weak / Purify us from all sins\n\n(4/8) O You who accepted suffering for us / And was crucified between two thieves / Remember us on Judgment Day / Grant us Your heavenly kingdom\n\n(5/8) Our father the patriarch, the pillar of faith / The bishops and all the priests / The children, brethren, and parents / And heal the sick of the church\n\n(6/8) We ask of our Lord Jesus / To hear our requests / We supplicate Him with all awe / To gain His eternal delight\n\n(7/8) Blessed are those who have mercy / Who give to the poor and fast and pray / The Holy Spirit will fill their hearts / The Son will show them mercy on Judgment Day\n\n(8/8) Blessed are those who have mercy / From God they shall obtain mercy / On Judgment Day Christ will set them apart / May His Holy Spirit fill all their heart" },
    { language: 'arabic', text: "(٨/١) أذكرنى يارب فى ملكوتك / كما ذكرت يوسف ونيقوديموس / واللص اليمين سمع صوتك / القائل إمضى إلى الفردوس\n\n(٨/٢) يا من أحييتنا بصلبوتك / إخزى عنا بى ذيافلوس / وإحفظنا بقوة لاهوتك / بصلاة مريم تى بارثينوس\n\n(٨/٣) شعب المسيح يكون فى سلام / مشمول بالنعمة الإلهية / يا طبيب المرضى والأسقام / طهرنا من كل خطية\n\n(٨/٤) يا من قبل عنا الآلام / وصُلِب بين لصين حرامية / أذكرنا فى يوم الزحام / وهبنا ملكوتك الأبدية\n\n(٨/٥) البابا بطركنا عمود الدين / والأساقفة والكهنة بأجمعهم / والبنين والأخوة والوالدين / ومرضى البيعة إشفيهم\n\n(٨/٦) ونسأل من ربنا يسوع / أن يجعل دعاءنا مسموع / ونتضرع إليه بكل خشوع / لنفوز بنعيمه السرمدية\n\n(٨/٧) طوبى للرحما على المساكين / فإن الرحمة تحل عليهم / والمسيح يرحمهم في يوم الدين / ويحل بروح قدسه فيهم" },
  ] },
  { id: "vp-conclusion-of-the-adam-psali", title: "Ⲗⲟⲓⲡⲟⲛ ⲁⲛϣⲁⲛⲑⲱⲟⲩϯ (Conclusion of the Adam Psali)", versions: [
    { language: 'coptic', text: "Ⲗⲟⲓⲡⲟⲛ ⲁⲛϣⲁⲛⲑⲱⲟⲩϯ: ⲉ̀ϯⲡ̀ⲣⲟⲥⲉⲩⲭⲏ: ⲙⲁⲣⲉⲛⲥ̀ⲙⲟⲩ ⲉ̀ⲡⲓⲣⲁⲛ: ⲛ̀ⲧⲉ Ⲡⲁϭⲟⲓⲥ Ⲓⲏⲥⲟⲩⲥ.\n\nϪⲉ ⲧⲉⲛⲛⲁⲥ̀ⲙⲟⲩ ⲉ̀ⲣⲟⲕ: ⲱ̀ Ⲡⲁϭⲟⲓⲥ Ⲓⲏⲥⲟⲩⲥ: ⲛⲁϩⲙⲉⲛ ϧⲉⲛ ⲡⲉⲕⲣⲁⲛ: ϫⲉ ⲁⲛⲉⲣϩⲉⲗⲡⲓⲥ ⲉ̀ⲣⲟⲕ.\n\nⲆⲟⲝⲁ Ⲡⲁⲧⲣⲓ ⲕⲉ Ⲩ̀ⲓⲱ: ⲕⲉ Ⲁ̀ⲅⲓⲱ Ⲡ̀ⲛⲉⲩⲙⲁⲧⲓ: ⲕⲉ ⲛⲩⲛ ⲕⲉ ⲁ̀ⲓ̀ ⲕⲉ ⲓⲥ ⲧⲟⲩⲥ: ⲉ̀ⲱ̀ⲛⲁⲥ ⲧⲱⲛ ⲉ̀ⲱ̀ⲛⲱⲛ ⲁ̀ⲙⲏⲛ." },
    { language: 'english', text: "And whenever we, gather for prayer, let us bless the name, of my Lord Jesus.\n\nWe bless You, O my Lord Jesus, deliver us through Your name, for we have hope in You.\n\nGlory to the Father and the Son, and the Holy Spirit, now and forever and unto, the age of the ages Amen." },
    { language: 'arabic', text: "وأيضاً إذا ما إجتمعنا، للصلاة، فلنبارك إسم، ربي يسوع.\n\nلأننا نباركك، يا ربي يسوع، نجنا بإسمك، لأننا توكلنا عليك.\n\nالمجد للآب والإبن، والروح القدوس، الآن وكل أوان، وإلى دهر الدهور آمين." },
    { language: 'englishArabic', text: "Wa aydan idha ma igtama'na, lis-salah, fal-nubarik ism, Rabbi Yasou'.\n\nLi-annana nubarikuk, ya Rabbi Yasou', naggina bi-ismik, li-annana tawakkalna 'alayk.\n\nEl-magd lil-Ab wal-Ibn, war-Rouh el-quddous, el-an wa kull awan, wa ila dahr ed-dohour, ameen." },
  ] },
  { id: "vp-adam-nativity-psali-on-sunday-theotokia", title: "Adam Nativity Psali On Sunday Theotokia", versions: [
    { language: 'coptic', text: "Ⲁ̀ Ⲫϯ ⲡⲓⲛⲁⲏⲧ: ⲡ̀ⲟⲩⲣⲟ ⲛ̀ⲛⲓⲉ̀ⲱⲛ: ⲡⲓⲛⲓϣϯ ⲛ̀ⲣⲉϥϣⲉⲛϩⲏⲧ: ⲟⲩⲟϩ ⲛ̀ⲁ̀ⲗⲏⲑⲓⲛⲟⲥ.\n\nⲂⲱⲣⲡ ⲛⲁⲛ ⲙ̀ⲡⲉϥⲥⲁϫⲓ: ⲉ̀ϯϣⲉⲗⲏⲧ ⲙ̀ⲙⲏⲓ: ⲁϥϣⲱⲡⲓ ϧⲉⲛ ⲧⲉⲥⲛⲉϫⲓ: ⲉⲑⲃⲉ ⲡⲉⲛⲟⲩϫⲁⲓ.\n\nⲄⲉⲛⲛⲉⲑⲓⲥ ⲟ̀ ⲉⲕⲡⲁⲣⲑⲉⲛⲟⲩ: ⲙ̀ⲫ̀ⲣⲏϯ ⲙ̀ⲡⲁⲓⲉ̀ϩⲟⲟⲩ: ϯⲙⲟⲩⲙⲓ ⲛ̀ⲁⲑⲙⲟⲩ: Ⲓⲏ︦ⲥ︦ ⲡ̀ⲟⲩⲣⲟ ⲛ̀ⲧⲉ ⲡ̀ⲱ̀ⲟⲩ.\n\nⲆⲁⲩⲓⲇ ⲁ̀ⲙⲟⲩ ⲧⲉⲛⲙⲏϯ: ⲛ̀ϩⲁⲛϫⲱⲙ ⲙ̀ⲯⲁⲗⲓⲁ̀: ⲉ̀ϯⲃⲁⲕⲓ ⲛ̀ⲧⲉ Ⲫϯ: ⲉⲑⲙⲉϩ ⲛ̀ⲉⲩⲗⲟⲅⲓⲁ̀.\n\nⲈⲡⲓⲇⲏ ⲅⲁⲣ ⲁϥϯⲙⲁϯ: ⲉ̀ϣⲱⲡⲓ ⲛ̀ϧⲏⲧⲥ: ⲛ̀ϫⲉ ⲡⲉⲛⲣⲉϥⲥⲱϯ: ⲫⲏⲉ̀ⲧⲁⲩⲥⲉⲙⲛⲏⲧⲥ.\n\nⲌⲉⲟϣ ⲉ̀ⲙⲁϣⲱ: ⲛ̀ϫⲉ ⲛⲉⲉⲩⲫⲟⲙⲓⲁ̀: ⲡⲁⲣⲁ ⲧ̀ⲏ̀ⲡⲓ ⲙ̀ⲡⲓϣⲱ: ⲱ̀ ⲧⲉⲛⲟ︦ⲥ︦ Ⲙⲁⲣⲓⲁ̀\n\nⲎⲡⲡⲉ ⲅⲁⲣ ⲁ̀ⲗⲏⲑⲱⲥ: ⲡⲁⲓⲣⲏϯ ⲟⲛ ⲁϥϫⲱ ⲙ̀ⲙⲟⲥ: ⲛ̀ϫⲉ Ⲏ̀ⲥⲁⲏ̀ⲁⲥ: ⲕⲉ ⲡ̀ⲣⲟⲫⲏⲧⲏⲥ ⲟ̀ⲥⲓⲟⲥ.\n\nⲐⲁⲓ ⲧⲉ ϯⲛⲓϣϯ ⲛ̀ϣ̀ⲫⲏⲣⲓ: ⲟⲩⲁ̀ⲗⲟⲩ ⲛⲁⲛ ⲁⲩⲙⲓⲥⲓ: ⲁⲩϯ ⲛⲁⲛ ⲛ̀ⲟⲩϣⲏⲣⲓ: ⲫⲁ ⲡⲓⲥⲟϭⲛⲓ ⲛ̀ϣ̀ⲫⲏⲣⲓ.\n\nⲒⲏ︦ⲥ︦ Ⲡⲭ︦ⲥ︦ ⲡⲓϫⲱⲣⲓ: ⲡⲓⲉ̀ⲝⲟⲩⲥⲓⲁⲥⲧⲏⲥ: ⲫⲏⲉ̀ⲣⲉ ⲧⲉϥⲁⲣⲭⲏ: ⲭⲏ ϩⲓϫⲉⲛ ⲛⲉϥⲙⲟⲩϯ ⲧⲏⲣⲥ\n\nⲔⲁⲗⲱⲥ ⲟⲛ ⲁϥϫⲟⲥ: ⲛ̀ϫⲉ Ⲓⲉⲍⲉⲕⲓⲏⲗ: ⲉ̀ϫⲉⲛ Ⲙⲁⲥⲓⲁⲥ: ⲡ̀ⲟⲩⲣⲟ ⲙ̀Ⲡⲓ︦ⲥ︦ⲗ︦.\n\nⲖⲟⲓⲡⲟⲛ ⲁⲓⲛⲁⲩ ⲉ̀ⲟⲩⲡⲩⲗⲏ: ⲛ̀ⲥⲁ ⲛⲓⲙⲁⲛ̀ϣⲁⲓ: ⲉⲥⲧⲟⲃ ϧⲉⲛ ⲟⲩⲧⲉⲃⲥ ⲛ̀ϣ̀ⲫⲏⲣⲓ: Ⲫϯ ⲡⲓⲣⲉϥⲛⲁⲓ.\n\nⲘ̀ⲡⲉ ϩ̀ⲗⲓ ϣⲉ ⲉ̀ϧⲟⲩⲛ: ⲉ̀ⲣⲟϥ ⲉ̀ⲃⲏⲗ ⲛ̀ⲑⲟϥ: ⲧⲉⲛϩⲱⲥ ⲛⲁϥ ϧⲉⲛ ⲟⲩⲥ̀ⲙⲟⲩ: ⲕⲁⲧⲁ ⲡⲉⲑⲣⲁⲛⲁϥ.\n\nⲚⲓⲟⲩⲣⲱⲟⲩ ⲛ̀ϩⲁⲛⲙⲁⲅⲟⲥ: ⲁⲩⲓ̀ ⲉ̀ⲃⲟⲗ ⲥⲁ ⲡⲉⲓⲉⲃⲧ: ⲁⲩⲟⲩⲱϣⲧ ⲙ̀Ⲡⲭ︦ⲥ︦: ⲫⲁ ⲡⲓⲣⲁⲛ ⲉⲧⲧⲁⲓⲏ̀ⲟⲩ\n\nⲜⲁⲡⲓⲛⲁ ⲁⲩⲟⲩⲱⲛ: ⲛ̀ⲛⲟⲩⲁ̀ϩⲱⲣ ⲁⲩⲓ̀ⲛⲓ: ⲛⲁϥ ⲛ̀ϩⲁⲛⲇⲱⲣⲟⲛ: ⲧ̀ⲣⲓⲁ̀ⲇⲓⲕⲟⲛ ⲁⲩϯⲙⲏⲓⲛⲓ.\n\nⲞⲩⲗⲓⲃⲁⲛⲟⲥ ϩⲱⲥ ⲛⲟⲩϯ: ⲛⲉⲙ ⲟⲩⲛⲟⲩⲃ ϩⲱⲥ ⲟⲩⲣⲟ: ⲛⲉⲙ ⲟⲩϣⲁⲗ ⲁⲩϯⲙⲏⲓⲛⲓ: ⲉ̀ⲡⲉϥϫⲓⲛⲙⲟⲩ ⲛ̀ⲣⲉϥⲧⲁⲛϧⲟ\n\nⲠⲁⲓⲣⲏϯ ⲛⲓⲟⲩⲣⲱⲟⲩ: ⲛ̀ⲧⲉ ⲛⲓⲀ̀ⲣⲁⲃⲟⲥ: ⲛⲉⲙ ⲛⲓⲙⲁⲛⲉ̀ⲥⲱⲟⲩ: ⲛⲉⲙ Ⲥⲁⲃⲁ ⲛⲉⲙ ⲛⲓⲛⲏⲥⲟⲥ.\n\nⲪⲏ ⲅⲁⲣ ⲉ̀ⲧⲁⲩⲙⲁⲥϥ: ⲉ̀ⲃⲟⲗ ϧⲉⲛ Ⲙⲁⲣⲓⲁ̀: ⲛ̀ⲑⲟϥ ⲡⲉ ⲫⲏⲉ̀ⲧⲁϥⲁϣϥ: ⲉⲑⲃⲉ ⲛⲉⲛⲁ̀ⲛⲟⲙⲓⲁ̀\n\nⲬⲱⲗⲉⲙ ⲇⲉ ⲟⲛ ⲁϥⲥⲟⲧⲧⲉⲛ: ⲉ̀ⲃⲟⲗϧⲉⲛ ϯⲑ̀ⲣⲁⲩⲥⲓⲥ: ϩⲓⲧⲉⲛ ⲡⲉϥⲙⲟⲩ ⲁϥⲟⲗⲧⲉⲛ: ⲉ̀ϯ ⲁ̀ⲛⲁⲡⲁⲩⲥⲓⲥ\n\nⲮⲩⲭⲏ ⲛⲓⲃⲉⲛ ⲉⲩⲥⲟⲡ: ⲙⲁⲣⲟⲩϭ̀ⲛⲉϫⲱⲟⲩ ⲛⲁϥ: ⲛⲉⲙ ⲡⲉϥⲓⲱⲧ ⲫⲏⲉ︦ⲑ︦ⲩ︦: ⲁ̀ϫⲟⲥ ϧⲉⲛ ⲟⲩⲟⲩⲛⲟϥ.\n\nⲰ̀ ⲡⲓⲙⲁⲛⲉ̀ⲥⲱⲟⲩ: ⲛ̀ⲣⲉϥⲛⲟϩⲉⲙ ⲛ̀ⲕⲁⲗⲱⲥ: ϧⲉⲛ ϩⲁⲛϩⲱⲇⲏ ⲛ̀ⲉ̀ⲥⲱⲟⲩ: ⲉⲛϩⲱⲥ ⲛⲁⲕ ⲁⲥ ⲫⲁⲗⲱⲥ" },
    { language: 'english', text: "God the merciful, the King of the ages, the Great and compassionate, and the true one.\n\nHe sent His Word, to the true bride, and dwelt in her womb, for our salvation.\n\nHe was born of the Virgin, on this day, the overflowing fountain, Jesus the King of Glory.\n\nO David come in our midst, with your book of Psalms, to the city of God, full of blessing.\n\nOur Savior, who knows her, delighted to, dwell in her.\n\nMany are, your praises, more than the sand of the sea, O Mary our lady.\n\nFor truly, it was said to us, by Isaiah, the true prophet.\n\nThis is a great wonder, unto us a Child is born, unto us a Son is given, of great counsel.\n\nJesus Christ the Mighty, and the government, will be upon, His shoulder.\n\nTruly indeed, it was said by Ezekiel, about the Messiah, the King of Israel.\n\nI also saw, a Gate towards the East, sealed with a mysterious seal, and God the merciful.\n\nNo man shall enter it, but Him who did, we praise Him with praises, that befits Him.\n\nThe kings of the Magi, came from the East, and worshiped the Christ, whose name is honored.\n\nTruly, they opened their gifts, and offered unto him, three offerings.\n\nFrankincense a symbol of divinity, gold for his kingship, and Myrrh a symbol, of his life-giving death.\n\nAlso the kings, of the arabs, and the shepherds, and Saba and Algeria.\n\nFor He who was, born of Mary, was crucified, for our sins.\n\nHurry and save us, from our enemies, O who by His death, carried our sins.\n\nLet all souls give, reverence to Him, with His Holy Father, and say with joy.\n\nO Shepherd and Savior, we sing unto you, and give praise to you, incessantly." },
    { language: 'arabic', text: "الله الرحوم ملك الدهور العظيم المتحنن والحقيقي.\n\nأرسل لنا كلمته إلي العروس الحقيقية وحل في بطنها من أجل خلاصنا.\n\nولد من العذراء في مثل هذا اليوم الينبوع الغير الناضب يسوع ملك المجد.\n\nيا داود تعال في وسطنا بكتاب مزاميرك إلي مدينة الله المملوءة بركة.\n\nاذ سر أن يحل فيها مخلصنا الذي اتقنها.\n\nكثيرة جداً هي مدائحك أكثر من عدد الرمل يا سيدنتا مريم.\n\nلانه هكذا بالحقيقة أيضاً قال أشعياء النبي الكامل\n\nهذه أعجوبة عظيمة غلام ولد لنا وابناً أعطيناه هو صاحب المشورة العظمي.\n\nيسوع المسيح المتسلط القوي الذي سلطانه علي منكبيه\n\nحسناً قال ايضاً حزقيال علي الماسيا ملك اسرائيل.\n\nوأيضاًُ رأيت باباُ ناحية المشارق مختوماً بخاتم عجيب والله الرحوم\n\nلم يدخله أحد غيرة نسبحه تسبيحاً كما يرضيه\n\nأ تي ملوك المجوس من المشرق وسجدوا للمسيح ذي الاسم المكرم\n\nحقاً فتحوا كنوزهم وقدموا له قرابين ثلاثة\n\n•‬ ⏎ ‫لباناً علامة علي الوهيتة وذهباً اشارة الي انه ملك ومراً اشارة الي موته المحيي.\n\n•‬ ⏎ ‫وهكذا ملوك العرب والرعاة وسابا والجزائر.+ وهكذا ملوك العرب والرعاة وسابا والجزائر.\n\nلان الذي ولد من مريم هو الذي صلب من أجل اثامنا.\n\nاسرع أيضاً وخلصنا من أعدئنا يا من بموته احتمل آلامنا\n\n•‬ ⏎ ‫فلتخضع كل الانفس له مع أبيك القدوس ولنقل بفرح.\n\nأيها الراعي المخلص حسناً نرتل لك ونسبحك بغير فتور." },
  ] },
];

